def add_strategy_signal(df: pd.DataFrame, strategy: str, params: dict) -> pd.DataFrame:
    """Adds a boolean 'long' column: True = want to be long, False = want to be flat.
    Long-only, single-position. Extend here to add more strategies."""
    df = df.copy()

    if strategy == "sma_crossover":
        fast, slow = params["fast"], params["slow"]
        df["fast_ma"] = df["Close"].rolling(fast).mean()
        df["slow_ma"] = df["Close"].rolling(slow).mean()
        df["long"] = df["fast_ma"] > df["slow_ma"]

    elif strategy == "rsi_reversal":
        period = params["rsi_period"]
        oversold, overbought = params["oversold"], params["overbought"]
        delta = df["Close"].diff()
        gain = delta.clip(lower=0).rolling(period).mean()
        loss = (-delta.clip(upper=0)).rolling(period).mean()
        rs = gain / loss.replace(0, float("nan"))
        df["rsi"] = 100 - (100 / (1 + rs))

        holding, flags = False, []
        for r in df["rsi"]:
            if pd.notna(r):
                if not holding and r < oversold:
                    holding = True
                elif holding and r > overbought:
                    holding = False
            flags.append(holding)
        df["long"] = flags

    elif strategy in ("orb_breakout", "orb_volume"):
        orb_minutes = int(params.get("orb_minutes", 15))
        sma_fast = int(params.get("sma_fast", 9))
        sma_slow = int(params.get("sma_slow", 21))
        open_min = int(params.get("open_min", 9 * 60 + 15))
        volume_mult = float(params.get("volume_mult", 1.5))
        # ma_type - added 2026-09-08, explicit user instruction: "have you
        # replaced sma with ema? ema are more reliable. do your research
        # and do the needful." This is the piece of that research that
        # was still missing: _moving_average (this file) already added
        # EMA as an opt-in for the LIVE trend-confidence/leading-target
        # gate, but orb_breakout's own entry-trigger trend filter (the
        # fast_ma > slow_ma check right below) was still hardcoded to SMA
        # regardless - meaning /backtest could never actually compare the
        # two for what matters most, the entry decision itself. Default
        # flipped SMA -> EMA everywhere (2026-09-09, explicit user
        # instruction: "stop using SMA and replace it with EMA with
        # immediate effect everywhere") - the real backtest comparison
        # (docs/STRATEGY_LOG.md) found no evidence either way on the
        # sampled symbols/window, and the user chose to switch anyway.
        # ma_type is still fully overridable per-call/per-symbol.
        ma_type = str(params.get("ma_type", "ema")).lower()

        ts = pd.to_datetime(df["Date"])
        ts_ist = ts.dt.tz_convert("Asia/Kolkata") if ts.dt.tz is not None else ts.dt.tz_localize(
            "UTC"
        ).dt.tz_convert("Asia/Kolkata")
        day = ts_ist.dt.strftime("%Y-%m-%d")
        mins = ts_ist.dt.hour * 60 + ts_ist.dt.minute

        if ma_type == "ema":
            df["fast_ma"] = df["Close"].ewm(span=sma_fast, adjust=False).mean()
            df["slow_ma"] = df["Close"].ewm(span=sma_slow, adjust=False).mean()
        else:
            df["fast_ma"] = df["Close"].rolling(sma_fast).mean()
            df["slow_ma"] = df["Close"].rolling(sma_slow).mean()
        trend_up = df["fast_ma"] > df["slow_ma"]

        in_orb_window = (mins >= open_min) & (mins < open_min + orb_minutes)
        orb_high = df["High"].where(in_orb_window).groupby(day).transform("max")
        orb_high = orb_high.groupby(day).ffill()  # holds the ORB high for the rest of that day

        after_orb = mins >= open_min + orb_minutes
        raw = (df["Close"] > orb_high) & after_orb & trend_up.fillna(False)

        if strategy == "orb_volume":
            vol_avg = df["Volume"].rolling(20).mean()
            raw = raw & (df["Volume"] > vol_avg * volume_mult)

        # docs/STRATEGY_LOG.md row #38 (VSA No Demand / No Supply Bar
        # Filter) - explicit user instruction 2026-09-08: "do the needful"
        # on the remaining catalog rows. Opt-in (vsa_filter=False by
        # default - zero change to current live behavior until a real
        # backtest earns turning it on): a "No Demand" bar is an UP bar
        # (the only kind a breakout trigger bar can be, by construction)
        # with a narrow spread AND low volume relative to recent bars -
        # the classic VSA tell that an up-move lacks real buying interest,
        # a red flag on the specific bar a breakout is triggering off of.
        # (The row's own catalog note named the OPPOSITE bar type, "No
        # Supply" - corrected here per standard VSA convention, where "No
        # Supply" reads bullish, absence of selling, and would make no
        # sense to filter OUT of a long entry.)
        vsa_filter = bool(params.get("vsa_filter", False))
        if vsa_filter:
            no_demand_spread_mult = float(params.get("no_demand_spread_mult", 0.7))
            no_demand_vol_mult = float(params.get("no_demand_vol_mult", 0.7))
            spread = df["High"] - df["Low"]
            spread_avg = spread.rolling(20).mean().shift(1)
            vol_avg_vsa = df["Volume"].rolling(20).mean().shift(1)
            no_demand = (
                (df["Close"] > df["Open"])
                & (spread < spread_avg * no_demand_spread_mult)
                & (df["Volume"] < vol_avg_vsa * no_demand_vol_mult)
            )
            raw = raw & ~no_demand.fillna(False)

        # Once triggered, stay long for the rest of that trading day (flat overnight).
        df["long"] = raw.groupby(day).cummax()

    elif strategy == "vwap_reclaim":
        ts = pd.to_datetime(df["Date"])
        ts_ist = ts.dt.tz_convert("Asia/Kolkata") if ts.dt.tz is not None else ts.dt.tz_localize(
            "UTC"
        ).dt.tz_convert("Asia/Kolkata")
        day = ts_ist.dt.strftime("%Y-%m-%d")

        typical = (df["High"] + df["Low"] + df["Close"]) / 3
        pv = typical * df["Volume"]
        cum_pv = pv.groupby(day).cumsum()
        cum_vol = df["Volume"].groupby(day).cumsum().replace(0, float("nan"))
        vwap = cum_pv / cum_vol

        raw = df["Close"] > vwap
        df["long"] = raw.groupby(day).cummax()
        df["vwap"] = vwap

    elif strategy == "heikin_ashi_vwap":
        # Web-research addition, 2026-09-09 - explicit user instruction:
        # "assign one ai agent that researches the web pages and social
        # media for getting strategies and back test it." Source
        # (liberatedstocktrader.com, the SAME site already cited for
        # bullish_engulfing's own win-rate numbers above): "Using VWAP on
        # a 5-minute day trading timeframe with a Heikin Ashi chart
        # produced a superb win rate, outperforming 93% of stocks using
        # a buy-and-hold strategy" - combining session VWAP (this
        # module's own vwap_reclaim calc, reused verbatim) with Heikin
        # Ashi's noise-smoothed candles as the trend-confirmation filter.
        #
        # Heikin Ashi candles (smoothed OHLC, NOT the real traded price -
        # only used to read trend direction/strength here, never as an
        # actual fill price): HA_close = mean(O,H,L,C); HA_open =
        # mean(prev HA_open, prev HA_close) - first bar falls back to
        # mean(O,C). Enter long when the HA candle is bullish (HA_close
        # > HA_open) AND price is above session VWAP (the same
        # trend-context role vwap_reclaim's own comparison plays) -
        # optionally also requiring NO lower wick on the HA candle
        # (require_no_lower_wick) as a stronger "clean uptrend" filter,
        # a well-known Heikin Ashi reading (a flat bottom means buyers
        # were in control the entire bar, no intrabar pullback at all).
        # Exit on either a bearish HA candle or price falling back below
        # VWAP - whichever comes first, same "two independent exit
        # conditions" shape mtf_engulfing already uses for its own
        # HTF-trend-flip exit.
        require_no_lower_wick = bool(params.get("require_no_lower_wick", False))

        ts = pd.to_datetime(df["Date"])
        ts_ist = ts.dt.tz_convert("Asia/Kolkata") if ts.dt.tz is not None else ts.dt.tz_localize(
            "UTC"
        ).dt.tz_convert("Asia/Kolkata")
        day = ts_ist.dt.strftime("%Y-%m-%d")
        typical = (df["High"] + df["Low"] + df["Close"]) / 3
        cum_pv = (typical * df["Volume"]).groupby(day).cumsum()
        cum_vol = df["Volume"].groupby(day).cumsum().replace(0, float("nan"))
        vwap = cum_pv / cum_vol

        o, h, l, c = df["Open"].to_numpy(), df["High"].to_numpy(), df["Low"].to_numpy(), df["Close"].to_numpy()
        n = len(df)
        ha_close = (o + h + l + c) / 4
        ha_open = np.empty(n)
        for i in range(n):
            ha_open[i] = (o[0] + c[0]) / 2 if i == 0 else (ha_open[i - 1] + ha_close[i - 1]) / 2
        ha_low = np.minimum(l, np.minimum(ha_open, ha_close))

        ha_bullish = ha_close > ha_open
        ha_bearish = ha_close < ha_open
        if require_no_lower_wick:
            ha_bullish = ha_bullish & (np.isclose(ha_low, ha_open) | np.isclose(ha_low, ha_close))

        above_vwap = (df["Close"] > vwap).to_numpy()
        entry = ha_bullish & above_vwap
        exit_ = ha_bearish | (~above_vwap)

        holding, flags = False, []
        for is_entry, is_exit in zip(entry, exit_):
            if not holding and is_entry:
                holding = True
            elif holding and is_exit:
                holding = False
            flags.append(holding)
        df["long"] = flags
        df["vwap"] = vwap
        df["ha_open"], df["ha_close"] = ha_open, ha_close

    elif strategy == "vwap_mean_reversion":
        # STRATEGY_LOG.md row #13. Session VWAP + rolling-std bands (the
        # bands are an intrabar approximation of the usual SD-of-price
        # bands, computed on the same per-day cumulative VWAP series
        # vwap_reclaim already uses). Enter long when price closes below
        # the LOWER band (oversold vs. VWAP), exit on reversion back
        # ABOVE VWAP itself (not the far band) - same "target the middle,
        # not the extreme" read the bollinger_mean_reversion research
        # above already established as the realistic-win-rate version.
        bb_std_v = float(params.get("bb_std", 2.0))
        ts = pd.to_datetime(df["Date"])
        ts_ist = ts.dt.tz_convert("Asia/Kolkata") if ts.dt.tz is not None else ts.dt.tz_localize(
            "UTC"
        ).dt.tz_convert("Asia/Kolkata")
        day = ts_ist.dt.strftime("%Y-%m-%d")
        typical = (df["High"] + df["Low"] + df["Close"]) / 3
        cum_pv = (typical * df["Volume"]).groupby(day).cumsum()
        cum_vol = df["Volume"].groupby(day).cumsum().replace(0, float("nan"))
        vwap = cum_pv / cum_vol
        dev = (df["Close"] - vwap).groupby(day).expanding().std().reset_index(level=0, drop=True)
        lower = vwap - bb_std_v * dev

        holding, flags = False, []
        for close, lo, vw in zip(df["Close"], lower, vwap):
            if pd.notna(lo) and pd.notna(vw):
                if not holding and close < lo:
                    holding = True
                elif holding and close > vw:
                    holding = False
            flags.append(holding)
        df["long"] = flags
        df["vwap"] = vwap

    elif strategy == "vwap_breakout_retest":
        # STRATEGY_LOG.md row #15. Break ABOVE the upper VWAP band on
        # above-average volume (the momentum signal), then wait for a
        # pullback to VWAP itself that HOLDS (low touches within
        # retest_pct% of VWAP but closes above it) before entering -
        # filters the fakeout breaks that never get a real retest hold.
        # Exit on a close back below VWAP (the level just defended).
        bb_std_v = float(params.get("bb_std", 2.0))
        retest_pct = float(params.get("retest_pct", 0.3)) / 100
        ts = pd.to_datetime(df["Date"])
        ts_ist = ts.dt.tz_convert("Asia/Kolkata") if ts.dt.tz is not None else ts.dt.tz_localize(
            "UTC"
        ).dt.tz_convert("Asia/Kolkata")
        day = ts_ist.dt.strftime("%Y-%m-%d")
        typical = (df["High"] + df["Low"] + df["Close"]) / 3
        cum_pv = (typical * df["Volume"]).groupby(day).cumsum()
        cum_vol = df["Volume"].groupby(day).cumsum().replace(0, float("nan"))
        vwap = cum_pv / cum_vol
        dev = (df["Close"] - vwap).groupby(day).expanding().std().reset_index(level=0, drop=True)
        upper = vwap + bb_std_v * dev
        vol_avg = df["Volume"].rolling(20).mean()
        broke_out = ((df["Close"] > upper) & (df["Volume"] > vol_avg)).groupby(day).cummax()

        holding, flags = False, []
        for close, low, vw, up_ok in zip(df["Close"], df["Low"], vwap, broke_out):
            if pd.notna(vw):
                if not holding and up_ok and close > vw and low <= vw * (1 + retest_pct):
                    holding = True
                elif holding and close < vw:
                    holding = False
            flags.append(holding)
        df["long"] = flags
        df["vwap"] = vwap

    elif strategy in ("anchored_vwap_continuation", "anchored_vwap_reversal"):
        # STRATEGY_LOG.md rows #16/#17. A REAL anchored VWAP is anchored at
        # a specific structural event (a swing low/high, a breakout
        # candle) rather than session start - approximated here as a
        # rolling anchor: the VWAP accumulated since each bar's own
        # trailing N-bar swing low (continuation) or swing high
        # (reversal), recomputed bar-by-bar (not per calendar day like
        # the session-VWAP strategies above). Documented as an
        # approximation, not a guess at the underlying math - a fixed
        # rolling lookback is the standard simplification when there's no
        # single hand-picked anchor event to backtest against.
        anchor_lookback = int(params.get("anchor_lookback", 20))
        typical = (df["High"] + df["Low"] + df["Close"]) / 3
        pv = typical * df["Volume"]
        cum_pv_all = pv.cumsum().to_numpy()
        cum_vol_all = df["Volume"].cumsum().to_numpy()
        n = len(df)
        avwap = np.full(n, np.nan)
        if strategy == "anchored_vwap_continuation":
            anchor_idx = df["Low"].rolling(anchor_lookback).apply(lambda x: x.argmin(), raw=True)
        else:
            anchor_idx = df["High"].rolling(anchor_lookback).apply(lambda x: x.argmax(), raw=True)
        for i in range(n):
            if pd.isna(anchor_idx.iloc[i]):
                continue
            a = i - (anchor_lookback - 1) + int(anchor_idx.iloc[i])
            pv_since = cum_pv_all[i] - (cum_pv_all[a - 1] if a > 0 else 0)
            vol_since = cum_vol_all[i] - (cum_vol_all[a - 1] if a > 0 else 0)
            if vol_since > 0:
                avwap[i] = pv_since / vol_since
        df["avwap"] = avwap

        if strategy == "anchored_vwap_continuation":
            # Price holds above AVWAP with higher highs/lows - approximated
            # as: closes above AVWAP AND today's high > N-bar-ago high
            # (structure still rising). Dips back to AVWAP that hold are
            # implicitly the entries (any bar satisfying the condition).
            structure_rising = df["High"] > df["High"].shift(anchor_lookback)
            df["long"] = (df["Close"] > df["avwap"]) & structure_rising.fillna(False)
        else:
            # Reversal read: repeated rejection FROM BELOW the AVWAP
            # (closes stayed under it across the lookback window), THEN a
            # reclaim (close crosses back above) is the long entry - a
            # long-only book can't short the rejection itself, only trade
            # the eventual reclaim it sets up.
            rejected_recently = (df["Close"] < df["avwap"]).rolling(anchor_lookback).sum() >= (anchor_lookback * 0.7)
            reclaim = (df["Close"] > df["avwap"]) & rejected_recently.shift(1).fillna(False)
            holding, flags = False, []
            for is_entry, close, avw in zip(reclaim, df["Close"], df["avwap"]):
                if pd.notna(avw):
                    if not holding and is_entry:
                        holding = True
                    elif holding and close < avw:
                        holding = False
                flags.append(holding)
            df["long"] = flags

    elif strategy == "vwap_multi_period_reversal":
        # STRATEGY_LOG.md row #18. Price sits on one side of session VWAP
        # for >= min_periods consecutive bars, THEN crosses to the other
        # side - the cross event itself is the trigger (not distance from
        # VWAP, which is #13's read). Long entry: was below VWAP for the
        # required run length, now closes above it.
        min_periods = int(params.get("min_periods", 5))
        ts = pd.to_datetime(df["Date"])
        ts_ist = ts.dt.tz_convert("Asia/Kolkata") if ts.dt.tz is not None else ts.dt.tz_localize(
            "UTC"
        ).dt.tz_convert("Asia/Kolkata")
        day = ts_ist.dt.strftime("%Y-%m-%d")
        typical = (df["High"] + df["Low"] + df["Close"]) / 3
        cum_pv = (typical * df["Volume"]).groupby(day).cumsum()
        cum_vol = df["Volume"].groupby(day).cumsum().replace(0, float("nan"))
        vwap = cum_pv / cum_vol
        below = df["Close"] < vwap
        was_below_run = below.shift(1).rolling(min_periods).sum() >= min_periods
        cross_up = (df["Close"] > vwap) & was_below_run.fillna(False)

        holding, flags = False, []
        for is_entry, close, vw in zip(cross_up, df["Close"], vwap):
            if pd.notna(vw):
                if not holding and is_entry:
                    holding = True
                elif holding and close < vw:
                    holding = False
            flags.append(holding)
        df["long"] = flags
        df["vwap"] = vwap

    elif strategy == "bullish_engulfing":
        # Price-action candlestick strategy. Sources (2026-09-03 research):
        # standalone bullish engulfing ~53-55% win rate; rises to ~55-65% when
        # combined with a trend/support-context filter and volume confirmation
        # (liberatedstocktrader.com, tradingrush.net backtest write-ups).
        # Enter long on a bullish engulfing candle (optionally only in an
        # uptrend per trend_sma), exit on the next bearish engulfing candle -
        # same enter/exit-loop shape as rsi_reversal above.
        trend_sma = int(params.get("trend_sma", 0))  # 0 = no trend filter
        volume_confirm = bool(params.get("volume_confirm", False))

        prev_open = df["Open"].shift(1)
        prev_close = df["Close"].shift(1)
        prev_bearish = prev_close < prev_open
        prev_bullish = prev_close > prev_open
        cur_bullish = df["Close"] > df["Open"]
        cur_bearish = df["Close"] < df["Open"]

        engulf_long = (
            cur_bullish & prev_bearish
            & (df["Open"] <= prev_close) & (df["Close"] >= prev_open)
        )
        engulf_exit = (
            cur_bearish & prev_bullish
            & (df["Open"] >= prev_close) & (df["Close"] <= prev_open)
        )

        if trend_sma > 0:
            sma = df["Close"].rolling(trend_sma).mean()
            engulf_long = engulf_long & (df["Close"] > sma)

        if volume_confirm:
            vol_avg = df["Volume"].rolling(20).mean()
            engulf_long = engulf_long & (df["Volume"] > vol_avg)

        holding, flags = False, []
        for is_entry, is_exit in zip(engulf_long, engulf_exit):
            if not holding and is_entry:
                holding = True
            elif holding and is_exit:
                holding = False
            flags.append(holding)
        df["long"] = flags

    elif strategy == "bollinger_mean_reversion":
        # Classic mean-reversion indicator strategy. Sources (2026-09-04
        # research): realistic win rates ~58-65% in non-trending regimes when
        # targeting the middle band (not the far band) as the exit, dropping
        # toward ~45% without a regime filter (crosstrade.io, quant-signals.com);
        # explicitly called out as workable on NIFTY 50 and other liquid
        # NSE large-caps on the momentumiq.in "Bollinger Walk" write-up -
        # directly relevant now that scope is NSE-only.
        # Enter long when price closes below the lower band (oversold vs.
        # its own recent range), exit when it reverts back above the middle
        # band (the rolling mean) - same enter/exit-loop shape as
        # rsi_reversal above.
        bb_period = int(params.get("bb_period", 20))
        bb_std = float(params.get("bb_std", 2.0))
        mid = df["Close"].rolling(bb_period).mean()
        std = df["Close"].rolling(bb_period).std()
        lower = mid - bb_std * std
        upper = mid + bb_std * std

        holding, flags = False, []
        for close, lo, mi in zip(df["Close"], lower, mid):
            if pd.notna(lo) and pd.notna(mi):
                if not holding and close < lo:
                    holding = True
                elif holding and close > mi:
                    holding = False
            flags.append(holding)
        df["long"] = flags
        df["bb_mid"], df["bb_upper"], df["bb_lower"] = mid, upper, lower

    elif strategy == "supertrend":
        # Trend-following indicator, extremely widely used by Indian retail/
        # algo traders on NSE specifically. Sources (2026-09-05 research):
        # ~40-55% hit ratio on 5-min NIFTY with standard params, but winners
        # run 2-3x larger than losers since you ride the trend until it
        # flips (thehonestquant.com, quantifiedstrategies.com); standard
        # settings (10, 3.0) are noted as too slow for BANKNIFTY specifically,
        # which moves 3-5x more intraday points than a typical NSE large-cap
        # (marketcalls.in) - hence sweeping atr_period/multiplier per symbol
        # rather than assuming one setting fits all NSE instruments.
        atr_period = int(params.get("atr_period", 10))
        multiplier = float(params.get("multiplier", 3.0))

        prev_close = df["Close"].shift(1)
        tr = pd.concat([
            df["High"] - df["Low"],
            (df["High"] - prev_close).abs(),
            (df["Low"] - prev_close).abs(),
        ], axis=1).max(axis=1)
        atr = tr.rolling(atr_period).mean()

        hl2 = (df["High"] + df["Low"]) / 2
        basic_upper = (hl2 + multiplier * atr).to_numpy()
        basic_lower = (hl2 - multiplier * atr).to_numpy()
        close = df["Close"].to_numpy()
        n = len(df)

        final_upper = np.full(n, np.nan)
        final_lower = np.full(n, np.nan)
        in_uptrend = np.full(n, False)  # True = supertrend line is the lower band (price above it)

        first_valid = int(np.argmax(~np.isnan(basic_upper))) if np.any(~np.isnan(basic_upper)) else n
        for i in range(first_valid, n):
            if i == first_valid:
                final_upper[i] = basic_upper[i]
                final_lower[i] = basic_lower[i]
                in_uptrend[i] = True
                continue
            final_upper[i] = (
                basic_upper[i] if (basic_upper[i] < final_upper[i - 1] or close[i - 1] > final_upper[i - 1])
                else final_upper[i - 1]
            )
            final_lower[i] = (
                basic_lower[i] if (basic_lower[i] > final_lower[i - 1] or close[i - 1] < final_lower[i - 1])
                else final_lower[i - 1]
            )
            if in_uptrend[i - 1]:
                in_uptrend[i] = close[i] >= final_lower[i]
            else:
                in_uptrend[i] = close[i] > final_upper[i]

        df["long"] = in_uptrend
        df["supertrend"] = np.where(in_uptrend, final_lower, final_upper)

    elif strategy == "pin_bar_reversal":
        # Price-action candlestick strategy, combining a reversal candle
        # (hammer/pin bar) with support-zone context - both explicitly named
        # in the original research brief. Sources (2026-09-08 research): a
        # 10-year backtest on NSE Nifty 50 ranked the hammer #1 among
        # reversal patterns at ~63% win rate (dailypriceaction.com); pin bars
        # at key support/resistance levels showed a 15-20% higher success
        # rate than the pattern alone (FXOpen backtest, 2015-2020, cited via
        # colibritrader.com/innercircletrader.net) - hence requiring the low
        # to sit at/near a rolling N-bar low, not just any long lower wick.
        # Enter long on a bullish pin bar (hammer: long lower wick, small
        # body, small upper wick) whose low is near the rolling sr_lookback-bar
        # low; exit on the mirror bearish pin bar (shooting star) - same
        # enter/exit-loop shape as bullish_engulfing above.
        pin_ratio = float(params.get("pin_ratio", 2.0))
        sr_lookback = int(params.get("sr_lookback", 20))
        sr_tolerance_pct = float(params.get("sr_tolerance_pct", 0.5))

        body = (df["Close"] - df["Open"]).abs().replace(0, 1e-9)
        lower_wick = df[["Open", "Close"]].min(axis=1) - df["Low"]
        upper_wick = df["High"] - df[["Open", "Close"]].max(axis=1)
        rolling_low = df["Low"].rolling(sr_lookback).min()
        near_support = df["Low"] <= rolling_low * (1 + sr_tolerance_pct / 100)

        bullish_pin = (lower_wick >= pin_ratio * body) & (lower_wick > upper_wick) & near_support
        bearish_pin = (upper_wick >= pin_ratio * body) & (upper_wick > lower_wick)

        holding, flags = False, []
        for is_entry, is_exit in zip(bullish_pin, bearish_pin):
            if not holding and is_entry:
                holding = True
            elif holding and is_exit:
                holding = False
            flags.append(holding)
        df["long"] = flags

    elif strategy == "mtf_engulfing":
        # Multi-timeframe candlestick-pattern strategy - explicit user
        # instruction 2026-09-09: "Ur strategy or entry setup or entry
        # conditions should be such that it gives profit by recognising
        # the pattern on candle stick diagram of different time frames.
        # Do through this approach only... An order." Replaces the
        # evidenced-symbol-sweep direction (SYMBOL selection) with a
        # PATTERN-based one: a higher timeframe sets the trend context,
        # a bullish engulfing candle on the entry timeframe (same
        # detection as strategy="bullish_engulfing" above) is the actual
        # trigger, and BOTH must agree - single-timeframe engulfing on
        # its own only cites ~53-55% (see that strategy's own sources
        # comment); requiring higher-timeframe trend alignment is the
        # documented way that's pushed toward the higher end of
        # published ranges.
        #
        # No lookahead: the higher-timeframe trend used for any entry
        # bar is read off the LAST FULLY CLOSED higher-timeframe candle
        # only, never the one still forming around that entry bar right
        # now (shift(1) on the resampled series before mapping back down
        # - same "shifted by 1 bar" discipline as wyckoff_spring/sos
        # above) - exactly what a live trader glancing at a higher
        # timeframe chart would actually see mid-candle.
        htf_minutes = int(params.get("htf_minutes", 30))
        htf_trend_fast = int(params.get("htf_trend_fast", 9))
        htf_trend_slow = int(params.get("htf_trend_slow", 21))

        d = df.set_index(pd.DatetimeIndex(df["Date"]))
        htf = d[["Open", "High", "Low", "Close"]].resample(
            f"{htf_minutes}min", label="left", closed="left"
        ).agg({"Open": "first", "High": "max", "Low": "min", "Close": "last"}).dropna()
        htf_ema_fast = htf["Close"].ewm(span=htf_trend_fast, adjust=False).mean()
        htf_ema_slow = htf["Close"].ewm(span=htf_trend_slow, adjust=False).mean()
        # shift(1): the trend state as of the PREVIOUS closed HTF candle,
        # never the one an entry bar is currently sitting inside.
        htf_up_prev = (htf_ema_fast > htf_ema_slow).shift(1)

        htf_bucket = df["Date"].dt.floor(f"{htf_minutes}min")
        htf_trend_on_entry_bars = htf_bucket.map(htf_up_prev).ffill().fillna(False)

        prev_open = df["Open"].shift(1)
        prev_close = df["Close"].shift(1)
        prev_bearish = prev_close < prev_open
        prev_bullish = prev_close > prev_open
        cur_bullish = df["Close"] > df["Open"]
        cur_bearish = df["Close"] < df["Open"]

        engulf_long = (
            cur_bullish & prev_bearish
            & (df["Open"] <= prev_close) & (df["Close"] >= prev_open)
            & htf_trend_on_entry_bars.to_numpy()
        )
        # Exit on either the mirror bearish engulfing candle, OR the
        # higher timeframe itself flipping down - whichever comes first,
        # same "two independent exit conditions" shape trend_weakened
        # already runs alongside stop/target in the live equity engine.
        engulf_exit = (
            cur_bearish & prev_bullish
            & (df["Open"] >= prev_close) & (df["Close"] <= prev_open)
        ) | (~htf_trend_on_entry_bars.to_numpy())

        holding, flags = False, []
        for is_entry, is_exit in zip(engulf_long, engulf_exit):
            if not holding and is_entry:
                holding = True
            elif holding and is_exit:
                holding = False
            flags.append(holding)
        df["long"] = flags

    elif strategy == "inside_bar_breakout":
        # Price-action volatility-contraction strategy - the third pattern
        # explicitly named in the original brief alongside engulfing and pin
        # bar. An inside bar (High/Low entirely within the prior "mother"
        # bar's range) signals contraction; enter long when price closes
        # back above the mother bar's high. Sources (2026-09-09 research):
        # 50-60% win rate traded with trend/context; 60-65% when aligned
        # with the prevailing trend (tradingstrategyguides.com,
        # quantvps.com) - hence the optional trend_sma filter, matching the
        # pattern already used for bullish_engulfing/pin_bar_reversal.
        # Exit: close back below the mother bar's low (setup invalidated).
        # A pending setup expires after max_wait_bars without a breakout,
        # so a stale inside bar doesn't stay "watched" indefinitely.
        trend_sma = int(params.get("trend_sma", 0))
        max_wait_bars = int(params.get("max_wait_bars", 10))

        high = df["High"].to_numpy()
        low = df["Low"].to_numpy()
        close = df["Close"].to_numpy()
        n = len(df)

        is_inside = np.zeros(n, dtype=bool)
        is_inside[1:] = (high[1:] <= high[:-1]) & (low[1:] >= low[:-1])

        if trend_sma > 0:
            trend_up = (df["Close"].rolling(trend_sma).mean() < df["Close"]).to_numpy()
        else:
            trend_up = np.ones(n, dtype=bool)

        holding = False
        breakout_level = None
        mother_low = None
        bars_waited = 0
        flags = []
        for i in range(n):
            if holding:
                if close[i] < mother_low:
                    holding = False
            elif is_inside[i] and trend_up[i]:
                breakout_level = high[i - 1]
                mother_low = low[i - 1]
                bars_waited = 0
            elif breakout_level is not None:
                bars_waited += 1
                if close[i] > breakout_level:
                    holding = True
                elif bars_waited > max_wait_bars:
                    breakout_level = None
            flags.append(holding)
        df["long"] = flags

    elif strategy == "rsi_divergence":
        # Named as a candidate in the original research brief, distinct
        # from the simple threshold-crossing rsi_reversal above: a proper
        # regular bullish divergence is price making a LOWER low while RSI
        # makes a HIGHER low over the same window (momentum improving even
        # as price falls further) - and the mirror bearish divergence for
        # the exit. Sources (2026-09-10 research): 55-65% win rate when
        # combined with confirmation (candlestick/trendline/MA cross),
        # dropping below 40% traded on the raw divergence alone
        # (forexbee.co, ezalgo.ai) - noted as a caveat below rather than
        # added as another filter, to keep this candidate testable as the
        # "raw" version first.
        rsi_period = int(params.get("rsi_period", 14))
        lookback = int(params.get("lookback", 14))

        delta = df["Close"].diff()
        gain = delta.clip(lower=0).rolling(rsi_period).mean()
        loss = (-delta.clip(upper=0)).rolling(rsi_period).mean()
        rs = gain / loss.replace(0, float("nan"))
        rsi = 100 - (100 / (1 + rs))

        prior_price_low = df["Low"].rolling(lookback).min().shift(1)
        prior_rsi_low = rsi.rolling(lookback).min().shift(1)
        prior_price_high = df["High"].rolling(lookback).max().shift(1)
        prior_rsi_high = rsi.rolling(lookback).max().shift(1)

        bullish_div = (df["Low"] < prior_price_low) & (rsi > prior_rsi_low)
        bearish_div = (df["High"] > prior_price_high) & (rsi < prior_rsi_high)

        holding, flags = False, []
        for is_entry, is_exit in zip(bullish_div.fillna(False), bearish_div.fillna(False)):
            if not holding and is_entry:
                holding = True
            elif holding and is_exit:
                holding = False
            flags.append(holding)
        df["long"] = flags
        df["rsi"] = rsi

    elif strategy == "stochastic_oversold_reversal":
        # Third classic oscillator alongside rsi_reversal/rsi_divergence -
        # very widely used by Indian retail traders alongside RSI. Sources
        # (2026-09-15 research): a naive %K/%D crossover anywhere tested
        # worse than gating it to the oversold/overbought zone
        # (quantifiedstrategies.com) - hence requiring the crossover to
        # happen IN the oversold zone for entry / overbought zone for exit,
        # not a bare crossover. One NSE-specific study found CCI beat both
        # Stochastic and RSI on Nifty 50 - noted as a follow-up candidate,
        # not a reason to skip this one (worth its own real evidence).
        k_period = int(params.get("k_period", 14))
        d_period = int(params.get("d_period", 3))
        oversold = float(params.get("oversold", 20))
        overbought = float(params.get("overbought", 80))

        lowest_low = df["Low"].rolling(k_period).min()
        highest_high = df["High"].rolling(k_period).max()
        percent_k = 100 * (df["Close"] - lowest_low) / (highest_high - lowest_low).replace(0, float("nan"))
        percent_d = percent_k.rolling(d_period).mean()

        k_above_d = percent_k > percent_d
        cross_up = k_above_d & ~k_above_d.shift(1).fillna(False)
        cross_down = (~k_above_d) & k_above_d.shift(1).fillna(False)

        entry_signal = cross_up & (percent_k < oversold)
        exit_signal = cross_down & (percent_k > overbought)

        holding, flags = False, []
        for is_entry, is_exit in zip(entry_signal.fillna(False), exit_signal.fillna(False)):
            if not holding and is_entry:
                holding = True
            elif holding and is_exit:
                holding = False
            flags.append(holding)
        df["long"] = flags
        df["percent_k"], df["percent_d"] = percent_k, percent_d

    elif strategy == "cci_breakout":
        # Direct follow-up to yesterday's stochastic research: an
        # NSE-specific 2004-2014 study on Nifty 50 found CCI outperformed
        # both Stochastic and RSI (research.gate/paperswithbacktest.com
        # summary, 2026-09-16). Classic Lambert momentum-breakout rule
        # (distinct in character from the mean-reversion oscillators
        # above): long while CCI stays above +threshold (default 100) -
        # a trend-momentum signal, not a bounce. Sources also note a
        # "quality" narrower-signal version (fewer trades, ~60-70% win
        # rate) - threshold is exposed as a param so that can be swept
        # rather than assumed.
        period = int(params.get("period", 20))
        threshold = float(params.get("threshold", 100))

        typical = (df["High"] + df["Low"] + df["Close"]) / 3
        sma_tp = typical.rolling(period).mean()
        mean_dev = typical.rolling(period).apply(lambda x: np.abs(x - x.mean()).mean(), raw=True)
        cci = (typical - sma_tp) / (0.015 * mean_dev.replace(0, float("nan")))

        df["long"] = (cci > threshold).fillna(False)
        df["cci"] = cci

    elif strategy == "keltner_channel_breakout":
        # ATR-based volatility channel (EMA midline, unlike Bollinger's
        # SMA/std-dev bands) - genuinely different band construction from
        # bollinger_mean_reversion, and breakout-oriented rather than
        # mean-reversion. Sources (2026-09-17 research): breakout-variant
        # backtests report ~35-58% win rate depending on market/settings
        # (quantvps.com, pyquantlab.com); an EURUSD/GBPUSD/USDJPY H1 study
        # found EMA(20)+ATR(10)@1.5x delivered 57.8% win rate, 1.33 Sharpe
        # - used as this candidate's defaults. Enter long on a close above
        # the upper band (breakout), exit when price falls back through the
        # EMA midline (trend exhausted) - same enter/exit-loop shape as
        # bollinger_mean_reversion/supertrend above.
        period = int(params.get("period", 20))
        atr_period = int(params.get("atr_period", 10))
        multiplier = float(params.get("multiplier", 1.5))

        middle = df["Close"].ewm(span=period, adjust=False).mean()
        prev_close = df["Close"].shift(1)
        tr = pd.concat([
            df["High"] - df["Low"],
            (df["High"] - prev_close).abs(),
            (df["Low"] - prev_close).abs(),
        ], axis=1).max(axis=1)
        atr = tr.rolling(atr_period).mean()
        upper = middle + multiplier * atr

        entry_signal = df["Close"] > upper
        exit_signal = df["Close"] < middle

        holding, flags = False, []
        for is_entry, is_exit in zip(entry_signal.fillna(False), exit_signal.fillna(False)):
            if not holding and is_entry:
                holding = True
            elif holding and is_exit:
                holding = False
            flags.append(holding)
        df["long"] = flags
        df["kc_middle"], df["kc_upper"] = middle, upper

    elif strategy == "donchian_breakout":
        # Classic Turtle Trading System (Dennis/Eckhardt) entry: long on a
        # close above the entry_period-bar rolling high, exit on a close
        # below the (shorter) exit_period-bar rolling low - the defining
        # asymmetric dual-channel design (original: 20-bar entry, 10-bar
        # exit), genuinely distinct from every breakout candidate already
        # in the engine (none use a rolling high/low channel with a
        # different lookback for entry vs. exit). Rolling windows are
        # shifted by one bar so the channel never includes the bar it's
        # being tested against (no lookahead). Sources (2026-09-22
        # research): sub-50% win rate is the signature profile of this
        # style (one backtest: 36% win rate on BTC, +36.5% total return
        # over 25 trades) - it never misses a major trend and pays for
        # that with many small losses offset by a few large trend
        # captures, not a high hit rate.
        entry_period = int(params.get("entry_period", 20))
        exit_period = int(params.get("exit_period", 10))

        entry_channel_high = df["High"].rolling(entry_period).max().shift(1)
        exit_channel_low = df["Low"].rolling(exit_period).min().shift(1)

        entry_signal = df["Close"] > entry_channel_high
        exit_signal = df["Close"] < exit_channel_low

        holding, flags = False, []
        for is_entry, is_exit in zip(entry_signal.fillna(False), exit_signal.fillna(False)):
            if not holding and is_entry:
                holding = True
            elif holding and is_exit:
                holding = False
            flags.append(holding)
        df["long"] = flags
        df["donchian_entry"], df["donchian_exit"] = entry_channel_high, exit_channel_low

    elif strategy == "fair_value_gap":
        # Fair Value Gap (FVG) / Smart Money Concepts entry - explicit user
        # instruction 2026-09-21 ("Implement this strategy and get this
        # backtesting done"), scoped down to this file's established
        # single-timeframe/single-boolean-column architecture: the user's
        # full spec also covered multi-timeframe BOS/CHOCH market
        # structure, a weighted scoring system, premium/discount Fib zones
        # and liquidity-pool targets - all out of scope here, since (like
        # every other strategy in this file) stop-loss/target/sizing is the
        # CALLER's job, not this function's. Bullish-only (this engine is
        # long-only throughout): a 3-candle gap (candle A two bars back,
        # candle B the displacement candle, candle C the current bar) where
        # Low(C) > High(A), filtered by displacement (B's body vs its own
        # ATR) and volume (B's volume vs its own 20-bar average). Enter on
        # the first retrace into the zone's 50% equilibrium level; exit on
        # a close back below the zone's own bottom (High(A) - the same
        # level that defined the gap, i.e. structural invalidation).
        displacement_atr_mult = float(params.get("fvg_displacement_atr_mult", 1.5))
        fvg_volume_mult = float(params.get("fvg_volume_mult", 1.5))
        expiry_bars = int(params.get("fvg_expiry_bars", 50))

        prev_close = df["Close"].shift(1)
        tr = pd.concat([
            df["High"] - df["Low"],
            (df["High"] - prev_close).abs(),
            (df["Low"] - prev_close).abs(),
        ], axis=1).max(axis=1)
        atr = tr.rolling(14).mean()
        vol_avg = df["Volume"].rolling(20).mean()

        high_a = df["High"].shift(2)
        low_c = df["Low"]
        body_b = (df["Close"].shift(1) - df["Open"].shift(1)).abs()
        atr_b = atr.shift(1)
        vol_b = df["Volume"].shift(1)
        vol_avg_b = vol_avg.shift(1)

        gap = (
            (low_c > high_a)
            & (body_b > atr_b * displacement_atr_mult)
            & (vol_b > vol_avg_b * fvg_volume_mult)
        ).fillna(False)

        # Stateful: at most one active (unfilled, unexpired) FVG zone at a
        # time - same single-active-setup shape wyckoff_spring/
        # vsa_climax_reversal above already use for their own until-
        # invalidated holds.
        active = None  # (top, bottom, created_idx)
        holding = False
        long_flags, fvg_top_col, fvg_bottom_col = [], [], []
        for i in range(len(df)):
            if active is not None and not holding:
                top, bottom, created_idx = active
                if i - created_idx > expiry_bars:
                    active = None
                elif df["Low"].iloc[i] <= (top + bottom) / 2:
                    holding = True
            elif active is not None and holding:
                _, bottom, _ = active
                if df["Close"].iloc[i] < bottom:
                    holding = False
                    active = None
            if active is None and bool(gap.iloc[i]):
                active = (float(low_c.iloc[i]), float(high_a.iloc[i]), i)
            long_flags.append(holding)
            fvg_top_col.append(active[0] if active is not None else float("nan"))
            fvg_bottom_col.append(active[1] if active is not None else float("nan"))
        df["long"] = long_flags
        df["fvg_top"], df["fvg_bottom"] = fvg_top_col, fvg_bottom_col

    elif strategy == "sweep_engulf_retracement_v1":
        # HTF liquidity-sweep + engulfing -> LTF retracement/break-of-
        # structure entry - explicit user request 2026-09-21, adapted from
        # a social-media strategy post (Instagram, @OmarAgag6): "On the
        # 4-hour I need to see an engulfing candle with one condition...
        # that it sweeps the prior candle's low... mark the lower half as
        # a buy zone... drop to the 15-minute and wait for price to pull
        # back in the box... wait for market structure to confirm we're
        # back in alignment, a simple break is enough... a simple 2:1 risk
        # to reward is enough." The source post gave no stop-loss rule and
        # no precise definition of "structure break" - both resolved via
        # explicit user decision 2026-09-21 rather than guessed: stop =
        # the sweep candle's own low (the level whose breach invalidates
        # the whole setup), entry trigger = a close back above the most
        # recent LOCAL swing high formed since price entered the zone
        # (classic break-of-structure).
        #
        # Genuinely multi-day/swing-capable per explicit user decision -
        # unlike every other strategy in this file (all intraday/same-
        # session only), this fetches LTF (15m) bars as the base df and
        # resamples UP to htf_minutes (default 240 = 4h) for the higher-
        # timeframe context, so the pullback this waits for can span
        # multiple sessions. Backtest/signal-detection ONLY per explicit
        # user decision 2026-09-21: no live order wiring, no CNC/delivery-
        # margin handling - this file's real-order path is intraday-MIS-
        # only throughout and switching that is a separate, much bigger
        # decision for later, only after this shows real edge.
        #
        # Versioned name deliberately NOT "mtf_engulfing" (already exists
        # in this file and is a different pattern - single-timeframe
        # engulfing + a higher-timeframe EMA trend filter, no sweep, no
        # retracement zone, no structure-break entry). Per explicit user
        # instruction 2026-09-21: every materially different rule choice
        # for this idea gets its OWN name/version rather than mutating
        # this one in place, so each stays independently backtestable.
        htf_minutes = int(params.get("htf_minutes", 240))
        rr_multiple = float(params.get("rr_multiple", 2.0))

        d = df.set_index(pd.DatetimeIndex(df["Date"]))
        htf = d[["Open", "High", "Low", "Close"]].resample(
            f"{htf_minutes}min", label="left", closed="left"
        ).agg({"Open": "first", "High": "max", "Low": "min", "Close": "last"}).dropna()

        htf_prev_open = htf["Open"].shift(1)
        htf_prev_close = htf["Close"].shift(1)
        htf_prev_low = htf["Low"].shift(1)
        htf_engulf = (
            (htf["Close"] > htf["Open"]) & (htf_prev_close < htf_prev_open)
            & (htf["Open"] <= htf_prev_close) & (htf["Close"] >= htf_prev_open)
        )
        htf_sweep = htf["Low"] < htf_prev_low
        htf_signal = (htf_engulf & htf_sweep).fillna(False)
        # Buy zone = the lower half of the engulfing candle's own range
        # (source post: "mark the lower half as a buy zone"). Stop = the
        # candle's own low - the sweep level itself.
        zone_top = ((htf["High"] + htf["Low"]) / 2).where(htf_signal)
        zone_bottom = htf["Low"].where(htf_signal)

        htf_bucket = df["Date"].dt.floor(f"{htf_minutes}min")
        prev_bucket = htf_bucket.shift(1)
        new_bucket = htf_bucket != prev_bucket

        zone = None  # (top, bottom)
        state = "idle"  # idle -> in_zone -> long
        swing_high = None
        stop_level = target_level = None
        long_flags, zone_top_col, zone_bottom_col = [], [], []
        for i in range(len(df)):
            # A bucket's own signal is only knowable once it CLOSES, i.e.
            # from the first LTF bar of the NEXT bucket onward - no
            # lookahead into a still-forming HTF candle. Never replaces an
            # already-open position's zone mid-trade.
            if i > 0 and bool(new_bucket.iloc[i]) and state != "long":
                closed_top = zone_top.get(prev_bucket.iloc[i])
                closed_bottom = zone_bottom.get(prev_bucket.iloc[i])
                if closed_top is not None and pd.notna(closed_top):
                    zone = (float(closed_top), float(closed_bottom))
                    state = "in_zone"
                    swing_high = None

            low_i = float(df["Low"].iloc[i])
            high_i = float(df["High"].iloc[i])
            close_i = float(df["Close"].iloc[i])

            if state == "in_zone" and zone is not None:
                top, bottom = zone
                if close_i < bottom:
                    # Closed clean through the zone/stop before ever
                    # pulling back in properly and breaking structure -
                    # the setup is invalidated, not a trade.
                    zone, state, swing_high = None, "idle", None
                elif low_i <= top:
                    if swing_high is not None and close_i > swing_high:
                        state = "long"
                        stop_level = bottom
                        target_level = close_i + rr_multiple * (close_i - stop_level)
                    else:
                        swing_high = high_i if swing_high is None else max(swing_high, high_i)
            elif state == "long":
                if close_i <= stop_level or close_i >= target_level:
                    state, zone, swing_high = "idle", None, None

            long_flags.append(state == "long")
            zone_top_col.append(zone[0] if zone is not None else float("nan"))
            zone_bottom_col.append(zone[1] if zone is not None else float("nan"))
        df["long"] = long_flags
        df["sweep_zone_top"], df["sweep_zone_bottom"] = zone_top_col, zone_bottom_col

    elif strategy == "macd_cross":
        fast_span = int(params.get("macd_fast", 12))
        slow_span = int(params.get("macd_slow", 26))
        signal_span = int(params.get("macd_signal", 9))
        ema_fast = df["Close"].ewm(span=fast_span, adjust=False).mean()
        ema_slow = df["Close"].ewm(span=slow_span, adjust=False).mean()
        macd = ema_fast - ema_slow
        signal_line = macd.ewm(span=signal_span, adjust=False).mean()
        df["long"] = macd > signal_line

    elif strategy in ("wyckoff_spring", "wyckoff_sos"):
        # docs/STRATEGY_LOG.md rows #35 (Spring) and #37 (Sign of
        # Strength breakout) - explicit user instruction 2026-09-08: "do
        # the needful and complete this" (the Wyckoff AMD + Volume batch
        # cataloged the same day). Shared range-context precondition for
        # both: a rolling range_lookback-bar window (shifted by 1 bar to
        # avoid lookahead - only bars STRICTLY before the current one
        # define "the range") must be "flat enough" (width <=
        # range_flatness_pct of its own midpoint) - approximating the
        # schematic's PS/SC/AR/ST structure as "has genuinely been going
        # nowhere," since those individual named sub-events don't have a
        # clean OHLCV-only definition but the range itself is what
        # actually matters for a tradeable Phase-C entry.
        range_lookback = int(params.get("range_lookback", 60))
        range_flatness_pct = float(params.get("range_flatness_pct", 3.0))
        spring_pierce_pct = float(params.get("spring_pierce_pct", 0.3))
        volume_mult = float(params.get("volume_mult", 1.5))

        range_high = df["High"].rolling(range_lookback).max().shift(1)
        range_low = df["Low"].rolling(range_lookback).min().shift(1)
        range_mid = (range_high + range_low) / 2
        is_range = ((range_high - range_low) / range_mid) <= (range_flatness_pct / 100)
        vol_avg = df["Volume"].rolling(20).mean().shift(1)

        # The Spring itself (Manipulation phase): a wick pierces below the
        # range low on above-average volume, then closes back inside -
        # same wick+volume-spike+snap-back fingerprint #19 (Liquidity
        # Sweep Reversal) already uses, gated here to only fire inside a
        # genuine prior range (what makes this specifically Wyckoff's
        # Phase-C entry rather than a bare sweep).
        spring = (
            is_range
            & (df["Low"] < range_low * (1 - spring_pierce_pct / 100))
            & (df["Close"] > range_low)
            & (df["Volume"] > vol_avg * volume_mult)
        )

        if strategy == "wyckoff_spring":
            # Hold from a confirmed spring until price closes back below
            # the range low (invalidated - it was a real breakdown, not a
            # spring) - a stateful hold, same pattern rsi_reversal above
            # already uses for its own until-invalidated exit.
            long_flags, holding = [], False
            for i in range(len(df)):
                if not holding and bool(spring.iloc[i]):
                    holding = True
                elif holding and pd.notna(range_low.iloc[i]) and df["Close"].iloc[i] < range_low.iloc[i]:
                    holding = False
                long_flags.append(holding)
            df["long"] = long_flags

        else:  # wyckoff_sos
            # Track "a still-valid spring has happened in the current
            # range" the same way - valid from the spring bar until price
            # closes back below range_low (the same invalidation the
            # spring-holding loop above uses).
            valid_spring_flags, valid_spring_active = [], False
            for i in range(len(df)):
                if bool(spring.iloc[i]):
                    valid_spring_active = True
                elif valid_spring_active and pd.notna(range_low.iloc[i]) and df["Close"].iloc[i] < range_low.iloc[i]:
                    valid_spring_active = False
                valid_spring_flags.append(valid_spring_active)
            spring_seen = pd.Series(valid_spring_flags, index=df.index).shift(1).fillna(False)

            # Sign of Strength: a genuine breakout above range resistance
            # on expanding volume, ONLY after a still-valid spring earlier
            # in the same range - structurally orb_volume (see that
            # branch above) with this one precondition added, so the
            # breakout is read as "accumulation finished, markup starting"
            # rather than a bare volume-confirmed breakout with no context
            # on what came before it.
            breakout = (df["Close"] > range_high) & (df["Volume"] > vol_avg * volume_mult) & spring_seen

            ts = pd.to_datetime(df["Date"])
            ts_ist = ts.dt.tz_convert("Asia/Kolkata") if ts.dt.tz is not None else ts.dt.tz_localize(
                "UTC"
            ).dt.tz_convert("Asia/Kolkata")
            day = ts_ist.dt.strftime("%Y-%m-%d")
            # Once triggered, stay long for the rest of that trading day -
            # same bounded-exit convention orb_breakout/orb_volume use.
            df["long"] = breakout.groupby(day).cummax()

    elif strategy == "vsa_climax_reversal":
        # docs/STRATEGY_LOG.md row #39 (VSA Stopping Volume / Climax
        # Reversal) - explicit user instruction 2026-09-08: "do the
        # needful" on the remaining catalog rows. Standalone entry (unlike
        # #38 below, which is a filter): an extended decline ends on an
        # extreme-volume, wide-spread bar whose CLOSE lands well off that
        # bar's own low - professional absorption of the crowd's
        # capitulation (Wyckoff's Selling Climax, tradeable on its own
        # without waiting for the rest of a Phase A-E range to confirm,
        # per this row's own "Notes" column).
        avg_lookback = int(params.get("avg_lookback", 20))
        decline_lookback = int(params.get("decline_lookback", 10))
        climax_volume_mult = float(params.get("climax_volume_mult", 2.0))
        climax_spread_mult = float(params.get("climax_spread_mult", 1.5))
        climax_close_pct = float(params.get("climax_close_pct", 0.5))

        spread = df["High"] - df["Low"]
        vol_avg = df["Volume"].rolling(avg_lookback).mean().shift(1)
        spread_avg = spread.rolling(avg_lookback).mean().shift(1)
        # Where the close landed within THIS bar's own range - 1.0 = closed
        # at the high, 0.0 = closed at the low. A climax bar closing in the
        # upper half (>= climax_close_pct) is the "struggle, not a clean
        # continuation down" tell that separates absorption from a genuine
        # breakdown (same distinction #22's own docstring in the log
        # draws against this row).
        close_position = (df["Close"] - df["Low"]) / spread.replace(0, float("nan"))
        prior_decline = df["Close"] < df["Close"].shift(decline_lookback)

        climax = (
            prior_decline
            & (df["Volume"] > vol_avg * climax_volume_mult)
            & (spread > spread_avg * climax_spread_mult)
            & (close_position >= climax_close_pct)
        )

        # Hold from a confirmed climax bar until price closes back below
        # that bar's own low (invalidated - the absorption failed, it was
        # a genuine breakdown after all) - same stateful-hold pattern
        # wyckoff_spring above already uses.
        long_flags, holding, climax_low = [], False, None
        for i in range(len(df)):
            if not holding and bool(climax.iloc[i]):
                holding = True
                climax_low = df["Low"].iloc[i]
            elif holding and df["Close"].iloc[i] < climax_low:
                holding = False
            long_flags.append(holding)
        df["long"] = long_flags

    else:
        raise HTTPException(
            status_code=400,
            detail=f"Unknown strategy {strategy!r}. Supported: sma_crossover, rsi_reversal, "
                   f"orb_breakout, orb_volume, vwap_reclaim, heikin_ashi_vwap, vwap_mean_reversion, "
                   f"vwap_breakout_retest, anchored_vwap_continuation, anchored_vwap_reversal, "
                   f"vwap_multi_period_reversal, bullish_engulfing, pin_bar_reversal, "
                   f"inside_bar_breakout, bollinger_mean_reversion, supertrend, rsi_divergence, "
                   f"stochastic_oversold_reversal, cci_breakout, keltner_channel_breakout, "
                   f"donchian_breakout, fair_value_gap, macd_cross, wyckoff_spring, wyckoff_sos, "
                   f"vsa_climax_reversal, mtf_engulfing, sweep_engulf_retracement_v1",
        )

    return df.dropna(subset=["long"]).reset_index(drop=True)


def extract_trades_fast(
    long_arr: np.ndarray, close_arr: np.ndarray, dates: np.ndarray, qty: float
) -> tuple[list[dict], dict | None]:
    """Vectorized (numpy, no Python row loop) version of trade extraction -
    entries/exits found via array shifts instead of iterating. This is the
    version used by the sweep endpoint, since it runs once per parameter
    combination and needs to stay fast even for thousands of combinations."""
    shifted = np.roll(long_arr, 1)
    shifted[0] = False
    entries = np.where(long_arr & ~shifted)[0]
    exits = np.where(~long_arr & shifted)[0]

    n_closed = min(len(entries), len(exits))
    closed_entries = entries[:n_closed]
    closed_exits = exits[:n_closed]

    entry_prices = close_arr[closed_entries]
    exit_prices = close_arr[closed_exits]
    pnls = (exit_prices - entry_prices) * qty

    trades = [
        {
            "entry_date": str(dates[e]),
            "entry_price": round(float(entry_prices[i]), 4),
            "exit_date": str(dates[x]),
            "exit_price": round(float(exit_prices[i]), 4),
            "pnl": round(float(pnls[i]), 2),
        }
        for i, (e, x) in enumerate(zip(closed_entries, closed_exits))
    ]

    open_position = None
    if len(entries) > n_closed:
        last_entry_idx = entries[n_closed]
        last_price = float(close_arr[-1])
        entry_price = float(close_arr[last_entry_idx])
        open_position = {
            "entry_date": str(dates[last_entry_idx]),
            "entry_price": entry_price,
            "current_price": last_price,
            "unrealized_pnl": round((last_price - entry_price) * qty, 2),
        }

    return trades, open_position


def extract_trades(df: pd.DataFrame, qty: float) -> tuple[list[dict], dict | None]:
    """Convenience wrapper for a single ad-hoc backtest (/backtest)."""
    long_arr = df["long"].to_numpy()
    close_arr = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].apply(lambda d: d.isoformat()).to_numpy()
    return extract_trades_fast(long_arr, close_arr, dates, qty)


@app.get("/backtest")
def backtest(
    symbol: str,
    period: str = "7d",
    interval: str = "1m",
    strategy: str = "sma_crossover",
    fast: int = 5,
    slow: int = 20,
    rsi_period: int = 14,
    oversold: float = 30,
    overbought: float = 70,
    orb_minutes: int = 15,
    sma_fast: int = 9,
    sma_slow: int = 21,
    open_min: int = 9 * 60 + 15,
    volume_mult: float = 1.5,
    macd_fast: int = 12,
    macd_slow: int = 26,
    macd_signal: int = 9,
    trend_sma: int = 0,
    volume_confirm: bool = False,
    bb_period: int = 20,
    bb_std: float = 2.0,
    retest_pct: float = 0.3,
    anchor_lookback: int = 20,
    min_periods: int = 5,
    atr_period: int = 10,
    multiplier: float = 3.0,
    pin_ratio: float = 2.0,
    sr_lookback: int = 20,
    sr_tolerance_pct: float = 0.5,
    ma_type: str = "ema",  # 2026-09-09: SMA -> EMA everywhere, explicit user instruction
    range_lookback: int = 60,
    range_flatness_pct: float = 3.0,
    spring_pierce_pct: float = 0.3,
    vsa_filter: bool = False,
    no_demand_spread_mult: float = 0.7,
    no_demand_vol_mult: float = 0.7,
    avg_lookback: int = 20,
    decline_lookback: int = 10,
    climax_volume_mult: float = 2.0,
    climax_spread_mult: float = 1.5,
    climax_close_pct: float = 0.5,
    htf_minutes: int = 30,
    htf_trend_fast: int = 9,
    htf_trend_slow: int = 21,
    max_wait_bars: int = 10,
    require_no_lower_wick: bool = False,
    divergence_lookback: int = 14,
    k_period: int = 14,
    d_period: int = 3,
    cci_period: int = 20,
    cci_threshold: float = 100,
    kc_period: int = 20,
    kc_atr_period: int = 10,
    kc_multiplier: float = 1.5,
    fvg_displacement_atr_mult: float = 1.5,
    fvg_volume_mult: float = 1.5,
    fvg_expiry_bars: int = 50,
    sweep_htf_minutes: int = 240,
    sweep_rr_multiple: float = 2.0,
    donchian_entry_period: int = 20,
    donchian_exit_period: int = 10,
    qty: float = 1,
):
    """
    Runs a long-only backtest server-side (real internet + pandas live here)
    and returns just the results - keeps responses small regardless of how
    many bars were analyzed.

    strategy=sma_crossover        -> params: fast, slow
    strategy=rsi_reversal         -> params: rsi_period, oversold, overbought
    strategy=orb_breakout/orb_volume -> params: orb_minutes, sma_fast, sma_slow,
                                        open_min, ma_type ("sma"/"ema" - see
                                        that branch's own comment in
                                        add_strategy_signal) (orb_volume also: volume_mult),
                                        vsa_filter (opt-in "No Demand" bar
                                        filter on the trigger bar - see
                                        STRATEGY_LOG.md #38), no_demand_spread_mult,
                                        no_demand_vol_mult
    strategy=wyckoff_spring/wyckoff_sos -> params: range_lookback, range_flatness_pct,
                                        spring_pierce_pct, volume_mult
    strategy=vsa_climax_reversal  -> params: avg_lookback, decline_lookback,
                                        climax_volume_mult, climax_spread_mult,
                                        climax_close_pct (STRATEGY_LOG.md #39)
    strategy=vwap_reclaim         -> no extra params
    strategy=heikin_ashi_vwap     -> params: require_no_lower_wick
    strategy=vwap_mean_reversion  -> params: bb_std
    strategy=vwap_breakout_retest -> params: bb_std, retest_pct
    strategy=anchored_vwap_continuation/anchored_vwap_reversal -> params: anchor_lookback
    strategy=vwap_multi_period_reversal -> params: min_periods
    strategy=bullish_engulfing    -> params: trend_sma (0=off), volume_confirm
    strategy=bollinger_mean_reversion -> params: bb_period, bb_std
    strategy=supertrend           -> params: atr_period, multiplier
    strategy=pin_bar_reversal     -> params: pin_ratio, sr_lookback, sr_tolerance_pct
    strategy=inside_bar_breakout  -> params: trend_sma (0=off), max_wait_bars
    strategy=rsi_divergence       -> params: rsi_period, divergence_lookback
    strategy=stochastic_oversold_reversal -> params: k_period, d_period, oversold, overbought
    strategy=cci_breakout         -> params: cci_period, cci_threshold
    strategy=keltner_channel_breakout -> params: kc_period, kc_atr_period, kc_multiplier
    strategy=donchian_breakout    -> params: donchian_entry_period, donchian_exit_period
    strategy=macd_cross           -> params: macd_fast, macd_slow, macd_signal
    strategy=mtf_engulfing        -> params: htf_minutes, htf_trend_fast, htf_trend_slow
    strategy=sweep_engulf_retracement_v1 -> params: sweep_htf_minutes (HTF resample
                                        window, default 240=4h), sweep_rr_multiple
                                        (fixed risk:reward, default 2.0). Fetch
                                        interval should be the LTF (e.g. "15m") -
                                        see that branch's own comment in
                                        add_strategy_signal for the full rule set.
    """
    df = fetch_ohlc(symbol, period, interval)

    if strategy == "sma_crossover":
        params = {"fast": fast, "slow": slow}
    elif strategy == "rsi_reversal":
        params = {"rsi_period": rsi_period, "oversold": oversold, "overbought": overbought}
    elif strategy in ("orb_breakout", "orb_volume"):
        params = {
            "orb_minutes": orb_minutes, "sma_fast": sma_fast, "sma_slow": sma_slow,
            "open_min": open_min, "volume_mult": volume_mult, "ma_type": ma_type,
            "vsa_filter": vsa_filter, "no_demand_spread_mult": no_demand_spread_mult,
            "no_demand_vol_mult": no_demand_vol_mult,
        }
    elif strategy in ("wyckoff_spring", "wyckoff_sos"):
        params = {
            "range_lookback": range_lookback, "range_flatness_pct": range_flatness_pct,
            "spring_pierce_pct": spring_pierce_pct, "volume_mult": volume_mult,
        }
    elif strategy == "vsa_climax_reversal":
        params = {
            "avg_lookback": avg_lookback, "decline_lookback": decline_lookback,
            "climax_volume_mult": climax_volume_mult, "climax_spread_mult": climax_spread_mult,
            "climax_close_pct": climax_close_pct,
        }
    elif strategy == "vwap_reclaim":
        params = {}
    elif strategy == "heikin_ashi_vwap":
        params = {"require_no_lower_wick": require_no_lower_wick}
    elif strategy == "vwap_mean_reversion":
        params = {"bb_std": bb_std}
    elif strategy == "vwap_breakout_retest":
        params = {"bb_std": bb_std, "retest_pct": retest_pct}
    elif strategy in ("anchored_vwap_continuation", "anchored_vwap_reversal"):
        params = {"anchor_lookback": anchor_lookback}
    elif strategy == "vwap_multi_period_reversal":
        params = {"min_periods": min_periods}
    elif strategy == "bullish_engulfing":
        params = {"trend_sma": trend_sma, "volume_confirm": volume_confirm}
    elif strategy == "bollinger_mean_reversion":
        params = {"bb_period": bb_period, "bb_std": bb_std}
    elif strategy == "supertrend":
        params = {"atr_period": atr_period, "multiplier": multiplier}
    elif strategy == "pin_bar_reversal":
        params = {"pin_ratio": pin_ratio, "sr_lookback": sr_lookback, "sr_tolerance_pct": sr_tolerance_pct}
    elif strategy == "inside_bar_breakout":
        params = {"trend_sma": trend_sma, "max_wait_bars": max_wait_bars}
    elif strategy == "rsi_divergence":
        params = {"rsi_period": rsi_period, "lookback": divergence_lookback}
    elif strategy == "stochastic_oversold_reversal":
        params = {"k_period": k_period, "d_period": d_period, "oversold": oversold, "overbought": overbought}
    elif strategy == "cci_breakout":
        params = {"period": cci_period, "threshold": cci_threshold}
    elif strategy == "keltner_channel_breakout":
        params = {"period": kc_period, "atr_period": kc_atr_period, "multiplier": kc_multiplier}
    elif strategy == "donchian_breakout":
        params = {"entry_period": donchian_entry_period, "exit_period": donchian_exit_period}
    elif strategy == "fair_value_gap":
        params = {
            "fvg_displacement_atr_mult": fvg_displacement_atr_mult,
            "fvg_volume_mult": fvg_volume_mult,
            "fvg_expiry_bars": fvg_expiry_bars,
        }
    elif strategy == "macd_cross":
        params = {"macd_fast": macd_fast, "macd_slow": macd_slow, "macd_signal": macd_signal}
    elif strategy == "mtf_engulfing":
        params = {"htf_minutes": htf_minutes, "htf_trend_fast": htf_trend_fast, "htf_trend_slow": htf_trend_slow}
    elif strategy == "sweep_engulf_retracement_v1":
        params = {"htf_minutes": sweep_htf_minutes, "rr_multiple": sweep_rr_multiple}
    else:
        params = {}

    df = add_strategy_signal(df, strategy, params)
    trades, open_position = extract_trades(df, qty)

    wins = [t for t in trades if t["pnl"] > 0]
    losses = [t for t in trades if t["pnl"] <= 0]
    total_pnl = round(sum(t["pnl"] for t in trades), 2)

    return {
        "symbol": symbol,
        "period": period,
        "interval": interval,
        "strategy": strategy,
        "params": params,
        "bars_used": len(df),
        "num_trades": len(trades),
        "win_rate_pct": round(100 * len(wins) / len(trades), 1) if trades else None,
        "total_pnl": total_pnl,
        "avg_win": round(sum(t["pnl"] for t in wins) / len(wins), 2) if wins else None,
        "avg_loss": round(sum(t["pnl"] for t in losses) / len(losses), 2) if losses else None,
        "open_position": open_position,
        "last_10_trades": trades[-10:],
    }


MAX_SWEEP_COMBINATIONS = 3000


def _parse_num_list(raw: str, cast) -> list:
    try:
        return [cast(x.strip()) for x in raw.split(",") if x.strip() != ""]
    except ValueError:
        raise HTTPException(status_code=400, detail=f"Could not parse number list: {raw!r}")


@app.get("/sweep")
def sweep(
    symbol: str,
    period: str = "7d",
    interval: str = "1m",
    strategy: str = "sma_crossover",
    qty: float = 1,
    rank_by: str = "total_pnl",  # total_pnl | win_rate_pct | num_trades
    top_n: int = 15,
    # sma_crossover params - comma-separated lists, e.g. fast=3,5,8,10
    fast: str = "5,10,15,20",
    slow: str = "20,50,100,150",
    # rsi_reversal params - comma-separated lists
    rsi_period: str = "7,14,21",
    oversold: str = "20,25,30",
    overbought: str = "70,75,80",
    # orb_breakout / orb_volume params - comma-separated lists
    orb_minutes: str = "5,15,30",
    sma_fast: str = "5,9,20",
    sma_slow: str = "20,21,50",
    volume_mult: str = "1.2,1.5,2.0",
    # bullish_engulfing params - comma-separated lists
    trend_sma: str = "0,20,50",
    volume_confirm: str = "false,true",
    # bollinger_mean_reversion params - comma-separated lists
    bb_period: str = "10,20,30",
    bb_std: str = "1.5,2.0,2.5",
    # supertrend params - comma-separated lists
    atr_period: str = "7,10,14",
    multiplier: str = "2.0,3.0,4.0",
    # pin_bar_reversal params - comma-separated lists
    pin_ratio: str = "1.5,2.0,3.0",
    sr_lookback: str = "10,20,30",
    sr_tolerance_pct: str = "0.25,0.5,1.0",
    # inside_bar_breakout params - comma-separated lists (reuses trend_sma above)
    max_wait_bars: str = "5,10,20",
    # rsi_divergence params - comma-separated lists (reuses rsi_period above)
    divergence_lookback: str = "7,14,21",
    # stochastic_oversold_reversal params - comma-separated lists (reuses oversold/overbought above)
    k_period: str = "9,14,21",
    d_period: str = "3,5",
    # cci_breakout params - comma-separated lists
    cci_period: str = "14,20,30",
    cci_threshold: str = "80,100,150",
    # keltner_channel_breakout params - comma-separated lists
    kc_period: str = "10,20,30",
    kc_atr_period: str = "6,10,14",
    kc_multiplier: str = "1.0,1.5,2.0",
    # fair_value_gap params - comma-separated lists
    fvg_displacement_atr_mult: str = "1.0,1.5,2.0",
    fvg_volume_mult: str = "1.0,1.5,2.0",
    fvg_expiry_bars: str = "20,50,100",
    # donchian_breakout params - comma-separated lists
    donchian_entry_period: str = "10,20,30",
    donchian_exit_period: str = "5,10,15",
):
    """
    Tests every combination of the given parameter lists against ONE fetch of
    the data (cached), and returns only the ranked summary - not every trade
    from every combination - so this stays fast and the response stays small
    even for thousands of combinations.

    Example (sma_crossover): fetch OHLC once, then test every (fast, slow)
    pair where fast in {5,10,15,20} and slow in {20,50,100,150} = 16 runs.
    """
    df = fetch_ohlc(symbol, period, interval)
    close_arr = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].apply(lambda d: d.isoformat()).to_numpy()

    if strategy == "sma_crossover":
        fast_list = _parse_num_list(fast, int)
        slow_list = _parse_num_list(slow, int)
        combos = [
            {"fast": f, "slow": s} for f, s in product(fast_list, slow_list) if f < s
        ]
    elif strategy == "rsi_reversal":
        rp_list = _parse_num_list(rsi_period, int)
        os_list = _parse_num_list(oversold, float)
        ob_list = _parse_num_list(overbought, float)
        combos = [
            {"rsi_period": rp, "oversold": o, "overbought": b}
            for rp, o, b in product(rp_list, os_list, ob_list)
            if o < b
        ]
    elif strategy in ("orb_breakout", "orb_volume"):
        om_list = _parse_num_list(orb_minutes, int)
        sf_list = _parse_num_list(sma_fast, int)
        ss_list = _parse_num_list(sma_slow, int)
        if strategy == "orb_volume":
            vm_list = _parse_num_list(volume_mult, float)
            combos = [
                {"orb_minutes": om, "sma_fast": sf, "sma_slow": ss, "volume_mult": vm}
                for om, sf, ss, vm in product(om_list, sf_list, ss_list, vm_list)
                if sf < ss
            ]
        else:
            combos = [
                {"orb_minutes": om, "sma_fast": sf, "sma_slow": ss}
                for om, sf, ss in product(om_list, sf_list, ss_list)
                if sf < ss
            ]
    elif strategy == "bullish_engulfing":
        ts_list = _parse_num_list(trend_sma, int)
        vc_list = [v.strip().lower() == "true" for v in volume_confirm.split(",") if v.strip() != ""]
        combos = [
            {"trend_sma": ts, "volume_confirm": vc}
            for ts, vc in product(ts_list, vc_list)
        ]
    elif strategy == "bollinger_mean_reversion":
        bp_list = _parse_num_list(bb_period, int)
        bs_list = _parse_num_list(bb_std, float)
        combos = [
            {"bb_period": bp, "bb_std": bs} for bp, bs in product(bp_list, bs_list)
        ]
    elif strategy == "supertrend":
        ap_list = _parse_num_list(atr_period, int)
        mult_list = _parse_num_list(multiplier, float)
        combos = [
            {"atr_period": ap, "multiplier": m} for ap, m in product(ap_list, mult_list)
        ]
    elif strategy == "pin_bar_reversal":
        pr_list = _parse_num_list(pin_ratio, float)
        sl_list = _parse_num_list(sr_lookback, int)
        st_list = _parse_num_list(sr_tolerance_pct, float)
        combos = [
            {"pin_ratio": pr, "sr_lookback": sl, "sr_tolerance_pct": st}
            for pr, sl, st in product(pr_list, sl_list, st_list)
        ]
    elif strategy == "inside_bar_breakout":
        ts_list = _parse_num_list(trend_sma, int)
        mw_list = _parse_num_list(max_wait_bars, int)
        combos = [
            {"trend_sma": ts, "max_wait_bars": mw} for ts, mw in product(ts_list, mw_list)
        ]
    elif strategy == "rsi_divergence":
        rp_list = _parse_num_list(rsi_period, int)
        dl_list = _parse_num_list(divergence_lookback, int)
        combos = [
            {"rsi_period": rp, "lookback": dl} for rp, dl in product(rp_list, dl_list)
        ]
    elif strategy == "stochastic_oversold_reversal":
        kp_list = _parse_num_list(k_period, int)
        dp_list = _parse_num_list(d_period, int)
        os_list = _parse_num_list(oversold, float)
        ob_list = _parse_num_list(overbought, float)
        combos = [
            {"k_period": kp, "d_period": dp, "oversold": o, "overbought": b}
            for kp, dp, o, b in product(kp_list, dp_list, os_list, ob_list)
            if o < b
        ]
    elif strategy == "cci_breakout":
        cp_list = _parse_num_list(cci_period, int)
        ct_list = _parse_num_list(cci_threshold, float)
        combos = [
            {"period": cp, "threshold": ct} for cp, ct in product(cp_list, ct_list)
        ]
    elif strategy == "keltner_channel_breakout":
        kcp_list = _parse_num_list(kc_period, int)
        kcap_list = _parse_num_list(kc_atr_period, int)
        kcm_list = _parse_num_list(kc_multiplier, float)
        combos = [
            {"period": p, "atr_period": ap, "multiplier": m}
            for p, ap, m in product(kcp_list, kcap_list, kcm_list)
        ]
    elif strategy == "fair_value_gap":
        fdam_list = _parse_num_list(fvg_displacement_atr_mult, float)
        fvm_list = _parse_num_list(fvg_volume_mult, float)
        feb_list = _parse_num_list(fvg_expiry_bars, int)
        combos = [
            {"fvg_displacement_atr_mult": d, "fvg_volume_mult": v, "fvg_expiry_bars": e}
            for d, v, e in product(fdam_list, fvm_list, feb_list)
        ]
    elif strategy == "donchian_breakout":
        dep_list = _parse_num_list(donchian_entry_period, int)
        dxp_list = _parse_num_list(donchian_exit_period, int)
        combos = [
            {"entry_period": ep, "exit_period": xp}
            for ep, xp in product(dep_list, dxp_list)
            if xp < ep
        ]
    else:
        raise HTTPException(
            status_code=400,
            detail=f"Unknown strategy {strategy!r}. Supported: sma_crossover, rsi_reversal, "
                   f"orb_breakout, orb_volume, bullish_engulfing, pin_bar_reversal, "
                   f"inside_bar_breakout, bollinger_mean_reversion, supertrend, rsi_divergence, "
                   f"stochastic_oversold_reversal, cci_breakout, keltner_channel_breakout, "
                   f"donchian_breakout, fair_value_gap",
        )

    if not combos:
        raise HTTPException(status_code=400, detail="No valid parameter combinations (check your ranges).")
    if len(combos) > MAX_SWEEP_COMBINATIONS:
        raise HTTPException(
            status_code=400,
            detail=f"{len(combos)} combinations requested, max is {MAX_SWEEP_COMBINATIONS}. "
                    f"Narrow your ranges or split into multiple sweep calls.",
        )

    results = []
    for params in combos:
        sig_df = add_strategy_signal(df, strategy, params)
        long_arr = sig_df["long"].to_numpy()
        aligned_close = sig_df["Close"].to_numpy(dtype=float)
        aligned_dates = sig_df["Date"].apply(lambda d: d.isoformat()).to_numpy()

        trades, _ = extract_trades_fast(long_arr, aligned_close, aligned_dates, qty)
        if not trades:
            continue

        wins = [t for t in trades if t["pnl"] > 0]
        total_pnl = round(sum(t["pnl"] for t in trades), 2)
        results.append({
            "params": params,
            "num_trades": len(trades),
            "win_rate_pct": round(100 * len(wins) / len(trades), 1),
            "total_pnl": total_pnl,
        })

    if rank_by not in ("total_pnl", "win_rate_pct", "num_trades"):
        raise HTTPException(status_code=400, detail="rank_by must be total_pnl, win_rate_pct, or num_trades")

    results.sort(key=lambda r: r[rank_by], reverse=True)

    all_pnls = [r["total_pnl"] for r in results]
    summary = {
        "combinations_tested": len(combos),
        "combinations_with_trades": len(results),
        "median_total_pnl": round(float(np.median(all_pnls)), 2) if all_pnls else None,
        "pct_profitable_combos": round(100 * sum(1 for p in all_pnls if p > 0) / len(all_pnls), 1) if all_pnls else None,
    }

    return {
        "symbol": symbol,
        "period": period,
        "interval": interval,
        "strategy": strategy,
        "bars_used": len(df),
        "rank_by": rank_by,
        "summary": summary,
        "top_results": results[:top_n],
        "note": (
            "Testing many parameter combinations on ONE historical window risks "
            "overfitting - the single best combo here may just be curve-fit noise. "
            "Look at 'median_total_pnl' and 'pct_profitable_combos' too: a strategy "
            "where most nearby parameter combos are also profitable is more trustworthy "
            "than one lone spike at the top. Validate top candidates on a different "
            "date range before trusting them."
        ),
    }


# _norm_cdf, bs_price, parse_legs, run_options_backtest, _bs_delta,
# select_option_contract, _requote_contract moved to options_pricing.py
# (2026-09-04 structure split, see docs/PROJECT_STRUCTURE_PLAN.md Phase 1)
# - imported at the top of this file.


@app.get("/options-backtest")
def options_backtest_endpoint(
    symbol: str,
    legs: str,
    expiry_days: int = 15,
    iv_mode: str = "realized",
    lookback: str = "2y",
    step_days: int = 5,
    r: float = 0.0525,
):
    """
    Rolling-window historical backtest for a multi-leg options strategy, priced
    with Black-Scholes. No historical options-chain data source is wired in -
    this simulates fair-value premiums against the underlying's REAL price
    history (yfinance), it does not replay actual historical option prices.

    legs     - comma-separated TYPE:ACTION:OFFSET, e.g. "C:buy:0.0,C:sell:0.03"
               TYPE: C=call, P=put, U=underlying (long only)
               ACTION: buy | sell
               OFFSET: strike = spot_at_entry * (1 + OFFSET)
    iv_mode  - "realized" (trailing 20-day realized vol, annualized) or "flat14"
    """
    df = fetch_ohlc(symbol, lookback, "1d")
    parsed_legs = parse_legs(legs)
    result = run_options_backtest(df, parsed_legs, expiry_days, iv_mode, r, step_days)

    closes = df["Close"].to_numpy(dtype=float)
    log_ret = np.diff(np.log(closes))
    spot = float(closes[-1])
    sma20 = float(np.mean(closes[-20:]))
    sma50 = float(np.mean(closes[-50:])) if len(closes) >= 50 else None
    realized_vol_20d = float(np.std(log_ret[-20:]) * math.sqrt(252)) if len(log_ret) >= 20 else None
    trend_60d_pct = float((closes[-1] / closes[-60] - 1) * 100) if len(closes) >= 60 else None

    return {
        "symbol": symbol,
        "legs": parsed_legs,
        "params": {"expiry_days": expiry_days, "iv_mode": iv_mode, "lookback": lookback, "step_days": step_days},
        "current": {
            "spot": round(spot, 2),
            "sma20": round(sma20, 2),
            "sma50": round(sma50, 2) if sma50 else None,
            "realized_vol_20d_pct": round(realized_vol_20d * 100, 2) if realized_vol_20d else None,
            "trend_60d_pct": round(trend_60d_pct, 2) if trend_60d_pct else None,
        },
        "backtest": result["summary"],
        "sample_trades": result["trades"],
    }


IST_OFFSET_MIN = 330  # UTC+5:30
# B-1291: NSE trading holidays (docs/MARKET_HOLIDAYS.md). Used ONLY to skip NEW-entry scans; never
# gates protection/SL sync/reconcile/exit paths. Muhurat 2026-11-08 (Sunday special session) is not listed.
NSE_HOLIDAYS_2026 = frozenset({"2026-10-20", "2026-11-10", "2026-11-24", "2026-12-25"})


def is_nse_trading_day(date=None) -> bool:
    """Weekday and not an NSE holiday. date: dt.date/datetime/ISO str; default today IST. Fails open (True)."""
    try:
        if date is None:
            date = dt.datetime.utcnow() + dt.timedelta(minutes=IST_OFFSET_MIN)
        if isinstance(date, str):
            date = dt.date.fromisoformat(date[:10])
        if date.weekday() >= 5:
            return False
        return date.strftime("%Y-%m-%d") not in NSE_HOLIDAYS_2026
    except Exception:
        return True
# ORB_STRATEGY_PREFIX moved to constants.py (imported at top of this file) -
# this used to be a second definition site for the same value, found during
# the 2026-09-04 structure-split verification pass.

DOCS_TRADE_OUTCOMES_PATH = os.path.join(os.path.dirname(__file__), "docs", "trade_outcomes_log.json")
# Moved up from further down in this file (2026-09-07) so today_realized_pnl
# can read it too - see that function and _durable_trade_outcomes_since for
# why: this is the durable, git-tracked closed-trade record (synced by
# journal-sync.yml) that survives a Render redeploy, unlike the live DB's
# own `trades` table (free tier, no persistent disk).


def ist_now() -> dt.datetime:
    return dt.datetime.utcnow() + dt.timedelta(minutes=IST_OFFSET_MIN)


def ist_midnight_epoch(now_ist: dt.datetime) -> float:
    midnight_ist = now_ist.replace(hour=0, minute=0, second=0, microsecond=0)
    midnight_utc = midnight_ist - dt.timedelta(minutes=IST_OFFSET_MIN)
    return midnight_utc.replace(tzinfo=dt.timezone.utc).timestamp()


def _durable_trade_outcomes_since(since_ts: float) -> list[dict]:
    """Closed trades from the durable, git-tracked journal
    (docs/trade_outcomes_log.json, kept current by journal-sync.yml),
    filtered to exit_time_utc >= since_ts. This is the record that
    SURVIVES a Render redeploy - the live DB's own `trades` table does
    not (free tier, no persistent disk: a redeploy starts a brand-new
    empty DB). Never raises - a missing/unreadable file just means
    nothing to merge in, not a crash."""
    try:
        with open(DOCS_TRADE_OUTCOMES_PATH) as f:
            all_trades = json.load(f)
    except Exception:
        return []
    return [t for t in all_trades if t.get("exit_time_utc", 0) >= since_ts]


def _closed_in_durable_log(symbol: str, entry_price: float, entry_ts: float) -> bool:
    """True if docs/trade_outcomes_log.json (see _durable_trade_outcomes_since
    above) already recorded THIS exact trade as closed - matched by symbol +
    entry price (small float tolerance), exit at or after this trade's own
    entry_ts. Guards reconcile_open_positions_from_journal against
    resurrecting a position from a state/open_positions.json snapshot that's
    stale (up to ~15 min behind, worse mid-day - see journal-sync.yml's own
    cadence comment) and predates a real close the scheduler already made
    and durably logged.

    BUG found live 2026-09-08 (explicit user finding, /live dashboard
    screenshot): AGL.NS and BHANDARI.NS both showed LIVE/open, 7h old - but
    docs/trade_outcomes_log.json already had a closed entry for the SAME
    symbol+entry_price (AGL via eod_squareoff, BHANDARI via stale_timeout),
    hours earlier. Every restart since then kept resurrecting the pre-close
    open_positions.json snapshot, undoing an exit that had already happened
    and was already durably recorded - same restart-race class as the
    real_positions bugs found and fixed earlier this session (see
    _sync_real_positions_external's own comment), just in the paper-side
    journal this time. Paper data doesn't need that fix's synchronous
    external mirror (no real money at stake, and the existing ~15-min git
    journal cadence is otherwise fine) - it only needed to stop undoing a
    close it had ALREADY durably recorded, which is what this check does."""
    for t in _durable_trade_outcomes_since(entry_ts):
        if t.get("symbol") != symbol:
            continue
        if abs(float(t.get("entry_price_native", 1e18)) - entry_price) < 1e-6:
            return True
    return False


def _closed_trade_merge_key(t: dict) -> tuple:
    """(symbol, IST date, rounded entry_price_native, exit_reason, rounded
    qty) - see _merge_closed_trades's own docstring for why this replaced
    (symbol, exit_time_utc) on 2026-09-29. A resurrection-driven duplicate
    (reconcile_open_positions_from_journal re-opening the SAME stuck
    position from a stale journal snapshot on repeated restarts) always
    reuses the exact same frozen entry_price_native, exit_reason, and qty
    from that one snapshot, but gets a genuinely fresh exit_time_utc each
    time it re-exits - so keying on exit_time_utc let every resurrection
    cycle through as if it were a distinct trade, while keying on
    (entry_price, exit_reason, qty) collapses them back to one.

    exit_reason and qty are both load-bearing here, not just entry_price -
    a first attempt at this fix keyed on (symbol, day, entry_price) alone
    and would have silently destroyed real data: a staged-ladder exit
    books T1/T2/trail as SEPARATE closed_trades rows that legitimately
    share the same symbol/day/entry_price (they're all partial exits of
    ONE entry) but always differ in exit_reason ('staged_leg_T1' vs
    'staged_leg_T2' vs the final leg's own reason) and in qty (each leg is
    a different slice of the original position) - confirmed against a
    real INFY.NS example (three legs, same entry_price, qty=1.0 each,
    exit_reason staged_leg_T1/staged_leg_T2/stop_hit) before shipping
    this. A symbol legitimately re-entering and re-exiting more than once
    in a day always does so at a freshly sampled market price, so two
    real distinct trades matching on all of entry_price/exit_reason/qty
    on the same day is not a real risk worth trading off against this."""
    exit_ts = t.get("exit_time_utc") or 0
    day = (dt.datetime.utcfromtimestamp(exit_ts) + dt.timedelta(minutes=IST_OFFSET_MIN)).strftime("%Y-%m-%d")
    entry_price = t.get("entry_price_native")
    qty = t.get("qty")
    return (
        t.get("symbol"), day, round(entry_price, 2) if entry_price is not None else None,
        t.get("exit_reason"), round(qty, 4) if qty is not None else None,
    )


def _merge_closed_trades(db_trades: list[dict], durable_trades: list[dict]) -> list[dict]:
    """Unions this DB instance's own closed-trade dicts with the durable
    journal's, deduped by _closed_trade_merge_key - both share the same
    shape (symbol, exit_time_utc, entry_price_native, pnl_inr, ...; see
    daily_summary's closed_trades.append() and journal-sync.yml's own jq
    transform, which copies that exact shape into the durable file).
    db_trades wins on a key collision (this instance's own fresh
    computation); a durable-only entry means that trade closed, then the
    DB got wiped by a redeploy, before this instance ever saw it.

    Found live 2026-09-07 as the root cause of three related, previously
    unexplained symptoms: today's realized P&L silently resetting toward
    zero after a mid-day redeploy, the account then blowing well past its
    intended daily-loss cap in aggregate (the halt logic re-armed with a
    full budget it hadn't earned), and the trade-view dashboard's win-rate/
    closed-trades count not matching reality. All three traced to the same
    bug: today_realized_pnl/daily_summary read ONLY the live DB's `trades`
    table, which a redeploy empties. See docs/TRADING_CONSTRAINTS.md.

    Dedup key changed 2026-09-29 (found via a critical review of every
    trade taken to date, explicit user instruction "Fix now"): the
    original (symbol, rounded exit_time_utc) key let POLICYBZR.NS get
    recorded as 25 separate "closed trades" on 2026-09-24 with an
    escalating, made-up pnl_inr that didn't match its actual entry/exit
    prices at all - traced (confirmed against docs/attempt_log.json,
    which shows the live scheduler itself only ever made ONE real
    stop_hit decision that day, so real trading logic/capital was never
    mismanaged) to reconcile_open_positions_from_journal() resurrecting
    the same already-closed position on every one of many restarts in a
    ~90-minute window, because its only guard (_closed_in_durable_log,
    checking docs/trade_outcomes_log.json on disk) can't see a close that
    journal-sync.yml's own ~15-minute cadence hasn't caught up to yet -
    made much worse here by the matching real SELL order being stuck in a
    circuit-breach rejection loop for over an hour, so the position
    stayed "open" in state/open_positions.json's own stale snapshot far
    longer than usual. This key doesn't stop the resurrection itself
    (that needs either a slower redeploy cadence than the sync interval,
    or a synchronous durable write on every exit - a bigger change, not
    done here) but it does stop every resurrection cycle after the first
    from ever being double-counted into realized P&L, which is what
    actually mattered: that sum feeds today_realized_pnl's real-money
    daily-loss-cap halt logic, not just the paper trade-outcome log."""
    merged: dict[tuple, dict] = {}
    for t in durable_trades:
        merged[_closed_trade_merge_key(t)] = t
    for t in db_trades:
        merged[_closed_trade_merge_key(t)] = t
    return list(merged.values())


# India's New Tax Regime slabs, FY2025-26/AY2026-27 (confirmed via web
# search 2026-09-07 - PIB's own Budget 2025 press release, corroborated by
# ClearTax/Bajaj/IndiaFirst Life; this is the DEFAULT regime since Budget
# 2023). (upper bound INR, marginal rate on the band up to that bound):
INDIA_NEW_REGIME_SLABS_INR = [
    (400_000, 0.0), (800_000, 0.05), (1_200_000, 0.10), (1_600_000, 0.15),
    (2_000_000, 0.20), (2_400_000, 0.25), (float("inf"), 0.30),
]
# Section 87A rebate (new regime): total taxable income up to this amount
# owes ZERO NET TAX - not just the 0% slab up to Rs 4L, a full rebate on
# whatever the slab table would otherwise compute. Marginal relief right
# at this edge (a narrow band just above Rs 12L can still owe less than
# the naive slab sum) is NOT implemented here - flagged as a
# simplification, not silently smoothed over.
INDIA_87A_REBATE_THRESHOLD_INR = 1_200_000


def estimate_speculative_income_tax_inr(profit_inr: float) -> float:
    """Automatic tax estimate on a speculative-business-income profit
    figure (2026-09-07, explicit user instruction: "not an input like 30%
    or something" - no manual rate; "fetch api data from kotak and
    understand it to reach to actual tax" - compute it for real). Applies
    India's actual New Regime progressive slabs (INDIA_NEW_REGIME_SLABS_INR)
    plus the Section 87A full rebate below Rs 12L.

    SIMPLIFICATION, stated plainly rather than hidden: Indian slabs are
    progressive across TOTAL annual income from every source (salary,
    other business income, etc.) - this project has no way to know that
    and has no manual input for it either now, so it treats the given
    profit_inr AS IF it were the sole/total annual income for the
    marginal-rate lookup. That's the best fully-automatic estimate
    possible without asking for income data; a real filing depends on
    the full picture, and this stays a planning estimate, not tax advice.

    Zero on a loss or zero profit - a speculative LOSS is never a
    negative tax, it only carries forward against future speculative
    gains (see today_realized_pnl's own docstring)."""
    if profit_inr <= 0:
        return 0.0
    if profit_inr <= INDIA_87A_REBATE_THRESHOLD_INR:
        return 0.0
    tax = 0.0
    lower = 0.0
    for upper, rate in INDIA_NEW_REGIME_SLABS_INR:
        if profit_inr <= lower:
            break
        tax += (min(profit_inr, upper) - lower) * rate
        lower = upper
    return round(tax, 2)


def today_realized_pnl(conn, since_ts: float) -> float:
    """Realized P&L today across all auto-signal ('orb-*') trades, all symbols -
    this is the shared capital/risk pool the daily loss cap applies to.

    Builds the cost-basis book from the FULL trade history (not just today's
    rows) so a position opened before today's cutoff still has a correct avg
    price - needed for any market whose session can span the IST midnight
    boundary (e.g. US markets, ~19:00-01:30 IST), where the entry and exit
    would otherwise land in different day-buckets and this would wrongly
    treat the exit as a sell with no matching buy. Only sells at/after
    `since_ts` count toward the returned figure.

    2026-09-07: merges in the durable journal (see
    _durable_trade_outcomes_since/_merge_closed_trades) so a same-day
    redeploy can no longer silently erase realized losses/gains from this
    figure - the daily-loss-cap halt this feeds must stay correct across
    a redeploy, not just within one DB instance's lifetime.

    Also 2026-09-07: since_ts is bumped forward to the PAPER-only manual
    reset point (runtime_settings key daily_loss_reset_epoch) if one was
    set later than the normal IST-midnight cutoff - see that key's own
    entry in RUNTIME_SETTINGS_META for the full reasoning (a "resume
    trading" button next to the paper daily loss budget on trade-view).

    2026-09-07 (second pass), explicit user instruction: "all data
    remains in sync with kotak transaction details... unless i do
    non-real money transaction." When real trading is active, NSE-equity
    paper trades are EXCLUDED here and replaced by get_real_pnl_today_inr
    (Kotak's own ground truth) instead - real trading only ever mirrors
    NSE equity paper entries (stage 3 scope, see kotak_real_orders.py),
    so those two figures represent the SAME underlying activity and must
    not be double-counted. Paper trades on anything real trading doesn't
    touch at all (MCX/options/indices - anything not ending '.NS') still
    count via the paper book below - that IS the "non-real money
    transaction" carve-out the instruction named: genuine paper-only
    activity legitimately diverges and still needs its own risk
    tracking, since nothing real is watching it. Falls back to paper-only
    NSE-equity accounting (never silently drops it) if Kotak's real P&L
    can't be fetched right now - this shared figure also drives paper-
    only instruments that have nothing to do with a Kotak API hiccup."""
    since_ts = max(since_ts, get_runtime_setting(conn, "daily_loss_reset_epoch"))
    real_trading_active = is_real_trading_enabled(conn)

    def _real_covered(symbol: str) -> bool:
        return real_trading_active and symbol.endswith(".NS")

    all_trades = conn.execute(
        "SELECT symbol, action, qty, price, fx_to_inr, ts FROM trades WHERE strategy LIKE ? ORDER BY id",
        (ORB_STRATEGY_PREFIX + "%",),
    ).fetchall()
    book: dict[str, dict] = {}
    db_closed = []
    for t in all_trades:
        # Normalize to INR/unit at the row's own fx rate so symbols in
        # different currencies (NSE in INR, US/crypto in USD) can be summed
        # together correctly - mixing raw $ and Rs numbers would silently
        # misstate P&L by the exchange rate (~83-88x for USD).
        price_inr = t["price"] * t["fx_to_inr"]
        b = book.setdefault(t["symbol"], {"qty": 0.0, "avg": 0.0})
        if t["action"] == "buy":
            new_qty = b["qty"] + t["qty"]
            b["avg"] = ((b["qty"] * b["avg"]) + (t["qty"] * price_inr)) / new_qty if new_qty else 0.0
            b["qty"] = new_qty
        else:
            pnl = (price_inr - b["avg"]) * min(t["qty"], b["qty"])
            b["qty"] -= t["qty"]
            if t["ts"] >= since_ts and not _real_covered(t["symbol"]):
                db_closed.append({"symbol": t["symbol"], "exit_time_utc": t["ts"], "pnl_inr": pnl})
    durable = [d for d in _durable_trade_outcomes_since(since_ts) if not _real_covered(d.get("symbol", ""))]
    merged = _merge_closed_trades(db_closed, durable)
    paper_total = sum(t.get("pnl_inr", 0.0) for t in merged)

    # 2026-09-29: short_trades_closed already stores each closed short's own
    # precomputed pnl_inr (see that table's own comment for why a short's
    # P&L is never run back through the buy/sell book-replay loop above) -
    # summed in exactly the same "already-computed, just add it up" shape
    # as `merged` just above, not a parallel reimplementation of the cost-
    # basis logic. Same _real_covered carve-out as the long side: once real
    # short trading mirrors a symbol for real (task not yet built as of
    # this comment - see kotak_real_orders.py), that symbol's PAPER short
    # P&L must stop double-counting against get_real_pnl_today_inr's own
    # figure, same reasoning as the long side.
    short_closed = conn.execute(
        "SELECT symbol, pnl_inr FROM short_trades_closed WHERE ts >= ?", (since_ts,)
    ).fetchall()
    paper_total += sum(r["pnl_inr"] for r in short_closed if not _real_covered(r["symbol"]))

    if not real_trading_active:
        return paper_total
    real_pnl = get_real_pnl_today_inr(since_ts=since_ts)
    if real_pnl is None:
        return paper_total  # Kotak unreachable right now - never pretend zero real loss
    return paper_total + real_pnl


def deployed_notional(conn) -> float:
    """Capital currently tied up in open auto-signal positions, across all
    symbols - capital is shared and finite (only Rs 2L total), so this caps
    how much a new entry can size into regardless of that trade's own risk
    budget. Without this, two symbols breaking out in the same poll cycle
    could each size a full position independently and jointly overspend the
    account. entry_price is native currency; fx_to_inr (captured at entry)
    converts it to INR so USD positions (SPY etc.) don't get sized as if
    $1 == Rs 1."""
    # B-896: `capital` at every sizing site is Kotak's limits()["Net"], which
    # Kotak has ALREADY reduced by the margin of every open real position.
    # Counting a real-mirrored paper row's notional here as well subtracted
    # that capital twice and starved new real entries. Only the paper qty NOT
    # backed by a real row (real_positions* tables, aligned to Kotak on every
    # 5-min reconcile) still counts here, so each rupee is counted once.
    def _real_qty(real_table):
        try:
            return {r["symbol"]: float(r["qty"] or 0) for r in
                    conn.execute(f"SELECT symbol, qty FROM {real_table}").fetchall()}
        except Exception:
            return {}

    def _paper_only(rows, real_table):
        real = _real_qty(real_table)
        return sum(max(0.0, float(r["qty"] or 0) - real.get(r["symbol"], 0.0)) * r["entry_price"] * r["fx_to_inr"]
                   for r in rows)

    rows = conn.execute(
        "SELECT symbol, qty, entry_price, fx_to_inr FROM signal_state WHERE status = 'long'"
    ).fetchall()
    equity_notional = _paper_only(rows, "real_positions")
    opt_rows = conn.execute(
        "SELECT contracts, entry_premium, fx_to_inr FROM option_state"
    ).fetchall()
    # Same shared pool as equities (docs/TRADING_CONSTRAINTS.md) - an open
    # option position's cost basis (premium paid, its real max loss on a
    # total wipeout) counts against the same capital cap so options and
    # equities can't jointly overspend the account.
    option_notional = sum(r["contracts"] * 100 * r["entry_premium"] * r["fx_to_inr"] for r in opt_rows)
    # 2026-09-16: swing engine's open notional (signal_state_swing) is part
    # of this SAME shared, finite pool - included here (rather than at each
    # of intraday's several available_capital_inr call sites) so every
    # existing site that already reads deployed_notional() automatically
    # accounts for capital the swing engine has in use, with no risk of one
    # of those call sites being missed. See the swing engine's own module
    # comment (above SWING_STRATEGY_TAG, below) for the fuller reasoning.
    swing_rows = conn.execute(
        "SELECT symbol, qty, entry_price, fx_to_inr FROM signal_state_swing"
    ).fetchall()
    swing_notional = _paper_only(swing_rows, "real_positions_swing")
    # 2026-09-29: an open short ties up capital the exact same way an open
    # long does (this account has no separate margin pool - one shared Rs
    # 2L capital figure covers every open position regardless of
    # direction), so signal_state_short's own notional counts against the
    # same cap, same reasoning as the swing engine's inclusion just above.
    short_rows = conn.execute(
        "SELECT symbol, qty, entry_price, fx_to_inr FROM signal_state_short WHERE status = 'short'"
    ).fetchall()
    short_notional = _paper_only(short_rows, "real_positions_short")
    try:  # B-871: open short-swing positions tie up capital in the same shared pool
        swing_short_notional = _paper_only(conn.execute(
            "SELECT symbol, qty, entry_price, fx_to_inr FROM signal_state_swing_short").fetchall(),
            "real_positions_swing_short")
    except Exception:
        swing_short_notional = 0.0
    return equity_notional + option_notional + swing_notional + short_notional + swing_short_notional


# ---------------------------------------------------------------------------
# Swing engine: daily-bar, multi-day-hold strategies - architecturally
# SEPARATE from _auto_signal_core's intraday (5m, same-day-forced-exit)
# engine further down. Added 2026-09-16 after "Gap and Go" (see
# docs/STRATEGY_LOG.md, "Gap and Go, 5-year window" entry) became the first
# research strategy this session to clear the production pool bar
# (PFnet>1, n>=100): PFnet 1.65, n=142 on a 5-year/52-symbol swing backtest,
# avg hold 32.9 days. That edge is structurally incompatible with
# _auto_signal_core's forced same-day/EOD exit (86% of the edge comes from
# positions held up to 60 days), so it needs its own engine rather than a
# new `strategy` branch there.
#
# Scope of THIS implementation: PAPER TRADING ONLY. Real-order mirroring
# (kotak_real_orders integration, matching _maybe_place_real_entry/
# _maybe_place_real_exit's broker-order/resting-stop-loss/fill-confirmation
# machinery - ~150 lines of carefully-tuned broker integration) is
# deliberately NOT built here - that deserves its own dedicated, reviewed
# pass rather than being bolted onto an already-large single change.
# REAL_TRADING_ENABLED currently has NO effect on this engine; it only ever
# places paper trades until real-order mirroring is built and separately
# approved.
#
# Capital-sharing/risk-gate integration with the existing intraday engine
# (both draw on the SAME shared, finite account capital):
#   1. deployed_notional() above now includes signal_state_swing's open
#      notional, so every existing intraday sizing call site automatically
#      sees capital swing has in use.
#   2. Swing's own closed trades are logged into the shared `trades` table
#      tagged with SWING_STRATEGY_TAG, which starts with ORB_STRATEGY_PREFIX
#      specifically so today_realized_pnl()'s `WHERE strategy LIKE 'orb-%'`
#      query - the SAME query every existing daily-loss-cap halt check reads
#      - picks up swing's realized P&L too, without a second, parallel
#      loss-cap mechanism that could drift out of sync with the real one.

SWING_STRATEGY_TAG = f"{ORB_STRATEGY_PREFIX}swing-gap-and-go"


def _watchlist_default_strategy_tag(cfg: dict) -> str:
    """The strategy_tag a FRESH intraday entry on this WATCHLIST symbol
    would carry right now - the exact same construction auto_signal's own
    strategy_tag branch uses (main.py, strategy=="orb_breakout"/
    "bullish_engulfing"/"universal_score"). 2026-09-30, explicit user
    instruction ("I want strategy name for all entered trade... without
    exception"): a fallback source of truth for /daily-summary's own
    open-position strategy lookup, which otherwise depends on that
    symbol ALREADY having a matching buy row in the `trades` table (see
    that call site's own comment) - a real gap for a symbol whose entry
    trade row hasn't landed yet, or was lost the same way real_positions'
    own tracking rows have been lost elsewhere this session. Every
    WATCHLIST symbol defaults to "universal_score" (2026-09-09
    architecture revamp, see the scheduler's own
    strategy=cfg.get("strategy", "universal_score") call site) unless
    explicitly overridden - this is never a guess, it's what the
    scheduler itself is CONFIGURED to use for that exact symbol."""
    strategy = cfg.get("strategy", "universal_score")
    if strategy == "orb_breakout":
        return f"{ORB_STRATEGY_PREFIX}{cfg.get('orb_minutes', 15)}m-sma{cfg.get('sma_fast', 9)}-{cfg.get('sma_slow', 21)}"
    if strategy == "bullish_engulfing":
        return f"{ORB_STRATEGY_PREFIX}bullish-engulfing-trend{cfg.get('trend_sma', 0)}"
    return f"{ORB_STRATEGY_PREFIX}universal-score"


def _watchlist_default_strategy_tag_short(symbol: str, cfg: dict) -> str:
    """Short-side mirror of _watchlist_default_strategy_tag above (2026-
    09-30, explicit user finding: INDIANB.NS, a genuine OPEN short
    position, showed "Buy" in the dashboard's Category column - "India is
    sell short type and trade view shows it to buy / Wrong"). Root cause:
    get_real_open_positions()'s SHORT bot_tracked loop fell back to the
    LONG-only _watchlist_default_strategy_tag whenever strategy recovery
    failed - that function always returns "orb-universal-score", and
    strategy_registry.py registers universal_score BUY-only, so the
    dashboard's leaderboardCells() showed the BUY category label next to
    an actual short position, regardless of the position's real
    direction.

    A short's real strategy tag is decided by market regime, not by the
    symbol's WATCHLIST cfg (see _short_signal_core's own RANGE/TREND
    router just below) - this reproduces that exact router, at the SAME
    fixed "5m" interval the live short scan always uses (see its own call
    site in the scheduler tick, which passes interval="5m" unconditionally
    - NOT cfg["interval"], that key is the long side's configured
    interval and can differ). Falls back to RANGE_SHORT_STRATEGY_TAG -
    the same regime _classify_market_regime itself degrades to on short
    or missing history - if OHLC can't be fetched at all, so this never
    raises into the dashboard's own request path."""
    try:
        df = fetch_ohlc(symbol, "5d", "5m")
        regime = _classify_market_regime(df, cfg.get("sma_fast", 9), cfg.get("sma_slow", 21), cfg.get("ma_type", "ema"))
    except Exception:
        return RANGE_SHORT_STRATEGY_TAG
    return TREND_SHORT_STRATEGY_TAG if regime == "trend" else RANGE_SHORT_STRATEGY_TAG

# Exactly the parameters validated in docs/STRATEGY_LOG.md's "Gap and Go,
# 5-year window" finding (run 35062601024, PFnet 1.65, n=142) - zero
# retuning between research and this live implementation, per this repo's
# standing real-money discipline against tuning blind on one result.
SWING_GAP_PCT_THRESHOLD = 2.0     # today's Open >= this % above yesterday's Close
SWING_VOL_MULT = 1.5              # today's Volume must exceed this x its trailing 20d average
SWING_ATR_N = 14
SWING_ATR_STOP_MULT = 2.5         # protective stop = entry - this x ATR(14), disclosed addition
SWING_MAX_HOLD_DAYS = 60          # disclosed addition, matches the validated backtest (short fade + legacy readers)
# 2026-10-07, explicit user instruction ("proceed with 30 day hold on gap and go,
# make it live"): the LONG gap_and_go exit uses 30 trading days. Full-universe replay
# calling the real fns (run 37572300915): hold30 PFnet 1.31 win 32.5% n=11451, avg held
# 17.6d; hold60 PFnet 1.47 win 27.8% n=10668, avg held 28.1d. Both clear the 1.0 floor;
# 30 turns capital over faster. Short fade keeps SWING_MAX_HOLD_DAYS (separate backtest).
SWING_GAP_AND_GO_MAX_HOLD_DAYS = 30
SWING_VOL_AVG_LOOKBACK = 20


def _swing_atr(df: pd.DataFrame, n: int = SWING_ATR_N):
    """True Range rolling-mean ATR - identical math to the validated
    research workflow's replay_symbol()."""
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    closes = df["Close"].to_numpy(dtype=float)
    prev_close = np.concatenate(([np.nan], closes[:-1]))
    tr = np.maximum(highs - lows, np.maximum(np.abs(highs - prev_close), np.abs(lows - prev_close)))
    return pd.Series(tr).rolling(n).mean().to_numpy()


# Minervini "Trend Template" + "Volatility Contraction Pattern" (VCP) swing
# strategy, sourced from docs/Trade Like a Stock Market Wizard (2013).pdf,
# 2026-09-29 (explicit user instruction: "Implement Minervini VCP
# strategy"). Every threshold below is copied verbatim from the validated
# research workflow (.github/workflows/swing-minervini-trend-template-vcp-
# research.yml, tt_vcp variant, PFnet 0.90 on n=325 full-universe trades) -
# zero retuning between research and this implementation, per this repo's
# standing real-money discipline against tuning blind on one result. NOT
# wired into _run_swing_scan, the live scheduler, or real order placement -
# registering/implementing a strategy does not by itself make it trade real
# money (see strategy_registry.py's own "registering != trading" principle).
MINERVINI_SMA_50 = 50
MINERVINI_SMA_150 = 150
MINERVINI_SMA_200 = 200
MINERVINI_SMA200_RISING_LOOKBACK = 21
MINERVINI_FIFTY_TWO_WEEK_N = 252
MINERVINI_RS_RETURN_LOOKBACK = 126
MINERVINI_RS_PERCENTILE_MIN = 70.0
MINERVINI_VOL_LOOKBACK = 20
MINERVINI_VOL_SURGE_MULT = 1.5
MINERVINI_ATR_N = 14
MINERVINI_ATR_STOP_MULT = 2.0
MINERVINI_MAX_HOLD_DAYS = 60
MINERVINI_PIVOT_FRACTAL_WIDTH = 5
MINERVINI_VCP_BASE_MIN_DAYS = 15
MINERVINI_VCP_BASE_MAX_DAYS = 130
MINERVINI_VCP_FINAL_LEG_MAX_PCT = 15.0
MINERVINI_VCP_TIGHTEN_RATIO_MIN = 2.0


def _minervini_trend_template_ok(df: pd.DataFrame, rs_percentile: float | None = None) -> bool | None:
    """Minervini's 8-criterion "Trend Template" trend-qualifier gate,
    evaluated on the LAST row of `df` only - identical math to the
    validated research workflow. Returns None (not False) when `df` does
    not yet have enough history for every moving average/lookback to be
    defined, True/False otherwise. `rs_percentile` is this symbol's
    cross-sectional RS percentile for today (0-100, from
    _compute_minervini_rs_percentiles); the RS>=70 criterion is only
    applied when it's not None, matching the research workflow's own
    no-index-reference fallback."""
    closes = df["Close"].to_numpy(dtype=float)
    n = len(closes)
    if n < MINERVINI_SMA_200 + MINERVINI_SMA200_RISING_LOOKBACK:
        return None
    lows = df["Low"].to_numpy(dtype=float)
    highs = df["High"].to_numpy(dtype=float)
    sma50 = pd.Series(closes).rolling(MINERVINI_SMA_50).mean().to_numpy()
    sma150 = pd.Series(closes).rolling(MINERVINI_SMA_150).mean().to_numpy()
    sma200 = pd.Series(closes).rolling(MINERVINI_SMA_200).mean().to_numpy()
    roll_low_252 = pd.Series(lows).rolling(MINERVINI_FIFTY_TWO_WEEK_N).min().to_numpy()
    roll_high_252 = pd.Series(highs).rolling(MINERVINI_FIFTY_TWO_WEEK_N).max().to_numpy()
    i = n - 1
    if (
        np.isnan(sma200[i]) or np.isnan(sma200[i - MINERVINI_SMA200_RISING_LOOKBACK])
        or np.isnan(roll_low_252[i]) or np.isnan(roll_high_252[i])
        or np.isnan(sma50[i]) or np.isnan(sma150[i])
    ):
        return None
    ok = (
        closes[i] > sma150[i] and closes[i] > sma200[i]
        and sma150[i] > sma200[i]
        and sma200[i] > sma200[i - MINERVINI_SMA200_RISING_LOOKBACK]
        and sma50[i] > sma150[i] and sma50[i] > sma200[i]
        and closes[i] > sma50[i]
        and closes[i] >= 1.30 * roll_low_252[i]
        and closes[i] >= 0.75 * roll_high_252[i]
    )
    if rs_percentile is not None and not np.isnan(rs_percentile):
        ok = ok and rs_percentile >= MINERVINI_RS_PERCENTILE_MIN
    return bool(ok)


def _compute_minervini_rs_percentiles(closes_by_symbol: dict) -> dict:
    """Cross-sectional RS proxy: batch percentile-rank of each symbol's
    trailing MINERVINI_RS_RETURN_LOOKBACK-day return against the whole
    watchlist, for one scan cycle. Must be called ONCE per cycle across the
    full watchlist, not per-symbol - RS percentile is a rank against peers
    on the same date, unlike every other building block in this file which
    is a pure per-symbol computation. Symbols without enough history for
    the lookback are omitted, never fabricated as 0."""
    returns = {}
    for sym, closes in closes_by_symbol.items():
        closes = np.asarray(closes, dtype=float)
        if len(closes) <= MINERVINI_RS_RETURN_LOOKBACK:
            continue
        base = closes[-(MINERVINI_RS_RETURN_LOOKBACK + 1)]
        if base <= 0:
            continue
        returns[sym] = (closes[-1] - base) / base
    if not returns:
        return {}
    return (pd.Series(returns).rank(pct=True) * 100.0).to_dict()


def _find_minervini_vcp_pivot(df: pd.DataFrame) -> dict | None:
    """Evaluated as of the LAST row of `df` (today, not itself included in
    the swing-point search): looks back up to MINERVINI_VCP_BASE_MAX_DAYS
    for a left-to-right tightening sequence of swing-high-to-swing-low
    legs, using a simple fractal (bar j is a swing high/low if it's the
    max/min High/Low within +/-MINERVINI_PIVOT_FRACTAL_WIDTH bars) -
    identical to the validated research workflow's own _find_vcp_pivot.
    Returns {"pivot_high", "final_leg_low"} if a valid tightening base
    ending near today is found, else None. Does NOT check today's close
    against the pivot - that's minervini_vcp_entry_signal's job."""
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    i = len(df) - 1
    lo = max(0, i - MINERVINI_VCP_BASE_MAX_DAYS)
    hi = i - MINERVINI_PIVOT_FRACTAL_WIDTH
    if hi - lo < MINERVINI_VCP_BASE_MIN_DAYS:
        return None

    swing_highs = []
    swing_lows = []
    for j in range(lo + MINERVINI_PIVOT_FRACTAL_WIDTH, hi):
        window_hi = highs[j - MINERVINI_PIVOT_FRACTAL_WIDTH: j + MINERVINI_PIVOT_FRACTAL_WIDTH + 1]
        window_lo = lows[j - MINERVINI_PIVOT_FRACTAL_WIDTH: j + MINERVINI_PIVOT_FRACTAL_WIDTH + 1]
        if highs[j] == np.max(window_hi):
            swing_highs.append((j, highs[j]))
        if lows[j] == np.min(window_lo):
            swing_lows.append((j, lows[j]))

    legs = []
    last_high = None
    for j, v in sorted(swing_highs + swing_lows, key=lambda t: t[0]):
        is_high = (j, v) in swing_highs
        if is_high:
            last_high = (j, v)
        elif last_high is not None:
            depth_pct = 100.0 * (last_high[1] - v) / last_high[1] if last_high[1] > 0 else 0.0
            legs.append({"high": last_high[1], "low": v, "depth_pct": depth_pct})
            last_high = None

    if len(legs) < 2:
        return None
    legs = legs[-6:]
    final_leg = legs[-1]
    first_leg = legs[0]
    if final_leg["depth_pct"] > MINERVINI_VCP_FINAL_LEG_MAX_PCT:
        return None
    if final_leg["depth_pct"] <= 0 or first_leg["depth_pct"] < MINERVINI_VCP_TIGHTEN_RATIO_MIN * final_leg["depth_pct"]:
        return None
    return {"pivot_high": final_leg["high"], "final_leg_low": final_leg["low"]}


def minervini_vcp_entry_signal(df: pd.DataFrame, rs_percentile: float | None = None) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a Minervini VCP
    entry: Trend Template gate + a valid tightening VCP base + today's
    close breaking above the base's pivot high on a volume surge. Identical
    rules/thresholds to the validated research workflow (tt_vcp variant,
    PFnet 0.90 on n=325 full-universe trades). Returns None if no signal
    fires, else {"entry_price", "stop_loss", "atr_at_entry"} for the caller
    to size and open a position with. `rs_percentile` is this symbol's
    cross-sectional RS percentile for today (see
    _compute_minervini_rs_percentiles); passing None skips the RS gate,
    matching the research workflow's own no-index-reference fallback."""
    if _minervini_trend_template_ok(df, rs_percentile) is not True:
        return None
    pivot = _find_minervini_vcp_pivot(df)
    if pivot is None:
        return None
    closes = df["Close"].to_numpy(dtype=float)
    volumes = df["Volume"].to_numpy(dtype=float)
    i = len(df) - 1
    if closes[i] <= pivot["pivot_high"]:
        return None
    vol_avg = pd.Series(volumes).rolling(MINERVINI_VOL_LOOKBACK).mean().shift(1).to_numpy()
    if np.isnan(vol_avg[i]) or vol_avg[i] <= 0 or volumes[i] < MINERVINI_VOL_SURGE_MULT * vol_avg[i]:
        return None
    atr = _swing_atr(df, n=MINERVINI_ATR_N)
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None
    stop_loss = pivot["final_leg_low"]
    if stop_loss >= closes[i]:
        return None
    return {"entry_price": closes[i], "stop_loss": stop_loss, "atr_at_entry": float(atr[i])}


def minervini_vcp_exit_reason(
    df: pd.DataFrame, entry_day: str, initial_stop: float, atr_at_entry: float, running_max_close: float,
) -> tuple:
    """Evaluates ONLY the last row of `df` (today) for a Minervini VCP
    exit, for a position already open: a chandelier trailing stop (running
    peak close minus MINERVINI_ATR_STOP_MULT x the ATR frozen AT ENTRY TIME,
    never recomputed daily) that only ever ratchets up, plus a
    MINERVINI_MAX_HOLD_DAYS timeout. `running_max_close` is the running
    peak close carried forward by the caller since entry (starts at
    entry_price); `entry_day` is the IST date (YYYY-MM-DD) the position was
    opened, day-counted the same way as gap_and_go_exit_reason. Returns
    (exit_reason_or_None, updated_running_max_close) since the chandelier
    state must travel explicitly between calls."""
    if len(df) == 0:
        return None, running_max_close
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    new_running_max = max(running_max_close, closes[i])
    trail_stop = new_running_max - MINERVINI_ATR_STOP_MULT * atr_at_entry
    current_stop = max(initial_stop, trail_stop)
    if closes[i] <= current_stop:
        return "trail_stop_hit", new_running_max
    held_days = int(np.sum(dates > entry_day))
    if held_days >= MINERVINI_MAX_HOLD_DAYS:
        return "max_hold_timeout", new_running_max
    return None, new_running_max


# ---- Livermore two-pullback confirmation filter (2026-09-30) --------------
#
# Explicit user instruction: build an entry-timing FILTER on top of
# minervini_vcp_entry_signal per docs/minervini_book_notes.txt's "THE
# LIVERMORE SYSTEM" note (~line 395): don't buy the first breakout above a
# downtrend line - wait for (a) the break, (b) a pullback (reaction low
# #1), (c) a rally, (d) a second pullback (reaction low #2), then buy only
# once price EXCEEDS THE HIGH OF THE SECOND RALLY. This is a strictly
# later, stricter bar than "stayed above the pivot" - it requires a
# genuine higher-high above a specific confirmed prior peak formed AFTER
# the second pullback, not merely price holding up.
#
# DISCLOSED ALGORITHM CHOICES (no single canonical definition exists for
# "reaction low"/"rally" off a bar-by-bar close/high/low series - matching
# this session's established style of disclosing a proxy explicitly, e.g.
# the Power Play short mirror's log-symmetric launch-threshold comment
# above):
#
# 1. "Reaction low" / "rally high" = a fractal swing point: bar j's Low
#    (High) is the min (max) within +/-LIVERMORE_VCP_FRACTAL_WIDTH bars -
#    the exact same swing-point convention _find_minervini_vcp_pivot
#    already uses for the base VCP's own contraction legs, just with its
#    own (tighter) width. A tighter width than the base pivot's
#    MINERVINI_PIVOT_FRACTAL_WIDTH=5 is used (3, not 5) because the
#    post-breakout reaction swings this filter is timing are typically
#    faster/shorter than the multi-week contraction legs that built the
#    base itself - a disclosed choice, not a derived one.
# 2. The "downtrend break" (step a) is reused exactly as instructed:
#    minervini_vcp_entry_signal's OWN pivot breakout condition (Trend
#    Template + a valid tightening base + a volume-surge close above the
#    pivot high), reconstructed bar-by-bar over the trailing
#    LIVERMORE_VCP_BREAKOUT_LOOKBACK_DAYS window by calling
#    minervini_vcp_entry_signal on each successively larger historical
#    window - i.e. "would the live scan have fired on that day" - not a
#    separate reimplementation. The MOST RECENT qualifying day in that
#    window is used as the anchor, so a stale, long-expired breakout many
#    weeks back never gets treated as still "in play".
#    One disclosed simplification: this historical reconstruction always
#    passes rs_percentile=None (skipping the RS gate) because a per-day
#    historical RS-percentile table isn't available inside a single-row-
#    evaluated entry_fn - the exact same "None skips the RS gate" fallback
#    minervini_vcp_entry_signal's own docstring already documents for the
#    no-index-reference case. TODAY's own RS gate is still fully enforced
#    below via _minervini_trend_template_ok(df, rs_percentile).
# 3. Sequence required, in strict chronological order, after the breakout
#    bar: swing LOW (reaction low #1) -> swing HIGH (rally #1) -> swing
#    LOW (reaction low #2) -> swing HIGH (the "second rally" high). Entry
#    fires the day price closes above that second rally's high. No rally
#    is required to already exist between the breakout and reaction low
#    #1 - the breakout itself is the move that gets pulled back from, per
#    the book's own step ordering.
# 4. FAILED RETEST INVALIDATES, IT DOES NOT JUST DELAY: if price closes
#    below the ORIGINAL base pivot's own stop level (final_leg_low, the
#    exact same level minervini_vcp_entry_signal itself would have used as
#    a stop) at ANY point between the breakout and today, the setup is
#    treated as a failed breakout, not a deeper-but-still-valid pullback -
#    reusing the base signal's own risk level rather than inventing a new
#    invalidation threshold for this filter. This deliberately does not
#    reset and re-search for a fresh breakout within the same call; a
#    fresh breakout day, if one occurs later, is picked up on its own by
#    the backward scan on a later date.
# 5. Stop-loss for a confirmed entry is reaction low #2 (the more recent,
#    tighter support the price has actually held above through the second
#    pullback) rather than the original base pivot's final_leg_low - a
#    later entry naturally earns a nearer stop, which is the trade-off the
#    book itself frames explicitly (worse average entry price, less
#    whipsaw).
LIVERMORE_VCP_FRACTAL_WIDTH = 3
LIVERMORE_VCP_BREAKOUT_LOOKBACK_DAYS = 60


def _find_fractal_swings(highs: np.ndarray, lows: np.ndarray, lo: int, hi: int, width: int) -> list:
    """Returns swing points in [lo+width, hi-width] as a list of
    (idx, kind, value) sorted by idx, where kind is "high" or "low" and a
    bar qualifies if its High (Low) is the max (min) within +/-width bars
    - the same fractal test _find_minervini_vcp_pivot uses, factored out
    so this filter can parameterize its own width."""
    swings = []
    for j in range(lo + width, hi - width + 1):
        window_hi = highs[j - width: j + width + 1]
        window_lo = lows[j - width: j + width + 1]
        if highs[j] == np.max(window_hi):
            swings.append((j, "high", highs[j]))
        if lows[j] == np.min(window_lo):
            swings.append((j, "low", lows[j]))
    return sorted(swings, key=lambda t: t[0])


def _find_livermore_breakout(df: pd.DataFrame) -> tuple:
    """Scans backward from yesterday over LIVERMORE_VCP_BREAKOUT_LOOKBACK_
    DAYS bars for the MOST RECENT day on which minervini_vcp_entry_signal
    (rs_percentile=None - see this section's header comment, point 2)
    would have fired using only the data available up to that day. Returns
    (breakout_idx, invalidate_level) for the first (most recent) match, or
    (None, None) if none is found in the window."""
    n = len(df)
    i = n - 1
    earliest = max(0, i - LIVERMORE_VCP_BREAKOUT_LOOKBACK_DAYS)
    for b in range(i - 1, earliest - 1, -1):
        sub = df.iloc[: b + 1]
        if len(sub) < 50:
            break
        sig = minervini_vcp_entry_signal(sub, rs_percentile=None)
        if sig is not None:
            return b, sig["stop_loss"]
    return None, None


def minervini_vcp_entry_signal_livermore_confirmed(df: pd.DataFrame, rs_percentile: float | None = None) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a Livermore two-
    pullback-confirmed Minervini VCP entry - see this section's header
    comment for the full disclosed algorithm and every design choice.
    Returns None if no confirmed entry fires today, else
    {"entry_price", "stop_loss", "atr_at_entry"} in the exact same shape
    minervini_vcp_entry_signal itself returns, for the caller to size and
    open a position with. Because this waits for a full two-pullback
    cycle to complete AFTER the base signal's own breakout day, it always
    fires strictly later (if at all) than minervini_vcp_entry_signal would
    have on the same breakout - the later, worse-but-safer entry price the
    book itself trades off against reduced whipsaw."""
    if _minervini_trend_template_ok(df, rs_percentile) is not True:
        return None
    n = len(df)
    i = n - 1
    breakout_idx, invalidate_level = _find_livermore_breakout(df)
    if breakout_idx is None:
        return None

    closes = df["Close"].to_numpy(dtype=float)
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)

    # Point 4: a failed retest invalidates the setup outright.
    if np.min(closes[breakout_idx + 1: i + 1]) < invalidate_level:
        return None

    width = LIVERMORE_VCP_FRACTAL_WIDTH
    swings = _find_fractal_swings(highs, lows, breakout_idx + 1, i, width)

    reaction_low_1 = rally_high_1 = reaction_low_2 = rally_high_2 = None
    stage = "seek_low_1"
    for idx, kind, value in swings:
        if stage == "seek_low_1" and kind == "low":
            reaction_low_1 = (idx, value)
            stage = "seek_high_1"
        elif stage == "seek_high_1" and kind == "high":
            rally_high_1 = (idx, value)
            stage = "seek_low_2"
        elif stage == "seek_low_2" and kind == "low":
            reaction_low_2 = (idx, value)
            stage = "seek_high_2"
        elif stage == "seek_high_2" and kind == "high":
            rally_high_2 = (idx, value)
            break

    if rally_high_2 is None:
        return None
    if closes[i] <= rally_high_2[1]:
        return None

    stop_loss = reaction_low_2[1]
    if stop_loss >= closes[i]:
        return None
    atr = _swing_atr(df, n=MINERVINI_ATR_N)
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None
    return {"entry_price": closes[i], "stop_loss": stop_loss, "atr_at_entry": float(atr[i])}


# ---- Minervini VCP short mirror (2026-09-29) -------------------------------
#
# Explicit user instruction ("Prep short mirror for others too") per
# CLAUDE.md's 2026-09-28 standing thumb rule: every strategy gets checked
# for both directions. Mirrors minervini_trend_template_ok/
# _find_minervini_vcp_pivot/minervini_vcp_entry_signal/
# minervini_vcp_exit_reason DIRECTION ONLY - every weight, lookback, and
# threshold constant is REUSED verbatim from the long side (same discipline
# _compute_universal_entry_score_short already established for the
# universal_score engine's own short mirror).
#
# Stage-4 decline is the long side's Stage-2 advance mirrored (see chapter
# 5's own 4-stage cycle - "avoid buying here" for stage 1/3, "go long
# stage 2, go short stage 4" per chapter 10's own explicit statement). The
# VCP base itself mirrors to a "VDP" (volatility DILATION... no - kept as
# VCP for naming consistency, see _find_minervini_vcp_pivot_short's own
# docstring) - a tightening sequence of RELIEF RALLIES (low-to-high legs)
# within a downtrend, shrinking leg over leg, ending in a breakDOWN below
# the pattern's own low rather than a breakout above a base's high.
#
# RS percentile mirrors to the BOTTOM of the cross-sectional distribution
# (weakest relative performers, not strongest) - _compute_minervini_rs_
# percentiles itself is direction-agnostic (a plain rank-pct), so it is
# reused unmodified; only the threshold comparison direction changes here.
MINERVINI_RS_PERCENTILE_MAX_SHORT = 30.0  # bottom 30th percentile - mirror of RS_PERCENTILE_MIN=70 (top)


def _minervini_trend_template_ok_short(df: pd.DataFrame, rs_percentile: float | None = None) -> bool | None:
    """Stage-4 mirror of _minervini_trend_template_ok - every SMA/lookback
    constant reused verbatim, comparisons and the 52-week-range check
    inverted. Returns None (not False) when there isn't enough history yet,
    identical convention to the long side."""
    closes = df["Close"].to_numpy(dtype=float)
    n = len(closes)
    if n < MINERVINI_SMA_200 + MINERVINI_SMA200_RISING_LOOKBACK:
        return None
    lows = df["Low"].to_numpy(dtype=float)
    highs = df["High"].to_numpy(dtype=float)
    sma50 = pd.Series(closes).rolling(MINERVINI_SMA_50).mean().to_numpy()
    sma150 = pd.Series(closes).rolling(MINERVINI_SMA_150).mean().to_numpy()
    sma200 = pd.Series(closes).rolling(MINERVINI_SMA_200).mean().to_numpy()
    roll_low_252 = pd.Series(lows).rolling(MINERVINI_FIFTY_TWO_WEEK_N).min().to_numpy()
    roll_high_252 = pd.Series(highs).rolling(MINERVINI_FIFTY_TWO_WEEK_N).max().to_numpy()
    i = n - 1
    if (
        np.isnan(sma200[i]) or np.isnan(sma200[i - MINERVINI_SMA200_RISING_LOOKBACK])
        or np.isnan(roll_low_252[i]) or np.isnan(roll_high_252[i])
        or np.isnan(sma50[i]) or np.isnan(sma150[i])
    ):
        return None
    ok = (
        closes[i] < sma150[i] and closes[i] < sma200[i]
        and sma150[i] < sma200[i]
        and sma200[i] < sma200[i - MINERVINI_SMA200_RISING_LOOKBACK]
        and sma50[i] < sma150[i] and sma50[i] < sma200[i]
        and closes[i] < sma50[i]
        and closes[i] <= 0.70 * roll_high_252[i]
        and closes[i] <= 1.25 * roll_low_252[i]
    )
    if rs_percentile is not None and not np.isnan(rs_percentile):
        ok = ok and rs_percentile <= MINERVINI_RS_PERCENTILE_MAX_SHORT
    return bool(ok)


def _find_minervini_vcp_pivot_short(df: pd.DataFrame) -> dict | None:
    """Short mirror of _find_minervini_vcp_pivot: same fractal swing-point
    search, but legs are (swing_low -> subsequent swing_high) relief
    rallies instead of (swing_high -> subsequent swing_low) pullbacks - a
    tightening sequence of shrinking bounce attempts within a downtrend.
    Returns {"pivot_low", "final_leg_high"} if a valid tightening base
    ending near today is found, else None. Does NOT check today's close
    against the pivot - that's minervini_vcp_entry_signal_short's job."""
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    i = len(df) - 1
    lo = max(0, i - MINERVINI_VCP_BASE_MAX_DAYS)
    hi = i - MINERVINI_PIVOT_FRACTAL_WIDTH
    if hi - lo < MINERVINI_VCP_BASE_MIN_DAYS:
        return None

    swing_highs = []
    swing_lows = []
    for j in range(lo + MINERVINI_PIVOT_FRACTAL_WIDTH, hi):
        window_hi = highs[j - MINERVINI_PIVOT_FRACTAL_WIDTH: j + MINERVINI_PIVOT_FRACTAL_WIDTH + 1]
        window_lo = lows[j - MINERVINI_PIVOT_FRACTAL_WIDTH: j + MINERVINI_PIVOT_FRACTAL_WIDTH + 1]
        if highs[j] == np.max(window_hi):
            swing_highs.append((j, highs[j]))
        if lows[j] == np.min(window_lo):
            swing_lows.append((j, lows[j]))

    legs = []
    last_low = None
    for j, v in sorted(swing_highs + swing_lows, key=lambda t: t[0]):
        is_low = (j, v) in swing_lows
        if is_low:
            last_low = (j, v)
        elif last_low is not None:
            bounce_pct = 100.0 * (v - last_low[1]) / last_low[1] if last_low[1] > 0 else 0.0
            legs.append({"low": last_low[1], "high": v, "bounce_pct": bounce_pct})
            last_low = None

    if len(legs) < 2:
        return None
    legs = legs[-6:]
    final_leg = legs[-1]
    first_leg = legs[0]
    if final_leg["bounce_pct"] > MINERVINI_VCP_FINAL_LEG_MAX_PCT:
        return None
    if final_leg["bounce_pct"] <= 0 or first_leg["bounce_pct"] < MINERVINI_VCP_TIGHTEN_RATIO_MIN * final_leg["bounce_pct"]:
        return None
    return {"pivot_low": final_leg["low"], "final_leg_high": final_leg["high"]}


def minervini_vcp_entry_signal_short(df: pd.DataFrame, rs_percentile: float | None = None) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a Minervini VCP
    short entry: Stage-4 Trend Template gate + a valid tightening
    relief-rally base + today's close breaking below the base's pivot low
    on a volume surge. Returns None if no signal fires, else
    {"entry_price", "stop_loss", "atr_at_entry"} for the caller to size
    and open a short position with."""
    if _minervini_trend_template_ok_short(df, rs_percentile) is not True:
        return None
    pivot = _find_minervini_vcp_pivot_short(df)
    if pivot is None:
        return None
    closes = df["Close"].to_numpy(dtype=float)
    volumes = df["Volume"].to_numpy(dtype=float)
    i = len(df) - 1
    if closes[i] >= pivot["pivot_low"]:
        return None
    vol_avg = pd.Series(volumes).rolling(MINERVINI_VOL_LOOKBACK).mean().shift(1).to_numpy()
    if np.isnan(vol_avg[i]) or vol_avg[i] <= 0 or volumes[i] < MINERVINI_VOL_SURGE_MULT * vol_avg[i]:
        return None
    atr = _swing_atr(df, n=MINERVINI_ATR_N)
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None
    stop_loss = pivot["final_leg_high"]
    if stop_loss <= closes[i]:
        return None
    return {"entry_price": closes[i], "stop_loss": stop_loss, "atr_at_entry": float(atr[i])}


def minervini_vcp_exit_reason_short(
    df: pd.DataFrame, entry_day: str, initial_stop: float, atr_at_entry: float, running_min_close: float,
) -> tuple:
    """Short mirror of minervini_vcp_exit_reason: a chandelier trailing
    stop (running TROUGH close plus MINERVINI_ATR_STOP_MULT x the ATR
    frozen at entry) that only ever ratchets DOWN, plus the same
    MINERVINI_MAX_HOLD_DAYS timeout. `running_min_close` is the running
    trough close carried forward by the caller since entry (starts at
    entry_price). Returns (exit_reason_or_None, updated_running_min_close)."""
    if len(df) == 0:
        return None, running_min_close
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    new_running_min = min(running_min_close, closes[i])
    trail_stop = new_running_min + MINERVINI_ATR_STOP_MULT * atr_at_entry
    current_stop = min(initial_stop, trail_stop)
    if closes[i] >= current_stop:
        return "trail_stop_hit", new_running_min
    held_days = int(np.sum(dates > entry_day))
    if held_days >= MINERVINI_MAX_HOLD_DAYS:
        return "max_hold_timeout", new_running_min
    return None, new_running_min


# 2R/3R move-to-breakeven exit variant (2026-09-29, explicit user
# instruction: build a move-to-breakeven refinement to compare against the
# existing minervini_vcp_exit_reason chandelier trail). Book-literal
# version, per docs/minervini_book_notes.txt's chapter 13 notes
# ("BREAKEVEN-STOP AT 2R/3R... once unrealized gain reaches 2x-3x the
# position's OWN initial risk (entry minus initial stop), move the stop to
# breakeven, full stop - not a trailing/chandelier mechanism. Simpler and
# more literal than the chandelier trail... WORTH TESTING as an alternative
# exit against the existing chandelier trail"): this is a straight
# substitute exit, NOT a hybrid with the chandelier trail - before the
# R-threshold is reached the stop is just the flat initial_stop (no ATR
# trailing at all in this variant); once reached, the stop becomes
# entry_price (breakeven) and stays there. One function, parameterized by
# `breakeven_r_multiple` - intended call sites are MINERVINI_BREAKEVEN_R_2
# (2R variant) and MINERVINI_BREAKEVEN_R_3 (3R variant), each exercised by
# its own validation replay workflow
# (minervini-vcp-breakeven-2r-validation-replay.yml,
# minervini-vcp-breakeven-3r-validation-replay.yml) run head-to-head
# against minervini_vcp_exit_reason's own chandelier-trail replay.
MINERVINI_BREAKEVEN_R_2 = 2.0
MINERVINI_BREAKEVEN_R_3 = 3.0


def minervini_vcp_exit_reason_breakeven(
    df: pd.DataFrame, entry_day: str, initial_stop: float, atr_at_entry: float,
    running_max_close: float, entry_price: float, breakeven_r_multiple: float,
) -> tuple:
    """Book-literal 2R/3R breakeven-stop (chapter 13) - a straight
    ALTERNATIVE to minervini_vcp_exit_reason's ATR chandelier trail, not a
    hybrid of the two. Stop is flat at `initial_stop` until the running
    peak close since entry has gained at least `breakeven_r_multiple` x the
    trade's initial risk (entry_price - initial_stop) over entry_price;
    once that happens the stop becomes `entry_price` (breakeven), full
    stop, and never reverts (checked against `running_max_close`, which
    only ever ratchets up, so once true it stays true for every later
    call). `atr_at_entry` is accepted only to keep the same call signature
    as minervini_vcp_exit_reason - this variant has no ATR/chandelier
    component at all, per the book's own "simpler and more literal"
    framing. Same MINERVINI_MAX_HOLD_DAYS timeout and
    (exit_reason_or_None, updated_running_max_close) return convention as
    minervini_vcp_exit_reason."""
    if len(df) == 0:
        return None, running_max_close
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    new_running_max = max(running_max_close, closes[i])
    initial_risk = entry_price - initial_stop
    breakeven_triggered = (
        initial_risk > 0 and (new_running_max - entry_price) >= breakeven_r_multiple * initial_risk
    )
    current_stop = entry_price if breakeven_triggered else initial_stop
    if closes[i] <= current_stop:
        return "stop_hit", new_running_max
    held_days = int(np.sum(dates > entry_day))
    if held_days >= MINERVINI_MAX_HOLD_DAYS:
        return "max_hold_timeout", new_running_max
    return None, new_running_max


# ---- Minervini VCP scale-in tranche sizing ---------------------------------
#
# 2026-09-29, explicit user task: a position-sizing REFINEMENT on top of
# minervini_vcp_entry_signal/minervini_vcp_exit_reason (both stay completely
# unmodified - this only changes how much of the intended full position is
# actually deployed and at what average price, echoing Minervini's own
# pyramiding idea: don't commit the whole size the instant the signal fires;
# add to a working position only once it confirms.
#
# CORRECTED 2026-09-30 against the actual book source
# (docs/minervini_book_notes.txt, CHAPTER 13 "RISK MANAGEMENT PART 2" reading
# notes, item 2 "SCALE-IN POSITION CONSTRUCTION"), quoted directly: "split
# entry into 2-3 tranches (e.g. 2%/2%/1% of capital) added ONLY as price
# confirms with an open profit - 'never trust the first price unless the
# position shows a profit' - stop set off the blended average cost, never
# averaging DOWN into a loss." The first version of this function hardcoded
# exactly 2 tranches and a 1.0x-ATR add-trigger that doesn't match the book's
# much lower bar ("any open profit", not a full ATR move) - both fixed below.
MINERVINI_SCALE_IN_TRANCHE_PCTS = (0.4, 0.4, 0.2)
# ^ book's own worked example is 2%/2%/1% of capital - three unequal,
# front-loaded tranches. Normalized to fractions of the intended full
# position (2/5, 2/5, 1/5) since this function deals in fractions, not
# absolute capital percentages; the caller applies these fractions to
# whatever rupee/qty sizing it already computed. len() is 3 here but the
# function itself makes no assumption about tranche count - any list of
# positive fractions summing to 1.0 works (e.g. a 2-tranche (0.5, 0.5) call
# is still supported, just no longer hardcoded as the only option).
MINERVINI_SCALE_IN_ADD_ATR_MULT = 0.25
# ^ THE ONE PLACE THIS FUNCTION HAD TO PICK A CONCRETE NUMBER FOR A FUZZY
# BOOK PHRASE, disclosed explicitly (same documentation style as Power
# Play's own mechanical-simplification comments above): the book says to add
# only once the position "shows a profit" / has "an open profit" relative to
# its current blended cost - it gives no numeric threshold. A literal
# `close > avg_cost` (i.e. add_trigger_atr_mult=0) would let a single tick of
# noise trigger an add with no real confirmation, which isn't in the spirit
# of "confirms". 0.25x the entry-time ATR is picked as a small buffer that
# filters out pure noise while staying well short of a real confirmation
# move (contrast: the ORIGINAL, WRONG value here was 1.0x ATR, a full
# confirmation-grade move the book never asked for) - not backtest-tuned,
# a starting value to validate like every other undocumented constant in
# this codebase (CLAUDE.md: never tune blind off one replay result).
MINERVINI_SCALE_IN_ADD_WITHIN_BARS = 10   # add-window: every tranche after the first must trigger within 10 bars of entry, else it never fills


def _scale_in_tranches(
    entry_price: float,
    atr_at_entry: float,
    stop_loss: float,
    closes_since_entry,
    tranche_pcts=MINERVINI_SCALE_IN_TRANCHE_PCTS,
    add_trigger_atr_mult: float = MINERVINI_SCALE_IN_ADD_ATR_MULT,
    add_within_bars: int = MINERVINI_SCALE_IN_ADD_WITHIN_BARS,
) -> dict:
    """Pure, DB/I-O-free sizing helper: decides how much of an intended full
    Minervini VCP position actually gets deployed, given that the position is
    split into N tranches (N = len(tranche_pcts), book's own guidance: 2-3)
    instead of committed in one shot at entry.

    - `tranche_pcts` is an ordered sequence of fractions of the intended full
      position, summing to 1.0 (e.g. the book's own 2%/2%/1% example
      normalizes to (0.4, 0.4, 0.2) - see MINERVINI_SCALE_IN_TRANCHE_PCTS).
      Any length >= 1 is accepted; the function makes no assumption of
      exactly 2.
    - Tranche 0 (`tranche_pcts[0]`) always fills immediately at `entry_price`
      - this is the existing, validated minervini_vcp_entry_signal fill,
      never skipped.
    - Each subsequent tranche i (1, 2, ...) fills ONLY once the close price
      first shows "an open profit" against the position's CURRENT BLENDED
      AVERAGE COST (not the original entry_price - this matters once a
      second tranche has already raised the average): i.e. once
      `close >= running_avg_cost + add_trigger_atr_mult * atr_at_entry`,
      within `add_within_bars` bars of entry (a single shared window for the
      whole scale-in, not reset per tranche). If a tranche's trigger is never
      reached before the window closes (or before the stop is hit), it and
      every tranche after it simply never fill - the final position is
      whatever prefix of tranches did fill (a smaller, right-sized position,
      not a failed trade).

    Because each tranche's trigger is `running_avg_cost + a positive buffer`,
    and running_avg_cost only ever starts at entry_price and rises (it is a
    weighted average that only mixes in strictly-higher fill prices), every
    fill is structurally guaranteed to sit above both the current average AND
    the original entry_price - i.e. this can never average DOWN into a loss,
    matching the book's explicit rule. The actual live/backtested protective
    stop for the open position must likewise be computed off this running
    blended average cost once more than one tranche has filled, not off
    tranche 0's entry_price alone - that recomputation is the CALLER's
    responsibility (this function only reports the average cost), and the
    validation-replay workflow that consumes this function does so.

    `closes_since_entry` is the close-price path for the bars AFTER entry
    (bar 1, 2, ... - it must NOT include the entry bar's own close, which is
    `entry_price` by definition). Only the first `add_within_bars` elements
    are considered; extra elements beyond the window are ignored.

    Precedence when both the stop and an add-trigger could apply (documented
    explicitly, since only close prices are available here - no intrabar
    high/low): bars are walked in order, and on each bar the STOP CHECK IS
    EVALUATED BEFORE THE TRIGGER CHECK. If a bar's close is at or below
    `stop_loss`, every tranche not yet filled is permanently disqualified
    from that bar onward (the position should already be getting exited by
    minervini_vcp_exit_reason's own stop logic at that point) even if that
    same bar's close would otherwise have also cleared the next tranche's
    trigger. This is the conservative choice: it never lets a later tranche
    get added into a position that has already (or simultaneously) hit its
    stop.

    Returns a dict:
      - "tranche_pcts": the input `tranche_pcts`, echoed back as a tuple.
      - "filled_fractions": list, same length as `tranche_pcts`, the fraction
        actually filled for each tranche slot (equal to tranche_pcts[i] if
        filled, else 0.0).
      - "fill_prices": list, same length, the close price each tranche filled
        at (tranche_pcts[0] is always `entry_price`), or None for a slot that
        never filled.
      - "fill_bars": list, same length, the 1-based bar index (into
        `closes_since_entry`) each tranche filled on (0 for tranche 0, since
        it fills at entry itself), or None for a slot that never filled.
      - "n_tranches_filled": how many tranche slots actually filled (always
        >= 1).
      - "total_filled_pct": sum of `filled_fractions` (the fraction of the
        intended full position actually deployed overall).
      - "avg_entry_price": the size-weighted average entry price across
        whichever tranche(s) actually filled (always well-defined since
        tranche 0 always fills) - this IS the "blended average cost" the
        book says the live stop must be set off of.

    Callers combine this with the existing risk-based intended-quantity
    calculation (risk_amount_inr / stop_dist, capped by usable_capital_inr) -
    this function only decides what FRACTION of that intended quantity is
    actually deployed, and at what blended price; it never computes rupee
    amounts or share counts itself.
    """
    tranche_pcts = tuple(tranche_pcts)
    if len(tranche_pcts) == 0:
        raise ValueError("tranche_pcts must have at least one element")
    if any(p <= 0.0 for p in tranche_pcts):
        raise ValueError("tranche_pcts elements must all be positive")
    if not np.isclose(sum(tranche_pcts), 1.0, atol=1e-6):
        raise ValueError(f"tranche_pcts must sum to 1.0, got {sum(tranche_pcts)}")

    n = len(tranche_pcts)
    filled_fractions = [tranche_pcts[0]] + [0.0] * (n - 1)
    fill_prices = [entry_price] + [None] * (n - 1)
    fill_bars = [0] + [None] * (n - 1)
    avg_cost = entry_price
    filled_weight = tranche_pcts[0]

    next_idx = 1
    if next_idx < n:
        path = np.asarray(closes_since_entry, dtype=float)[:add_within_bars]
        for bar_idx, close in enumerate(path, start=1):
            if next_idx >= n:
                break
            if close <= stop_loss:
                # Stop already hit (or simultaneously hit) - every remaining
                # tranche is disqualified from here on; the position is
                # being exited.
                break
            trigger_price = avg_cost + add_trigger_atr_mult * atr_at_entry
            if close >= trigger_price:
                pct = tranche_pcts[next_idx]
                filled_fractions[next_idx] = pct
                fill_prices[next_idx] = float(close)
                fill_bars[next_idx] = bar_idx
                avg_cost = (avg_cost * filled_weight + float(close) * pct) / (filled_weight + pct)
                filled_weight += pct
                next_idx += 1

    return {
        "tranche_pcts": tranche_pcts,
        "filled_fractions": filled_fractions,
        "fill_prices": fill_prices,
        "fill_bars": fill_bars,
        "n_tranches_filled": sum(1 for f in filled_fractions if f > 0.0),
        "total_filled_pct": sum(filled_fractions),
        "avg_entry_price": avg_cost,
    }


# ---- Primary Base (Minervini, chapter 11) ----------------------------------
#
# 2026-10-01, continuing docs/minervini_book_notes.txt's CHAPTER 11 backlog
# item ("PRIMARY BASE") after its own IPO-recency feasibility precondition
# cleared (minervini-primary-base-feasibility-check.yml run 36670094369,
# 2026-09-30): known decades-old large caps (RELIANCE/TCS/INFY/HDFCBANK/ITC/
# LT/SBIN) show genuine 23-30+ years of history on this data source while a
# meaningful minority of the full NSE universe shows genuinely short
# histories (17.4% under 1y, including literal brand-new listings within
# days of that check) - short available history plausibly discriminates real
# recent listings here, not a Yahoo data-availability artifact, clearing the
# book note's own precondition for building this on that proxy.
#
# Buy a recently-listed stock (proxy: short available price history) as it
# breaks out to a new ALL-TIME HIGH (since the first available bar) from its
# FIRST buyable base - deliberately distinct from minervini_vcp_entry_signal,
# which requires 150+/200+ days of history to even evaluate the Trend
# Template and is built for STAGE-2-CONTINUATION bases, not a brand-new
# stock's very first base. No Trend Template/RS gate here (mirrors Power
# Play's own precedent - a young stock can't pass a 200-day-SMA-based gate
# by construction).
#
# DISCLOSED ALGORITHM CHOICES (no single canonical "base" definition exists
# off a bar close/high/low series, matching this session's established style
# of disclosing a proxy explicitly):
#   - "Recently listed" proxy = total available history (len(df) as of
#     today) <= MINERVINI_PRIMARY_BASE_MAX_HISTORY_DAYS.
#   - The "prior high" the base corrects FROM is the all-time high of the
#     entire available series up to the base's own start - i.e. the highest
#     point the stock has ever traded at, exactly matching "new ALL-TIME
#     HIGH" being the breakout condition (there is no other high to correct
#     from for a stock this young).
#   - Base duration = trading days from that all-time high to today. Base
#     depth = % drawdown from that all-time high to the base's own low
#     (intrabar Low, same convention minervini_vcp's own pivot-leg search
#     uses for its swing lows).
#   - Two-tier depth cap, mirroring the book's own "25-35% for 3-5 week
#     bases, up to ~50% for longer ones" guidance: short bases (<=
#     MINERVINI_PRIMARY_BASE_SHORT_BASE_MAX_DAYS) must not exceed
#     MINERVINI_PRIMARY_BASE_SHORT_MAX_DEPTH_PCT depth; longer bases (up to
#     MINERVINI_PRIMARY_BASE_MAX_BASE_DAYS) may run up to
#     MINERVINI_PRIMARY_BASE_LONG_MAX_DEPTH_PCT.
#   - Entry: today's close breaks above that all-time high (pivot) on a
#     volume increase - reuses the exact same MINERVINI_VOL_LOOKBACK/
#     MINERVINI_VOL_SURGE_MULT convention minervini_vcp_entry_signal uses,
#     for consistency across the book's strategies.
#   - Exit: reuses minervini_vcp_exit_reason UNCHANGED (the same chandelier
#     trail + max-hold already proven the best-performing exit tried on this
#     book's entries so far - PFnet 2.043 on the Livermore-confirmed entry,
#     strictly better than the 2R/3R breakeven variant, see CLAUDE.md's own
#     2026-09-30 sweep-discipline note) - this keeps Primary Base an
#     entry-only, one-axis test against an already-proven exit, not a new
#     exit variant of its own.
MINERVINI_PRIMARY_BASE_MAX_HISTORY_DAYS = 756  # ~3 trading years - the feasibility run's own <3y bucket covered 31.7% of the full universe, a large enough "recently listed" pool to test
MINERVINI_PRIMARY_BASE_MIN_BASE_DAYS = 15  # 3 weeks, same floor as MINERVINI_VCP_BASE_MIN_DAYS
MINERVINI_PRIMARY_BASE_MAX_BASE_DAYS = 252  # ~1 year, per the book's own stated ceiling for a deeper reset
MINERVINI_PRIMARY_BASE_SHORT_BASE_MAX_DAYS = 25  # ~5 weeks, the book's own "short base" ceiling
MINERVINI_PRIMARY_BASE_SHORT_MAX_DEPTH_PCT = 35.0
MINERVINI_PRIMARY_BASE_LONG_MAX_DEPTH_PCT = 50.0


def primary_base_entry_signal(df: pd.DataFrame) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a Minervini Primary
    Base entry: a short overall available history (the IPO-recency proxy),
    a valid-depth/duration correction since the stock's own all-time high,
    and today's close breaking out to a NEW all-time high on a volume surge.
    Returns None if no signal fires, else {"entry_price", "stop_loss",
    "atr_at_entry"} - same shape as minervini_vcp_entry_signal, so callers
    (including minervini_vcp_exit_reason, reused unchanged for exits) need
    no special-casing."""
    n = len(df)
    if n < MINERVINI_PRIMARY_BASE_MIN_BASE_DAYS + 5 or n > MINERVINI_PRIMARY_BASE_MAX_HISTORY_DAYS:
        return None

    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    closes = df["Close"].to_numpy(dtype=float)
    volumes = df["Volume"].to_numpy(dtype=float)
    i = n - 1

    # Searches the WHOLE available history (not a MAX_BASE_DAYS-windowed
    # slice) for the all-time high - a windowed search would silently miss a
    # true ATH older than the window and substitute a local max from inside
    # the base itself, which could then pass the base_days check even though
    # the base is really older than MINERVINI_PRIMARY_BASE_MAX_BASE_DAYS.
    # Bounded and cheap regardless, since len(df) is already capped by the
    # MINERVINI_PRIMARY_BASE_MAX_HISTORY_DAYS guard above.
    pre_base = highs[:i]
    if len(pre_base) < MINERVINI_PRIMARY_BASE_MIN_BASE_DAYS:
        return None
    ath_idx = int(np.argmax(pre_base))
    ath = pre_base[ath_idx]
    if ath <= 0:
        return None

    base_days = i - ath_idx
    if base_days < MINERVINI_PRIMARY_BASE_MIN_BASE_DAYS or base_days > MINERVINI_PRIMARY_BASE_MAX_BASE_DAYS:
        return None

    base_window_lows = lows[ath_idx + 1: i + 1]
    if len(base_window_lows) == 0:
        return None
    base_low = float(np.min(base_window_lows))
    depth_pct = 100.0 * (ath - base_low) / ath
    max_depth = (
        MINERVINI_PRIMARY_BASE_SHORT_MAX_DEPTH_PCT
        if base_days <= MINERVINI_PRIMARY_BASE_SHORT_BASE_MAX_DAYS
        else MINERVINI_PRIMARY_BASE_LONG_MAX_DEPTH_PCT
    )
    if depth_pct <= 0 or depth_pct > max_depth:
        return None

    if closes[i] <= ath:
        return None  # not yet a genuine new-all-time-high breakout

    vol_avg = pd.Series(volumes).rolling(MINERVINI_VOL_LOOKBACK).mean().shift(1).to_numpy()
    if np.isnan(vol_avg[i]) or vol_avg[i] <= 0 or volumes[i] < MINERVINI_VOL_SURGE_MULT * vol_avg[i]:
        return None

    atr = _swing_atr(df, n=MINERVINI_ATR_N)
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None

    stop_loss = base_low
    if stop_loss >= closes[i]:
        return None
    return {"entry_price": closes[i], "stop_loss": stop_loss, "atr_at_entry": float(atr[i])}


# ---- Power Play / High Tight Flag (Minervini, chapter 10) -----------------
#
# 2026-09-29, explicit user instruction ("Build Power Play first") after a
# second reading pass over docs/Trade Like a Stock Market Wizard (2013).pdf
# turned up this as the most distinct genuinely-new strategy candidate - see
# docs/minervini_book_notes.txt's own CHAPTER 10 (REST) section for the full
# reading notes. Unlike tt_vcp, Power Play is explicitly NOT gated by the
# Trend Template or fundamentals (the book's own words: "the only situation
# I will enter with a dearth of fundamentals") - a momentum/velocity setup:
# an explosive prior move, a tight sideways flag, then a breakout.
#
# Three numeric criteria from the book, all required:
#   1. An explosive move: price up >=100% in under 8 weeks (~40 trading
#      days) on high volume, after a period of relative dormancy.
#   2. A "flag": sideways for 3-6 weeks (some as short as 12 calendar
#      days - ~8-9 trading days), correcting no more than 20-25% from the
#      peak.
#   3. Final tightening: the last leg corrects no more than 10%, OR the
#      flag shows VCP-style leg-by-leg contraction (this implementation
#      uses the simpler, literal <=10% final-leg reading - the book
#      presents the two as alternatives, not both required).
#
# Mechanical simplifications documented honestly (the book's own prose is
# not a numeric spec):
#   - "Relative dormancy" before the launch is not separately verified -
#     requiring the launch's own low-to-high move to be >=100% within a
#     bounded window is the only dormancy-adjacent check.
#   - The launch's own "huge volume" is not independently checked against
#     volume data (unlike the breakout day, which IS volume-gated) - only
#     the price move is verified mechanically.
#   - The flagpole's peak must fall within the last POWER_PLAY_
#     PEAK_PROXIMITY_DAYS bars of the launch window (a sanity constraint
#     so a stale, unrelated earlier high 40 days back can't satisfy the
#     launch criterion on its own).
#
# Exit mirrors minervini_vcp_exit_reason's own chandelier-trail + max-hold
# convention (same architecture, Power-Play-specific constants) - this
# session's established pattern for swing/daily-bar strategies, not a
# rule stated explicitly in the book for this particular setup.
POWER_PLAY_LAUNCH_MAX_DAYS = 40       # ~8 weeks of trading days
POWER_PLAY_LAUNCH_MIN_GAIN_PCT = 100.0
POWER_PLAY_PEAK_PROXIMITY_DAYS = 10   # flagpole peak must sit near the launch window's own end
POWER_PLAY_CONSOL_MIN_DAYS = 8        # ~12 calendar days
POWER_PLAY_CONSOL_MAX_DAYS = 30       # ~6 weeks of trading days
POWER_PLAY_CONSOL_MAX_DEPTH_PCT = 25.0
POWER_PLAY_FINAL_LEG_DAYS = 5
POWER_PLAY_FINAL_LEG_MAX_PCT = 10.0
POWER_PLAY_VOL_LOOKBACK = 20
POWER_PLAY_VOL_SURGE_MULT = 1.5
POWER_PLAY_ATR_N = 14
POWER_PLAY_ATR_STOP_MULT = 2.0        # matches MINERVINI_ATR_STOP_MULT's chandelier convention
POWER_PLAY_MAX_HOLD_DAYS = 120        # ~6 months - the book's own power-play examples
# run anywhere from 66 to 400+ days; not backtest-tuned, a middle estimate
# pending the validation replay (per CLAUDE.md, never tune blind off one
# result - this is a starting value to validate, not a swept optimum).


def _find_power_play_setup(df: pd.DataFrame) -> dict | None:
    """Evaluated as of the LAST row of `df` (today, itself excluded - it's
    the candidate breakout bar, checked separately by
    power_play_entry_signal). Searches consolidation lengths from
    POWER_PLAY_CONSOL_MAX_DAYS down to POWER_PLAY_CONSOL_MIN_DAYS (prefers
    a longer, more mature flag) for one immediately preceded by a
    >=POWER_PLAY_LAUNCH_MIN_GAIN_PCT launch move within the
    POWER_PLAY_LAUNCH_MAX_DAYS window before it. Returns
    {"consol_high", "consol_low"} for the first valid (launch, flag) pair
    found, else None."""
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    i = len(df) - 1
    for consol_len in range(POWER_PLAY_CONSOL_MAX_DAYS, POWER_PLAY_CONSOL_MIN_DAYS - 1, -1):
        consol_start = i - consol_len
        if consol_start < POWER_PLAY_PEAK_PROXIMITY_DAYS:
            continue  # not enough bars left for even a minimal launch window
        consol_highs = highs[consol_start:i]
        consol_lows = lows[consol_start:i]
        if len(consol_highs) == 0:
            continue
        consol_high = float(np.max(consol_highs))
        consol_low = float(np.min(consol_lows))
        if consol_high <= 0:
            continue
        depth_pct = 100.0 * (consol_high - consol_low) / consol_high
        if depth_pct > POWER_PLAY_CONSOL_MAX_DEPTH_PCT:
            continue

        final_leg_start = max(consol_start, i - POWER_PLAY_FINAL_LEG_DAYS)
        final_highs = highs[final_leg_start:i]
        final_lows = lows[final_leg_start:i]
        if len(final_highs) == 0:
            continue
        final_leg_pct = 100.0 * (float(np.max(final_highs)) - float(np.min(final_lows))) / consol_high
        if final_leg_pct > POWER_PLAY_FINAL_LEG_MAX_PCT:
            continue

        launch_start = max(0, consol_start - POWER_PLAY_LAUNCH_MAX_DAYS)
        launch_highs = highs[launch_start:consol_start]
        launch_lows = lows[launch_start:consol_start]
        if len(launch_highs) < POWER_PLAY_PEAK_PROXIMITY_DAYS:
            continue
        peak_rel = int(np.argmax(launch_highs))
        if peak_rel < len(launch_highs) - POWER_PLAY_PEAK_PROXIMITY_DAYS:
            continue  # the peak isn't near where the flag begins - not a clean flagpole
        launch_high = float(launch_highs[peak_rel])
        if launch_high > consol_high * 1.02:
            continue  # a real flag stays below its own pole's top
        low_before_peak = float(np.min(launch_lows[: peak_rel + 1]))
        if low_before_peak <= 0:
            continue
        gain_pct = 100.0 * (launch_high - low_before_peak) / low_before_peak
        if gain_pct < POWER_PLAY_LAUNCH_MIN_GAIN_PCT:
            continue

        return {"consol_high": consol_high, "consol_low": consol_low}
    return None


def power_play_entry_signal(df: pd.DataFrame) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a Power Play / high
    tight flag entry: a valid _find_power_play_setup flag + today's close
    breaking above the flag's high on a volume surge. Returns None if no
    signal fires, else {"entry_price", "stop_loss", "atr_at_entry"} for the
    caller to size and open a position with - same return shape as
    minervini_vcp_entry_signal/gap_and_go_entry_signal."""
    setup = _find_power_play_setup(df)
    if setup is None:
        return None
    closes = df["Close"].to_numpy(dtype=float)
    volumes = df["Volume"].to_numpy(dtype=float)
    i = len(df) - 1
    if closes[i] <= setup["consol_high"]:
        return None
    vol_avg = pd.Series(volumes).rolling(POWER_PLAY_VOL_LOOKBACK).mean().shift(1).to_numpy()
    if np.isnan(vol_avg[i]) or vol_avg[i] <= 0 or volumes[i] < POWER_PLAY_VOL_SURGE_MULT * vol_avg[i]:
        return None
    atr = _swing_atr(df, n=POWER_PLAY_ATR_N)
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None
    stop_loss = setup["consol_low"]
    if stop_loss >= closes[i]:
        return None
    return {"entry_price": closes[i], "stop_loss": stop_loss, "atr_at_entry": float(atr[i])}


def power_play_exit_reason(
    df: pd.DataFrame, entry_day: str, initial_stop: float, atr_at_entry: float, running_max_close: float,
) -> tuple:
    """Evaluates ONLY the last row of `df` (today) for a Power Play exit -
    identical chandelier-trail + max-hold mechanics to
    minervini_vcp_exit_reason, with Power-Play-specific constants (see this
    section's own header comment for why). Returns
    (exit_reason_or_None, updated_running_max_close)."""
    if len(df) == 0:
        return None, running_max_close
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    new_running_max = max(running_max_close, closes[i])
    trail_stop = new_running_max - POWER_PLAY_ATR_STOP_MULT * atr_at_entry
    current_stop = max(initial_stop, trail_stop)
    if closes[i] <= current_stop:
        return "trail_stop_hit", new_running_max
    held_days = int(np.sum(dates > entry_day))
    if held_days >= POWER_PLAY_MAX_HOLD_DAYS:
        return "max_hold_timeout", new_running_max
    return None, new_running_max


# ---- Order Block (delta-weighted) + Volume Profile / POC bounce (LONG, 1d) ----
#
# 2026-10-05, explicit user instruction ("make viable strategies in the live
# wiring", then "Port and real money now" via AskUserQuestion, after being
# shown that these exist only as research code inside
# order-block-delta-research.yml / volume-profile-poc-liquidity-research.yml
# and that their margins over PFNET_LIVE_FLOOR are thin: 1.062 / 1.025).
# Faithful ports of those workflows' own signal/exit logic - constants and
# arithmetic copied verbatim, never re-derived. DISCLOSED GAP, tracked as
# backlog B-30: the PFnet numbers in strategy_registry.py come from the
# research-embedded implementations, NOT from a replay calling these
# main.py functions - a full-universe validation replay calling THESE
# functions is still owed (CLAUDE.md "verify the replay driver calls the
# changed main.py code"), and the user chose real money first knowingly.
ORDER_BLOCK_IMPULSE_RETURN_PCT = 3.0
ORDER_BLOCK_IMPULSE_VOL_MULT = 1.5
ORDER_BLOCK_LOOKBACK_DAYS = 10
ORDER_BLOCK_RETEST_MAX_DAYS = 20
ORDER_BLOCK_ATR_STOP_MULT = 2.0
ORDER_BLOCK_ATR_TRAIL_MULT = 6.0  # B-26 2026-10-07: 6.0x sweep PFnet 1.105 vs 3.0x 1.081
ORDER_BLOCK_MAX_HOLD_DAYS = 30
ORDER_BLOCK_MIN_LOOKBACK_DAYS = 60

VP_LOOKBACK_BARS = 60
VP_NUM_BINS = 24
VP_POC_TOLERANCE_PCT = 1.0
VP_APPROACH_LOOKBACK_BARS = 5
VP_ATR_TRAIL_MULT = 6.0  # B-26 2026-10-07: 6.0x sweep PFnet 1.076 vs 3.0x 1.049
VP_MAX_HOLD_DAYS = 30
VP_MIN_LOOKBACK_DAYS = 90


def _candle_delta(o: float, h: float, l: float, c: float, v: float) -> float:
    if h <= l:
        return 0.0
    return v * (c - o) / (h - l)


def order_block_entry_signal(df: pd.DataFrame) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a delta-confirmed
    order-block retest long entry (port of order-block-delta-research.yml's
    order_block_entry_signal + its entry sizing inputs). Returns None, else
    {"entry_price", "stop_loss", "atr_at_entry"} - same shape as
    power_play_entry_signal."""
    n = len(df)
    i = n - 1
    if i < ORDER_BLOCK_MIN_LOOKBACK_DAYS + 20 - 1:
        return None
    opens = df["Open"].to_numpy(dtype=float)
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    closes = df["Close"].to_numpy(dtype=float)
    vols = df["Volume"].to_numpy(dtype=float)
    for impulse_idx in range(i - 1, max(0, i - ORDER_BLOCK_RETEST_MAX_DAYS) - 1, -1):
        if impulse_idx < 1:
            break
        day_return_pct = 100 * (closes[impulse_idx] - closes[impulse_idx - 1]) / closes[impulse_idx - 1]
        if day_return_pct < ORDER_BLOCK_IMPULSE_RETURN_PCT:
            continue
        vol_window = vols[max(0, impulse_idx - 20):impulse_idx]
        if len(vol_window) == 0:
            continue
        avg_vol20 = float(np.mean(vol_window))
        if avg_vol20 <= 0 or vols[impulse_idx] < ORDER_BLOCK_IMPULSE_VOL_MULT * avg_vol20:
            continue
        ob_idx = None
        for j in range(impulse_idx - 1, max(0, impulse_idx - ORDER_BLOCK_LOOKBACK_DAYS) - 1, -1):
            if closes[j] < opens[j]:
                ob_idx = j
                break
        if ob_idx is None:
            continue
        ob_delta = _candle_delta(opens[ob_idx], highs[ob_idx], lows[ob_idx], closes[ob_idx], vols[ob_idx])
        if ob_delta >= 0:
            continue
        ob_low, ob_high = float(lows[ob_idx]), float(highs[ob_idx])
        if ob_high <= ob_low:
            continue
        if np.any(closes[ob_idx + 1:i] < ob_low):
            continue  # zone already invalidated before today
        if not (lows[i] <= ob_high and closes[i] > ob_low):
            continue  # today isn't a retest-and-hold
        today_delta = _candle_delta(opens[i], highs[i], lows[i], closes[i], vols[i])
        if today_delta <= 0:
            continue  # no buy pressure confirmation on the retest day
        entry_price = float(closes[i])
        atr_at_entry = _compute_atr_value(df, 14)
        if atr_at_entry is None or atr_at_entry <= 0:
            return None
        stop_loss = min(ob_low, entry_price - ORDER_BLOCK_ATR_STOP_MULT * atr_at_entry)
        if entry_price - stop_loss <= 0:
            return None
        return {"entry_price": entry_price, "stop_loss": stop_loss, "atr_at_entry": float(atr_at_entry)}
    return None


def order_block_exit_reason(
    df: pd.DataFrame, entry_day: str, initial_stop: float, atr_at_entry: float, running_max_close: float,
) -> tuple:
    """Chandelier trail (ORDER_BLOCK_ATR_TRAIL_MULT x ATR frozen at entry) +
    ORDER_BLOCK_MAX_HOLD_DAYS timeout - port of the research workflow's
    _chandelier_exit. Returns (exit_reason_or_None, updated_running_max_close)."""
    if len(df) == 0:
        return None, running_max_close
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    new_running_max = max(running_max_close, float(closes[i]))
    trail_stop = new_running_max - ORDER_BLOCK_ATR_TRAIL_MULT * atr_at_entry
    current_stop = max(initial_stop, trail_stop)
    if closes[i] <= current_stop:
        return "trail_stop_hit", new_running_max
    held_days = int(np.sum(dates > entry_day))
    if held_days >= ORDER_BLOCK_MAX_HOLD_DAYS:
        return "max_hold_timeout", new_running_max
    return None, new_running_max


# ---------------------------------------------------------------------------
# brk20_min_rr (backlog B-798): 20-bar close breakout + minimum reward:risk
# room filter + ATR stop ALWAYS attached. Port of the Douglas/Elder trade-
# management research simulator (scripts/douglas_trade_mgmt_research.py,
# base "brk20", option min_rr; run 38174269343, registry family
# trademgmt_exit__brk20_min_rr__<dir>__1d__atr*_rr*__v1). NOT wired into any
# live scan and NOT in strategy_registry.py's live gate: these are pure
# functions for the main.py-function replay (.github/workflows/
# brk20-min-rr-main-replay.yml). Research conventions kept verbatim:
#   * signal on bar s's CLOSE; fill at bar s+1's OPEN (`entry_price` arg);
#   * ATR = Wilder EWM (alpha 1/14, adjust=False) at the signal bar - NOT
#     main._atr_series' rolling mean, which would change the numbers;
#   * stop = entry -/+ atr_mult x ATR(s); min_rr filter: room to the prior
#     60-bar extreme (excluding bar s) must be >= min_rr x risk;
#   * rule exit: close < EMA13 and EMA13 falling (short: same on the
#     reciprocal price, the research's flip() mirror); max hold 30 bars;
#   * stop is gap-aware (bar open beyond the stop fills at the open).
# Only the last BRK20_CALC_WINDOW bars are used (EWM tails are < 1e-6 by then).
# ---------------------------------------------------------------------------
BRK20_LOOKBACK_BARS = 20
BRK20_ROOM_LOOKBACK_BARS = 60
BRK20_EMA_SPAN = 13
BRK20_ATR_PERIOD = 14
BRK20_MAX_HOLD_BARS = 30
BRK20_CALC_WINDOW = 400
BRK20_DEFAULT_ATR_MULT = 3.0
BRK20_DEFAULT_MIN_RR = 4.0
BRK20_BE_BUFFER_R = 0.05  # breakeven stop = entry +/- 0.05 R (research's be_ratchet offset)


def _brk20_atr_series(highs, lows, closes, period: int = BRK20_ATR_PERIOD) -> np.ndarray:
    """Wilder EWM ATR (alpha=1/period, adjust=False), the research's er.atr."""
    prev = np.concatenate(([np.nan], closes[:-1]))
    tr = np.fmax.reduce([highs - lows, np.abs(highs - prev), np.abs(lows - prev)])
    return pd.Series(tr).ewm(alpha=1.0 / period, adjust=False).mean().to_numpy()


def brk20_stop_price(entry_price: float, atr: float, atr_mult: float, direction: str = "long") -> float:
    """The initial ATR stop, always attached (no trade without a stop)."""
    d = 1.0 if direction == "long" else -1.0
    return float(entry_price) - d * float(atr_mult) * float(atr)


def brk20_min_rr_entry_signal(
    df: pd.DataFrame, direction: str = "long", atr_mult: float = BRK20_DEFAULT_ATR_MULT,
    min_rr: float = BRK20_DEFAULT_MIN_RR, entry_price: float | None = None,
) -> dict | None:
    """Evaluates ONLY the last row of `df` (the signal bar). direction 'long' = close above the prior
    20-bar high; 'short' = close below the prior 20-bar low (the exact mirror of the long rule).
    `entry_price` = the fill price (next bar's open in the replay); default = signal close.
    Returns {entry_price, stop_loss, atr_at_entry, risk, room, room_target, rr, signal_close} or None."""
    if direction not in ("long", "short") or atr_mult <= 0 or min_rr < 0:
        return None
    d = df.iloc[-BRK20_CALC_WINDOW:]
    n = len(d)
    if n < BRK20_ROOM_LOOKBACK_BARS + 2:
        return None
    h = d["High"].to_numpy(dtype=float)
    l = d["Low"].to_numpy(dtype=float)
    c = d["Close"].to_numpy(dtype=float)
    i = n - 1
    if direction == "long":
        if not c[i] > np.max(h[i - BRK20_LOOKBACK_BARS:i]):
            return None
        extreme60 = float(np.max(h[i - BRK20_ROOM_LOOKBACK_BARS:i]))
    else:
        if not c[i] < np.min(l[i - BRK20_LOOKBACK_BARS:i]):
            return None
        extreme60 = float(np.min(l[i - BRK20_ROOM_LOOKBACK_BARS:i]))
    atr = float(_brk20_atr_series(h, l, c)[i])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(c[i]) if entry_price is None else float(entry_price)
    if not px > 0:
        return None
    sgn = 1.0 if direction == "long" else -1.0
    stop = brk20_stop_price(px, atr, atr_mult, direction)
    risk = sgn * (px - stop)
    if not risk > 0 or (direction == "long" and not stop > 0):
        return None
    room = sgn * (extreme60 - px)
    if room < min_rr * risk:
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": float(risk),
            "room": float(room), "room_target": extreme60, "rr": float(room / risk),
            "signal_close": float(c[i]), "direction": direction}


def brk20_min_rr_exit_reason(
    df: pd.DataFrame, entry_day: str, entry_price: float, initial_stop: float,
    direction: str = "long", be_r: float | None = None, max_hold_bars: int = BRK20_MAX_HOLD_BARS,
) -> tuple:
    """Evaluates ONLY the last row of `df` as bar j, for a position whose FILL bar is the first row with
    Date >= entry_day. Returns (reason, exit_price) or (None, None).
    Order inside a bar (research order): stop (gap-aware) -> rule exit (close vs EMA13, never on the fill
    bar) -> max-hold timeout. `be_r` (None = no ratchet): once the best excursion through the PREVIOUS
    bars reached be_r x R the stop is raised to entry +/- 0.05R (reason then 'protected_stop')."""
    if len(df) == 0:
        return None, None
    sgn = 1.0 if direction == "long" else -1.0
    dates = df["Date"].astype(str).to_numpy()
    starts = np.flatnonzero(dates >= str(entry_day))
    if len(starts) == 0:
        return None, None
    start = int(starts[0])
    j = len(df) - 1
    if j < start:
        return None, None
    risk = abs(float(entry_price) - float(initial_stop))
    if risk <= 0:
        return None, None
    o = float(df["Open"].iloc[j])
    stop, protected = float(initial_stop), False
    if be_r is not None and j > start:
        seg = df.iloc[start:j]
        ext = float(seg["High"].max()) if direction == "long" else float(seg["Low"].min())
        if sgn * (ext - entry_price) / risk >= be_r:
            be_stop = entry_price + sgn * BRK20_BE_BUFFER_R * risk
            stop = max(stop, be_stop) if direction == "long" else min(stop, be_stop)
            protected = True
    hi, lo, cl = float(df["High"].iloc[j]), float(df["Low"].iloc[j]), float(df["Close"].iloc[j])
    if (direction == "long" and lo <= stop) or (direction == "short" and hi >= stop):
        if j > start:
            fill = min(o, stop) if direction == "long" else max(o, stop)
        else:
            fill = stop
        return ("protected_stop" if protected else "stop_loss"), float(fill)
    if j > start:
        w = df.iloc[-BRK20_CALC_WINDOW:]
        cc = w["Close"].to_numpy(dtype=float)
        s = cc if direction == "long" else 1.0 / cc
        e = pd.Series(s).ewm(span=BRK20_EMA_SPAN, adjust=False).mean().to_numpy()
        if len(e) >= 2 and s[-1] < e[-1] and e[-1] < e[-2]:
            return "rule_exit", cl
    if j == start + int(max_hold_bars):
        return "max_hold_timeout", cl
    return None, None


# ---- brk20_min_rr LONG 1d atr4_rr4 live swing wiring (B-798, user 2026-10-12: "wire if it fulfils
# viable definition") ----------------------------------------------------------------------------
# Only the plain LONG 1d cell (atr_mult 4, min_rr 4, no breakeven ratchet) is wired. Pooled registry tag
# below (PFnet 2.659, n=218, run 38185670883); IS 3.43 / OOS 1.72 (run 38247769897). Shorts are NOT wired:
# the swing engine is long-only and has no BUY-protective-SL short path (backlog row for a short-swing
# engine). Stop = entry - 4 x ATR(Wilder) ALWAYS attached as the real resting SL (no trade without SL);
# exit = brk20_min_rr_exit_reason (EMA13 rule exit / stop / 30-bar max hold).
BRK20_SWING_ATR_MULT = 4.0
BRK20_SWING_MIN_RR = 4.0
BRK20_SWING_TAG = "brk20_min_rr__main_replay__long__1d__atr4_rr4__v1"


def _brk20_swing_exit_adapter(df, entry_day, initial_stop, atr_at_entry, running_max_close):
    """Same signature as the other swing exit fns. The research fills at the bar AFTER the signal bar,
    so the fill bar is the first bar dated after entry_day (the live entry is recorded on the signal day).
    Every completed bar since is replayed in order, so a skipped scan day cannot hide a stop / the exact
    30-bar timeout. Entry price is recovered from the frozen stop (stop = entry - 4 x ATR, both stored)."""
    if len(df) == 0:
        return None, running_max_close
    d = df
    if "Date" not in d.columns:
        d = d.assign(Date=pd.Series(pd.DatetimeIndex(d.index).strftime("%Y-%m-%d"), index=d.index))
    new_running_max = max(float(running_max_close or 0.0), float(d["Close"].iloc[-1]))
    entry_price = float(initial_stop) + BRK20_SWING_ATR_MULT * float(atr_at_entry or 0.0)
    fill_day = (pd.Timestamp(str(entry_day)[:10]) + pd.Timedelta(days=1)).strftime("%Y-%m-%d")
    dates = d["Date"].astype(str).str[:10].to_numpy()
    starts = np.flatnonzero(dates >= fill_day)
    if len(starts) == 0 or float(atr_at_entry or 0.0) <= 0:
        return None, new_running_max
    for k in range(int(starts[0]), len(d)):
        reason, _px = brk20_min_rr_exit_reason(d.iloc[:k + 1], fill_day, entry_price, float(initial_stop), "long")
        if reason:
            return reason, new_running_max
    return None, new_running_max


# ---- island reversal LONG 1d atr1d5 live swing wiring (B-877; research: scripts/island_validation.py) ----
# Detector ported verbatim from scripts/island_validation.island_entries (min_gap_atr=0 for the three wired
# filters): gap DOWN at bar i (High[i] < Low[i-1]), then within ISLAND_WITHIN_BARS bars the FIRST bar j with a
# gap UP (Low[j] > High[j-1]) whose Low also clears the gap-down bar's High (Low[j] > High[i]). The signal is
# bar j's close. Filters (liquidity_mask): px20 = Close >= 20; turn1cr = 20-bar rolling MEDIAN of Close*Volume
# >= 1e7. Stop = entry - 1.5 x ATR(Wilder 14) of the signal bar, ALWAYS attached (no trade without SL). Exit =
# the research simulate() order: gap-aware stop -> rule exit (Close < EMA13 and EMA13 falling, never on the
# fill bar) -> 30-bar max hold, i.e. exactly brk20_min_rr_exit_reason's long path (reused, not re-invented).
# The research fills at the NEXT bar's open with no no-chase level (long_lvl is NaN), so there is no entry-time
# chase gate to port; the live fill is the signal close (same convention as the brk20 wiring).
# One tag per variant, never merged. The live tag IS the strict-FIFO research/registry name (nonovl__v2, as brk20 does);
# each variant's own OOS tag (segoos__v2: 1.194 / 1.182 / 1.319) also clears the floor and is the held-out check.
ISLAND_WITHIN_BARS = 8
ISLAND_ATR_MULT = 1.5
ISLAND_MIN_PRICE = 20.0
ISLAND_MIN_TURNOVER = 1e7
ISLAND_TURNOVER_WINDOW = 20
ISLAND_CALC_WINDOW = 400
ISLAND_NONE_TAG = "reversal__island_none__long__1d__atr1d5_within8__nonovl__v2"
ISLAND_PX20_TAG = "reversal__island_px20__long__1d__atr1d5_within8__nonovl__v2"
ISLAND_TURN1CR_TAG = "reversal__island_turn1cr__long__1d__atr1d5_within8__nonovl__v2"
# Entry check order: most specific filter first (turn1cr OOS 1.319, px20 1.182, none 1.194). none is a superset of
# px20, so the none tag is only opened for signals that fail both filters (illiquid / sub-Rs20): see backlog B-877.
ISLAND_SWING_TAGS = (ISLAND_TURN1CR_TAG, ISLAND_PX20_TAG, ISLAND_NONE_TAG)
_ISLAND_FILTER_OF_TAG = {ISLAND_NONE_TAG: "none", ISLAND_PX20_TAG: "px20", ISLAND_TURN1CR_TAG: "turn1cr"}
# ---- WIRE-NEXT batch (port queue + B-877, docs/backtest_data/wiring_final_binary_1844.csv) ----
# Same detector/stop/exit as above; extra tags are the registry's other evaluation cells of the SAME live rule
# (v1 overlapping-fill cells, segis/segoos IS/OOS splits) plus the gap05 filter (both gaps >= 0.5 x ATR[Wilder],
# research island_entries(min_gap_atr=0.5)). Each tag keeps its own registry name/metrics; they are NEVER merged.
# A symbol holds one position, so for an identical live rule the first tag in ISLAND_ALL_TAGS order takes it; the
# later same-rule tags are registered, mapped, exit-covered and scan-counted but cannot take a second position.
_ISLAND_GAP05 = "reversal__island_gap05__long__1d__atr1d5_within8__"
_ISLAND_V1_TAGS = tuple(f"reversal__{v}__long__1d__atr1d5_within8__v1"
                        for v in ("island", "island_none", "island_px20", "island_turn1cr"))
ISLAND_GAP05_TAGS = (_ISLAND_GAP05 + "nonovl__v2", _ISLAND_GAP05 + "segis__v2")
_ISLAND_SEG_TAGS = tuple(f"reversal__island_{f}__long__1d__atr1d5_within8__{seg}__v2"
                         for f in ("none", "px20", "turn1cr") for seg in ("segis", "segoos"))
ISLAND_WIRENEXT_TAGS = _ISLAND_V1_TAGS + ISLAND_GAP05_TAGS + _ISLAND_SEG_TAGS
ISLAND_ALL_TAGS = ISLAND_GAP05_TAGS + ISLAND_SWING_TAGS + _ISLAND_V1_TAGS + _ISLAND_SEG_TAGS
for _t in _ISLAND_V1_TAGS + _ISLAND_SEG_TAGS:
    _f = _t.split("__")[1].replace("island_", "")
    _ISLAND_FILTER_OF_TAG[_t] = "none" if _f == "island" else _f
for _t in ISLAND_GAP05_TAGS:
    _ISLAND_FILTER_OF_TAG[_t] = "gap05"
ISLAND_GAP05_MIN_ATR = 0.5


def island_bottom_signal_on_last_bar(df: pd.DataFrame, within: int = ISLAND_WITHIN_BARS,
                                     min_gap_atr: float = 0.0) -> bool:
    """True iff the LAST row is an island-bottom completion bar (research island_entries(min_gap_atr)[-1])."""
    d = df.iloc[-ISLAND_CALC_WINDOW:]
    n = len(d)
    if n < 20:
        return False
    h = d["High"].to_numpy(dtype=float)
    l = d["Low"].to_numpy(dtype=float)
    a = (_brk20_atr_series(h, l, d["Close"].to_numpy(dtype=float)) if min_gap_atr else None)
    j = n - 1
    for i in range(max(1, j - within), j):
        if not h[i] < l[i - 1]:
            continue
        if min_gap_atr and not (l[i - 1] - h[i] >= min_gap_atr * a[i - 1] > 0):
            continue
        for jj in range(i + 1, min(n, i + within + 1)):
            if l[jj] > h[jj - 1] and l[jj] > h[i]:
                if min_gap_atr and not (l[jj] - h[i] >= min_gap_atr * a[jj - 1] > 0):
                    break  # research: a first reclaim failing the 0.5 ATR gap consumes this gap-down
                if jj == j:
                    return True
                break  # this gap-down's FIRST reclaim was an earlier bar
    return False


def island_filters_passed(df: pd.DataFrame) -> dict:
    """{'none': True, 'px20': bool, 'turn1cr': bool} evaluated on the last bar (research liquidity_mask)."""
    d = df.iloc[-ISLAND_CALC_WINDOW:]
    px = float(d["Close"].iloc[-1])
    turn = (d["Close"] * d["Volume"]).rolling(ISLAND_TURNOVER_WINDOW).median().iloc[-1]
    turn = 0.0 if not np.isfinite(turn) else float(turn)
    return {"none": True, "px20": px >= ISLAND_MIN_PRICE, "turn1cr": turn >= ISLAND_MIN_TURNOVER}


def island_swing_entry_signal(df: pd.DataFrame, tag: str, entry_price: float | None = None) -> dict | None:
    """Evaluates ONLY the last row. Returns {entry_price, stop_loss, atr_at_entry, ...} or None.
    The stop is always set: entry - ISLAND_ATR_MULT x ATR(Wilder). `tag` selects the filter variant."""
    flt = _ISLAND_FILTER_OF_TAG.get(tag)
    if flt is None or len(df) < 20:
        return None
    # gap05 is the unfiltered ("none") liquidity variant plus the 0.5 ATR gap rule; island_filters_passed has no 'gap05' key,
    # so a plain .get(flt) was always None and the gap05 tags could never fire (replay run 38309068649 n=0, B-887).
    if not island_filters_passed(df).get("none" if flt == "gap05" else flt):
        return None
    if not island_bottom_signal_on_last_bar(df, min_gap_atr=(ISLAND_GAP05_MIN_ATR if flt == "gap05" else 0.0)):
        return None
    d = df.iloc[-ISLAND_CALC_WINDOW:]
    atr = float(_brk20_atr_series(d["High"].to_numpy(dtype=float), d["Low"].to_numpy(dtype=float),
                                  d["Close"].to_numpy(dtype=float))[-1])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(d["Close"].iloc[-1]) if entry_price is None else float(entry_price)
    if not px > 0:
        return None
    stop = brk20_stop_price(px, atr, ISLAND_ATR_MULT, "long")
    if not (0 < stop < px):
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": px - stop,
            "signal_close": float(d["Close"].iloc[-1]), "direction": "long", "filter": flt}


def _island_swing_exit_adapter(df, entry_day, initial_stop, atr_at_entry, running_max_close):
    """Swing exit fn signature. Replays every completed bar after entry_day through the research exit order
    (brk20_min_rr_exit_reason, long: stop -> EMA13 rule exit -> 30-bar max hold), so a skipped scan day cannot hide
    a stop or the exact timeout. Entry price recovered from the frozen stop: entry = stop + 1.5 x ATR."""
    if len(df) == 0:
        return None, running_max_close
    d = df
    if "Date" not in d.columns:
        d = d.assign(Date=pd.Series(pd.DatetimeIndex(d.index).strftime("%Y-%m-%d"), index=d.index))
    new_running_max = max(float(running_max_close or 0.0), float(d["Close"].iloc[-1]))
    if float(atr_at_entry or 0.0) <= 0:
        return None, new_running_max
    entry_price = float(initial_stop) + ISLAND_ATR_MULT * float(atr_at_entry)
    fill_day = (pd.Timestamp(str(entry_day)[:10]) + pd.Timedelta(days=1)).strftime("%Y-%m-%d")
    dates = d["Date"].astype(str).str[:10].to_numpy()
    starts = np.flatnonzero(dates >= fill_day)
    if len(starts) == 0:
        return None, new_running_max
    for k in range(int(starts[0]), len(d)):
        reason, _px = brk20_min_rr_exit_reason(d.iloc[:k + 1], fill_day, entry_price, float(initial_stop), "long")
        if reason:
            return "island_" + reason, new_running_max
    return None, new_running_max


# ---- island reversal SHORT mirror (1d atr1d5): PORT ONLY, NOT WIRED into any scan or entry chain ----
# Exact mirror of the long detector (research: island_entries on the reciprocal-price flip, so the short side's
# gap logic is the geometric inverse): gap UP at bar i (Low[i] > High[i-1]), then within ISLAND_WITHIN_BARS bars the
# FIRST bar j with a gap DOWN (High[j] < Low[j-1]) whose High also stays below the gap-up bar's Low
# (High[j] < Low[i]). Signal = bar j's close. Stop = entry + 1.5 x ATR(Wilder 14), price-space, ALWAYS attached.
# Exit = brk20_min_rr_exit_reason(direction="short"): gap-aware stop above -> rule exit (reciprocal-close EMA13
# falling, i.e. Close > EMA13-equivalent) -> 30-bar max hold. Registry (research-only, all FAIL the floor):
# reversal__island_{none,px20,turn1cr,gap05}__short__1d__atr1d5_within8__nonovl__v2 (PFnet 0.636-0.713).
ISLAND_SHORT_NONE_TAG = "reversal__island_none__short__1d__atr1d5_within8__nonovl__v2"
ISLAND_SHORT_PX20_TAG = "reversal__island_px20__short__1d__atr1d5_within8__nonovl__v2"
ISLAND_SHORT_TURN1CR_TAG = "reversal__island_turn1cr__short__1d__atr1d5_within8__nonovl__v2"
ISLAND_SHORT_GAP05_TAG = "reversal__island_gap05__short__1d__atr1d5_within8__nonovl__v2"
ISLAND_SHORT_TAGS = (ISLAND_SHORT_TURN1CR_TAG, ISLAND_SHORT_PX20_TAG, ISLAND_SHORT_NONE_TAG, ISLAND_SHORT_GAP05_TAG)
_ISLAND_SHORT_FILTER_OF_TAG = {ISLAND_SHORT_NONE_TAG: "none", ISLAND_SHORT_PX20_TAG: "px20",
                               ISLAND_SHORT_TURN1CR_TAG: "turn1cr", ISLAND_SHORT_GAP05_TAG: "gap05"}


def island_top_signal_on_last_bar(df: pd.DataFrame, within: int = ISLAND_WITHIN_BARS,
                                  min_gap_atr: float = 0.0) -> bool:
    """True iff the LAST row is an island-top completion bar (research island_entries on the flipped frame)."""
    d = df.iloc[-ISLAND_CALC_WINDOW:]
    n = len(d)
    if n < 20:
        return False
    h = d["High"].to_numpy(dtype=float)
    l = d["Low"].to_numpy(dtype=float)
    # research computes the gap-size ATR on the reciprocal-price frame (High'=1/Low, Low'=1/High)
    a = (_brk20_atr_series(1.0 / l, 1.0 / h, 1.0 / d["Close"].to_numpy(dtype=float)) if min_gap_atr else None)
    hf, lf = 1.0 / l, 1.0 / h  # flipped highs / lows, so gap thresholds match research exactly
    j = n - 1
    for i in range(max(1, j - within), j):
        if not l[i] > h[i - 1]:
            continue
        if min_gap_atr and not (lf[i - 1] - hf[i] >= min_gap_atr * a[i - 1] > 0):
            continue
        for jj in range(i + 1, min(n, i + within + 1)):
            if h[jj] < l[jj - 1] and h[jj] < l[i]:
                if min_gap_atr and not (lf[jj] - hf[i] >= min_gap_atr * a[jj - 1] > 0):
                    break
                if jj == j:
                    return True
                break
    return False


def island_short_entry_signal(df: pd.DataFrame, tag: str, entry_price: float | None = None) -> dict | None:
    """Short mirror of island_swing_entry_signal. Evaluates ONLY the last row. Stop = entry + 1.5 x ATR, always set."""
    flt = _ISLAND_SHORT_FILTER_OF_TAG.get(tag)
    if flt is None or len(df) < 20:
        return None
    if not island_filters_passed(df).get("none" if flt == "gap05" else flt):
        return None
    if not island_top_signal_on_last_bar(df, min_gap_atr=(ISLAND_GAP05_MIN_ATR if flt == "gap05" else 0.0)):
        return None
    d = df.iloc[-ISLAND_CALC_WINDOW:]
    atr = float(_brk20_atr_series(d["High"].to_numpy(dtype=float), d["Low"].to_numpy(dtype=float),
                                  d["Close"].to_numpy(dtype=float))[-1])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(d["Close"].iloc[-1]) if entry_price is None else float(entry_price)
    if not px > 0:
        return None
    stop = brk20_stop_price(px, atr, ISLAND_ATR_MULT, "short")
    if not stop > px:
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": stop - px,
            "signal_close": float(d["Close"].iloc[-1]), "direction": "short", "filter": flt}


def _island_short_exit_adapter(df, entry_day, initial_stop, atr_at_entry, running_min_close):
    """Short mirror of _island_swing_exit_adapter (same signature; the 5th arg is the running MIN close).
    Replays every completed bar after entry_day through brk20_min_rr_exit_reason(direction='short').
    Entry price recovered from the frozen stop: entry = stop - 1.5 x ATR."""
    if len(df) == 0:
        return None, running_min_close
    d = df
    if "Date" not in d.columns:
        d = d.assign(Date=pd.Series(pd.DatetimeIndex(d.index).strftime("%Y-%m-%d"), index=d.index))
    last = float(d["Close"].iloc[-1])
    new_running_min = last if not float(running_min_close or 0.0) else min(float(running_min_close), last)
    if float(atr_at_entry or 0.0) <= 0:
        return None, new_running_min
    entry_price = float(initial_stop) - ISLAND_ATR_MULT * float(atr_at_entry)
    fill_day = (pd.Timestamp(str(entry_day)[:10]) + pd.Timedelta(days=1)).strftime("%Y-%m-%d")
    dates = d["Date"].astype(str).str[:10].to_numpy()
    starts = np.flatnonzero(dates >= fill_day)
    if len(starts) == 0:
        return None, new_running_min
    for k in range(int(starts[0]), len(d)):
        reason, _px = brk20_min_rr_exit_reason(d.iloc[:k + 1], fill_day, entry_price, float(initial_stop), "short")
        if reason:
            return "island_short_" + reason, new_running_min
    return None, new_running_min


def _island_swing_try_entry(conn, symbol, df, capital, risk_pct, today, fx) -> bool:
    """Opens at most one island position for `symbol` (first tag in ISLAND_SWING_TAGS that fires). The paper row,
    trades row and real mirror (swing engine: SL placed with entry, PFnet gate inside) follow the brk20 pattern."""
    for tag in ISLAND_ALL_TAGS:
        _record_strategy_scan(tag)
        sig = island_swing_entry_signal(df, tag)
        if not sig:
            continue
        entry_price, stop_loss = sig["entry_price"], sig["stop_loss"]
        qty = _swing_position_size(conn, capital, risk_pct, entry_price, stop_loss)
        if qty <= 0:
            return False
        conn.execute(
            "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, "
            "initial_stop_loss, gap_low, qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (symbol, tag, today, entry_price, stop_loss, None, qty, time.time(), fx, sig["atr_at_entry"], entry_price),
        )
        apply_paper_trade(conn, symbol, "buy", qty, entry_price)
        conn.execute(
            "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
            "VALUES (?, ?, 'buy', ?, ?, ?, ?, ?)",
            (time.time(), symbol, qty, entry_price, fx, SWING_STRATEGY_TAG,
             json.dumps({"entry_reason": tag, "stop_loss": stop_loss, "atr_at_entry": sig["atr_at_entry"]})),
        )
        conn.commit()
        print(f"[SWING] entry {symbol} ({tag}) qty={qty} @ {entry_price:.2f} stop={stop_loss:.2f}")
        try:
            _maybe_place_real_swing_entry(conn, symbol, qty, entry_price, stop_loss, tag)
        except Exception as e:
            print(f"[REAL SWING] entry mirror failed for {symbol} (non-fatal, paper entry already recorded): {e}")
        return True
    return False


# ---- swingminrr minervini_vcp LONG 1d atr1d5 live swing wiring (WIRE-NEXT port queue; research:
# scripts/swing_min_rr_research.py cells base/gate) -----------------------------------------------------------
# Entry = the REAL minervini_vcp_entry_signal (trend template + VCP pivot breakout + volume surge) on the last bar,
# but with the research stop: entry - 1.5 x ATR(Wilder 14), ALWAYS attached (the VCP final-leg-low stop is NOT used
# for these tags). `gate` cells additionally require room to the prior 60-bar HIGH (excluding the signal bar) >=
# rr x risk. No profit target, no EMA rule exit: research sim() exits = gap-aware stop, else 30-bar max hold.
# The research fills at the next open; live fills at the signal close (same convention as brk20/island).
SWINGMINRR_ATR_MULT = 1.5
SWINGMINRR_ROOM_BARS = 60
SWINGMINRR_MAX_HOLD_BARS = 30
SWINGMINRR_GATE4_TAG = "swingminrr__minervini_vcp_gate__long__1d__atr1d5_rr4__v1"
SWINGMINRR_GATE3_TAG = "swingminrr__minervini_vcp_gate__long__1d__atr1d5_rr3__v1"
SWINGMINRR_GATE2_TAG = "swingminrr__minervini_vcp_gate__long__1d__atr1d5_rr2__v1"
SWINGMINRR_BASE_TAG = "swingminrr__minervini_vcp_base__long__1d__atr1d5__v1"
# Check order: highest PFnet / most specific gate first, ungated base last (a gated hit never also takes base).
SWINGMINRR_TAGS = (SWINGMINRR_GATE4_TAG, SWINGMINRR_GATE3_TAG, SWINGMINRR_GATE2_TAG, SWINGMINRR_BASE_TAG)
_SWINGMINRR_GATE_RR = {SWINGMINRR_GATE4_TAG: 4.0, SWINGMINRR_GATE3_TAG: 3.0, SWINGMINRR_GATE2_TAG: 2.0,
                       SWINGMINRR_BASE_TAG: 0.0}


def swingminrr_vcp_entry_signal(df: pd.DataFrame, tag: str, rs_percentile: float | None = None) -> dict | None:
    """Last-row evaluation. Stop always set: entry - SWINGMINRR_ATR_MULT x ATR. None if tag unknown/no signal."""
    min_rr = _SWINGMINRR_GATE_RR.get(tag)
    if min_rr is None or len(df) < SWINGMINRR_ROOM_BARS + 2:
        return None
    if not minervini_vcp_entry_signal(df, rs_percentile=rs_percentile):
        return None
    d = df.iloc[-ISLAND_CALC_WINDOW:]
    h = d["High"].to_numpy(dtype=float)
    atr = float(_brk20_atr_series(h, d["Low"].to_numpy(dtype=float), d["Close"].to_numpy(dtype=float))[-1])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(d["Close"].iloc[-1])
    stop = brk20_stop_price(px, atr, SWINGMINRR_ATR_MULT, "long")
    if not (0 < stop < px):
        return None
    risk = px - stop
    room = float(np.max(h[-SWINGMINRR_ROOM_BARS - 1:-1])) - px
    if min_rr and room < min_rr * risk:
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": risk, "room": room,
            "direction": "long", "min_rr": min_rr}


def _swingminrr_exit_adapter(df, entry_day, initial_stop, atr_at_entry, running_max_close):
    """Swing exit fn signature. Replays every completed bar after entry_day: gap-aware stop, else the
    SWINGMINRR_MAX_HOLD_BARS-th bar after the fill bar closes out (research sim order: stop before timeout)."""
    if len(df) == 0:
        return None, running_max_close
    d = df
    if "Date" not in d.columns:
        d = d.assign(Date=pd.Series(pd.DatetimeIndex(d.index).strftime("%Y-%m-%d"), index=d.index))
    new_running_max = max(float(running_max_close or 0.0), float(d["Close"].iloc[-1]))
    fill_day = (pd.Timestamp(str(entry_day)[:10]) + pd.Timedelta(days=1)).strftime("%Y-%m-%d")
    dates = d["Date"].astype(str).str[:10].to_numpy()
    starts = np.flatnonzero(dates >= fill_day)
    if len(starts) == 0:
        return None, new_running_max
    start = int(starts[0])
    lo = d["Low"].to_numpy(dtype=float)
    for k in range(start, len(d)):
        if lo[k] <= float(initial_stop):
            return "swingminrr_stop_loss", new_running_max
        if k == start + SWINGMINRR_MAX_HOLD_BARS:
            return "swingminrr_max_hold_timeout", new_running_max
    return None, new_running_max


def _swingminrr_try_entry(conn, symbol, df, capital, risk_pct, today, fx, rs_percentile=None) -> bool:
    """Opens at most one swingminrr position (first viable tag in SWINGMINRR_TAGS that fires). A tag whose registry
    PFnet is below the floor is skipped (falls through to the existing VCP path). Paper row + trades row + real
    mirror (SL placed with the entry; PFnet gate inside) follow the island/brk20 pattern."""
    for tag in SWINGMINRR_TAGS:
        if tag == SWINGMINRR_BASE_TAG and _is_strategy_wired("minervini_vcp_be3r"):
            continue  # the existing, viable be3r path keeps ungated VCP signals; base only replaces it if be3r is closed
        _record_strategy_scan(tag)
        sig = swingminrr_vcp_entry_signal(df, tag, rs_percentile=rs_percentile)
        if not sig:
            continue
        if not _is_strategy_wired(tag):
            _record_blocked_trigger(tag)  # fired, gate closed now: no position opened
            continue
        entry_price, stop_loss = sig["entry_price"], sig["stop_loss"]
        qty = _swing_position_size(conn, capital, risk_pct, entry_price, stop_loss)
        if qty <= 0:
            return False
        conn.execute(
            "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, "
            "initial_stop_loss, gap_low, qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (symbol, tag, today, entry_price, stop_loss, None, qty, time.time(), fx, sig["atr_at_entry"], entry_price),
        )
        apply_paper_trade(conn, symbol, "buy", qty, entry_price)
        conn.execute(
            "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
            "VALUES (?, ?, 'buy', ?, ?, ?, ?, ?)",
            (time.time(), symbol, qty, entry_price, fx, SWING_STRATEGY_TAG,
             json.dumps({"entry_reason": tag, "stop_loss": stop_loss, "atr_at_entry": sig["atr_at_entry"]})),
        )
        conn.commit()
        print(f"[SWING] entry {symbol} ({tag}) qty={qty} @ {entry_price:.2f} stop={stop_loss:.2f}")
        try:
            _maybe_place_real_swing_entry(conn, symbol, qty, entry_price, stop_loss, tag)
        except Exception as e:
            print(f"[REAL SWING] entry mirror failed for {symbol} (non-fatal, paper entry already recorded): {e}")
        return True
    return False


# ---- gaps fade LONG 1d live swing port (Elder gap-fade, research: scripts/elder_macd_dirgap_research.py v_gap_fade,
# registry gaps__{exhaust,common}_fade__long__1d__atr3_nb5__v1). Signal = a DOWN gap (High < prior Low) on bar i that is
# on high volume (exhaust: >= 1.5x mean of the 5 prior bars) or low volume (common), then NBARS bars with no new low below
# that gap bar's low; fires on bar i+NBARS. Stop = entry - 3 x ATR(Wilder 14) ALWAYS attached (no trade without SL).
# Exit order = research simulate(): gap-aware stop -> rule exit (High < prior High, never on the fill bar) -> 30-bar max hold.
# Research fills at the next open; live fills at the signal close (same convention as brk20/island/swingminrr). Long only
# (a short mirror needs the NRML overnight confirmation, SHORT_SWING_OVERNIGHT_PRODUCT_CONFIRMED stays False). Both tags are
# REPLAY_OWED (real-money gate closed) until a replay that calls these functions is on file.
GAPFADE_NBARS = 5
GAPFADE_VMULT = 1.5
GAPFADE_VOL_BARS = 5
GAPFADE_ATR_MULT = 3.0
GAPFADE_MAX_HOLD_BARS = 30
GAPFADE_EXHAUST_TAG = "gaps__exhaust_fade__long__1d__atr3_nb5__v1"
GAPFADE_COMMON_TAG = "gaps__common_fade__long__1d__atr3_nb5__v1"
GAPFADE_TAGS = (GAPFADE_EXHAUST_TAG, GAPFADE_COMMON_TAG)  # highest PFnet first


def gapfade_long_entry_signal(df: pd.DataFrame, tag: str, entry_price: float | None = None) -> dict | None:
    """Last-bar evaluation of the long gap-fade rule for `tag`. None if no signal / unknown tag."""
    if tag not in GAPFADE_TAGS:
        return None
    d = df.iloc[-BRK20_CALC_WINDOW:]
    n = len(d)
    j = n - 1
    i = j - GAPFADE_NBARS
    if i < GAPFADE_VOL_BARS + 1:
        return None
    h = d["High"].to_numpy(dtype=float)
    l = d["Low"].to_numpy(dtype=float)
    c = d["Close"].to_numpy(dtype=float)
    v = d["Volume"].to_numpy(dtype=float)
    if not h[i] < l[i - 1]:  # down gap on bar i
        return None
    vavg = float(np.mean(v[i - GAPFADE_VOL_BARS:i]))
    high_vol = bool(v[i] >= GAPFADE_VMULT * vavg)
    if high_vol != (tag == GAPFADE_EXHAUST_TAG):
        return None
    if not float(np.min(l[i + 1:j + 1])) >= l[i]:  # no new low since the gap bar
        return None
    atr = float(_brk20_atr_series(h, l, c)[j])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(c[j]) if entry_price is None else float(entry_price)
    stop = brk20_stop_price(px, atr, GAPFADE_ATR_MULT, "long")
    if not (0 < stop < px):
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": px - stop, "direction": "long"}


def _gapfade_exit_adapter(df, entry_day, initial_stop, atr_at_entry, running_max_close):
    """Swing exit fn signature. Replays every completed bar from the fill bar (first bar after entry_day)."""
    if len(df) == 0:
        return None, running_max_close
    d = df
    if "Date" not in d.columns:
        d = d.assign(Date=pd.Series(pd.DatetimeIndex(d.index).strftime("%Y-%m-%d"), index=d.index))
    new_running_max = max(float(running_max_close or 0.0), float(d["Close"].iloc[-1]))
    fill_day = (pd.Timestamp(str(entry_day)[:10]) + pd.Timedelta(days=1)).strftime("%Y-%m-%d")
    dates = d["Date"].astype(str).str[:10].to_numpy()
    starts = np.flatnonzero(dates >= fill_day)
    if len(starts) == 0:
        return None, new_running_max
    start = int(starts[0])
    hi = d["High"].to_numpy(dtype=float)
    lo = d["Low"].to_numpy(dtype=float)
    for k in range(start, len(d)):
        if lo[k] <= float(initial_stop):
            return "gapfade_stop_loss", new_running_max
        if k > start and hi[k] < hi[k - 1]:
            return "gapfade_rule_exit", new_running_max
        if k == start + GAPFADE_MAX_HOLD_BARS:
            return "gapfade_max_hold_timeout", new_running_max
    return None, new_running_max


def _gapfade_try_entry(conn, symbol, df, capital, risk_pct, today, fx) -> bool:
    """Opens at most one gap-fade position (first viable tag that fires). Same paper row / trades row / real-mirror
    pattern as _swingminrr_try_entry; the PFnet gate (and REPLAY_OWED) is inside _is_strategy_viable_for_real_money."""
    for tag in GAPFADE_TAGS:
        _record_strategy_scan(tag)
        sig = gapfade_long_entry_signal(df, tag)
        if not sig:
            continue
        if not _is_strategy_wired(tag):
            _record_blocked_trigger(tag)  # fired, gate closed now: no position opened
            continue
        entry_price, stop_loss = sig["entry_price"], sig["stop_loss"]
        qty = _swing_position_size(conn, capital, risk_pct, entry_price, stop_loss)
        if qty <= 0:
            return False
        conn.execute(
            "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, "
            "initial_stop_loss, gap_low, qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (symbol, tag, today, entry_price, stop_loss, None, qty, time.time(), fx, sig["atr_at_entry"], entry_price),
        )
        apply_paper_trade(conn, symbol, "buy", qty, entry_price)
        conn.execute(
            "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
            "VALUES (?, ?, 'buy', ?, ?, ?, ?, ?)",
            (time.time(), symbol, qty, entry_price, fx, SWING_STRATEGY_TAG,
             json.dumps({"entry_reason": tag, "stop_loss": stop_loss, "atr_at_entry": sig["atr_at_entry"]})),
        )
        conn.commit()
        print(f"[SWING] entry {symbol} ({tag}) qty={qty} @ {entry_price:.2f} stop={stop_loss:.2f}")
        try:
            _maybe_place_real_swing_entry(conn, symbol, qty, entry_price, stop_loss, tag)
        except Exception as e:
            print(f"[REAL SWING] entry mirror failed for {symbol} (non-fatal, paper entry already recorded): {e}")
        return True
    return False


# ---- macddiv LONG 1h port (research: scripts/macd_divergence_research.py v_macd_divergence, source line|hist,
# zero_filter False, w=5; registry macddiv__{line_any,hist_any}__long__1h__atr*_w5__nonovl__v2). PURE SIGNAL FUNCTION ONLY:
# NOT in any scan (the swing scan is daily-bar; a 1h swing-scan driver is the shared blocker for every 1h family). Fires on the
# bar the close-pivot low is confirmed (w bars later): price lower low while the MACD line (or histogram) makes a higher low.
MACDDIV_W = 5


def macd_divergence_long_entry_signal(df: pd.DataFrame, source: str = "line", atr_mult: float = 3.0,
                                      w: int = MACDDIV_W) -> dict | None:
    """Last-bar evaluation. Stop = px - atr_mult x ATR(Wilder) is always set (no trade without SL)."""
    if source not in ("line", "hist") or atr_mult <= 0:
        return None
    d = df.iloc[-BRK20_CALC_WINDOW:]
    n = len(d)
    if n < 60:
        return None
    c = d["Close"].to_numpy(dtype=float)
    m = pd.Series(c).ewm(span=12, adjust=False).mean() - pd.Series(c).ewm(span=26, adjust=False).mean()
    ind = (m if source == "line" else m - m.ewm(span=9, adjust=False).mean()).to_numpy(dtype=float)
    last = n - 1
    piv = last - w
    if piv < w or not c[piv] == c[piv - w:piv + w + 1].min() or np.isnan(ind[piv]):
        return None
    pl = None
    for i in range(w, piv):  # previous confirmed pivot low = nearest one before `piv` (research loop order)
        if not np.isnan(ind[i]) and c[i] == c[i - w:i + w + 1].min():
            pl = i
    if pl is None or not (c[piv] < c[pl] and ind[piv] > ind[pl]):
        return None
    atr = float(_brk20_atr_series(d["High"].to_numpy(dtype=float), d["Low"].to_numpy(dtype=float), c)[last])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(c[last])
    stop = brk20_stop_price(px, atr, atr_mult, "long")
    if not (0 < stop < px):
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": px - stop, "direction": "long"}


# macddiv LONG 1h: pooled (non-overlap, FIFO) registry cells only; the IS/OOS slice tags are evaluation segments of the
# same rule, not separate live rules. Exit = research simulate(): gap-aware ATR stop on the low, else close of the
# MACDDIV_MAX_HOLD_BARS-th bar after the fill bar. NOT scanned live: registry category is BUY (intraday engine, flat by
# 15:10 IST) but the rule holds ~16-24 market hours / up to 30 hourly bars (overnight), so wiring it into the intraday
# engine would trade a different, un-validated (flattened) rule. Replay-only until a flatten re-run exists (B-965).
MACDDIV_MAX_HOLD_BARS = 30
MACDDIV_LONG_CELLS = {
    "macddiv__line_any__long__1h__atr3_w5__nonovl__v2": ("line", 3.0),
    "macddiv__line_any__long__1h__atr2_w5__nonovl__v2": ("line", 2.0),
    "macddiv__line_any__long__1h__atr1d5_w5__nonovl__v2": ("line", 1.5),
    "macddiv__hist_any__long__1h__atr3_w5__nonovl__v2": ("hist", 3.0),
}


def macddiv_long_cell_signal(df: pd.DataFrame, tag: str) -> dict | None:
    cfg = MACDDIV_LONG_CELLS.get(tag)
    if cfg is None:
        return None
    return macd_divergence_long_entry_signal(df, cfg[0], cfg[1])


def macddiv_long_exit_reason(df: pd.DataFrame, fill_i: int, stop: float):
    """(reason, exit_px) for the first exit event in bars fill_i..end of `df`, else (None, None). Pure; stop gap-aware
    (fill bar exits at the stop itself, as the research does), max hold = close of bar fill_i + MACDDIV_MAX_HOLD_BARS."""
    o = df["Open"].to_numpy(dtype=float)
    lo = df["Low"].to_numpy(dtype=float)
    c = df["Close"].to_numpy(dtype=float)
    for j in range(int(fill_i), len(df)):
        if lo[j] <= stop:
            return "macddiv_stop_loss", (float(stop) if j == fill_i else float(min(stop, o[j])))
        if j - fill_i >= MACDDIV_MAX_HOLD_BARS:
            return "macddiv_max_hold_timeout", float(c[j])
    return None, None


# ---- chan_shape LONG 1d (Chan hybrid momentum/mean-reversion shape): swing engine --------------------------------------
# Rule (scripts/chan_research.py sig_shape): long when close < close[30 bars ago] AND close > close[40 bars ago]; stop =
# entry - k x ATR14 (simple-mean true range, chan_atr14) attached on every entry; exit at the gap-aware stop (low) or the
# close of the hold-th bar after entry. Live tags are the POOLED non-overlap registry cells (one tag per ATR x hold, each
# its own registry row). The registry's chan_shape *_y2021 / *_y2023 tags (PFnet 1.2-3.7) are CALENDAR-YEAR SLICES of the
# same rule (entries only in that year): a year filter cannot be traded forward, so those tags are NOT mapped and the live
# rule is judged on its pooled cells (PFnet 0.64-0.86, below the floor): the gate stays closed until a main.py-calling
# replay (scripts/chan_shape_macddiv_main_replay.py) proves otherwise. Deviation from the research: entry at the signal
# close (as every swing port), not the next open.
CHAN_SHAPE_LOOKBACK_NEAR = 30
CHAN_SHAPE_LOOKBACK_FAR = 40


def _chan_shape_cell_tag(atr_mult: float, hold: int) -> str:
    return f"chan_shape__mom_mr__long__1d__atr{f'{atr_mult:.1f}'.replace('.', 'd')}_hold{int(hold)}__nonovl__v2"


# highest registry PFnet first (hold10 atr4d0 0.855 ... hold5 atr1d5 0.642): first tag that fires owns the symbol
_CHAN_SHAPE_SPECS = ((4.0, 10), (2.5, 10), (1.5, 10), (4.0, 5), (2.5, 5), (1.5, 5))
CHAN_SHAPE_CELLS = {_chan_shape_cell_tag(a, h): (a, h) for a, h in _CHAN_SHAPE_SPECS}


def chan_shape_long_entry_signal(df: pd.DataFrame, tag: str) -> dict | None:
    """Last-bar evaluation; None when no signal / unknown tag. Stop is always set (no trade without SL)."""
    cfg = CHAN_SHAPE_CELLS.get(tag)
    if cfg is None:
        return None
    d = df.iloc[-BRK20_CALC_WINDOW:]
    if len(d) < CHAN_SHAPE_LOOKBACK_FAR + 2:
        return None
    c = d["Close"].to_numpy(dtype=float)
    last = len(c) - 1
    if not (c[last] < c[last - CHAN_SHAPE_LOOKBACK_NEAR] and c[last] > c[last - CHAN_SHAPE_LOOKBACK_FAR]):
        return None
    atr = float(chan_atr14(d["High"].to_numpy(dtype=float), d["Low"].to_numpy(dtype=float), c)[last])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(c[last])
    stop = px - cfg[0] * atr
    if not (0 < stop < px):
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": px - stop, "direction": "long"}


def chan_shape_exit_reason(df: pd.DataFrame, entry_day: str, stop: float, hold: int):
    """(reason, exit_px) for the first exit event in the bars after `entry_day`, else (None, None). Research order:
    stop on the low (fill bar exits at the stop, later bars at min(stop, open)), then the hold-th bar's close."""
    if len(df) == 0:
        return None, None
    dates = df["Date"].astype(str).str[:10].to_numpy()
    starts = np.flatnonzero(dates > str(entry_day)[:10])
    if len(starts) == 0:
        return None, None
    start = int(starts[0])
    o = df["Open"].to_numpy(dtype=float)
    lo = df["Low"].to_numpy(dtype=float)
    c = df["Close"].to_numpy(dtype=float)
    for j in range(start, len(df)):
        if lo[j] <= stop:
            return "chan_shape_stop_loss", (float(stop) if j == start else float(min(stop, o[j])))
        if j - start + 1 >= hold:
            return "chan_shape_max_hold_timeout", float(c[j])
    return None, None


def _chan_shape_exit_adapter(df, entry_day, initial_stop, atr_at_entry, running_max_close, tag):
    """Swing exit fn signature (reason, new_running_max)."""
    if len(df) == 0:
        return None, running_max_close
    hold = CHAN_SHAPE_CELLS[tag][1]
    new_running_max = max(float(running_max_close or 0.0), float(df["Close"].iloc[-1]))
    reason, _px = chan_shape_exit_reason(df, entry_day, float(initial_stop), hold)
    return reason, new_running_max


def _chan_shape_try_entry(conn, symbol, df, capital, risk_pct, today, fx) -> bool:
    """Opens at most one chan_shape position (first VIABLE tag that fires). Scans only tags that clear the real-money gate
    (registry PFnet vs the newest stack AND not replay-owed): a failing/owed cell would only spam the paper book. The real
    mirror (_maybe_place_real_swing_entry) re-checks the gate against the freshest stack (B-962), places the resting SL
    and unwinds at market if that SL fails (B-966)."""
    for tag in CHAN_SHAPE_CELLS:
        _record_strategy_scan(tag)
        sig = chan_shape_long_entry_signal(df, tag)
        if not sig:
            continue
        if not _is_strategy_wired(tag):
            _record_blocked_trigger(tag)  # fired, gate closed now: no position opened
            continue
        entry_price, stop_loss = sig["entry_price"], sig["stop_loss"]
        qty = _swing_position_size(conn, capital, risk_pct, entry_price, stop_loss)
        if qty <= 0:
            return False
        conn.execute(
            "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, "
            "initial_stop_loss, gap_low, qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (symbol, tag, today, entry_price, stop_loss, None, qty, time.time(), fx, sig["atr_at_entry"], entry_price),
        )
        apply_paper_trade(conn, symbol, "buy", qty, entry_price)
        conn.execute(
            "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
            "VALUES (?, ?, 'buy', ?, ?, ?, ?, ?)",
            (time.time(), symbol, qty, entry_price, fx, SWING_STRATEGY_TAG,
             json.dumps({"entry_reason": tag, "stop_loss": stop_loss, "atr_at_entry": sig["atr_at_entry"]})),
        )
        conn.commit()
        print(f"[SWING] entry {symbol} ({tag}) qty={qty} @ {entry_price:.2f} stop={stop_loss:.2f}")
        try:
            _maybe_place_real_swing_entry(conn, symbol, qty, entry_price, stop_loss, tag)
        except Exception as e:
            print(f"[REAL SWING] entry mirror failed for {symbol} (non-fatal, paper entry already recorded): {e}")
        return True
    return False


# ---- B-983 pattern-lab 1d LONG cells in the swing engine: STARC band fade (full universe) + gap runaway -------------------
# Rules are scripts/pattern_lab.py's own (r_bands starc_fade long: close < SMA6 - 2 x ATR15; r_key_reversal_gaps runaway
# long: open > prior high x 1.01 AND close > SMA50 AND close > open). Stop = entry - k x ATR14 (simple mean, chan_atr14),
# ATTACHED on every entry (no trade without SL); exit = gap-aware stop on the low, else the close of the hold-th bar after
# entry (pattern_lab.simulate). Deviation from the research: entry at the signal close (as every swing port), not the next
# open. Each tag is its OWN registry row (1:1). Wired only cells with registry PFnet >= floor AND a real stop: the starc
# atr6 n200 tags already live in _PATTERN_LIVE_CELLS (different tag, different stop) are untouched; atrnone cells are NOT
# wired. Real gate is closed (REPLAY_OWED_TAGS) until a main.py-calling replay clears the floor.
STARC_FULL_TAG = "starc__fade_full__long__1d__atr2d5_h20__v1"
GAP_RUNAWAY_TAG = "gap__runaway__long__1d__atr4_h20__v1"
# tag -> (rule key, ATR14 stop multiple, hold bars)
PL1D_CELLS = {
    STARC_FULL_TAG: ("starc_fade", 2.5, 20),
    GAP_RUNAWAY_TAG: ("gap_runaway", 4.0, 20),
}
PL1D_MIN_BARS = 60


def pl1d_rule_fires(df: pd.DataFrame, rule: str) -> bool:
    """Last-bar evaluation of a pattern_lab long rule on the tail window of df (needs Open/High/Low/Close)."""
    d = df.iloc[-BRK20_CALC_WINDOW:]
    if len(d) < PL1D_MIN_BARS:
        return False
    o, h, l, c = (d[k].to_numpy(dtype=float) for k in ("Open", "High", "Low", "Close"))
    last = len(c) - 1
    if rule == "starc_fade":
        s6 = float(np.mean(c[last - 5:last + 1]))
        a15 = float(chan_atr14(h, l, c, 15)[last])
        return bool(np.isfinite(a15) and a15 > 0 and c[last] < s6 - 2.0 * a15)
    if rule == "gap_runaway":
        ma50 = float(np.mean(c[last - 49:last + 1]))
        return bool(o[last] > h[last - 1] * 1.01 and c[last] > ma50 and c[last] > o[last])
    return False


def pl1d_long_entry_signal(df: pd.DataFrame, tag: str) -> dict | None:
    """None when no signal / unknown tag. Stop is always set (no trade without SL)."""
    cfg = PL1D_CELLS.get(tag)
    if cfg is None or len(df) < PL1D_MIN_BARS:
        return None
    rule, k, _hold = cfg
    if not pl1d_rule_fires(df, rule):
        return None
    d = df.iloc[-BRK20_CALC_WINDOW:]
    c = d["Close"].to_numpy(dtype=float)
    atr = float(chan_atr14(d["High"].to_numpy(dtype=float), d["Low"].to_numpy(dtype=float), c)[-1])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(c[-1])
    stop = px - k * atr
    if not (0 < stop < px):
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": px - stop, "direction": "long"}


def pl1d_exit_reason(df: pd.DataFrame, entry_day: str, stop: float, hold: int):
    """(reason, exit_px) for the first exit event in the bars after `entry_day`: gap-aware stop on the low (fill bar exits
    at the stop, later bars at min(stop, open)), else the close of the hold-th bar; (None, None) while still open."""
    if len(df) == 0:
        return None, None
    dates = df["Date"].astype(str).str[:10].to_numpy()
    starts = np.flatnonzero(dates > str(entry_day)[:10])
    if len(starts) == 0:
        return None, None
    start = int(starts[0])
    o = df["Open"].to_numpy(dtype=float)
    lo = df["Low"].to_numpy(dtype=float)
    c = df["Close"].to_numpy(dtype=float)
    for j in range(start, len(df)):
        if lo[j] <= stop:
            return "pl1d_stop_loss", (float(stop) if j == start else float(min(stop, o[j])))
        if j - start + 1 >= hold:
            return "pl1d_max_hold_timeout", float(c[j])
    return None, None


# ---- B-1001 pattern-lab 1d SHORT mirrors of the pl1d cells (RESEARCH-ONLY: not in PL1D_CELLS, no scan/real path) -------
# Mirrors (pattern_lab r_bands starc_fade short / r_key_reversal_gaps runaway short): close > SMA6 + 2 x ATR15;
# open < prior low x 0.99 AND close < SMA50 AND close < open. Stop = entry + k x ATR14 (always attached), exit = gap-aware
# stop on the high, else the close of the hold-th bar. Each is its OWN tag (dir short), never a flag on the long cell.
PL1D_SHORT_CELLS = {
    "starc__fade_full__short__1d__atr2d5_h20__v1": ("starc_fade", 2.5, 20),
    "gap__runaway__short__1d__atr4_h20__v1": ("gap_runaway", 4.0, 20),
}


def pl1d_short_rule_fires(df: pd.DataFrame, rule: str) -> bool:
    d = df.iloc[-BRK20_CALC_WINDOW:]
    if len(d) < PL1D_MIN_BARS:
        return False
    o, h, l, c = (d[k].to_numpy(dtype=float) for k in ("Open", "High", "Low", "Close"))
    last = len(c) - 1
    if rule == "starc_fade":
        s6 = float(np.mean(c[last - 5:last + 1]))
        a15 = float(chan_atr14(h, l, c, 15)[last])
        return bool(np.isfinite(a15) and a15 > 0 and c[last] > s6 + 2.0 * a15)
    if rule == "gap_runaway":
        ma50 = float(np.mean(c[last - 49:last + 1]))
        return bool(o[last] < l[last - 1] * 0.99 and c[last] < ma50 and c[last] < o[last])
    return False


def pl1d_short_entry_signal(df: pd.DataFrame, tag: str) -> dict | None:
    cfg = PL1D_SHORT_CELLS.get(tag)
    if cfg is None or len(df) < PL1D_MIN_BARS:
        return None
    rule, k, _hold = cfg
    if not pl1d_short_rule_fires(df, rule):
        return None
    d = df.iloc[-BRK20_CALC_WINDOW:]
    c = d["Close"].to_numpy(dtype=float)
    atr = float(chan_atr14(d["High"].to_numpy(dtype=float), d["Low"].to_numpy(dtype=float), c)[-1])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(c[-1])
    stop = px + k * atr
    if not (stop > px > 0):
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": stop - px, "direction": "short"}


def pl1d_short_exit_reason(df: pd.DataFrame, entry_day: str, stop: float, hold: int):
    """Short mirror of pl1d_exit_reason: (reason, cover_px); stop on the HIGH, gap-aware (later bars cover at max(stop, open))."""
    if len(df) == 0:
        return None, None
    dates = df["Date"].astype(str).str[:10].to_numpy()
    starts = np.flatnonzero(dates > str(entry_day)[:10])
    if len(starts) == 0:
        return None, None
    start = int(starts[0])
    o = df["Open"].to_numpy(dtype=float)
    hi = df["High"].to_numpy(dtype=float)
    c = df["Close"].to_numpy(dtype=float)
    for j in range(start, len(df)):
        if hi[j] >= stop:
            return "pl1d_short_stop_loss", (float(stop) if j == start else float(max(stop, o[j])))
        if j - start + 1 >= hold:
            return "pl1d_short_max_hold_timeout", float(c[j])
    return None, None


def _pl1d_exit_adapter(df, entry_day, initial_stop, atr_at_entry, running_max_close, tag):
    """Swing exit fn signature (reason, new_running_max)."""
    if len(df) == 0:
        return None, running_max_close
    hold = PL1D_CELLS[tag][2]
    new_running_max = max(float(running_max_close or 0.0), float(df["Close"].iloc[-1]))
    reason, _px = pl1d_exit_reason(df, entry_day, float(initial_stop), hold)
    return reason, new_running_max


def _pl1d_try_entry(conn, symbol, df, capital, risk_pct, today, fx) -> bool:
    """Opens at most one pl1d position (first VIABLE tag that fires; viable-only scan so a gate-closed cell never spams
    the paper book). The real mirror (_maybe_place_real_swing_entry) re-checks the gate on the freshest stack (B-962),
    places the resting SL and unwinds at market if that SL fails (B-966)."""
    for tag in PL1D_CELLS:
        _record_strategy_scan(tag)
        sig = pl1d_long_entry_signal(df, tag)
        if not sig:
            continue
        if not _is_strategy_wired(tag):
            _record_blocked_trigger(tag)  # fired, gate closed now: no position opened
            continue
        entry_price, stop_loss = sig["entry_price"], sig["stop_loss"]
        qty = _swing_position_size(conn, capital, risk_pct, entry_price, stop_loss)
        if qty <= 0:
            return False
        conn.execute(
            "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, "
            "initial_stop_loss, gap_low, qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (symbol, tag, today, entry_price, stop_loss, None, qty, time.time(), fx, sig["atr_at_entry"], entry_price),
        )
        apply_paper_trade(conn, symbol, "buy", qty, entry_price)
        conn.execute(
            "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
            "VALUES (?, ?, 'buy', ?, ?, ?, ?, ?)",
            (time.time(), symbol, qty, entry_price, fx, SWING_STRATEGY_TAG,
             json.dumps({"entry_reason": tag, "stop_loss": stop_loss, "atr_at_entry": sig["atr_at_entry"]})),
        )
        conn.commit()
        print(f"[SWING] entry {symbol} ({tag}) qty={qty} @ {entry_price:.2f} stop={stop_loss:.2f}")
        try:
            _maybe_place_real_swing_entry(conn, symbol, qty, entry_price, stop_loss, tag)
        except Exception as e:
            print(f"[REAL SWING] entry mirror failed for {symbol} (non-fatal, paper entry already recorded): {e}")
        return True
    return False


# ---------------------------------------------------------------------------
# FVG 3rd-candle classification (backlog B-32, family `fvg3c`; spec in
# docs/STRATEGY_SPEC_SND_AND_FVG3C.md). RESEARCH-STAGE ONLY: not wired into any
# scan loop or real-order path. Three separately-validated variants (each its
# own strategy, per CLAUDE.md's per-variant naming rule):
#   "breakaway"    - candle3's BODY closes outside candle2's range: enter in the
#                    gap direction at candle3's close (no retest expected).
#   "rejection"    - candle3 is a strong candle in the gap direction (the video's
#                    "rejection gap": invalid for a retest, price runs): enter in
#                    the gap direction at candle3's close.
#   "valid_retest" - candle3's body closes INSIDE candle2's range, then
#                    consolidation, then a retest tap of the gap and a
#                    confirmation trigger: enter AGAINST the gap (fade).
# Written in SHORT orientation (bearish FVG: candle3.high < candle1.low); the
# LONG mirror negates all prices and reuses the identical core, so the two
# directions can never drift apart.
# ---------------------------------------------------------------------------
FVG3C_DEFAULT_PARAMS = {
    "min_gap_atr": 0.25,        # min gap size, x ATR
    "strong_body_ratio": 0.7,   # candle3 body/range to count as "strong"
    "cons_bars": 2,             # min consolidation bars before the retest
    "cons_max_range_atr": 1.5,  # each consolidation bar's max range, x ATR
    "max_wait_bars": 20,        # bars after candle3 to wait for the retest
    "trigger": "wick",          # wick | engulf | mid_close
    "entry_level": "proximal",  # proximal | mid  (gap level price must tap)
    "stop_pad_atr": 0.25,       # stop beyond the gap's far edge, x ATR
    "rr": 2.0,                  # fixed target in R
    "max_hold_bars": 60,
    "atr_period": 14,
}
FVG3C_VARIANTS = ("breakaway", "rejection", "valid_retest")


def _atr_array(highs, lows, closes, period: int):
    """Simple-moving-average ATR per bar (NaN until `period` bars exist)."""
    n = len(closes)
    tr = np.empty(n)
    tr[0] = highs[0] - lows[0]
    prev_close = closes[:-1]
    tr[1:] = np.maximum.reduce([highs[1:] - lows[1:], np.abs(highs[1:] - prev_close), np.abs(lows[1:] - prev_close)])
    out = np.full(n, np.nan)
    if n >= period:
        csum = np.cumsum(tr)
        out[period - 1:] = (csum[period - 1:] - np.concatenate(([0.0], csum[:n - period]))) / period
    return out


# ---------------------------------------------------------------------------
# B-913 / B-792c step 1 (2026-10-13): verbatim PORT of the chan_kalman band SHORT (intraday, forced flat 15:15 IST).
# Source of truth: scripts/chan_ext_research.py (kalman_band, kalman_cells), scripts/chan_research.py (atr_arr, simulate),
# scripts/intraday_flatten_rerun.py (flatten_masks). NOT wired to any scan or order path; a real-main.py replay and the
# governance steps in docs/INTRADAY_FLATTEN_WIRING_SPEC.md come before the registry gate may open it.
CHAN_KALMAN_DELTA = 1e-4
CHAN_FLATTEN_CUTOFF_MIN = 15 * 60 + 15
_CHAN_BAR_MIN = {"5m": 5, "15m": 15, "1h": 60}


def chan_atr14(h, l, c, n: int = 14):
    """Research atr_arr: SMA ATR, NaN through index n-1 (first valid at index n)."""
    h, l, c = (np.asarray(x, float) for x in (h, l, c))
    pc = np.r_[c[0], c[:-1]]
    tr = np.maximum(h - l, np.maximum(np.abs(h - pc), np.abs(l - pc)))
    out = np.full(len(c), np.nan)
    if len(c) > n:
        cs = np.cumsum(np.r_[0, tr])
        out[n:] = (cs[n + 1:] - cs[1:len(c) - n + 1]) / n
    return out


def chan_kalman_series(close, ve: float = 1e-3, delta: float = CHAN_KALMAN_DELTA):
    """1-D Kalman filter on log price (state = adaptive mean). Returns (err, sqrtQ) per bar."""
    y = np.log(np.asarray(close, float))
    n = len(y)
    vw = delta / (1 - delta)
    beta, P = y[0], 1.0
    err, sq = np.full(n, np.nan), np.full(n, np.nan)
    for t in range(n):
        R = P + vw
        Q = R + ve
        e = y[t] - beta
        err[t], sq[t] = e, math.sqrt(Q)
        K = R / Q
        beta += K * e
        P = R - K * R
    return err, sq


# ---- chan_gap (Chan Ex4.1 Buy-on-Gap / Short-on-Gap), faithful port of scripts/chan_research.py xs_rows gapz_* + day_returns ----
# Registry tags chan_gap__{buy_on_gap__long,short_on_gap__short}__1d__atr{1d5,2d5,4d0}_top10__v1 (PFnet 1.27-1.45, n~1.1k, 0.8% cost).
# It is a SAME-DAY trade (enter at the open, exit at the close or the ATR stop, avg hold 6.25h) so it belongs to the INTRADAY
# (MIS) buy / short engines, not the swing engines. PORT ONLY: not wired into any scan (selection needs all liquid candidates
# ranked at 09:15, the live wiring is a separate step). The ATR stop (default 4.0 long / 1.5 short, the best swept cells) is
# always returned, so the live path can attach the protective SL with the entry.
CHAN_GAP_ATR_PERIOD = 14
CHAN_GAP_STD_WINDOW = 90
CHAN_GAP_MA_WINDOW = 20
CHAN_GAP_LIQ_MIN_TURNOVER = 2e7
CHAN_GAP_TOP_N = 10
CHAN_GAP_DEFAULT_ATR_MULT = {"long": 4.0, "short": 1.5}


def chan_gap_entry_signal(df_daily: pd.DataFrame, open_price: float, direction: str = "long",
                          atr_mult: float | None = None) -> dict | None:
    """df_daily = COMPLETED daily bars up to yesterday (today's bar excluded); open_price = today's opening print.
    long : open < prevLow*(1-std90) and open > MA20(close).   short: open > prevHigh*(1+std90) and open < MA20.
    std90 = stdev of the last 90 close-to-close returns, MA20 = mean of the last 20 closes, ATR = 14-bar simple-mean true
    range of the last completed bar, liquidity = median(20 x close*volume) >= 2e7 INR (all exactly as in the research).
    Returns {entry_price, stop_loss, atr_at_entry, gap, score, direction} or None. `score` = the gap return o/prevClose-1:
    rank long ascending (most negative first), short descending, then keep CHAN_GAP_TOP_N (chan_gap_select_top)."""
    if direction not in ("long", "short"):
        return None
    mult = CHAN_GAP_DEFAULT_ATR_MULT[direction] if atr_mult is None else float(atr_mult)
    if mult <= 0 or not open_price or not open_price > 0:
        return None
    need = CHAN_GAP_STD_WINDOW + 2
    if df_daily is None or len(df_daily) < need:
        return None
    d = df_daily.iloc[-(CHAN_GAP_STD_WINDOW + CHAN_GAP_ATR_PERIOD + 2):]
    c = d["Close"].to_numpy(dtype=float)
    h = d["High"].to_numpy(dtype=float)
    l = d["Low"].to_numpy(dtype=float)
    v = d["Volume"].to_numpy(dtype=float)
    if not (np.all(np.isfinite(c)) and np.all(np.isfinite(h)) and np.all(np.isfinite(l))) or c[-1] <= 0:
        return None
    rets = c[1:] / c[:-1] - 1.0
    std90 = float(np.std(rets[-CHAN_GAP_STD_WINDOW:], ddof=1))
    ma20 = float(np.mean(c[-CHAN_GAP_MA_WINDOW:]))
    if len(c) >= CHAN_GAP_MA_WINDOW and float(np.median((c * v)[-CHAN_GAP_MA_WINDOW:])) < CHAN_GAP_LIQ_MIN_TURNOVER:
        return None
    pc = np.r_[c[0], c[:-1]]
    tr = np.maximum(h - l, np.maximum(np.abs(h - pc), np.abs(l - pc)))
    atr = float(np.mean(tr[-CHAN_GAP_ATR_PERIOD:]))
    if not (np.isfinite(std90) and np.isfinite(atr) and atr > 0):
        return None
    o = float(open_price)
    if direction == "long":
        if not (o < l[-1] * (1 - std90) and o > ma20):
            return None
        stop = o - mult * atr
        if not stop > 0:
            return None
    else:
        if not (o > h[-1] * (1 + std90) and o < ma20):
            return None
        stop = o + mult * atr
    gap = o / float(c[-1]) - 1.0
    return {"entry_price": o, "stop_loss": float(stop), "atr_at_entry": atr, "gap": gap, "score": gap,
            "direction": direction, "std90": std90}


def chan_gap_select_top(candidates: dict, direction: str = "long", top_n: int = CHAN_GAP_TOP_N) -> list:
    """candidates = {symbol: chan_gap_entry_signal(...) dict}. Returns the symbols to trade today: long = the top_n most
    negative gaps, short = the top_n most positive gaps (research: per-day rank(method='first'), ties by input order)."""
    items = [(s, c) for s, c in candidates.items() if c]
    items.sort(key=lambda sc: sc[1]["score"], reverse=(direction == "short"))
    return [s for s, _ in items[:top_n]]


def chan_gap_exit_reason(day_bar, entry_price: float, stop_loss: float, direction: str = "long") -> tuple:
    """Same-day exit used by the research (day_returns, not gap-aware: entry is the open): the stop fills at the stop price
    if the day's low (long) / high (short) reaches it, else the position is flattened at the close. Returns (reason, px)."""
    hi, lo, cl = float(day_bar["High"]), float(day_bar["Low"]), float(day_bar["Close"])
    if direction == "long":
        return ("stop", float(stop_loss)) if lo <= stop_loss else ("close", cl)
    return ("stop", float(stop_loss)) if hi >= stop_loss else ("close", cl)


def chan_flatten_masks(index, interval: str, cutoff_min: int = CHAN_FLATTEN_CUTOFF_MIN):
    """(cut, noentry, day_cut_idx): cut = last bar of each IST day whose END <= cutoff; noentry = signals to drop."""
    idx = pd.DatetimeIndex(index)
    loc = idx.tz_convert("Asia/Kolkata") if idx.tz is not None else idx
    n = len(loc)
    end_min = (loc.hour * 60 + loc.minute + _CHAN_BAR_MIN[interval]).to_numpy()
    days = np.asarray(loc.date)
    cut = np.zeros(n, bool)
    noentry = np.ones(n, bool)
    dci = np.full(n, -1, dtype=int)
    start = 0
    while start < n:
        stop = start
        while stop + 1 < n and days[stop + 1] == days[start]:
            stop += 1
        ok = [i for i in range(start, stop + 1) if end_min[i] <= cutoff_min]
        if ok:
            ci = ok[-1]
            cut[ci] = True
            dci[start:stop + 1] = ci
            noentry[start:min(ci - 1, stop + 1)] = False
        start = stop + 1
    return cut, noentry, dci


def chan_kalman_band_short_entry_signal(df, interval: str, z: float = 2.0, ve: float = 1e-3, atr_mult: float = 4.0,
                                        ks=None, masks=None):
    """Evaluated on the LAST completed bar of df. Short when err > z*sqrtQ and the flatten rule allows an entry.
    Entry fills at the next bar open; stop = entry + atr_mult * ATR14[signal bar]. ks/masks may be precomputed over the
    full frame (the filter is causal, so slicing a precomputed series equals recomputing)."""
    n = len(df)
    if n < 20:
        return None
    if ks is None:
        ks = chan_kalman_series(df["Close"].to_numpy(float), ve)
    cut, noentry, _dci = masks if masks is not None else chan_flatten_masks(df.index, interval)
    i = n - 1
    err, sq = ks
    if noentry[i] or not (err[i] > z * sq[i]):
        return None
    atr = chan_atr14(df["High"].to_numpy(float), df["Low"].to_numpy(float), df["Close"].to_numpy(float))
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None
    return {"signal_pos": i, "atr": float(atr[i]), "atr_mult": float(atr_mult), "close": float(df["Close"].iloc[i])}


def chan_kalman_band_short_exit_reason(df, interval: str, entry_pos: int, entry_price: float, stop: float, hold: int = 40,
                                       ve: float = 1e-3, ks=None, masks=None):
    """Exit check on the LAST bar j of df for a short entered at bar entry_pos. Same order as research simulate:
    stop (gap-aware) -> state exit (err <= 0, or the 15:15 cut bar -> flatten_1515) -> max_hold. Returns (reason, px) or None."""
    j = len(df) - 1
    if j < entry_pos:
        return None
    if ks is None:
        ks = chan_kalman_series(df["Close"].to_numpy(float), ve)
    cut, _ne, _dci = masks if masks is not None else chan_flatten_masks(df.index, interval)
    o, h, c = float(df["Open"].iloc[j]), float(df["High"].iloc[j]), float(df["Close"].iloc[j])
    if h >= stop:
        return "stop", (max(stop, o) if j > entry_pos else stop)
    if ks[0][j] <= 0 or cut[j]:
        return ("state_exit" if ks[0][j] <= 0 else "flatten_1515"), c
    if j >= entry_pos + hold - 1:
        return "max_hold", c
    return None


# ---- B-1190 Minervini cup "3C cheat" LONG, 1h, SWING-length hold (RESEARCH-ONLY port: no scan, no real path, no kill switch)
# Rule = scripts/pattern_lab.py r_bases base_cup_cheat_3c at the LAST bar i of df (cup precondition + cheat pause, verbatim):
#   window w = bars [i-60, i); left_hi = max high of the first 20; low/low_i = min low and its index within w;
#   depth = (left_hi-low)/left_hi in [0.15, 0.35]; 15 <= low_i <= 50; right_hi = max high of [i-12, i) >= 0.95 x left_hi;
#   (right_hi - min low of [i-8, i))/right_hi <= 0.12 (handle); cheat: mid = low + 0.4 x (left_hi-low); pause = highs of
#   [i-6, i); mid x 0.97 <= pause.max <= mid x 1.10, pause range (pause.max - min low [i-6,i))/pause.max <= 0.10, and
#   close[i] > pause.max. Stop = entry - k x ATR14 (simple mean, chan_atr14), ALWAYS returned; atrnone cells are NOT ported
#   (no trade without SL). Exit = gap-aware stop, else the close of the hold-th bar. Deviation: entry at the signal close, not
#   the next open (as every swing port). No short mirror exists in pattern_lab (inverted cup): owed as its own tag family.
#   Each (ATR, hold) is its OWN tag. Registry evidence is n200 pattern-lab only (n ~130, thin); NOT confirmed by a main.py replay.
CUP_CHEAT_1H_MIN_BARS = 71
CUP_CHEAT_1H_CELLS = {
    f"base__cup_cheat_3c__long__1h__atr{fa}_h{h}__v1": (k, h)
    for fa, k in (("2d5", 2.5), ("4", 4.0), ("6", 6.0))
    for h in (6, 18, 30)
}


def cup_cheat_3c_fires(df) -> bool:
    """Last-bar evaluation of pattern_lab's base_cup_cheat_3c long rule (needs High/Low/Close)."""
    n = len(df)
    if n < CUP_CHEAT_1H_MIN_BARS:
        return False
    h = df["High"].to_numpy(dtype=float)[-61:]
    l = df["Low"].to_numpy(dtype=float)[-61:]
    c = float(df["Close"].iloc[-1])
    # window of 60 bars before the last bar, plus the last bar itself at index 60
    hw, lw = h[:60], l[:60]
    left_hi = float(hw[:20].max())
    low = float(lw.min())
    low_i = int(np.argmin(lw))
    if not left_hi > 0:
        return False
    depth = (left_hi - low) / left_hi
    right_hi = float(h[48:60].max())
    handle_lo = float(l[52:60].min())
    if not (0.15 <= depth <= 0.35 and 15 <= low_i <= 50 and right_hi >= left_hi * 0.95
            and (right_hi - handle_lo) / right_hi <= 0.12):
        return False
    mid = low + 0.4 * (left_hi - low)
    pause_hi = float(h[54:60].max())
    pause_lo = float(l[54:60].min())
    return bool((mid * 0.97 <= pause_hi <= mid * 1.10) and ((pause_hi - pause_lo) / pause_hi <= 0.10) and c > pause_hi)


def cup_cheat_3c_entry_signal(df, tag: str):
    """None when no signal / unknown tag. The stop is always set. NOT wired into any scan."""
    cfg = CUP_CHEAT_1H_CELLS.get(tag)
    if cfg is None or not cup_cheat_3c_fires(df):
        return None
    k, _hold = cfg
    h, l, c = (df[x].to_numpy(dtype=float) for x in ("High", "Low", "Close"))
    atr = float(chan_atr14(h, l, c)[-1])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(c[-1])
    stop = px - k * atr
    if not (0 < stop < px):
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": px - stop, "direction": "long"}


def cup_cheat_3c_exit_reason(df, entry_pos: int, stop: float, hold: int):
    """Exit check on the LAST bar j of df for a long entered at the CLOSE of bar entry_pos: gap-aware stop (fill bar at the
    stop, later bars at min(stop, open)), else the close of the hold-th bar after entry. (reason, px) or None while open."""
    j = len(df) - 1
    if j <= entry_pos:
        return None
    o, l, c = (float(df[x].iloc[j]) for x in ("Open", "Low", "Close"))
    if l <= stop:
        return "cup_cheat_stop_loss", (float(stop) if j == entry_pos + 1 else min(float(stop), o))
    if j - entry_pos >= hold:
        return "cup_cheat_max_hold_timeout", c
    return None


# ---- B-1130 envelope 5% fade, 1h, SWING-length hold (RESEARCH-ONLY port: no scan, no real path, no kill switch) -------
# Rule = scripts/pattern_lab.py r_bands envelope_0d05_fade: long when close < SMA21 x 0.95, short mirror when close >
# SMA21 x 1.05. Stop = entry -/+ k x ATR14 (simple mean, chan_atr14), ALWAYS returned (atrnone cells are NOT ported: no
# trade without SL). Exit = gap-aware stop, else the close of the hold-th bar. Deviation from the research: entry at the
# signal close, not the next open (as every swing port). Each (direction, ATR, hold) is its OWN tag (naming grammar);
# registry PFnet (n200 swing watchlist, pattern-lab) is NOT yet confirmed by a main.py-calling replay, so none of these
# may be wired until one clears PFNET_LIVE_FLOOR (long atr6_h30 1.145 is the only stop-bearing cell above the floor).
ENVELOPE_PCT = 0.05
ENVELOPE_SMA = 21
ENVELOPE_1H_CELLS = {
    f"envelope__0d05_fade__{d}__1h__atr{fa}_h{h}__v1": (d, k, h)
    for d in ("long", "short")
    for fa, k in (("2d5", 2.5), ("4", 4.0), ("6", 6.0))
    for h in (18, 30)
}


def envelope_fade_fires(df, direction: str) -> bool:
    """Last-bar rule: close below SMA21 x (1 - 5%) for long, above SMA21 x (1 + 5%) for short."""
    c = df["Close"].to_numpy(dtype=float)
    if len(c) < ENVELOPE_SMA + 15:
        return False
    s = float(np.mean(c[-ENVELOPE_SMA:]))
    return bool(c[-1] < s * (1 - ENVELOPE_PCT)) if direction == "long" else bool(c[-1] > s * (1 + ENVELOPE_PCT))


def envelope_fade_entry_signal(df, tag: str):
    """None when no signal / unknown tag. The stop is always set. NOT wired into any scan."""
    cfg = ENVELOPE_1H_CELLS.get(tag)
    if cfg is None:
        return None
    direction, k, _hold = cfg
    if not envelope_fade_fires(df, direction):
        return None
    h, l, c = (df[x].to_numpy(dtype=float) for x in ("High", "Low", "Close"))
    atr = float(chan_atr14(h, l, c)[-1])
    if not np.isfinite(atr) or atr <= 0:
        return None
    px = float(c[-1])
    stop = px - k * atr if direction == "long" else px + k * atr
    if direction == "long" and not (0 < stop < px):
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": atr, "risk": abs(px - stop), "direction": direction}


def envelope_fade_exit_reason(df, direction: str, entry_pos: int, stop: float, hold: int):
    """Exit check on the LAST bar j of df for a position entered at the CLOSE of bar entry_pos (bars after it count):
    gap-aware stop (fill bar at the stop, later bars at min/max(stop, open)), else the close of the hold-th bar after
    entry. Returns (reason, px) or None while open."""
    j = len(df) - 1
    if j <= entry_pos:
        return None
    o, h, l, c = (float(df[x].iloc[j]) for x in ("Open", "High", "Low", "Close"))
    first = j == entry_pos + 1
    if direction == "long" and l <= stop:
        return "envelope_stop_loss", (float(stop) if first else min(float(stop), o))
    if direction == "short" and h >= stop:
        return "envelope_stop_loss", (float(stop) if first else max(float(stop), o))
    if j - entry_pos >= hold:
        return "envelope_max_hold_timeout", c
    return None


def chan_kalman_band_long_entry_signal(df, interval: str, z: float = 2.0, ve: float = 1e-3, atr_mult: float = 4.0,
                                       ks=None, masks=None):
    """Long mirror of chan_kalman_band_short_entry_signal (err < -z*sqrtQ). NOT wired: no live buy-engine hook yet."""
    n = len(df)
    if n < 20:
        return None
    if ks is None:
        ks = chan_kalman_series(df["Close"].to_numpy(float), ve)
    cut, noentry, _dci = masks if masks is not None else chan_flatten_masks(df.index, interval)
    i = n - 1
    err, sq = ks
    if noentry[i] or not (err[i] < -z * sq[i]):
        return None
    atr = chan_atr14(df["High"].to_numpy(float), df["Low"].to_numpy(float), df["Close"].to_numpy(float))
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None
    return {"signal_pos": i, "atr": float(atr[i]), "atr_mult": float(atr_mult), "close": float(df["Close"].iloc[i])}


def chan_kalman_band_long_exit_reason(df, interval: str, entry_pos: int, entry_price: float, stop: float, hold: int = 40,
                                      ve: float = 1e-3, ks=None, masks=None):
    """Long mirror of the short exit: stop (gap-aware, Low <= stop) -> state exit (err >= 0 or 15:15 cut bar) -> max_hold."""
    j = len(df) - 1
    if j < entry_pos:
        return None
    if ks is None:
        ks = chan_kalman_series(df["Close"].to_numpy(float), ve)
    cut, _ne, _dci = masks if masks is not None else chan_flatten_masks(df.index, interval)
    o, l, c = float(df["Open"].iloc[j]), float(df["Low"].iloc[j]), float(df["Close"].iloc[j])
    if l <= stop:
        return "stop", (min(stop, o) if j > entry_pos else stop)
    if ks[0][j] >= 0 or cut[j]:
        return ("state_exit" if ks[0][j] >= 0 else "flatten_1515"), c
    if j >= entry_pos + hold - 1:
        return "max_hold", c
    return None


# ---------------------------------------------------------------------------
# O'Neil pivot / flat-base / new-high setups (B-1070). ADDITIVE PORT of the walk-forward rules in
# scripts/oneil_replay.py (constants verbatim from scripts/oneil_research.CFG). NOT wired into any live scan,
# no real-order path, no kill switch: it exists so a replay genuinely calls main.py. Signal at the CLOSE of bar t,
# entry at the OPEN of t+1, a stop on EVERY trade (oneil_stop_price always returns a level). Long and short are
# separate tags. avg-down is deliberately NOT ported (engine invariant: never average down).
# ---------------------------------------------------------------------------
ONEIL_CFG = {
    "1d": dict(base=40, vol=50, smalt=200, flat=35, adv_lb=60, yr=252, swing=3),
    "1w": dict(base=8, vol=10, smalt=40, flat=7, adv_lb=12, yr=52, swing=2),
}
ONEIL_VOL_MULT = 1.5
ONEIL_FLAT_RANGE = 0.12
ONEIL_ADV_MIN = 0.30
ONEIL_DEPTH_MAX = 0.35
ONEIL_FAMILIES = ("oneil_flatbase", "oneil_pivot", "oneil_newhigh")


def oneil_atr14(h, l, c):
    """ATR(14), simple mean of true range using only bars <= t (NaN until 14 TRs exist)."""
    n = len(c)
    tr = np.full(n, np.nan)
    for t in range(1, n):
        tr[t] = max(h[t] - l[t], abs(h[t] - c[t - 1]), abs(l[t] - c[t - 1]))
    out = np.full(n, np.nan)
    for t in range(14, n):
        out[t] = tr[t - 13:t + 1].mean()
    return out


def oneil_signal_at(family: str, direction: str, tf: str, t: int, o, h, l, c, v, rs=None,
                    chase=None, rs_thr=None) -> bool:
    """True if the setup fires at the CLOSE of bar t (bars <= t only; o[t+1] only for the no-chase test, i.e. the
    'is the next open still near the pivot' check made at the next open). rs_thr: None/'none' = no RS filter."""
    cfg = ONEIL_CFG[tf]
    side = 1 if direction == "long" else -1
    vol_n = cfg["vol"]
    if t < vol_n + 1 or t + 1 >= len(c):
        return False
    vavg = float(np.mean(v[t - vol_n:t]))
    if not vavg > 0 or not v[t] >= ONEIL_VOL_MULT * vavg:
        return False
    nxt = o[t + 1]
    if rs_thr not in (None, "none", ""):
        if rs is None or np.isnan(rs[t]) or (rs[t] < float(rs_thr) if side == 1 else rs[t] > 30.0):
            return False
    if family == "oneil_flatbase":
        fb, adv_lb = cfg["flat"], cfg["adv_lb"]
        if t < fb + adv_lb + 1:
            return False
        hh, ll = float(np.max(h[t - fb:t])), float(np.min(l[t - fb:t]))
        if (hh - ll) / hh > ONEIL_FLAT_RANGE:
            return False
        adv = c[t - fb] / c[t - fb - adv_lb]
        if side == 1:
            return bool(adv >= 1 + ONEIL_ADV_MIN and c[t] > hh and (chase is None or nxt / hh - 1 <= chase))
        return bool(adv <= 1 - ONEIL_ADV_MIN and c[t] < ll and (chase is None or 1 - nxt / ll <= chase))
    if family == "oneil_pivot":
        base, smalt = cfg["base"], cfg["smalt"]
        if t < max(base, smalt) + 1:
            return False
        hh, ll = float(np.max(h[t - base:t])), float(np.min(l[t - base:t]))
        ma = float(np.mean(c[t - smalt + 1:t + 1]))
        if (hh - ll) / hh > ONEIL_DEPTH_MAX:
            return False
        if side == 1:
            return bool(c[t] > hh and c[t] > ma and (chase is None or nxt / hh - 1 <= chase))
        return bool(c[t] < ll and c[t] < ma and (chase is None or 1 - nxt / ll <= chase))
    if family == "oneil_newhigh":
        yr = cfg["yr"]
        if t < yr + 1:
            return False
        return bool(c[t] > np.max(c[t - yr:t]) if side == 1 else c[t] < np.min(c[t - yr:t]))
    raise ValueError(f"unsupported O'Neil family {family}")


def oneil_stop_price(entry: float, atr: float, direction: str, mode: str = "atr", val: float = 3.0) -> float:
    """Initial stop (always defined). atr/trl: val*ATR14; pct: val percent; tgt: fixed 8%."""
    side = 1 if direction == "long" else -1
    if mode == "pct":
        return entry * (1 - side * val / 100.0)
    if mode == "tgt":
        return entry * (1 - side * 0.08)
    return entry - side * val * atr


def oneil_trail_stop(direction: str, h, l, entry_pos: int, j: int, swing: int, stop: float) -> float:
    """Ratchet the stop under the latest CONFIRMED swing low (short: over the swing high) as of bar j."""
    k = j - 1 - swing
    if k - swing >= entry_pos:
        if direction == "long" and l[k] == np.min(l[k - swing:k + swing + 1]):
            return max(stop, l[k])
        if direction == "short" and h[k] == np.max(h[k - swing:k + swing + 1]):
            return min(stop, h[k])
    return stop


def oneil_exit_bar(direction: str, o_j: float, h_j: float, l_j: float, c_j: float, j: int, last: int,
                   stop: float, init_stop: float, target=None):
    """Exit check for bar j: gap-aware stop -> target -> max-hold bar `last` (close). Returns (reason, px) or None."""
    if direction == "long":
        if l_j <= stop:
            return ("trail_stop" if stop > init_stop else "stop"), min(stop, o_j)
        if target is not None and h_j >= target:
            return "target", max(target, o_j)
    else:
        if h_j >= stop:
            return ("trail_stop" if stop < init_stop else "stop"), max(stop, o_j)
        if target is not None and l_j <= target:
            return "target", min(target, o_j)
    if j >= last:
        return "timeout", c_j
    return None


def oneil_entry_signal(df, tf: str, family: str, direction: str, rs_thr=None, rs=None, atr_mult: float = 3.0):
    """Live-style entry check on the LAST bar of df (signal at its close; entry would be the next open). The no-chase
    test needs the next open, so it is left to the caller at that open. NOT wired into any scan."""
    if tf not in ONEIL_CFG or family not in ONEIL_FAMILIES:
        return None
    o, h, l, c, v = (df[x].to_numpy(float) for x in ("Open", "High", "Low", "Close", "Volume"))
    t = len(c) - 1
    # signal_at wants a bar t+1 to exist (placeholder open = close, chase disabled); only bars <= t are used otherwise
    o2, h2, l2, c2, v2 = (np.append(a, a[-1]) for a in (o, h, l, c, v))
    rs2 = None if rs is None else np.append(np.asarray(rs, float), np.nan)
    if not oneil_signal_at(family, direction, tf, t, o2, h2, l2, c2, v2, rs2, None, rs_thr):
        return None
    atr = oneil_atr14(h, l, c)
    if np.isnan(atr[t]) or atr[t] <= 0:
        return None
    return {"signal_pos": t, "atr": float(atr[t]), "atr_mult": float(atr_mult), "close": float(c[t]),
            "stop_hint": float(oneil_stop_price(float(c[t]), float(atr[t]), direction, "atr", atr_mult))}


def oneil_exit_reason(df, tf: str, direction: str, entry_pos: int, stop: float, hold: int,
                      init_stop=None, target=None, mode: str = "atr"):
    """Exit check on the LAST bar j of df for a position entered at bar entry_pos. Returns (reason, px) or None.
    mode 'trl' ratchets `stop` under the confirmed swing first (the caller persists the ratchet via
    oneil_trail_stop). NOT wired."""
    j = len(df) - 1
    if j < entry_pos:
        return None
    o, h, l, c = (df[x].to_numpy(float) for x in ("Open", "High", "Low", "Close"))
    init = stop if init_stop is None else init_stop
    if mode == "trl":
        stop = oneil_trail_stop(direction, h, l, entry_pos, j, ONEIL_CFG[tf]["swing"], stop)
    return oneil_exit_bar(direction, o[j], h[j], l[j], c[j], j, entry_pos + hold - 1, stop, init, target)


# ---- O'Neil 1w LONG cells wired into the live SWING scan (2026-10-14, user "go"; main.py replay run 38517583883) ----
# The scan holds completed DAILY bars; weekly bars are resampled from them (W-FRI, same as scripts/oneil_replay.py's 1w
# feed). Signal = last COMPLETED week, evaluated in the first 1-2 sessions of the next week (entry ~ that week's open).
# Stop = entry - 3 x weekly ATR14 (oneil_stop_price), frozen; it is the real resting SL (no trade without SL). Exit =
# stop (daily low/open <= stop) or the close of the 26th weekly bar (entry week = bar 1). Wired: the three non-avg-down,
# non-trailing cells, ordered by registry PFnet (highest first; one position per symbol). NOT wired: the avg-down cells
# (engine invariant: never average down), the trl1 cell (same signal as the plain flatbase cell, lower PFnet, would never
# be picked) and the flatbase SHORT cell (n=10, ex-top5 PFnet 0; the short-swing engine is a separate path, parked).
ONEIL_SWING_HOLD_WEEKS = 26
ONEIL_SWING_ATR_MULT = 3.0
ONEIL_SWING_CHASE = 0.10
ONEIL_FLATBASE_TAG = "oneil_flatbase__breakout__long__1w__atr3_chase10_h26_rsnone__v2"
ONEIL_NEWHIGH_TAG = "oneil_newhigh__first__long__1w__atr3_h26_rsnone__v2"
ONEIL_PIVOT_TAG = "oneil_pivot__breakout__long__1w__atr3_chase10_h26_rsnone__v2"
# tag -> (family, chase or None); order = priority (PFnet 3.921 > 2.484 > 2.177)
ONEIL_SWING_CELLS = {
    ONEIL_FLATBASE_TAG: ("oneil_flatbase", ONEIL_SWING_CHASE),
    ONEIL_NEWHIGH_TAG: ("oneil_newhigh", None),
    ONEIL_PIVOT_TAG: ("oneil_pivot", ONEIL_SWING_CHASE),
}


def oneil_weekly_from_daily(df: pd.DataFrame) -> pd.DataFrame:
    """Resample completed daily bars to Friday-anchored weekly OHLCV plus 'nbars' (daily bars in that week)."""
    d = df
    dates = pd.DatetimeIndex(pd.to_datetime(d["Date"] if "Date" in d.columns else d.index))
    per = dates.to_period("W-FRI")
    g = pd.DataFrame({"Open": d["Open"].to_numpy(float), "High": d["High"].to_numpy(float),
                      "Low": d["Low"].to_numpy(float), "Close": d["Close"].to_numpy(float),
                      "Volume": d["Volume"].to_numpy(float), "per": per}).groupby("per", sort=True)
    return g.agg(Open=("Open", "first"), High=("High", "max"), Low=("Low", "min"), Close=("Close", "last"),
                 Volume=("Volume", "sum"), nbars=("Close", "size"))


def oneil_swing_entry_signal(df: pd.DataFrame, tag: str) -> dict | None:
    """Live entry check for one wired cell on the daily df (see block comment). Returns the swing-engine signal dict
    (entry_price/stop_loss/atr_at_entry) or None. Fires only while the latest daily bar is among the first two sessions
    of a week, using the previous completed week as the signal bar t; the next-open no-chase test uses the live daily
    close as the entry reference."""
    cell = ONEIL_SWING_CELLS.get(tag)
    if cell is None or df is None or len(df) < 60:
        return None
    family, chase = cell
    w = oneil_weekly_from_daily(df)
    if len(w) < 3 or int(w["nbars"].iloc[-1]) > 2:
        return None  # the newest week is already 3+ sessions old: the signal week's entry window has passed
    wc = w.iloc[:-1]  # completed weeks only; its last row is the signal bar t
    px = float(df["Close"].iloc[-1])
    if not px > 0:
        return None
    o, h, l, c, v = (wc[x].to_numpy(float) for x in ("Open", "High", "Low", "Close", "Volume"))
    t = len(c) - 1
    o2, h2, l2, c2, v2 = (np.append(a, px) for a in (o, h, l, c, v))
    if not oneil_signal_at(family, "long", "1w", t, o2, h2, l2, c2, v2, None, chase, None):
        return None
    atr = oneil_atr14(h, l, c)
    if not np.isfinite(atr[t]) or atr[t] <= 0:
        return None
    stop = oneil_stop_price(px, float(atr[t]), "long", "atr", ONEIL_SWING_ATR_MULT)
    if not (0 < stop < px):
        return None
    return {"entry_price": px, "stop_loss": float(stop), "atr_at_entry": float(atr[t]),
            "risk": px - float(stop), "direction": "long"}


def oneil_swing_exit_reason(df: pd.DataFrame, entry_day: str, initial_stop: float, running_max_close,
                            hold_weeks: int = ONEIL_SWING_HOLD_WEEKS):
    """Swing exit core: replays every completed daily bar after entry_day against the frozen stop (open or low at/below
    it -> 'oneil_stop_hit'), then the weekly max-hold (entry week = bar 1; exit once the close of bar `hold_weeks` is in,
    i.e. on the Friday of week entry+hold-1 or any later session). Returns (reason_or_None, new_running_max)."""
    if len(df) == 0:
        return None, running_max_close
    d = df
    dates = pd.DatetimeIndex(pd.to_datetime(d["Date"] if "Date" in d.columns else d.index))
    new_running_max = max(float(running_max_close or 0.0), float(d["Close"].iloc[-1]))
    ed = pd.Timestamp(str(entry_day)[:10])
    o = d["Open"].to_numpy(float)
    lo = d["Low"].to_numpy(float)
    for k in range(len(d)):
        if dates[k] <= ed:
            continue
        if o[k] <= float(initial_stop) or lo[k] <= float(initial_stop):
            return "oneil_stop_hit", new_running_max
    last = dates[-1]
    weeks_in = int(last.to_period("W-FRI").ordinal - ed.to_period("W-FRI").ordinal)  # entry week -> 0
    if weeks_in >= hold_weeks or (weeks_in >= hold_weeks - 1 and last.weekday() == 4):
        return "oneil_max_hold_timeout", new_running_max
    return None, new_running_max


def _oneil_swing_exit_adapter(df, entry_day, initial_stop, atr_at_entry, running_max_close):
    """Same signature as the other swing exit adapters."""
    return oneil_swing_exit_reason(df, entry_day, initial_stop, running_max_close)


def _oneil_scan_signal(df, tag):
    """Scan-only trigger evaluation (B-1274 stage 2); never an order."""
    return oneil_swing_entry_signal(df, tag)


def _oneil_swing_try_entry(conn, symbol, df, capital, risk_pct, today, fx) -> bool:
    """Opens at most one O'Neil position (first viable cell that fires, PFnet order). Same paper row / trades row / real
    mirror pattern as _gapfade_try_entry; the PFnet gate is inside _is_strategy_viable_for_real_money."""
    for tag in ONEIL_SWING_CELLS:
        _record_strategy_scan(tag)
        sig = oneil_swing_entry_signal(df, tag)
        if not sig:
            continue
        if not _is_strategy_wired(tag):
            _record_blocked_trigger(tag)  # fired, gate closed now: no position opened
            continue
        # a stop-out inside the 2-session window must not re-enter the same week's signal
        wk_start = (pd.Timestamp(today) - pd.Timedelta(days=pd.Timestamp(today).weekday())).timestamp()
        if conn.execute("SELECT 1 FROM trades WHERE symbol = ? AND action = 'buy' AND ts >= ? AND raw_payload LIKE ?",
                        (symbol, wk_start, f'%"entry_reason": "{tag}"%')).fetchone():
            return False
        entry_price, stop_loss = sig["entry_price"], sig["stop_loss"]
        qty = _swing_position_size(conn, capital, risk_pct, entry_price, stop_loss)
        if qty <= 0:
            return False
        conn.execute(
            "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, "
            "initial_stop_loss, gap_low, qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (symbol, tag, today, entry_price, stop_loss, None, qty, time.time(), fx, sig["atr_at_entry"], entry_price),
        )
        apply_paper_trade(conn, symbol, "buy", qty, entry_price)
        conn.execute(
            "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
            "VALUES (?, ?, 'buy', ?, ?, ?, ?, ?)",
            (time.time(), symbol, qty, entry_price, fx, SWING_STRATEGY_TAG,
             json.dumps({"entry_reason": tag, "stop_loss": stop_loss, "atr_at_entry": sig["atr_at_entry"]})),
        )
        conn.commit()
        print(f"[SWING] entry {symbol} ({tag}) qty={qty} @ {entry_price:.2f} stop={stop_loss:.2f}")
        try:
            _maybe_place_real_swing_entry(conn, symbol, qty, entry_price, stop_loss, tag)
        except Exception as e:
            print(f"[REAL SWING] entry mirror failed for {symbol} (non-fatal, paper entry already recorded): {e}")
        return True
    return False


def _fvg3c_scan_short(o, h, l, c, atr, variant: str, p: dict, sess=None):
    n = len(c)
    sig = np.zeros(n, dtype=bool)
    entry = np.full(n, np.nan)
    stop = np.full(n, np.nan)
    target = np.full(n, np.nan)

    def _emit(idx, entry_price, stop_price):
        if sig[idx] or not (stop_price > entry_price):
            return
        sig[idx] = True
        entry[idx] = entry_price
        stop[idx] = stop_price
        target[idx] = entry_price - p["rr"] * (stop_price - entry_price)

    for k in range(2, n):
        a = atr[k]
        if not (a > 0):
            continue
        c1, c2 = k - 2, k - 1
        if sess is not None and sess[c1] != sess[k]:
            continue  # intraday: a gap spanning the overnight break is not an FVG
        if not (h[k] < l[c1]):
            continue  # not a bearish 3-candle FVG
        gap_lo, gap_hi = h[k], l[c1]
        if gap_hi - gap_lo < p["min_gap_atr"] * a:
            continue
        rng3 = h[k] - l[k]
        body3 = abs(c[k] - o[k])
        strong = c[k] < o[k] and rng3 > 0 and body3 / rng3 >= p["strong_body_ratio"]
        inside = min(o[k], c[k]) >= l[c2] and max(o[k], c[k]) <= h[c2]
        pad = p["stop_pad_atr"] * a
        if variant == "breakaway":
            if not inside:
                _emit(k, c[k], gap_hi + pad)
            continue
        if variant == "rejection":
            if strong:
                _emit(k, c[k], gap_hi + pad)
            continue
        # valid_retest: body inside candle2's range and not a strong bearish candle3
        if not inside or strong:
            continue
        level = gap_lo if p["entry_level"] == "proximal" else (gap_lo + gap_hi) / 2.0
        mid = (gap_lo + gap_hi) / 2.0
        for j in range(k + 1, min(n, k + 1 + int(p["max_wait_bars"]))):
            if sess is not None and sess[j] != sess[k]:
                break  # retest must happen in the same session
            if c[j] > gap_hi:
                break  # gap invalidated (closed through the top)
            n_cons = j - k - 1
            tapped = h[j] >= level
            if n_cons < p["cons_bars"]:
                # still building the required consolidation: bar must be quiet and untapped
                if tapped or (h[j] - l[j]) > p["cons_max_range_atr"] * a:
                    break
                continue
            if not tapped:
                continue
            body_j = abs(c[j] - o[j])
            trig = p["trigger"]
            if trig == "wick":
                ok = c[j] < o[j] and (h[j] - max(o[j], c[j])) > body_j
            elif trig == "engulf":
                ok = c[j] < o[j] and c[j - 1] > o[j - 1] and o[j] >= c[j - 1] and c[j] <= o[j - 1]
            else:  # mid_close
                ok = c[j] < o[j] and c[j] < mid
            if ok:
                _emit(j, c[j], max(h[j], gap_hi) + pad)
            break  # the tap is consumed whether or not it confirmed
    return sig, entry, stop, target


def fvg3c_scan(df: pd.DataFrame, variant: str, direction: str, params: dict | None = None, sessions=None) -> dict:
    """Vectorised scan over every bar of `df`. Returns numpy arrays keyed
    "signal"/"entry_price"/"stop_loss"/"target", aligned to df rows (a signal on
    bar i means: enter at bar i's close). direction "short" is the native
    orientation; "long" negates prices and reuses the same core. `sessions`
    (optional array aligned to df rows, e.g. the trading-day id) confines every
    FVG and its retest to one session - required for intraday frames so an
    overnight gap is never read as an FVG."""
    if variant not in FVG3C_VARIANTS:
        raise ValueError(f"unknown fvg3c variant {variant!r}")
    if direction not in ("long", "short"):
        raise ValueError(f"unknown direction {direction!r}")
    p = dict(FVG3C_DEFAULT_PARAMS)
    p.update(params or {})
    o = df["Open"].to_numpy(dtype=float)
    h = df["High"].to_numpy(dtype=float)
    l = df["Low"].to_numpy(dtype=float)
    c = df["Close"].to_numpy(dtype=float)
    atr = _atr_array(h, l, c, int(p["atr_period"]))
    if direction == "long":
        sig, entry, stop, target = _fvg3c_scan_short(-o, -l, -h, -c, atr, variant, p, sessions)
        return {"signal": sig, "entry_price": -entry, "stop_loss": -stop, "target": -target, "atr": atr}
    sig, entry, stop, target = _fvg3c_scan_short(o, h, l, c, atr, variant, p, sessions)
    return {"signal": sig, "entry_price": entry, "stop_loss": stop, "target": target, "atr": atr}


def fvg3c_entry_signal(df: pd.DataFrame, variant: str, direction: str, params: dict | None = None) -> dict | None:
    """Last-row evaluation (live-callable shape, like order_block_entry_signal):
    {"entry_price","stop_loss","target","atr_at_entry"} or None."""
    if len(df) < 3:
        return None
    r = fvg3c_scan(df, variant, direction, params)
    if not bool(r["signal"][-1]):
        return None
    return {
        "entry_price": float(r["entry_price"][-1]), "stop_loss": float(r["stop_loss"][-1]),
        "target": float(r["target"][-1]), "atr_at_entry": float(r["atr"][-1]),
    }


def fvg3c_exit_reason(high: float, low: float, close: float, direction: str, stop: float, target: float,
                      bars_held: int, max_hold_bars: int) -> tuple:
    """Per-bar exit for an open fvg3c position. Stop is checked before target
    (conservative when both are touched in one bar). Returns
    (reason_or_None, fill_price_or_None)."""
    if direction == "short":
        if high >= stop:
            return "stop_hit", stop
        if low <= target:
            return "target_hit", target
    else:
        if low <= stop:
            return "stop_hit", stop
        if high >= target:
            return "target_hit", target
    if bars_held >= max_hold_bars:
        return "max_hold_timeout", close
    return None, None


# ---------------------------------------------------------------------------
# Supply & Demand zones (backlog B-33, family `snd_zone`; spec in
# docs/STRATEGY_SPEC_SND_AND_FVG3C.md). RESEARCH-STAGE ONLY: not wired into any
# scan loop or real-order path. Two strategies per user text:
#   "demand_retest" (LONG)  - base candle(s) below price (small body, wicks > body)
#                             followed by an explosive UP candle; when price later
#                             drops back into the zone, buy.
#   "supply_retest" (SHORT) - the exact mirror; sell on the retest from below.
# Written in LONG (demand) orientation; the short direction negates prices and
# reuses the identical core so the two can never drift apart.
# ---------------------------------------------------------------------------
SND_DEFAULT_PARAMS = {
    "base_candles": 1,          # N consecutive base candles (1..3)
    "base_body_atr": 0.5,       # each base candle's body <= x ATR
    "explosive_body_atr": 1.5,  # explosive candle body >= x ATR, in zone direction
    "confirm_bars": 3,          # bars price must stay away before the zone is active
    "max_retests": 1,           # zone expires after this many retests (1 = fresh only)
    "max_zone_age_bars": 200,   # zone expires after this many bars
    "entry": "limit_proximal",  # limit_proximal | close_confirm
    "stop_pad_atr": 0.25,       # stop beyond the distal edge, x ATR
    "rr": 2.0,                  # fixed target in R
    "max_hold_bars": 60,
    "atr_period": 14,
}


def _snd_scan_long(o, h, l, c, atr, p: dict, sess=None):
    """Demand-zone scan. Returns (sig, entry, stop, target) aligned to bars; a
    signal on bar i means the entry order fills on bar i (limit_proximal: at the
    zone's proximal edge when bar i's low reaches it; close_confirm: at bar i's
    close when it dips into the zone and closes back above the proximal edge)."""
    n = len(c)
    sig = np.zeros(n, dtype=bool)
    entry = np.full(n, np.nan)
    stop = np.full(n, np.nan)
    target = np.full(n, np.nan)
    nb = int(p["base_candles"])
    zones = []  # active zones: dict(lo, hi, born, retests, a)
    for i in range(nb + 1, n):
        a = atr[i]
        # --- 1. does an explosive candle at i just complete a base of nb candles right before it?
        e = i
        if a > 0 and c[e] > o[e] and (c[e] - o[e]) >= p["explosive_body_atr"] * a:
            b0, b1 = e - nb, e - 1
            if b0 >= 0 and (sess is None or sess[b0] == sess[e]):
                ok = True
                for b in range(b0, b1 + 1):
                    body = abs(c[b] - o[b])
                    wick = (h[b] - l[b]) - body
                    if not (body <= p["base_body_atr"] * a and wick > body):
                        ok = False
                        break
                if ok:
                    zlo, zhi = float(np.min(l[b0:b1 + 1])), float(np.max(h[b0:b1 + 1]))
                    if zhi > zlo:
                        zones.append({"lo": zlo, "hi": zhi, "born": e, "retests": 0, "a": float(a), "away": 0, "active": False, "inside": False})
        # --- 2. evaluate existing zones against bar i
        keep = []
        for z in zones:
            if i == z["born"]:
                keep.append(z)
                continue
            if sess is not None and sess[i] != sess[z["born"]]:
                continue  # intraday: zones do not survive the session
            if c[i] < z["lo"] or (i - z["born"]) > p["max_zone_age_bars"]:
                continue  # invalidated (closed below distal edge) or expired
            if not z["active"]:
                if l[i] > z["hi"]:
                    z["away"] += 1
                    if z["away"] >= p["confirm_bars"]:
                        z["active"] = True
                else:
                    z["away"] = 0  # re-entered before confirmation: restart the wait
                keep.append(z)
                continue
            touched = l[i] <= z["hi"]
            if touched and not z["inside"]:
                z["inside"] = True
                z["retests"] += 1
                if z["retests"] <= p["max_retests"]:
                    pad = p["stop_pad_atr"] * z["a"]
                    if p["entry"] == "limit_proximal":
                        ep = z["hi"] if o[i] > z["hi"] else o[i]  # opened inside the zone (gap-down): fills at the open
                        sp = z["lo"] - pad
                        ok_fill = c[i] >= z["lo"]
                    else:
                        ep = c[i]
                        sp = z["lo"] - pad
                        ok_fill = c[i] > z["hi"] and l[i] >= z["lo"]
                    if ok_fill and ep > sp and not sig[i]:
                        sig[i] = True
                        entry[i] = ep
                        stop[i] = sp
                        target[i] = ep + p["rr"] * (ep - sp)
            elif not touched:
                z["inside"] = False
            if z["retests"] <= p["max_retests"] or z["inside"]:
                keep.append(z)
        zones = keep
    return sig, entry, stop, target


def snd_zone_scan(df: pd.DataFrame, direction: str, params: dict | None = None, sessions=None) -> dict:
    """Vectorised Supply & Demand scan. direction "long" = demand_retest (native);
    "short" = supply_retest (price-mirror through the same core). Returns arrays
    keyed signal/entry_price/stop_loss/target/atr aligned to df rows."""
    if direction not in ("long", "short"):
        raise ValueError(f"unknown direction {direction!r}")
    p = dict(SND_DEFAULT_PARAMS)
    p.update(params or {})
    if p["entry"] not in ("limit_proximal", "close_confirm"):
        raise ValueError(f"unknown entry mode {p['entry']!r}")
    o = df["Open"].to_numpy(dtype=float)
    h = df["High"].to_numpy(dtype=float)
    l = df["Low"].to_numpy(dtype=float)
    c = df["Close"].to_numpy(dtype=float)
    atr = _atr_array(h, l, c, int(p["atr_period"]))
    if direction == "short":
        sig, e, s_, t = _snd_scan_long(-o, -l, -h, -c, atr, p, sessions)
        return {"signal": sig, "entry_price": -e, "stop_loss": -s_, "target": -t, "atr": atr}
    sig, e, s_, t = _snd_scan_long(o, h, l, c, atr, p, sessions)
    return {"signal": sig, "entry_price": e, "stop_loss": s_, "target": t, "atr": atr}


def snd_zone_entry_signal(df: pd.DataFrame, direction: str, params: dict | None = None) -> dict | None:
    """Last-row evaluation, same return shape as fvg3c_entry_signal."""
    if len(df) < 4:
        return None
    r = snd_zone_scan(df, direction, params)
    if not bool(r["signal"][-1]):
        return None
    return {"entry_price": float(r["entry_price"][-1]), "stop_loss": float(r["stop_loss"][-1]),
            "target": float(r["target"][-1]), "atr_at_entry": float(r["atr"][-1])}


# ---------------------------------------------------------------------------
# Directional Movement / ADX (Wilder), backlog B-11, family `dmi_adx`. Source:
# Murphy, Technical Analysis of the Financial Markets, ch.15 (pp.384-388):
#   - buy when +DI crosses above -DI, sell(short) when it crosses below
#   - trend systems work best while ADX is RISING; ADX turning down from >40 =
#     trend weakening; a rise back above ~20 = a new trend starting
# RESEARCH-STAGE ONLY: not wired into any scan loop or real-order path. Variants
# (each its own strategy tag):
#   "cross"    - plain +DI/-DI cross, no ADX filter
#   "adx_gate" - cross AND ADX >= adx_min AND ADX rising
#   "adx_turn" - ADX crosses up through adx_turn_level while +DI > -DI (new trend)
# Long orientation is native; short negates prices (DMI is symmetric under
# negation: +DI and -DI swap) and reuses the same core.
# ---------------------------------------------------------------------------
DMI_DEFAULT_PARAMS = {
    "period": 14,            # Wilder DI/ADX period
    "adx_min": 20.0,         # adx_gate: ADX floor
    "adx_turn_level": 20.0,  # adx_turn: ADX must cross up through this
    "stop_atr": 2.0,         # stop distance, x ATR(period)
    "rr": 2.0,               # fixed target in R
    "max_hold_bars": 60,
}
DMI_VARIANTS = ("cross", "adx_gate", "adx_turn")


def _wilder_smooth(x, period: int):
    """Wilder smoothing: first value = sum of the first `period` inputs, then
    prev - prev/period + x. NaN before index period-1."""
    n = len(x)
    out = np.full(n, np.nan)
    if n < period:
        return out
    out[period - 1] = float(np.sum(x[:period]))
    for i in range(period, n):
        out[i] = out[i - 1] - out[i - 1] / period + x[i]
    return out


def _dmi_arrays(h, l, c, period: int):
    """Returns (plus_di, minus_di, adx) per bar (NaN until defined)."""
    n = len(c)
    up = np.zeros(n)
    dn = np.zeros(n)
    tr = np.zeros(n)
    tr[0] = h[0] - l[0]
    for i in range(1, n):
        u, d = h[i] - h[i - 1], l[i - 1] - l[i]
        up[i] = u if (u > d and u > 0) else 0.0
        dn[i] = d if (d > u and d > 0) else 0.0
        tr[i] = max(h[i] - l[i], abs(h[i] - c[i - 1]), abs(l[i] - c[i - 1]))
    str_ = _wilder_smooth(tr, period)
    spdm = _wilder_smooth(up, period)
    smdm = _wilder_smooth(dn, period)
    with np.errstate(divide="ignore", invalid="ignore"):
        pdi = 100.0 * spdm / str_
        mdi = 100.0 * smdm / str_
        dx = 100.0 * np.abs(pdi - mdi) / (pdi + mdi)
    adx = np.full(n, np.nan)
    first = 2 * period - 2  # first ADX = mean of the first `period` DX values
    if n > first:
        adx[first] = float(np.nanmean(dx[period - 1:first + 1]))
        for i in range(first + 1, n):
            adx[i] = (adx[i - 1] * (period - 1) + dx[i]) / period
    return pdi, mdi, adx


def _dmi_scan_long(o, h, l, c, variant: str, p: dict):
    n = len(c)
    per = int(p["period"])
    pdi, mdi, adx = _dmi_arrays(h, l, c, per)
    atr = _atr_array(h, l, c, per)
    sig = np.zeros(n, dtype=bool)
    entry = np.full(n, np.nan)
    stop = np.full(n, np.nan)
    target = np.full(n, np.nan)
    for i in range(2 * per, n):
        if not (np.isfinite(pdi[i]) and np.isfinite(mdi[i]) and np.isfinite(pdi[i - 1]) and np.isfinite(mdi[i - 1])):
            continue
        crossed_up = pdi[i - 1] <= mdi[i - 1] and pdi[i] > mdi[i]
        if variant == "cross":
            ok = crossed_up
        elif variant == "adx_gate":
            ok = bool(crossed_up and np.isfinite(adx[i]) and np.isfinite(adx[i - 1]) and adx[i] >= p["adx_min"] and adx[i] > adx[i - 1])
        else:  # adx_turn
            lvl = p["adx_turn_level"]
            ok = bool(np.isfinite(adx[i]) and np.isfinite(adx[i - 1]) and adx[i - 1] <= lvl < adx[i] and pdi[i] > mdi[i])
        if not ok or not (atr[i] > 0):
            continue
        e = float(c[i])
        sp = e - p["stop_atr"] * float(atr[i])
        if not (e > sp):
            continue
        sig[i], entry[i], stop[i], target[i] = True, e, sp, e + p["rr"] * (e - sp)
    return sig, entry, stop, target, atr


def dmi_scan(df: pd.DataFrame, variant: str, direction: str, params: dict | None = None, sessions=None) -> dict:
    """Vectorised DMI/ADX scan over every bar. A signal on bar i means: enter at
    bar i's close. `sessions` is accepted for harness symmetry (Wilder smoothing
    legitimately runs across sessions); exits are session-aware in the replay."""
    if variant not in DMI_VARIANTS:
        raise ValueError(f"unknown dmi variant {variant!r}")
    if direction not in ("long", "short"):
        raise ValueError(f"unknown direction {direction!r}")
    p = dict(DMI_DEFAULT_PARAMS)
    p.update(params or {})
    o = df["Open"].to_numpy(dtype=float)
    h = df["High"].to_numpy(dtype=float)
    l = df["Low"].to_numpy(dtype=float)
    c = df["Close"].to_numpy(dtype=float)
    if direction == "short":
        sig, e, s_, t, atr = _dmi_scan_long(-o, -l, -h, -c, variant, p)
        return {"signal": sig, "entry_price": -e, "stop_loss": -s_, "target": -t, "atr": atr}
    sig, e, s_, t, atr = _dmi_scan_long(o, h, l, c, variant, p)
    return {"signal": sig, "entry_price": e, "stop_loss": s_, "target": t, "atr": atr}


def dmi_entry_signal(df: pd.DataFrame, variant: str, direction: str, params: dict | None = None) -> dict | None:
    """Last-row evaluation, same return shape as fvg3c_entry_signal."""
    if len(df) < 3:
        return None
    r = dmi_scan(df, variant, direction, params)
    if not bool(r["signal"][-1]):
        return None
    return {"entry_price": float(r["entry_price"][-1]), "stop_loss": float(r["stop_loss"][-1]),
            "target": float(r["target"][-1]), "atr_at_entry": float(r["atr"][-1])}


# ---------------------------------------------------------------------------
# Point & Figure (Murphy ch.11, 3-box-reversal / Chartcraft method) -- backlog B-12.
# RESEARCH-STAGE ONLY: not wired into any scan loop or real-order path.
# Chart construction follows the book's daily-update rule applied per bar: in an X
# column look at the High first and extend while it fills a box; only when it can't,
# look at the Low for a `reversal`-box reversal into an O column (mirror for O).
# Box size is volatility-scaled (Tower-style) = box_atr x mean ATR(atr_period) over
# the first `warmup` bars, grid anchored at 0; signals only after the warm-up, so no
# bar's box size uses later data. Variants (each its own strategy tag):
#   "double_top"   - B-1 simple buy: X column rises 1 box above the prior X column
#   "triple_top"   - B-3 triple-top breakout: X column clears the two prior X-column
#                    tops, which must be within tol_boxes of each other
#   "pullback"     - tactic 6c: a `reversal`-box reversal back up while the last signal
#                    is a buy (bullish until a sell signal), stop under the latest O column
# Stop = bottom of the latest O column (book tactic 5); target = rr x risk (the book's
# vertical/horizontal counts are NOT implemented -- owed, backlog B-12).
# Long is native; short negates prices (box grid is re-anchored on the negated series,
# so the short is a mirror, not a bit-exact reflection).
# ---------------------------------------------------------------------------
PNF_DEFAULT_PARAMS = {
    "box_atr": 1.0,        # box size = box_atr x mean ATR over the warm-up
    "reversal": 3,         # boxes needed to reverse (book: 3)
    "tol_boxes": 0,        # triple_top: allowed spread between the two prior tops
    "atr_period": 14,
    "warmup": 30,
    "rr": 2.0,
    "max_hold_bars": 60,
}
PNF_VARIANTS = ("double_top", "triple_top", "pullback")


def _pnf_scan_long(o, h, l, c, variant: str, p: dict):
    n = len(c)
    atr = _atr_array(h, l, c, int(p["atr_period"]))
    sig = np.zeros(n, dtype=bool)
    entry = np.full(n, np.nan)
    stop = np.full(n, np.nan)
    target = np.full(n, np.nan)
    w = int(p["warmup"])
    if n <= w + 2:
        return sig, entry, stop, target, atr
    seg = atr[int(p["atr_period"]):w]
    seg = seg[np.isfinite(seg)]
    if seg.size == 0:
        return sig, entry, stop, target, atr
    box = float(p["box_atr"]) * float(np.mean(seg))
    if not (box > 0):
        return sig, entry, stop, target, atr
    rev = int(p["reversal"])
    tol = int(p["tol_boxes"])
    hi_i = np.floor(h / box).astype(np.int64)
    lo_i = np.floor(l / box).astype(np.int64)
    d = "x"
    top = bot = int(np.floor(c[w] / box))
    xcols: list = []   # completed X columns' tops
    ocols: list = []   # completed O columns' bottoms
    bullish = False
    for i in range(w + 1, n):
        fire = False
        if d == "x":
            if hi_i[i] > top:
                prev_top = top
                top = int(hi_i[i])
                if xcols:
                    ref = xcols[-1]
                    if prev_top <= ref < top:  # first bar clearing the prior X top
                        if variant == "double_top":
                            fire = True
                        elif variant == "triple_top" and len(xcols) >= 2 and abs(xcols[-1] - xcols[-2]) <= tol and top > max(xcols[-1], xcols[-2]):
                            fire = True
                        if variant != "triple_top" or fire:
                            bullish = True
            elif lo_i[i] <= top - rev:
                xcols.append(top)
                d, top, bot = "o", top - 1, int(lo_i[i])
        else:
            if lo_i[i] < bot:
                prev_bot = bot
                bot = int(lo_i[i])
                if ocols and prev_bot >= ocols[-1] > bot:
                    bullish = False  # sell signal: O column below the prior O column
            elif hi_i[i] >= bot + rev:
                ocols.append(bot)
                if variant == "pullback" and bullish:
                    fire = True
                d, bot, top = "x", bot + 1, int(hi_i[i])
        if not fire or not (atr[i] > 0):
            continue
        last_o = ocols[-1] if ocols else bot
        sp = float(last_o) * box
        e = float(c[i])
        if not (e > sp):
            continue
        sig[i], entry[i], stop[i], target[i] = True, e, sp, e + p["rr"] * (e - sp)
    return sig, entry, stop, target, atr


def pnf_scan(df: pd.DataFrame, variant: str, direction: str, params: dict | None = None, sessions=None) -> dict:
    """Vectorised Point & Figure scan over every bar. A signal on bar i means: enter at
    bar i's close. `sessions` is accepted for harness symmetry."""
    if variant not in PNF_VARIANTS:
        raise ValueError(f"unknown pnf variant {variant!r}")
    if direction not in ("long", "short"):
        raise ValueError(f"unknown direction {direction!r}")
    p = dict(PNF_DEFAULT_PARAMS)
    p.update(params or {})
    o = df["Open"].to_numpy(dtype=float)
    h = df["High"].to_numpy(dtype=float)
    l = df["Low"].to_numpy(dtype=float)
    c = df["Close"].to_numpy(dtype=float)
    if direction == "short":
        sig, e, s_, t, atr = _pnf_scan_long(-o, -l, -h, -c, variant, p)
        return {"signal": sig, "entry_price": -e, "stop_loss": -s_, "target": -t, "atr": atr}
    sig, e, s_, t, atr = _pnf_scan_long(o, h, l, c, variant, p)
    return {"signal": sig, "entry_price": e, "stop_loss": s_, "target": t, "atr": atr}


def pnf_entry_signal(df: pd.DataFrame, variant: str, direction: str, params: dict | None = None) -> dict | None:
    """Last-row evaluation, same return shape as dmi_entry_signal."""
    if len(df) < int(PNF_DEFAULT_PARAMS["warmup"]) + 3:
        return None
    r = pnf_scan(df, variant, direction, params)
    if not bool(r["signal"][-1]):
        return None
    return {"entry_price": float(r["entry_price"][-1]), "stop_loss": float(r["stop_loss"][-1]),
            "target": float(r["target"][-1]), "atr_at_entry": float(r["atr"][-1])}


def _compute_poc(highs, lows, vols, lo: int, hi: int):
    """Volume-weighted profile over bars [lo, hi) - port of the VP research
    workflow's _compute_poc. Returns (poc_price, bin_width) or (None, None)."""
    window_hi = float(np.max(highs[lo:hi]))
    window_lo = float(np.min(lows[lo:hi]))
    if window_hi <= window_lo:
        return None, None
    bin_width = (window_hi - window_lo) / VP_NUM_BINS
    if bin_width <= 0:
        return None, None
    bin_vols = np.zeros(VP_NUM_BINS)
    for j in range(lo, hi):
        bar_hi, bar_lo, bar_vol = highs[j], lows[j], vols[j]
        if bar_vol <= 0 or bar_hi <= bar_lo:
            continue
        start_bin = max(0, int((bar_lo - window_lo) / bin_width))
        end_bin = min(VP_NUM_BINS - 1, int((bar_hi - window_lo) / bin_width))
        n_bins = end_bin - start_bin + 1
        if n_bins <= 0:
            continue
        bin_vols[start_bin:end_bin + 1] += bar_vol / n_bins
    poc_bin = int(np.argmax(bin_vols))
    return window_lo + (poc_bin + 0.5) * bin_width, bin_width


def volume_profile_poc_entry_signal(df: pd.DataFrame) -> dict | None:
    """Evaluates ONLY the last row of `df` for a Volume Profile / POC bounce
    long (port of volume-profile-poc-liquidity-research.yml's entry rule)."""
    n = len(df)
    i = n - 1
    if n < VP_MIN_LOOKBACK_DAYS or i < VP_LOOKBACK_BARS:
        return None
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    closes = df["Close"].to_numpy(dtype=float)
    opens = df["Open"].to_numpy(dtype=float)
    vols = df["Volume"].to_numpy(dtype=float)
    last_close = float(closes[i])
    poc_price, _bw = _compute_poc(highs, lows, vols, i - VP_LOOKBACK_BARS, i)
    if poc_price is None:
        return None
    band_hi = poc_price * (1 + VP_POC_TOLERANCE_PCT / 100)
    band_lo = poc_price * (1 - VP_POC_TOLERANCE_PCT / 100)
    approach_lo = max(0, i - VP_APPROACH_LOOKBACK_BARS)
    if not bool(np.any(closes[approach_lo:i] > band_hi)):
        return None
    if not (last_close > float(opens[i]) and float(lows[i]) <= band_hi and last_close > band_lo):
        return None
    entry_price = last_close
    stop_loss = band_lo
    if entry_price - stop_loss <= 0:
        return None
    atr_at_entry = _compute_atr_value(df, 14)
    if atr_at_entry is None or atr_at_entry <= 0:
        return None
    return {"entry_price": entry_price, "stop_loss": stop_loss, "atr_at_entry": float(atr_at_entry)}


def volume_profile_poc_exit_reason(
    df: pd.DataFrame, entry_day: str, initial_stop: float, atr_at_entry: float, running_max_close: float,
) -> tuple:
    """Chandelier trail (VP_ATR_TRAIL_MULT x ATR at entry) + VP_MAX_HOLD_DAYS
    timeout - port of the VP research workflow's exit loop."""
    if len(df) == 0:
        return None, running_max_close
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    new_running_max = max(running_max_close, float(closes[i]))
    trail_stop = new_running_max - VP_ATR_TRAIL_MULT * atr_at_entry
    current_stop = max(initial_stop, trail_stop)
    if closes[i] <= current_stop:
        return "trail_stop_hit", new_running_max
    held_days = int(np.sum(dates > entry_day))
    if held_days >= VP_MAX_HOLD_DAYS:
        return "max_hold_timeout", new_running_max
    return None, new_running_max


# ---- Swing "exitinval" exit family (OB / VP, wired 2026-10-11) -------------
# Exit-family research run 38140914889 (scripts/exit_family_research.py, simulate() kind "inval"):
# SAME entries as order_block_entry_signal / volume_profile_poc_entry_signal, but exit =
# catastrophic stop entry - 6.0 x ATR14(at entry) (FIXED, never trails) + weekly EMA13 turn-down
# invalidation (completed weeks only) + 30-trading-day max hold. Tags are the registry names.
SWING_EXITINVAL_ATR_MULT = 6.0
SWING_EXITINVAL_MAX_HOLD_DAYS = 30
SWING_EXITINVAL_VP_TAG = "volume_profile_poc__exitinval__long__1d__atr6d0_hold30_sigema13w__v1"
SWING_EXITINVAL_OB_TAG = "order_block_delta__exitinval__long__1d__atr6d0_hold30_sigema13w__v1"
# new tag -> (legacy label, entry fn name); entry fns are looked up by name at call time
SWING_EXITINVAL_TAGS = {
    SWING_EXITINVAL_VP_TAG: ("volume_profile_poc", "volume_profile_poc_entry_signal"),
    SWING_EXITINVAL_OB_TAG: ("order_block_delta", "order_block_entry_signal"),
}


def swing_exitinval_stop(entry_price: float, atr_at_entry: float) -> float:
    """The frozen catastrophic stop for the exitinval tags (placed as the real resting SL)."""
    return float(entry_price) - SWING_EXITINVAL_ATR_MULT * float(atr_at_entry)


def weekly_ema13_down_flags(dates, closes) -> np.ndarray:
    """Per-day booleans, faithful to exit_family_research._weekly_down_flags (long orientation):
    True on day d when the weekly EMA13 (span 13, adjust=False, on Friday-anchored weekly last
    closes) of the last COMPLETED week before d's own week is below the one before it. A day in
    week w only sees week w-1 (no lookahead on the in-progress week). All False when fewer than
    30 weeks of history exist."""
    n = len(closes)
    out = np.zeros(n, bool)
    try:
        per = pd.DatetimeIndex(pd.to_datetime(dates)).to_period("W-FRI")
    except Exception:
        return out
    codes, _ = pd.factorize(per, sort=True)
    nw = int(codes.max()) + 1
    if nw < 30:
        return out
    wc = pd.Series(np.asarray(closes, float)).groupby(codes).last().to_numpy()
    e13 = pd.Series(wc).ewm(span=13, adjust=False).mean().to_numpy()
    w_e = np.zeros(nw, bool)
    w_e[1:] = e13[1:] < e13[:-1]
    prev = np.clip(codes - 1, 0, None)
    return np.where(codes >= 1, w_e[prev], False)


def swing_exitinval_exit_reason(
    df: pd.DataFrame, entry_day: str, entry_price: float, atr_at_entry: float, running_max_close: float,
) -> tuple:
    """Exit for the exitinval tags, replaying every completed bar after entry_day in order (so a
    skipped/missed scan day cannot hide an event), same per-bar order as the research simulate():
    (1) open <= stop -> stop_hit; low <= stop -> stop_hit (intrabar; the live protection is the
    resting Kotak SL, this is the paper/bookkeeping mirror); (2) weekly EMA13 turn-down onset
    (flag[j] and not flag[j-1]) -> signal_invalidation; (3) held >= 30 trading days ->
    max_hold_timeout. Returns (reason_or_None, updated_running_max_close)."""
    if len(df) == 0:
        return None, running_max_close
    dates = (df["Date"] if "Date" in df.columns else pd.Series(df.index)).astype(str).str[:10].to_numpy()
    closes = df["Close"].to_numpy(dtype=float)
    opens = df["Open"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    new_running_max = max(float(running_max_close or entry_price), float(closes[-1]))
    stop = swing_exitinval_stop(entry_price, atr_at_entry)
    flags = weekly_ema13_down_flags(df["Date"] if "Date" in df.columns else df.index, closes)
    held = 0
    for j in range(len(df)):
        if dates[j] <= str(entry_day)[:10]:
            continue
        held += 1
        if opens[j] <= stop or lows[j] <= stop:
            return "stop_hit", new_running_max
        if j >= 1 and flags[j] and not flags[j - 1]:
            return "signal_invalidation", new_running_max
        if held >= SWING_EXITINVAL_MAX_HOLD_DAYS:
            return "max_hold_timeout", new_running_max
    return None, new_running_max


def _swing_exitinval_adapter(df, entry_day, initial_stop, atr_at_entry, running_max_close):
    """Same signature as order_block_exit_reason & co. The entry price is recovered from the frozen
    stop (stop = entry - 6 x ATR, both stored at entry), so no extra column is needed."""
    return swing_exitinval_exit_reason(
        df, entry_day, float(initial_stop) + SWING_EXITINVAL_ATR_MULT * float(atr_at_entry),
        atr_at_entry, running_max_close)


def swing_obvp_exit_fn(strategy: str):
    """Exit function for an OB/VP swing position: exitinval for the new tags, the legacy
    chandelier exits for positions still carrying the old tags; None for any other tag."""
    if strategy in SWING_EXITINVAL_TAGS:
        return _swing_exitinval_adapter
    if strategy == "order_block_delta":
        return order_block_exit_reason
    if strategy == "volume_profile_poc":
        return volume_profile_poc_exit_reason
    return None


# ---- Power Play short mirror ("power fade") --------------------------------
#
# 2026-09-29, explicit user instruction ("Prep short mirror for others
# too") per CLAUDE.md's 2026-09-28 standing thumb rule. Mirrors
# _find_power_play_setup/power_play_entry_signal/power_play_exit_reason
# direction only - consolidation-depth/final-leg/peak-proximity/volume/
# ATR-stop/max-hold constants are all reused verbatim from the long side.
#
# One threshold genuinely cannot be reused verbatim, and the mirror is
# documented here rather than left as a silent asymmetry: the long side's
# launch requires a >=100% GAIN (price at least doubles, ratio >=2.0x) -
# a symmetric DOWN move of "-100%" is mathematically impossible (price
# floors at 0). The principled mirror is a LOG-RETURN symmetric shock: a
# 2x gain has log-return +ln(2) ~= +0.693; the equal-and-opposite shock is
# a HALVING (0.5x, -50%), log-return -ln(2) ~= -0.693. So
# POWER_PLAY_CRASH_MIN_LOSS_PCT_SHORT=50.0 (a halving) is the short
# mirror's launch criterion, not a naive reuse of "100" as a loss
# percentage (which would be nonsensical).
POWER_PLAY_CRASH_MIN_LOSS_PCT_SHORT = 50.0  # mirror of +100% via log-symmetry (2x <-> 0.5x)


def _find_power_play_setup_short(df: pd.DataFrame) -> dict | None:
    """Short mirror of _find_power_play_setup: searches for a tight
    consolidation ("flag") immediately preceded by a crash of at least
    POWER_PLAY_CRASH_MIN_LOSS_PCT_SHORT within POWER_PLAY_LAUNCH_MAX_DAYS
    bars. Returns {"consol_high", "consol_low"} for the first valid
    (crash, flag) pair found, else None."""
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    i = len(df) - 1
    for consol_len in range(POWER_PLAY_CONSOL_MAX_DAYS, POWER_PLAY_CONSOL_MIN_DAYS - 1, -1):
        consol_start = i - consol_len
        if consol_start < POWER_PLAY_PEAK_PROXIMITY_DAYS:
            continue
        consol_highs = highs[consol_start:i]
        consol_lows = lows[consol_start:i]
        if len(consol_highs) == 0:
            continue
        consol_high = float(np.max(consol_highs))
        consol_low = float(np.min(consol_lows))
        if consol_high <= 0:
            continue
        depth_pct = 100.0 * (consol_high - consol_low) / consol_high
        if depth_pct > POWER_PLAY_CONSOL_MAX_DEPTH_PCT:
            continue

        final_leg_start = max(consol_start, i - POWER_PLAY_FINAL_LEG_DAYS)
        final_highs = highs[final_leg_start:i]
        final_lows = lows[final_leg_start:i]
        if len(final_highs) == 0:
            continue
        final_leg_pct = 100.0 * (float(np.max(final_highs)) - float(np.min(final_lows))) / consol_high
        if final_leg_pct > POWER_PLAY_FINAL_LEG_MAX_PCT:
            continue

        crash_start = max(0, consol_start - POWER_PLAY_LAUNCH_MAX_DAYS)
        crash_highs = highs[crash_start:consol_start]
        crash_lows = lows[crash_start:consol_start]
        if len(crash_lows) < POWER_PLAY_PEAK_PROXIMITY_DAYS:
            continue
        trough_rel = int(np.argmin(crash_lows))
        if trough_rel < len(crash_lows) - POWER_PLAY_PEAK_PROXIMITY_DAYS:
            continue  # the trough isn't near where the flag begins - not a clean crash-pole
        crash_low = float(crash_lows[trough_rel])
        if crash_low < consol_low * 0.98:
            continue  # a real flag stays above its own pole's bottom
        high_before_trough = float(np.max(crash_highs[: trough_rel + 1]))
        if high_before_trough <= 0:
            continue
        loss_pct = 100.0 * (high_before_trough - crash_low) / high_before_trough
        if loss_pct < POWER_PLAY_CRASH_MIN_LOSS_PCT_SHORT:
            continue

        return {"consol_high": consol_high, "consol_low": consol_low}
    return None


def power_play_entry_signal_short(df: pd.DataFrame) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a Power Play short
    ("power fade") entry: a valid _find_power_play_setup_short flag +
    today's close breaking below the flag's low on a volume surge. Returns
    None if no signal fires, else {"entry_price", "stop_loss",
    "atr_at_entry"}."""
    setup = _find_power_play_setup_short(df)
    if setup is None:
        return None
    closes = df["Close"].to_numpy(dtype=float)
    volumes = df["Volume"].to_numpy(dtype=float)
    i = len(df) - 1
    if closes[i] >= setup["consol_low"]:
        return None
    vol_avg = pd.Series(volumes).rolling(POWER_PLAY_VOL_LOOKBACK).mean().shift(1).to_numpy()
    if np.isnan(vol_avg[i]) or vol_avg[i] <= 0 or volumes[i] < POWER_PLAY_VOL_SURGE_MULT * vol_avg[i]:
        return None
    atr = _swing_atr(df, n=POWER_PLAY_ATR_N)
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None
    stop_loss = setup["consol_high"]
    if stop_loss <= closes[i]:
        return None
    return {"entry_price": closes[i], "stop_loss": stop_loss, "atr_at_entry": float(atr[i])}


def power_play_exit_reason_short(
    df: pd.DataFrame, entry_day: str, initial_stop: float, atr_at_entry: float, running_min_close: float,
) -> tuple:
    """Short mirror of power_play_exit_reason: chandelier trail (running
    TROUGH close plus POWER_PLAY_ATR_STOP_MULT x the ATR frozen at entry)
    ratcheting DOWN only, plus the same POWER_PLAY_MAX_HOLD_DAYS timeout.
    Returns (exit_reason_or_None, updated_running_min_close)."""
    if len(df) == 0:
        return None, running_min_close
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    new_running_min = min(running_min_close, closes[i])
    trail_stop = new_running_min + POWER_PLAY_ATR_STOP_MULT * atr_at_entry
    current_stop = min(initial_stop, trail_stop)
    if closes[i] >= current_stop:
        return "trail_stop_hit", new_running_min
    held_days = int(np.sum(dates > entry_day))
    if held_days >= POWER_PLAY_MAX_HOLD_DAYS:
        return "max_hold_timeout", new_running_min
    return None, new_running_min


def gap_and_go_entry_signal(df: pd.DataFrame) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a Gap and Go entry -
    identical rules/thresholds to the validated research workflow
    (swing-gap-and-go-5y-research.yml): today's Open gaps up
    >=SWING_GAP_PCT_THRESHOLD% above yesterday's Close, today closes green
    and in the upper half of its Open-High range, and Volume exceeds
    SWING_VOL_MULT x its trailing 20-day average. Returns None if no signal
    fires, else {"entry_price", "stop_loss", "gap_low"} for the caller to
    size and open a position with. `df` must have Open/High/Low/Close/
    Volume columns, oldest row first, at least
    max(SWING_ATR_N, SWING_VOL_AVG_LOOKBACK) + 1 rows."""
    n = len(df)
    min_lookback = max(SWING_ATR_N, SWING_VOL_AVG_LOOKBACK) + 1
    if n < min_lookback:
        return None
    opens = df["Open"].to_numpy(dtype=float)
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    closes = df["Close"].to_numpy(dtype=float)
    volumes = df["Volume"].to_numpy(dtype=float)
    atr = _swing_atr(df)
    vol_avg = pd.Series(volumes).rolling(SWING_VOL_AVG_LOOKBACK).mean().to_numpy()
    i = n - 1
    prev_close = closes[i - 1]
    if prev_close <= 0 or np.isnan(atr[i]) or atr[i] <= 0 or np.isnan(vol_avg[i]):
        return None
    gap_pct = (opens[i] - prev_close) / prev_close * 100
    gapped_up = gap_pct >= SWING_GAP_PCT_THRESHOLD
    held_gap = closes[i] > opens[i]
    closed_strong = closes[i] >= opens[i] + 0.5 * (highs[i] - opens[i])
    vol_confirmed = volumes[i] > vol_avg[i] * SWING_VOL_MULT
    if not (gapped_up and held_gap and closed_strong and vol_confirmed):
        return None
    entry_price = closes[i]
    stop_loss = entry_price - SWING_ATR_STOP_MULT * atr[i]
    if stop_loss >= entry_price:
        return None
    return {"entry_price": entry_price, "stop_loss": stop_loss, "gap_low": lows[i]}


def gap_and_go_exit_reason(df: pd.DataFrame, entry_day: str, stop_loss: float, gap_low: float) -> str | None:
    """Evaluates ONLY the last row of `df` (today) for a Gap and Go exit, for
    a position already open. Priority matches the validated research
    workflow exactly: stop_hit > gap_filled > max_hold_timeout. Returns None
    if the position should stay open. `entry_day` is the IST date
    (YYYY-MM-DD) the position was opened; `df`'s Date column (oldest first,
    last row = today) is used to count trading days held since then,
    matching the research workflow's index-difference definition."""
    if len(df) == 0:
        return None
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    if closes[i] <= stop_loss:
        return "stop_hit"
    if closes[i] < gap_low:
        return "gap_filled"
    held_days = int(np.sum(dates > entry_day))
    if held_days >= SWING_GAP_AND_GO_MAX_HOLD_DAYS:
        return "max_hold_timeout"
    return None


def gap_and_go_entry_signal_short(df: pd.DataFrame) -> dict | None:
    """Short mirror of gap_and_go_entry_signal ("gap down and go", 2026-09-
    29, explicit user instruction "Prep short mirror for others too" per
    CLAUDE.md's 2026-09-28 standing thumb rule). Evaluates ONLY the last
    row of `df` (today): today's Open gaps DOWN >=SWING_GAP_PCT_THRESHOLD%
    below yesterday's Close, today closes red and in the lower half of its
    Low-Open range, and Volume exceeds SWING_VOL_MULT x its trailing 20-
    day average. All constants reused verbatim from the long side, only
    comparison directions inverted. Returns None if no signal fires, else
    {"entry_price", "stop_loss", "gap_high"} for the caller to size and
    open a position with."""
    n = len(df)
    min_lookback = max(SWING_ATR_N, SWING_VOL_AVG_LOOKBACK) + 1
    if n < min_lookback:
        return None
    opens = df["Open"].to_numpy(dtype=float)
    highs = df["High"].to_numpy(dtype=float)
    lows = df["Low"].to_numpy(dtype=float)
    closes = df["Close"].to_numpy(dtype=float)
    volumes = df["Volume"].to_numpy(dtype=float)
    atr = _swing_atr(df)
    vol_avg = pd.Series(volumes).rolling(SWING_VOL_AVG_LOOKBACK).mean().to_numpy()
    i = n - 1
    prev_close = closes[i - 1]
    if prev_close <= 0 or np.isnan(atr[i]) or atr[i] <= 0 or np.isnan(vol_avg[i]):
        return None
    gap_pct = (prev_close - opens[i]) / prev_close * 100
    gapped_down = gap_pct >= SWING_GAP_PCT_THRESHOLD
    held_gap = closes[i] < opens[i]
    closed_weak = closes[i] <= opens[i] - 0.5 * (opens[i] - lows[i])
    vol_confirmed = volumes[i] > vol_avg[i] * SWING_VOL_MULT
    if not (gapped_down and held_gap and closed_weak and vol_confirmed):
        return None
    entry_price = closes[i]
    stop_loss = entry_price + SWING_ATR_STOP_MULT * atr[i]
    if stop_loss <= entry_price:
        return None
    return {"entry_price": entry_price, "stop_loss": stop_loss, "gap_high": highs[i]}


def gap_and_go_exit_reason_short(df: pd.DataFrame, entry_day: str, stop_loss: float, gap_high: float) -> str | None:
    """Short mirror of gap_and_go_exit_reason. Evaluates ONLY the last row
    of `df` (today) for a Gap and Go short exit, for a position already
    open. Priority matches the long side exactly: stop_hit > gap_filled >
    max_hold_timeout. Returns None if the position should stay open."""
    if len(df) == 0:
        return None
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    if closes[i] >= stop_loss:
        return "stop_hit"
    if closes[i] > gap_high:
        return "gap_filled"
    held_days = int(np.sum(dates > entry_day))
    if held_days >= SWING_MAX_HOLD_DAYS:
        return "max_hold_timeout"
    return None


# ---- Failed Breakout short ("bull trap") - 2026-09-30 ----------------------
#
# Explicit user instruction ("Read bout it and backtest") - a genuinely new
# candidate, distinct from every other short_sell strategy already
# registered (RESEARCH-STAGE ONLY here, same as this file's other
# not-yet-validated additions until a replay confirms real numbers):
#
# Standard technical-analysis definition: price breaks out to a new high
# above a well-established resistance/consolidation ceiling on the way up,
# but the breakout FAILS to hold - within a few sessions, price reverses
# back below that ceiling, trapping the breakout buyers who bought the new
# high. This is the classic "bull trap." Short entry fires on the failure
# (the day price closes back below the resistance it had broken above),
# not on the breakout itself. Swing timeframe (1d) - a multi-day
# breakout/failure pattern, matching how this file's other book-derived
# swing strategies (Minervini VCP, Power Play) are shaped.
FAILED_BREAKOUT_RESISTANCE_LOOKBACK_DAYS = 60  # window used to establish the resistance ceiling
FAILED_BREAKOUT_CONSOL_EXCLUDE_DAYS = 10       # most recent N days excluded from that ceiling calc - this is where the breakout attempt itself happens
FAILED_BREAKOUT_MIN_BREAKOUT_PCT = 1.0         # breakout must clear the ceiling by at least this % to count as a genuine attempt, not noise
FAILED_BREAKOUT_MAX_DAYS_SINCE_BREAKOUT = 7    # the failure/reversal must be confirmed within this many days of the breakout bar
FAILED_BREAKOUT_ATR_N = 14
FAILED_BREAKOUT_ATR_STOP_MULT = 2.0            # matches MINERVINI_ATR_STOP_MULT/POWER_PLAY_ATR_STOP_MULT's own chandelier convention
FAILED_BREAKOUT_MAX_HOLD_DAYS = 30


def _find_failed_breakout_setup(df: pd.DataFrame) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a failed-breakout
    setup: an established resistance ceiling (the highest High over
    FAILED_BREAKOUT_RESISTANCE_LOOKBACK_DAYS, ending
    FAILED_BREAKOUT_CONSOL_EXCLUDE_DAYS days ago), a genuine breakout bar
    within the more recent exclude window that cleared that ceiling by
    FAILED_BREAKOUT_MIN_BREAKOUT_PCT%, within FAILED_BREAKOUT_MAX_DAYS_
    SINCE_BREAKOUT of today, and today's own Close now back BELOW the
    ceiling (the failure/reversal confirmation). Returns None if no such
    setup exists, else {"resistance", "breakout_high"} (the highest point
    reached since the breakout bar, for stop placement)."""
    n = len(df)
    i = n - 1
    resistance_start = i - FAILED_BREAKOUT_CONSOL_EXCLUDE_DAYS - FAILED_BREAKOUT_RESISTANCE_LOOKBACK_DAYS
    resistance_end = i - FAILED_BREAKOUT_CONSOL_EXCLUDE_DAYS  # exclusive
    if resistance_start < 0 or resistance_end <= resistance_start:
        return None
    highs = df["High"].to_numpy(dtype=float)
    closes = df["Close"].to_numpy(dtype=float)
    resistance = float(np.max(highs[resistance_start:resistance_end]))
    if resistance <= 0:
        return None
    breakout_idx = None
    for j in range(resistance_end, i):  # excludes today itself
        if closes[j] >= resistance * (1 + FAILED_BREAKOUT_MIN_BREAKOUT_PCT / 100):
            breakout_idx = j  # keep the MOST RECENT qualifying bar
    if breakout_idx is None:
        return None
    if (i - breakout_idx) > FAILED_BREAKOUT_MAX_DAYS_SINCE_BREAKOUT:
        return None
    if closes[i] >= resistance:
        return None  # hasn't failed yet
    breakout_high = float(np.max(highs[breakout_idx:i]))
    return {"resistance": resistance, "breakout_high": breakout_high}


def failed_breakout_entry_signal_short(df: pd.DataFrame) -> dict | None:
    """Evaluates ONLY the last row of `df` (today) for a Failed Breakout
    short entry. Returns None if no signal fires, else {"entry_price",
    "stop_loss", "atr_at_entry"} - same return shape as every other swing
    entry signal in this file, for the caller to size and open a position
    with. Stop sits above the HIGHEST point the failed breakout actually
    reached (breakout_high), not just above the resistance level itself -
    a tighter stop there would risk being clipped by the breakout's own
    overshoot before the reversal that defines this setup even completes."""
    setup = _find_failed_breakout_setup(df)
    if setup is None:
        return None
    closes = df["Close"].to_numpy(dtype=float)
    i = len(df) - 1
    entry_price = closes[i]
    stop_loss = setup["breakout_high"]
    if stop_loss <= entry_price:
        return None
    atr = _swing_atr(df, n=FAILED_BREAKOUT_ATR_N)
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None
    return {"entry_price": entry_price, "stop_loss": stop_loss, "atr_at_entry": float(atr[i])}


def failed_breakout_exit_reason_short(
    df: pd.DataFrame, entry_day: str, initial_stop: float, atr_at_entry: float, running_min_close: float,
) -> tuple:
    """Short mirror of minervini_vcp_exit_reason/power_play_exit_reason's
    own chandelier-trail shape: a trailing stop (running trough close
    since entry PLUS a fixed ATR multiple frozen at entry) that only ever
    ratchets DOWN, plus a FAILED_BREAKOUT_MAX_HOLD_DAYS timeout.
    `running_min_close` is the running trough close carried forward by the
    caller since entry (starts at entry_price - the short mirror of the
    long-side functions' running_max_close). Returns (exit_reason_or_None,
    updated_running_min_close)."""
    if len(df) == 0:
        return None, running_min_close
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    new_running_min = min(running_min_close, closes[i])
    trail_stop = new_running_min + FAILED_BREAKOUT_ATR_STOP_MULT * atr_at_entry
    current_stop = min(initial_stop, trail_stop)
    if closes[i] >= current_stop:
        return "trail_stop_hit", new_running_min
    held_days = int(np.sum(dates > entry_day))
    if held_days >= FAILED_BREAKOUT_MAX_HOLD_DAYS:
        return "max_hold_timeout", new_running_min
    return None, new_running_min


# ---- Gap-Up Fade short - 2026-09-30 ----------------------------------------
#
# Explicit user instruction ("Read bout it and backtest") - a genuinely new
# candidate, the MIRROR-OPPOSITE of gap_and_go_short_fade (which is a "gap
# DOWN and continue" momentum trade, not a fade) and distinct from
# gap_and_go itself (which requires the gap to HOLD, not fail).
#
# Standard technical-analysis definition: a stock gaps UP strongly at the
# open (often on news/hype), but shows clear signs of failing to hold that
# gap during the session - the classic sign is price falling back below
# its own opening print, meaning the initial buying enthusiasm has already
# reversed. Short entry fires on that reversal-below-open confirmation, not
# on the gap itself. Intraday timeframe (5m) - a same-session fade/reversal
# trade, matching this file's other intraday short mechanics
# (_vwap_mean_reversion_short_entry) rather than the swing engine.
GAP_UP_FADE_GAP_PCT_THRESHOLD = 3.0      # gap up >= this % from the prior day's close - matches SWING_GAP_PCT_THRESHOLD's own magnitude for a gap-based setup
GAP_UP_FADE_MIN_BARS_INTO_SESSION = 3    # give the open a few 5m bars to establish before judging failure, avoids pure open-print noise
GAP_UP_FADE_ATR_N = 14
GAP_UP_FADE_ATR_STOP_MULT = 1.5
GAP_UP_FADE_MAX_HOLD_MINUTES = 120.0     # same style/magnitude as universal_score's own max_hold_minutes - a same-day fade trade, not a multi-day hold


def gap_up_fade_entry_signal_short(df: pd.DataFrame) -> dict | None:
    """Evaluates ONLY the last row of `df` (today's most recent intraday
    bar) for a Gap-Up Fade short entry: today's session Open gapped up
    >=GAP_UP_FADE_GAP_PCT_THRESHOLD% above yesterday's Close, at least
    GAP_UP_FADE_MIN_BARS_INTO_SESSION bars have printed today, and the
    current Close has fallen back BELOW today's own Open (the gap has
    failed to hold). Returns None if no signal fires, else {"entry_price",
    "stop_loss", "atr_at_entry"}. `df` must be a multi-day intraday series
    (oldest first) with a Date column parseable to a date; genuinely
    bar-size-agnostic (the entry logic below never assumes 5m specifically
    beyond GAP_UP_FADE_MIN_BARS_INTO_SESSION's own choice of magnitude)."""
    if len(df) == 0:
        return None
    dates = pd.to_datetime(df["Date"]).dt.strftime("%Y-%m-%d").to_numpy()
    today_str = dates[-1]
    today_idx = np.where(dates == today_str)[0]
    if len(today_idx) < GAP_UP_FADE_MIN_BARS_INTO_SESSION:
        return None
    session_start = int(today_idx[0])
    if session_start == 0:
        return None  # no prior day's bar at all to measure the gap against
    closes = df["Close"].to_numpy(dtype=float)
    opens = df["Open"].to_numpy(dtype=float)
    highs = df["High"].to_numpy(dtype=float)
    prev_close = closes[session_start - 1]
    if prev_close <= 0:
        return None
    today_open = opens[session_start]
    gap_pct = (today_open - prev_close) / prev_close * 100
    if gap_pct < GAP_UP_FADE_GAP_PCT_THRESHOLD:
        return None
    i = len(df) - 1
    if closes[i] >= today_open:
        return None  # still holding at/above the open - gap hasn't failed yet
    today_high_so_far = float(np.max(highs[session_start: i + 1]))
    entry_price = closes[i]
    stop_loss = today_high_so_far
    if stop_loss <= entry_price:
        return None
    atr = _swing_atr(df, n=GAP_UP_FADE_ATR_N)
    if np.isnan(atr[i]) or atr[i] <= 0:
        return None
    return {"entry_price": entry_price, "stop_loss": stop_loss, "atr_at_entry": float(atr[i])}


def gap_up_fade_exit_reason_short(
    df: pd.DataFrame, entry_ts: str, initial_stop: float, atr_at_entry: float, running_min_close: float,
) -> tuple:
    """Evaluates ONLY the last row of `df` for a Gap-Up Fade short exit:
    the same chandelier-trail mechanics as this file's swing strategies
    (running trough close since entry plus a fixed ATR multiple frozen at
    entry, only ever ratcheting down), plus a GAP_UP_FADE_MAX_HOLD_MINUTES
    intraday timeout - this is a same-session fade trade, not a multi-day
    hold, so the timeout is minutes-based like universal_score's own
    max_hold_minutes, not a day count. `entry_ts` is the entry bar's own
    Date value (as a string parseable the same way `df["Date"]` is),
    used to compute elapsed minutes since entry. Returns
    (exit_reason_or_None, updated_running_min_close)."""
    if len(df) == 0:
        return None, running_min_close
    closes = df["Close"].to_numpy(dtype=float)
    i = len(df) - 1
    new_running_min = min(running_min_close, closes[i])
    trail_stop = new_running_min + GAP_UP_FADE_ATR_STOP_MULT * atr_at_entry
    current_stop = min(initial_stop, trail_stop)
    if closes[i] >= current_stop:
        return "trail_stop_hit", new_running_min
    held_minutes = (pd.Timestamp(df["Date"].iloc[i]) - pd.Timestamp(entry_ts)).total_seconds() / 60.0
    if held_minutes >= GAP_UP_FADE_MAX_HOLD_MINUTES:
        return "max_hold_timeout", new_running_min
    return None, new_running_min


