# 2026-09-28: lower-circuit guard - explicit user instruction, backed by a
# live example (POLICYBZR.NS, 2026-09-23 - _liquidity_gate's own flat-
# tape/zero-volume checks did NOT reliably catch this: a circuit-locked
# stock can still show nonzero volume/turnover and non-identical closes
# within any single 3-bar lookback window, e.g. during the burst that
# drove it into the lock, while being functionally frozen and untradeable
# for the rest of the session). NSE's own circuit bands (2%/5%/10%/20%
# depending on the stock, occasionally none for the largest caps) are set
# relative to the PREVIOUS DAY's closing price - a genuinely different
# signal from tape flatness, and a more direct match for what "hit lower
# circuit" actually means. See _likely_lower_circuit_locked's own
# docstring for why this is a conservative universal floor, not an exact
# per-symbol circuit check.
LOWER_CIRCUIT_GUARD_PCT = 9.0


def _atr_series(df: pd.DataFrame, period: int = 14) -> pd.Series:
    """True-range rolling-mean ATR (Wilder-style approximation, same class
    of formula the existing chandelier-exit strategy's own atr_period
    already uses elsewhere in add_strategy_signal) - the FULL series, not
    just the last value, so callers needing both "current ATR" and "ATR's
    own recent average" (the rejection filter below) derive both from one
    computation instead of two."""
    high = df["High"].to_numpy(dtype=float)
    low = df["Low"].to_numpy(dtype=float)
    close = df["Close"].to_numpy(dtype=float)
    prev_close = np.roll(close, 1)
    if len(prev_close):
        prev_close[0] = close[0]
    tr = np.maximum(high - low, np.maximum(np.abs(high - prev_close), np.abs(low - prev_close)))
    return pd.Series(tr).rolling(period).mean()


def _compute_atr_value(df: pd.DataFrame, period: int = 14) -> float | None:
    """Last bar's ATR only - see _atr_series for the full series."""
    series = _atr_series(df, period)
    val = series.iloc[-1] if len(series) else None
    return float(val) if val is not None and pd.notna(val) else None


def _compute_rsi_value(closes: np.ndarray, period: int = UNIVERSAL_RSI_PERIOD) -> float | None:
    """Standalone RSI reader for the universal engine, same Wilder-style
    formula add_strategy_signal's own rsi_reversal branch already uses -
    factored out fresh here (not reused from there) so this new engine can
    never perturb that existing, already-backtested strategy's exact
    numbers. Returns the LAST bar's RSI, or None if there isn't enough
    history yet."""
    if len(closes) < period + 1:
        return None
    s = pd.Series(closes)
    delta = s.diff()
    gain = delta.clip(lower=0).rolling(period).mean()
    loss = (-delta.clip(upper=0)).rolling(period).mean()
    last_gain, last_loss = gain.iloc[-1], loss.iloc[-1]
    if pd.isna(last_gain) or pd.isna(last_loss):
        return None
    if last_loss == 0:
        return 100.0
    rs = last_gain / last_loss
    return float(100 - (100 / (1 + rs)))


def _compute_session_vwap_value(today_df: pd.DataFrame) -> float | None:
    """Session VWAP (cumulative typical-price*volume / cumulative volume,
    reset every session by definition) - the LAST bar's value only.
    Returns None on a zero-volume session (index tickers - Yahoo reports
    volume:0 for every index bar, the exact root cause
    docs/STRATEGY_LOG.md's own VWAP-batch rows #13-18 already document, so
    VWAP is genuinely undefined there) rather than a silently-wrong
    divide-by-zero read."""
    if len(today_df) == 0:
        return None
    vol = today_df["Volume"].to_numpy(dtype=float)
    if float(np.nansum(vol)) <= 0:
        return None
    typical = ((today_df["High"] + today_df["Low"] + today_df["Close"]) / 3.0).to_numpy(dtype=float)
    cum_vol = np.cumsum(vol)
    cum_tp_vol = np.cumsum(typical * vol)
    if cum_vol[-1] <= 0:
        return None
    vwap = cum_tp_vol[-1] / cum_vol[-1]
    return float(vwap) if np.isfinite(vwap) else None


def _swing_structure_bullish(df: pd.DataFrame, lookback: int = UNIVERSAL_STRUCTURE_LOOKBACK) -> bool | None:
    """Approximates SMC/Wyckoff-style higher-high/higher-low market
    structure (docs/STRATEGY_LOG.md rows #32/#35's own "swing-high/swing-
    low sequence" definition) with the simplest honest OHLCV read: split
    the trailing `lookback` bars into two equal halves and require BOTH
    the high and the low of the second half to exceed the first half's -
    price making a higher high AND a higher low over the window, not just
    drifting up on one lopsided bar. Returns None if there isn't enough
    history yet (never a silent False)."""
    if len(df) < lookback * 2:
        return None
    window = df.iloc[-lookback * 2:]
    first_half, second_half = window.iloc[:lookback], window.iloc[lookback:]
    return bool(second_half["High"].max() > first_half["High"].max()
                and second_half["Low"].min() > first_half["Low"].min())


def _relative_strength_bullish(symbol_closes: np.ndarray, index_closes: np.ndarray,
                                lookback: int = UNIVERSAL_RS_LOOKBACK) -> bool | None:
    """Is this symbol outperforming the reference index over the same
    trailing window (docs/STRATEGY_LOG.md's "select stronger instruments"
    read) - plain %-return comparison, no data source beyond the index
    fetch _compute_universal_entry_score's caller already does. Returns
    None if either series doesn't have enough history yet."""
    if len(symbol_closes) < lookback + 1 or len(index_closes) < lookback + 1:
        return None
    sym_ret = symbol_closes[-1] / symbol_closes[-lookback - 1] - 1
    idx_ret = index_closes[-1] / index_closes[-lookback - 1] - 1
    return bool(sym_ret > idx_ret)


def _index_trend_bullish(index_closes: np.ndarray, sma_fast: int, sma_slow: int, ma_type: str = "ema") -> bool | None:
    """Is the broad market itself trending up (docs/STRATEGY_LOG.md row
    #26's "avoid fighting broader market") - the same _moving_average
    fast>slow read this engine already trusts for the traded symbol's own
    trend, applied to UNIVERSAL_REFERENCE_INDEX's closes instead."""
    if len(index_closes) < max(sma_fast, sma_slow):
        return None
    return bool(_moving_average(index_closes, sma_fast, ma_type) > _moving_average(index_closes, sma_slow, ma_type))


# ---- TREND-down short mirrors (2026-09-29, explicit user instruction: "I
# need at least one strategy for the short sell... this helps me downward
# trend of market... it's a must have" - built after the RANGE VWAP-spike
# short mirror's three validation passes (target-cluster fix, staged
# ladder, stricter entry filter) all left PFnet pinned at 0.17-0.26,
# nowhere near viable. TREND is the ONE long-side engine in this codebase
# with genuinely positive validated evidence (PFnet 0.09-0.13 in
# universal-score-entry-floor-research.yml, vs RANGE's much weaker
# ~0.06), so mirroring IT downward - not inventing a new signal from
# scratch - is the most evidence-grounded next candidate. Exactly the
# "TREND-down (8-factor score) mirror" CLAUDE.md already flagged as
# scoped out of the original short-selling pass ("a separate, larger
# undertaking, not a rule exception") - this is that undertaking.
# Every weight/threshold constant (UNIVERSAL_SCORE_WEIGHTS,
# UNIVERSAL_ENTRY_SCORE_MIN, UNIVERSAL_RVOL_*, UNIVERSAL_RSI_BAND,
# UNIVERSAL_MAX_ATR_MULT, UNIVERSAL_MAX_VWAP_EXTENSION_ATR,
# UNIVERSAL_MIN_REWARD_RISK, UNIVERSAL_STRUCTURE_LOOKBACK,
# UNIVERSAL_RS_LOOKBACK) is REUSED verbatim from the already-validated
# long side, never re-tuned for this mirror - "opposite setup, same
# role", the same architecture confirmed for the RANGE short mirror.

def _swing_structure_bearish(df: pd.DataFrame, lookback: int = UNIVERSAL_STRUCTURE_LOOKBACK) -> bool | None:
    """Mirror of _swing_structure_bullish: lower-high/lower-low market
    structure instead of higher-high/higher-low - require BOTH the high
    and the low of the second half of the trailing window to sit BELOW
    the first half's, not just one lopsided down bar."""
    if len(df) < lookback * 2:
        return None
    window = df.iloc[-lookback * 2:]
    first_half, second_half = window.iloc[:lookback], window.iloc[lookback:]
    return bool(second_half["High"].max() < first_half["High"].max()
                and second_half["Low"].min() < first_half["Low"].min())


def _relative_strength_bearish(symbol_closes: np.ndarray, index_closes: np.ndarray,
                                lookback: int = UNIVERSAL_RS_LOOKBACK) -> bool | None:
    """Mirror of _relative_strength_bullish: is this symbol UNDERperforming
    the reference index over the same trailing window - the natural short
    candidate is the laggard, not the leader."""
    if len(symbol_closes) < lookback + 1 or len(index_closes) < lookback + 1:
        return None
    sym_ret = symbol_closes[-1] / symbol_closes[-lookback - 1] - 1
    idx_ret = index_closes[-1] / index_closes[-lookback - 1] - 1
    return bool(sym_ret < idx_ret)


def _index_trend_bearish(index_closes: np.ndarray, sma_fast: int, sma_slow: int, ma_type: str = "ema") -> bool | None:
    """Mirror of _index_trend_bullish: is the broad market itself trending
    down - same "avoid fighting the broader market" rationale, just
    checking the fast MA is BELOW the slow one instead of above."""
    if len(index_closes) < max(sma_fast, sma_slow):
        return None
    return bool(_moving_average(index_closes, sma_fast, ma_type) < _moving_average(index_closes, sma_slow, ma_type))


# ==== Two-regime router (2026-09-10) ========================================
# Explicit user instruction, final decision after the #1/#9 discussion:
# "Option B - but only the two-regime version." The universal score above
# is not wrong - it's a good TREND-CONTINUATION engine being asked to
# operate in every market state, including ranging conditions where it
# structurally can't win (see the VWAP-mean-reversion worked example: a
# textbook oversold dip-buy scores near 0/100 on this engine, because
# every one of its 8 factors rewards the same "price going up" read).
# Fix chosen: keep the trend engine exactly as-is, gate it behind a small
# regime classifier, and route RANGE-regime symbols to the one strategy
# in the whole docs/STRATEGY_LOG.md catalog with real positive gross
# backtest evidence (row #13, VWAP mean reversion: 60 trades, 70% win
# rate, +Rs62.3) instead. Explicitly NOT the full regime x strategy-
# family matrix from the declined probabilistic-EV framework - two
# regimes, two engines, nothing more.
#
# "The objective should be: prove that selecting the correct engine for
# the current market state improves net expectancy after costs. If
# regime routing does not improve out-of-sample results, remove it." -
# NOT yet proven either way; this ships live (same real-money go-ahead
# as the rest of this engine) as a hypothesis to validate via a real
# /sweep once it has trade history, not as a confirmed edge.

def _classify_market_regime(df: pd.DataFrame, sma_fast: int, sma_slow: int, ma_type: str = "ema") -> str:
    """TREND or RANGE - the entire regime gate, deliberately the simplest
    version that reuses EXISTING, already-justified machinery rather than
    inventing a new indicator: _trend_confidence (the same normal-CDF
    statistical read the trend_weakened exit and the trend engine's own
    entry gate already trust) at the SAME TREND_WEAKENED_MIN_CONFIDENCE
    bar, AND a genuine higher-high/higher-low structure
    (_swing_structure_bullish) - BOTH must agree to call it TREND.

    Deliberately AND, not OR - found live while validating this exact
    fix: _trend_confidence's z-score is sensitive to a SINGLE sharp bar
    (a one-bar dip at the end of an otherwise genuinely ranging series
    spiked confidence to >0.99 with no real sustained trend behind it,
    which would have routed exactly the oversold-dip-buy setup this
    router exists to catch right back into the trend engine that
    structurally can't score it). Requiring _swing_structure_bullish too
    (an actual higher-high/higher-low sequence across two windows, not a
    single-bar statistic) filters that false positive out while still
    correctly reading a genuine clean uptrend as TREND (both conditions
    agree there).

    Never raises on short history - _trend_confidence/_swing_structure_
    bullish both already degrade to 0.0/None rather than crashing, and
    None reads as "not established" here, same as False."""
    closes = df["Close"].to_numpy(dtype=float)
    trend_conf = _trend_confidence(closes, sma_fast, sma_slow, ma_type)
    structure = _swing_structure_bullish(df)
    if trend_conf >= TREND_WEAKENED_MIN_CONFIDENCE and structure:
        return "trend"
    return "range"


def _vwap_deviation_z(today_df: pd.DataFrame) -> float | None:
    """Shared basis for _vwap_mean_reversion_entry and
    _range_regime_confidence: how many standard deviations today's
    latest close sits BELOW the session VWAP (session VWAP + expanding
    std-dev of price-vs-VWAP, same math as add_strategy_signal's own
    "vwap_mean_reversion" branch, docs/STRATEGY_LOG.md row #13, just
    scoped to today_df alone rather than that function's cross-day
    groupby). Positive when below VWAP (the RANGE regime's mean-
    reversion direction), negative when above.

    None (never a silent 0.0) on a zero-volume session (index tickers -
    same root cause _compute_session_vwap_value already documents) or
    with fewer than 2 bars today (can't compute a standard deviation
    yet)."""
    if len(today_df) < 2:
        return None
    vol = today_df["Volume"].to_numpy(dtype=float)
    if float(np.nansum(vol)) <= 0:
        return None
    typical = ((today_df["High"] + today_df["Low"] + today_df["Close"]) / 3.0).to_numpy(dtype=float)
    cum_vol = np.cumsum(vol)
    with np.errstate(invalid="ignore", divide="ignore"):
        vwap_series = np.cumsum(typical * vol) / np.where(cum_vol > 0, cum_vol, np.nan)
    closes = today_df["Close"].to_numpy(dtype=float)
    dev = pd.Series(closes - vwap_series).expanding().std()
    last_dev, last_vwap = dev.iloc[-1], vwap_series[-1]
    if pd.isna(last_dev) or pd.isna(last_vwap) or last_dev <= 0:
        return None
    return float((last_vwap - closes[-1]) / last_dev)


def _vwap_mean_reversion_entry(today_df: pd.DataFrame, bb_std: float = 2.0) -> bool | None:
    """Live single-tick entry trigger for the RANGE regime: fires once
    the close is bb_std standard deviations below session VWAP (a fresh
    z-score test on _vwap_deviation_z). Returns only whether THIS bar is
    a fresh entry trigger (not the whole stateful holding series that
    add_strategy_signal's own vwap_mean_reversion branch returns for
    backtesting) since _auto_signal_core only ever calls this when there
    is no open position to begin with.

    None (never a silent False) whenever _vwap_deviation_z itself can't
    be computed yet - see its own docstring for exactly when."""
    z = _vwap_deviation_z(today_df)
    if z is None:
        return None
    return bool(z >= bb_std)


def _vwap_mean_reversion_short_entry(today_df: pd.DataFrame, bb_std: float = 2.0) -> bool | None:
    """Short mirror of _vwap_mean_reversion_entry (2026-09-29, explicit
    user instruction to implement short selling) - fires once the close
    is bb_std standard deviations ABOVE session VWAP. _vwap_deviation_z is
    already SIGNED (positive below VWAP, negative above - see its own
    docstring), so the mirror is simply the opposite-sign threshold, not a
    new indicator: z <= -bb_std instead of z >= bb_std. Formula validated
    in universal-score-range-short-research.yml before being ported here
    verbatim - not reinvented for live code.

    None (never a silent False) whenever _vwap_deviation_z itself can't be
    computed yet - see its own docstring for exactly when."""
    z = _vwap_deviation_z(today_df)
    if z is None:
        return None
    return bool(z <= -bb_std)


RANGE_CONFIDENCE_ENTRY_Z = 2.0  # must match _vwap_mean_reversion_entry's own
# bb_std default - the z-score an entry always clears by construction, so
# this is _range_regime_confidence's natural "just barely qualified" floor
# for confidence-proportional sizing (task #6).
RANGE_CONFIDENCE_FULL_Z = 4.0  # z-score at which RANGE confidence-proportional
# sizing saturates at full risk_per_trade_pct - explicit user choice
# 2026-09-21, a symmetric doubling of RANGE_CONFIDENCE_ENTRY_Z (a ~4-sigma
# VWAP deviation is rare, so most RANGE trades size well below max).
#
# A RANGE confidence-decay exit (range_confidence_weakened) was also tried
# here 2026-09-21 as the RANGE-regime analog of trend_weakened - two
# designs (decay at the entry bar itself, then a hysteresis buffer at half
# the entry bar) were both validated via the 52-symbol/60-day replay and
# BOTH badly broken the RANGE regime (win rate 10.3%->1.7%, then ->2.8%;
# 85% and then 65% of RANGE trades still cut short almost immediately).
# Per explicit user decision 2026-09-21, dropped entirely rather than
# tuned further - confidence-proportional sizing (validated, neutral/
# correct) is the only task #6 piece that shipped. Do not re-add this
# exit without a genuinely different design, discussed with the user
# first (not a threshold nudge on this same shape).


def _range_regime_confidence(today_df: pd.DataFrame) -> float | None:
    """RANGE-regime analog of _trend_confidence: how statistically
    extreme today's VWAP deviation is, via the SAME normal-CDF transform
    (_norm_cdf) _trend_confidence itself uses on its own z-score - not a
    new statistical concept, just _vwap_deviation_z (already computed
    internally by _vwap_mean_reversion_entry) exposed as a continuous
    0-1 read instead of a boolean. Explicit user instruction 2026-09-21
    (task #6, confidence-proportional sizing): RANGE previously had NO
    continuous confidence measure at all, only a boolean entry trigger -
    this is what that trigger's own z-score becomes once exposed.

    A RANGE entry only ever fires at z >= RANGE_CONFIDENCE_ENTRY_Z by
    construction, so this never reads below _norm_cdf(RANGE_CONFIDENCE_ENTRY_Z)
    (~0.977) at entry time - it can still fall below that on a LATER tick
    as price reverts back toward VWAP. Used for confidence-proportional
    sizing only (task #6) - a RANGE confidence-decay exit built on this
    same read was tried and dropped; see RANGE_CONFIDENCE_FULL_Z's comment.

    None whenever _vwap_deviation_z can't be computed yet - never
    fabricated."""
    z = _vwap_deviation_z(today_df)
    if z is None:
        return None
    return _norm_cdf(z)


def _range_regime_short_confidence(today_df: pd.DataFrame) -> float | None:
    """Short mirror of _range_regime_confidence (2026-09-29). z is negative
    for a short setup (price above VWAP - see _vwap_deviation_z), so this
    reads the magnitude of the ABOVE-vwap extension via _norm_cdf(-z),
    exactly as validated in universal-score-range-short-research.yml.
    A short entry only fires at z <= -RANGE_CONFIDENCE_ENTRY_Z by
    construction, so this never reads below _norm_cdf(RANGE_CONFIDENCE_ENTRY_Z)
    at entry time, same floor as the long side.

    None whenever _vwap_deviation_z can't be computed yet - never
    fabricated."""
    z = _vwap_deviation_z(today_df)
    if z is None:
        return None
    return _norm_cdf(-z)


CONFIDENCE_SIZE_FLOOR = 0.25  # explicit user choice 2026-09-21 (task #6): a
# trade that just barely clears its own entry confidence bar risks only
# 25% of risk_per_trade_pct, scaling linearly up to the full 100% as
# confidence rises toward its own regime's ceiling - see
# _confidence_size_multiplier.


def _confidence_size_multiplier(confidence: float, entry_min: float, full_at: float = 1.0) -> float:
    """Linear confidence-proportional sizing (explicit user instruction
    2026-09-21, task #6: "confidence should be directly proportional to
    the qty you take for entry into that trade"). Scales risk_per_trade_pct
    DOWN only - a trade at the bare entry_min confidence floor gets
    CONFIDENCE_SIZE_FLOOR (25%) of the normal risk; a trade at full_at or
    beyond gets the full 100%. Never scales ABOVE 1.0 - the existing
    risk_per_trade_pct cap (1-2% of capital) is a hard ceiling this only
    ever shrinks under, matching the standing real-money discipline that
    a stronger signal must never risk MORE than the agreed cap.

    full_at <= entry_min (a misconfigured/degenerate call) falls back to
    1.0 (no scaling) rather than dividing by zero or inverting the
    intended direction."""
    if full_at <= entry_min:
        return 1.0
    frac = (confidence - entry_min) / (full_at - entry_min)
    frac = max(0.0, min(1.0, frac))
    return CONFIDENCE_SIZE_FLOOR + (1.0 - CONFIDENCE_SIZE_FLOOR) * frac


def _liquidity_gate(df: pd.DataFrame) -> tuple[bool, list[str]]:
    """Hard, fail-closed, regime-agnostic pre-entry liquidity/price-action
    gate - see LIQUIDITY_GATE_LOOKBACK_BARS's own comment for the live
    screenshots that motivated this. Three independent checks over the
    last LIQUIDITY_GATE_LOOKBACK_BARS bars, ALL must pass:
      1. every bar has nonzero volume - a gap bar (nothing traded that
         interval) anywhere in the recent window means the tape isn't
         continuously traded.
      2. total turnover (sum of close*volume) over those bars is at
         least LIQUIDITY_MIN_15MIN_TURNOVER_INR - an ABSOLUTE floor, not
         relative to the symbol's own (possibly always-thin) history the
         way volume_ok/RVOL both are.
      3. price actually moved over the window (not every close is
         identical) - a frozen LTP means no real two-sided trading even
         where volume prints something.

    Fail-closed on insufficient history (fewer than
    LIQUIDITY_GATE_LOOKBACK_BARS bars total) - never a silent pass.
    Returns (passed, reasons); reasons is empty iff passed. Applied to
    BOTH regimes uniformly (tape quality is regime-agnostic) - see the
    entry_candle_bullish check inside _compute_universal_entry_score for
    the SEPARATE, TREND-only "buyers dominant on the entry candle" read
    (deliberately not applied to the RANGE/mean-reversion path, which by
    design buys INTO a down candle - see _vwap_mean_reversion_entry)."""
    lookback = LIQUIDITY_GATE_LOOKBACK_BARS
    if len(df) < lookback:
        return False, ["insufficient_history_for_liquidity_gate"]
    window = df.iloc[-lookback:]
    closes = window["Close"].to_numpy(dtype=float)
    volumes = window["Volume"].to_numpy(dtype=float)
    reasons = []
    if np.any(volumes <= 0):
        reasons.append("zero_volume_bar_in_recent_window")
    turnover = float(np.sum(closes * volumes))
    if turnover < LIQUIDITY_MIN_15MIN_TURNOVER_INR:
        reasons.append("turnover_below_minimum")
    if np.all(closes == closes[0]):
        reasons.append("price_not_moving")
    return (len(reasons) == 0), reasons


def _likely_lower_circuit_locked(df: pd.DataFrame, today_str: str,
                                  threshold_pct: float = LOWER_CIRCUIT_GUARD_PCT) -> bool:
    """True if the last available close is down threshold_pct% or more
    from the PREVIOUS trading day's own close - see LOWER_CIRCUIT_GUARD_PCT's
    own module comment for the live finding this closes (POLICYBZR.NS,
    2026-09-23) and why this is a separate, distinct check from
    _liquidity_gate's own tape-flatness read rather than a tuning of it.

    threshold_pct is a conservative universal floor (default 9%, just
    inside the tightest common NSE circuit bands of 10%/5%) - this app
    has no per-stock circuit-band metadata to check an EXACT band. A
    false negative (missing a 2%/5%-band stock's own tighter lock) is
    possible; a false positive is unlikely since every entry path here
    also requires its own bullish technical signal (TREND's 8-factor
    score or RANGE's mean-reversion trigger) on the SAME bar - a stock
    already down 9%+ rarely also satisfies either unless something
    structural (like a lock, or the sharp drop feeding straight into a
    mean-reversion trigger) is going on, which is exactly the failure
    mode this guards against.

    Fails OPEN (returns False, i.e. does NOT block entry) when there's no
    prior trading day in `df` yet (a newly-listed symbol, or the very
    first day this app has data for it) - refusing every symbol with
    thin history is worse than occasionally missing a genuine circuit
    day. `df` must carry a `date_local` column (every caller here already
    has one - see _auto_signal_core's own df preparation)."""
    if "date_local" not in df.columns or df.empty:
        return False
    prior_rows = df[df["date_local"] < today_str]
    if prior_rows.empty:
        return False
    prior_close = float(prior_rows["Close"].iloc[-1])
    if prior_close <= 0:
        return False
    last_close = float(df["Close"].iloc[-1])
    move_pct = (last_close - prior_close) / prior_close * 100
    return move_pct <= -threshold_pct


def _compute_universal_entry_score(
    df: pd.DataFrame, today_df: pd.DataFrame,
    volume_ok: bool, sma_fast_val: float | None, sma_slow_val: float | None,
    index_closes: np.ndarray | None, sma_fast: int, sma_slow: int, ma_type: str = "ema",
    vol_ratio: float | None = None,
) -> dict:
    """The engine's single entry decision - an 8-factor weighted score (see
    UNIVERSAL_SCORE_WEIGHTS) PLUS a separate set of hard rejection filters,
    exactly this session's own approved read: "given the market right now,
    should I trade" -> score >= UNIVERSAL_ENTRY_SCORE_MIN AND no rejection
    filter tripped -> entry_allowed.

    `volume_ok` is the unchanged hard liquidity gate (feeds
    `liquidity_inadequate` below only); `vol_ratio` (current bar's volume
    over its own rolling average - i.e. RVOL) is a SEPARATE read that
    drives the volume_breakout score component's actual gradient (weak/
    partial/full credit) - kept distinct on purpose, see
    UNIVERSAL_RVOL_PARTIAL_MULT/FULL_MULT's own comment for why they used
    to be the same signal counted twice.

    Never raises on missing/short history - every component degrades to
    "not scored" (None in `breakdown`, excluded from both the achieved
    score and max_score) rather than crashing or silently scoring 0.
    Returns a dict safe to drop straight into _auto_signal_core's own
    `result`: score, max_score, score_pct, breakdown, rejection_reasons,
    entry_allowed."""
    closes = df["Close"].to_numpy(dtype=float)
    last_close = float(closes[-1])
    breakdown: dict[str, float | None] = {}
    weights = dict(UNIVERSAL_SCORE_WEIGHTS)

    has_index = index_closes is not None and len(index_closes) >= max(sma_fast, sma_slow, UNIVERSAL_RS_LOOKBACK + 1)
    if not has_index:
        weights.pop("relative_strength", None)
        weights.pop("index_trend", None)

    vwap = _compute_session_vwap_value(today_df)
    breakdown["above_vwap"] = None if vwap is None else (weights["above_vwap"] if last_close > vwap else 0.0)

    if sma_fast_val is not None and sma_slow_val is not None:
        breakdown["ema_cross"] = weights["ema_cross"] if sma_fast_val > sma_slow_val else 0.0
    else:
        breakdown["ema_cross"] = None

    structure_ok = _swing_structure_bullish(df)
    breakdown["structure_hh_hl"] = None if structure_ok is None else (weights["structure_hh_hl"] if structure_ok else 0.0)

    resistance = float(df["High"].iloc[-(UNIVERSAL_STRUCTURE_LOOKBACK + 1):-1].max()) if len(df) > UNIVERSAL_STRUCTURE_LOOKBACK else None
    breakdown["breakout_resistance"] = None if resistance is None else (
        weights["breakout_resistance"] if last_close > resistance else 0.0
    )

    if vol_ratio is None:
        breakdown["volume_breakout"] = None
    elif vol_ratio >= UNIVERSAL_RVOL_FULL_MULT:
        breakdown["volume_breakout"] = weights["volume_breakout"]
    elif vol_ratio >= UNIVERSAL_RVOL_PARTIAL_MULT:
        breakdown["volume_breakout"] = weights["volume_breakout"] * 0.5
    else:
        breakdown["volume_breakout"] = 0.0

    rsi_val = _compute_rsi_value(closes)
    lo, hi = UNIVERSAL_RSI_BAND
    breakdown["rsi_band"] = None if rsi_val is None else (weights["rsi_band"] if lo <= rsi_val <= hi else 0.0)

    if has_index:
        rs_ok = _relative_strength_bullish(closes, index_closes)
        breakdown["relative_strength"] = weights["relative_strength"] if rs_ok else 0.0
        idx_ok = _index_trend_bullish(index_closes, sma_fast, sma_slow, ma_type)
        breakdown["index_trend"] = weights["index_trend"] if idx_ok else 0.0

    # Bug found writing this fix's own regression test (2026-09-10): this
    # used to be sum(weights.values()) unconditionally - which only ever
    # actually shrank for relative_strength/index_trend (popped from
    # `weights` above when has_index is False), NOT for any of the other
    # 6 components whenever THEY come back None (e.g. above_vwap on a
    # zero-volume session, structure_hh_hl/rsi_band on a symbol's first
    # ~20-40 bars of history). The docstring's own claim - "every
    # component degrades to not-scored, excluded from both score and
    # max_score" - was true for exactly 2 of 8 components and silently
    # false for the other 6, understating score_pct (denominator too
    # large) precisely when data is sparsest, e.g. early in a session -
    # the same "score looks too low right after the market opens" failure
    # class already fixed once for the pre-revamp SMA/trend read (see
    # _auto_signal_core's own 2026-09-09 comment on that exact bug for
    # orb_breakout). Now genuinely excludes any None component from both
    # sides of the ratio, matching the docstring for real.
    max_score = sum(weights[k] for k, v in breakdown.items() if v is not None)
    score = sum(v for v in breakdown.values() if v is not None)
    score_pct = round(100.0 * score / max_score, 2) if max_score else 0.0

    # ---- Rejection filters - independent of score, checked regardless ----
    rejection_reasons = []
    atr_series = _atr_series(df)
    atr_val = float(atr_series.iloc[-1]) if len(atr_series) and pd.notna(atr_series.iloc[-1]) else None
    atr_recent_mean = (
        float(atr_series.iloc[-20:].mean())
        if len(atr_series) >= 20 and atr_series.iloc[-20:].notna().all() else None
    )
    if atr_val is not None and atr_recent_mean and atr_val > UNIVERSAL_MAX_ATR_MULT * atr_recent_mean:
        rejection_reasons.append("atr_abnormally_wide")
    if vwap is not None and atr_val:
        if abs(last_close - vwap) > UNIVERSAL_MAX_VWAP_EXTENSION_ATR * atr_val:
            rejection_reasons.append("too_extended_from_vwap")
    if not volume_ok:
        rejection_reasons.append("liquidity_inadequate")
    liquidity_gate_ok, liquidity_gate_reasons = _liquidity_gate(df)
    if not liquidity_gate_ok:
        rejection_reasons.extend(liquidity_gate_reasons)
    # Entry-candle-bullish check (2026-09-14, explicit user instruction):
    # "The candle at which u r buying then its respective volume should
    # be in favour of the trade... if u r planning to buy then buyers in
    # the volume of last candle's should be dominant." No bid/ask feed
    # exists to split a candle's volume into buy/sell-initiated (same gap
    # _liquidity_gate's own docstring notes), so this uses the standard
    # OHLCV proxy for "buyers were in control this candle": close above
    # open. TREND-only, deliberately NOT applied to the RANGE regime -
    # _vwap_mean_reversion_entry buys INTO a down candle by design (a
    # dip below the lower band), so requiring a green candle there would
    # neuter the one strategy in this codebase with real positive
    # backtest evidence (docs/STRATEGY_LOG.md row #13).
    if "Open" in df.columns and len(df) >= 1:
        last_open = float(df["Open"].iloc[-1])
        if last_close <= last_open:
            rejection_reasons.append("entry_candle_not_bullish")
    if resistance is not None and len(df) > UNIVERSAL_STRUCTURE_LOOKBACK:
        risk_ref = last_close - float(df["Low"].iloc[-(UNIVERSAL_STRUCTURE_LOOKBACK + 1):].min())
        reward_ref = resistance - last_close
        # Only a meaningful rejection while price is still BELOW resistance
        # (reward_ref > 0) - once last_close has cleared it (the breakout
        # itself), this ratio stops being informative and is left to the
        # score above instead.
        if risk_ref > 0 and reward_ref > 0 and reward_ref / risk_ref < UNIVERSAL_MIN_REWARD_RISK:
            rejection_reasons.append("reward_risk_below_minimum")

    return {
        "score": round(score, 1), "max_score": max_score, "score_pct": score_pct,
        "breakdown": breakdown, "rejection_reasons": rejection_reasons,
        "entry_allowed": bool(score_pct >= UNIVERSAL_ENTRY_SCORE_MIN and not rejection_reasons),
    }


def _compute_universal_entry_score_short(
    df: pd.DataFrame, today_df: pd.DataFrame,
    volume_ok: bool, sma_fast_val: float | None, sma_slow_val: float | None,
    index_closes: np.ndarray | None, sma_fast: int, sma_slow: int, ma_type: str = "ema",
    vol_ratio: float | None = None,
) -> dict:
    """TREND-down mirror of _compute_universal_entry_score (2026-09-29,
    explicit user instruction: "I need at least one strategy for the
    short sell... must have" - see the module comment above
    _swing_structure_bearish for the full rationale). Every weight and
    threshold is REUSED verbatim from the long side (UNIVERSAL_SCORE_WEIGHTS,
    UNIVERSAL_ENTRY_SCORE_MIN, etc.) - only the DIRECTION of each factor
    and rejection filter is mirrored. volume_breakout/rsi_band/
    atr_abnormally_wide/too_extended_from_vwap/liquidity gates are kept
    IDENTICAL (direction-agnostic by nature - a volume spike, an extreme
    RSI reading, an abnormally wide ATR, or an over-extended VWAP distance
    matter the same way regardless of which way price is moving)."""
    closes = df["Close"].to_numpy(dtype=float)
    last_close = float(closes[-1])
    breakdown: dict[str, float | None] = {}
    weights = dict(UNIVERSAL_SCORE_WEIGHTS)

    has_index = index_closes is not None and len(index_closes) >= max(sma_fast, sma_slow, UNIVERSAL_RS_LOOKBACK + 1)
    if not has_index:
        weights.pop("relative_strength", None)
        weights.pop("index_trend", None)

    vwap = _compute_session_vwap_value(today_df)
    breakdown["above_vwap"] = None if vwap is None else (weights["above_vwap"] if last_close < vwap else 0.0)

    if sma_fast_val is not None and sma_slow_val is not None:
        breakdown["ema_cross"] = weights["ema_cross"] if sma_fast_val < sma_slow_val else 0.0
    else:
        breakdown["ema_cross"] = None

    structure_ok = _swing_structure_bearish(df)
    breakdown["structure_hh_hl"] = None if structure_ok is None else (weights["structure_hh_hl"] if structure_ok else 0.0)

    support = float(df["Low"].iloc[-(UNIVERSAL_STRUCTURE_LOOKBACK + 1):-1].min()) if len(df) > UNIVERSAL_STRUCTURE_LOOKBACK else None
    breakdown["breakout_resistance"] = None if support is None else (
        weights["breakout_resistance"] if last_close < support else 0.0
    )

    # Volume/RSI-band gradients are IDENTICAL to the long side - see this
    # function's own docstring.
    if vol_ratio is None:
        breakdown["volume_breakout"] = None
    elif vol_ratio >= UNIVERSAL_RVOL_FULL_MULT:
        breakdown["volume_breakout"] = weights["volume_breakout"]
    elif vol_ratio >= UNIVERSAL_RVOL_PARTIAL_MULT:
        breakdown["volume_breakout"] = weights["volume_breakout"] * 0.5
    else:
        breakdown["volume_breakout"] = 0.0

    # RSI is a bounded 0-100 oscillator, not a directionless quantity - the
    # long side's UNIVERSAL_RSI_BAND (55.0, 70.0) defines "healthy bullish
    # momentum, not yet overbought". Its short mirror is the band's
    # reflection around 50, not the SAME absolute numbers reused verbatim
    # (that would test for bullish momentum on a bearish setup - a real
    # bug, not a values-are-direction-agnostic case like volume/ATR/VWAP-
    # extension below): "healthy bearish momentum, not yet oversold".
    rsi_val = _compute_rsi_value(closes)
    lo, hi = UNIVERSAL_RSI_BAND
    lo_short, hi_short = 100.0 - hi, 100.0 - lo
    breakdown["rsi_band"] = None if rsi_val is None else (weights["rsi_band"] if lo_short <= rsi_val <= hi_short else 0.0)

    if has_index:
        rs_ok = _relative_strength_bearish(closes, index_closes)
        breakdown["relative_strength"] = weights["relative_strength"] if rs_ok else 0.0
        idx_ok = _index_trend_bearish(index_closes, sma_fast, sma_slow, ma_type)
        breakdown["index_trend"] = weights["index_trend"] if idx_ok else 0.0

    max_score = sum(weights[k] for k, v in breakdown.items() if v is not None)
    score = sum(v for v in breakdown.values() if v is not None)
    score_pct = round(100.0 * score / max_score, 2) if max_score else 0.0

    # ---- Rejection filters - identical basis to the long side, mirrored direction only ----
    rejection_reasons = []
    atr_series = _atr_series(df)
    atr_val = float(atr_series.iloc[-1]) if len(atr_series) and pd.notna(atr_series.iloc[-1]) else None
    atr_recent_mean = (
        float(atr_series.iloc[-20:].mean())
        if len(atr_series) >= 20 and atr_series.iloc[-20:].notna().all() else None
    )
    if atr_val is not None and atr_recent_mean and atr_val > UNIVERSAL_MAX_ATR_MULT * atr_recent_mean:
        rejection_reasons.append("atr_abnormally_wide")
    if vwap is not None and atr_val:
        if abs(last_close - vwap) > UNIVERSAL_MAX_VWAP_EXTENSION_ATR * atr_val:
            rejection_reasons.append("too_extended_from_vwap")
    if not volume_ok:
        rejection_reasons.append("liquidity_inadequate")
    liquidity_gate_ok, liquidity_gate_reasons = _liquidity_gate(df)
    if not liquidity_gate_ok:
        rejection_reasons.extend(liquidity_gate_reasons)
    # Entry-candle-bearish mirror of the long side's entry-candle-bullish
    # check: sellers must be dominant on the candle you're shorting into -
    # close BELOW open (a red candle), not just any candle.
    if "Open" in df.columns and len(df) >= 1:
        last_open = float(df["Open"].iloc[-1])
        if last_close >= last_open:
            rejection_reasons.append("entry_candle_not_bearish")
    if support is not None and len(df) > UNIVERSAL_STRUCTURE_LOOKBACK:
        risk_ref = float(df["High"].iloc[-(UNIVERSAL_STRUCTURE_LOOKBACK + 1):].max()) - last_close
        reward_ref = last_close - support
        # Mirror of the long side's own comment: only meaningful while
        # price is still ABOVE support (reward_ref > 0) - once last_close
        # has broken below it (the breakdown itself), this ratio stops
        # being informative and is left to the score above instead.
        if risk_ref > 0 and reward_ref > 0 and reward_ref / risk_ref < UNIVERSAL_MIN_REWARD_RISK:
            rejection_reasons.append("reward_risk_below_minimum")

    return {
        "score": round(score, 1), "max_score": max_score, "score_pct": score_pct,
        "breakdown": breakdown, "rejection_reasons": rejection_reasons,
        "entry_allowed": bool(score_pct >= UNIVERSAL_ENTRY_SCORE_MIN and not rejection_reasons),
    }


# ---- Idea 4: Unger-style ride-winners, no fixed target, 1-day candles ------
#
# Named "Idea 4" (2026-09-29, explicit user instruction "Okay keep it as
# idea 4 / Named / And build it properly") after a critical review of every
# trade taken to date turned up score-signal-4h-1d-retest-research.yml's
# TARGET-axis finding: main.py's real 8-factor UNIVERSAL_SCORE_WEIGHTS
# entry (score>=UNIVERSAL_ENTRY_SCORE_MIN AND EMA9>EMA21), run at 1-DAY
# candles, with NO fixed target at all - ride to a fixed ATR(14)x1.5 stop
# (set once at entry, never trailed) or IDEA4_MAX_HOLD_DAYS calendar days,
# whichever comes first - the first result across this session's whole
# "idea 1-9" universal_score research sequence to cross PFnet > 1.0
# (PFnet 1.04, n=927, avg net +Rs79.92/trade, 5-year pooled). That number
# came from an INDEPENDENT REIMPLEMENTATION (the research workflow's own
# header: "does not call universal_score/orb_breakout live signal code");
# idea4_entry_signal/idea4_exit_reason below are the real, callable main.py
# functions this session's own CLAUDE.md discipline requires before that
# number can be trusted for a go/no-go call - see
# idea4-validation-replay.yml for the full-universe replay that calls them.
#
# Named after Andrea Unger (4-time World Cup Championship of Futures
# Trading champion) - see ride-winners-no-target-research.yml for the
# "let winners run, don't cap them with a fixed target" philosophy this
# mirrors.

IDEA4_ATR_STOP_MULT = 1.5  # matches the research script's BASELINE_ATR_MULT
IDEA4_MAX_HOLD_DAYS = 20  # matches the research script's MAX_HOLD_BARS (1 daily bar = 1 day)


def idea4_entry_signal(df: pd.DataFrame, index_closes: np.ndarray | None = None,
                        sma_fast: int = 9, sma_slow: int = 21, ma_type: str = "ema") -> dict | None:
    """Evaluates ONLY the last row of `df` (today, a 1-DAY candle) for an
    Idea 4 entry: main.py's real, UNMODIFIED _compute_universal_entry_score
    (score>=UNIVERSAL_ENTRY_SCORE_MIN and no rejection reason tripped),
    gated by an explicit EMA9>EMA21 pre-filter (the research script's own
    "score>=70, EMA9>EMA21" gate - the score's own ema_cross component
    alone only scores 0 on a bearish cross, it doesn't hard-reject).

    Daily bars have no intraday session, so `above_vwap` has no real
    session VWAP to read. Rather than reimplementing VWAP, this passes the
    trailing VOLUME_CONFIRM_LOOKBACK daily bars themselves as `today_df` -
    _compute_session_vwap_value's own cumulative typical-price*volume /
    volume formula, applied to that rolling window instead of a real
    session, is exactly the "rolling-VWAP adaptation" the research script
    computed by hand, so this reuses the real function unmodified rather
    than forking a daily-bar copy of it.

    Returns None if there isn't enough history yet, the trend/score/ATR
    gate doesn't clear, or the resulting stop would sit at/above entry;
    otherwise {entry_price, stop_loss, atr_at_entry, score_pct}."""
    min_history = max(sma_slow, VOLUME_CONFIRM_LOOKBACK + 1, UNIVERSAL_STRUCTURE_LOOKBACK * 2,
                       UNIVERSAL_RSI_PERIOD + 1) + 1
    if len(df) < min_history:
        return None
    closes = df["Close"].to_numpy(dtype=float)
    sma_f = _moving_average(closes, sma_fast, ma_type)
    sma_s = _moving_average(closes, sma_slow, ma_type)
    if sma_f <= sma_s:
        return None

    volume_ok, vol_avg = _volume_confirms(df["Volume"].to_numpy(dtype=float))
    current_volume = float(df["Volume"].iloc[-1])
    vol_ratio = (current_volume / vol_avg) if (vol_avg and vol_avg > 0) else None

    today_df = df.iloc[-VOLUME_CONFIRM_LOOKBACK:]
    score_result = _compute_universal_entry_score(
        df, today_df, volume_ok, sma_f, sma_s, index_closes, sma_fast, sma_slow, ma_type,
        vol_ratio=vol_ratio,
    )
    if not score_result["entry_allowed"]:
        return None

    atr_series = _atr_series(df)
    if len(atr_series) == 0 or pd.isna(atr_series.iloc[-1]):
        return None
    atr_val = float(atr_series.iloc[-1])
    if atr_val <= 0:
        return None

    entry_price = float(closes[-1])
    stop_loss = entry_price - IDEA4_ATR_STOP_MULT * atr_val
    if stop_loss >= entry_price:
        return None

    return {
        "entry_price": entry_price, "stop_loss": stop_loss, "atr_at_entry": atr_val,
        "score_pct": score_result["score_pct"],
    }


def idea4_exit_reason(df: pd.DataFrame, entry_day: str, stop_loss: float) -> str | None:
    """Evaluates ONLY the last row of `df` (today) for an Idea 4 exit.
    Unlike minervini_vcp_exit_reason's chandelier trail, Idea 4's own
    validated research variant used a FIXED stop set once at entry (never
    recomputed or trailed) and NO fixed target at all - ride the winner to
    either that fixed stop or IDEA4_MAX_HOLD_DAYS calendar days, whichever
    comes first. `entry_day` is the IST date (YYYY-MM-DD) the position was
    opened, day-counted identically to gap_and_go_exit_reason/
    minervini_vcp_exit_reason. Returns the exit reason string, or None to
    keep holding - no running-max state to thread since there's nothing to
    trail."""
    if len(df) == 0:
        return None
    closes = df["Close"].to_numpy(dtype=float)
    dates = df["Date"].astype(str).to_numpy()
    i = len(df) - 1
    if closes[i] <= stop_loss:
        return "stop_hit"
    held_days = int(np.sum(dates > entry_day))
    if held_days >= IDEA4_MAX_HOLD_DAYS:
        return "max_hold_exit"
    return None


# ---- Idea 4 short mirror ("ride losers down, no target") -------------------
#
# 2026-09-29, explicit user instruction ("Prep short mirror for others
# too") per CLAUDE.md's 2026-09-28 standing thumb rule. Mirrors
# idea4_entry_signal/idea4_exit_reason direction only: calls
# _compute_universal_entry_score_short (already built and validated this
# session for the TREND-down short mirror - see its own docstring) instead
