CHAN_LONG_CELLS = {_chan_long_cell_tag(a, v, z): (a, v, z) for a, v, z in _CHAN_LONG_CELL_SPECS}
CHAN_LONG_HOLD_BARS = 40
CHAN_LONG_ENTRY_CUTOFF_MIN = CHAN_SHORT_ENTRY_CUTOFF_MIN
