def _category_real_toggle(key: str, env_var: str) -> bool:
    """B-404: per-category real-trading toggle from the Live constraints
    panel (runtime_settings key). Value -1 / no row = not set from the panel,
    so the Render env var still decides (unchanged behaviour); 0 = off,
    1 = on. Never raises: any DB error falls back to the env var. The
    master ALL TRADING switch is enforced separately and always wins."""
    env_on = os.environ.get(env_var) == "YES"
    try:
        with closing(get_db()) as c:
            row = c.execute("SELECT value FROM runtime_settings WHERE key = ?", (key,)).fetchone()
        if row is None or float(row["value"]) < 0:
            return env_on
        return float(row["value"]) >= 0.5
    except Exception:
        return env_on


def is_real_trading_enabled(conn) -> bool:
    """TWO independent gates, both required - explicit user instruction,
    2026-09-04: (1) the paper kill switch (trading_control.enabled) - real
    entries are only ever attempted right after _auto_signal_core itself
    returns "entered_long" for an equity, which the kill switch already
    blocks when off, so this function doesn't re-check it directly, and
    (2) REAL_TRADING_ENABLED, a Render env var set manually there, kept
    deliberately separate from any code push or UI action so real trading
    can never turn on by itself.

    Until today this also checked a third gate - a real_trading_control DB
    row, toggled via a token-gated popup on trade-view. That popup was
    removed per explicit user instruction ("I will control real money
    trade from env variable manually whenever needed"); this function was
    NOT updated at the same time, so the DB row - stuck at enabled=1 with
    no UI left to see or change it - kept silently gating real trading
    with no visibility. Found live and fixed same-day: dropped that check
    entirely rather than leave an invisible switch armed. See
    docs/TRADING_CONSTRAINTS.md for the full history if this needs
    revisiting."""
    return _category_real_toggle("real_enabled_equity", "REAL_TRADING_ENABLED")


def _real_today_spent_inr(conn) -> float:
    """Sum of today's (IST calendar day) CONFIRMED real buy notional -
    the only thing that counts against REAL_TRADING_DAILY_CAP_INR. Sourced
    entirely from real_trades, which this codebase populates itself at
    order-attempt time using a verified live LTP - not from parsing
    Kotak's own trade_report()/order_report() (see kotak_real_orders.py's
    module docstring for why those aren't trusted for this)."""
    today = ist_now().strftime("%Y-%m-%d")
    row = conn.execute(
        "SELECT COALESCE(SUM(notional_inr), 0) AS s FROM real_trades "
        "WHERE day = ? AND side = 'B' AND status = 'confirmed'",
        (today,),
    ).fetchone()
    return float(row["s"] or 0.0)


_T1_HOLDINGS_MARKER = "T1 holdings"  # exact substring Kotak's own RMS rejection uses
_target_backfill_t1_rejected: set = set()  # B-1329: (symbol, IST day) whose backfill target Kotak T1-rejected
# Found live 2026-09-09 (MEDICAMEQ.NS - Medicamen Biotech Ltd, actually a
# regulatory Trade-to-Trade/T2T-segment stock, not just Kotak's own T1-
# holdings RMS check): the SAME same-day-sell restriction can surface
# under a COMPLETELY different message - "Insufficient quantity held for
# this order... Selling Trade-to-Trade stocks on the same day of purchase
# is not allowed." This is a harder constraint than a broker RMS quirk -
# it's SEBI/exchange surveillance-category enforced, meaning NEITHER a
# target NOR (once triggered) a stop-loss can ever complete same-day for
# a T2T stock, no workaround possible until T+1. Both markers are
# checked; the flag/table name stays "t1_restricted" (not renamed to
# avoid a migration) but now covers both root causes equally.
_T2T_SAME_DAY_MARKER = "Trade-to-Trade stocks on the same day"

# real_t1_restricted external persistence (Upstash Redis) - 2026-09-09,
# found live right after making the restriction PERMANENT: MEDICAMEQ.NS
# and SILVERCASE.NS had already been confirmed T1/T2T-restricted (a real
# Kotak rejection, logged), but real_t1_restricted is a plain SQLite
# table exactly as ephemeral as every other one on this Render service -
# the very next deploy (of the "make it permanent" fix itself, and every
# one since) wiped it clean again, so the dashboard's own target_status
# fell back to "not_yet_attempted" instead of "blocked" and a fresh real
# entry attempt tomorrow would have hit the exact same wall all over
# again - the "permanent" fix wasn't actually permanent against this
# app's own restart cadence. Same Upstash-mirror pattern as real_positions/
# rr_cursor/check_counts/runtime_settings above, applied here as one JSON
# snapshot of the whole table.
_T1_RESTRICTED_REDIS_KEY = "tv_paper_bot:real_t1_restricted:v1"


def _sync_t1_restricted_external(conn) -> None:
    """Call right after a new row is flagged. Best-effort and silent, same
    pattern as every other _sync_*_external above."""
    if not (UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN):
        return
    try:
        rows = conn.execute("SELECT symbol, day, flagged_at, detail FROM real_t1_restricted").fetchall()
        snapshot = [dict(r) for r in rows]
        requests.post(
            f"{UPSTASH_REDIS_REST_URL}/set/{_T1_RESTRICTED_REDIS_KEY}",
            headers={"Authorization": f"Bearer {UPSTASH_REDIS_REST_TOKEN}"},
            data=json.dumps(snapshot).encode("utf-8"),
            timeout=5,
        )
    except Exception as e:
        print(f"[t1_restricted_external] sync failed (non-fatal): {e}")


def hydrate_t1_restricted_from_external(conn) -> int:
    """Startup-time restore, sourced from Upstash - real-time, so a
    restriction confirmed on ANY earlier day/restart survives every
    future restart, making the 2026-09-09 'permanent, not day-scoped' fix
    to _is_t1_restricted actually permanent in practice, not just in
    intent. Returns how many rows were restored (0 if Upstash is unset/
    unreachable/empty)."""
    if not (UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN):
        return 0
    try:
        resp = requests.get(
            f"{UPSTASH_REDIS_REST_URL}/get/{_T1_RESTRICTED_REDIS_KEY}",
            headers={"Authorization": f"Bearer {UPSTASH_REDIS_REST_TOKEN}"},
            timeout=10,
        )
        resp.raise_for_status()
        raw = resp.json().get("result")
        if not raw:
            return 0
        snapshot = json.loads(raw)
        if not isinstance(snapshot, list):
            return 0
    except Exception as e:
        print(f"[t1_restricted_external] hydrate failed (non-fatal): {e}")
        return 0

    restored = 0
    for row in snapshot:
        try:
            conn.execute(
                "INSERT OR IGNORE INTO real_t1_restricted (symbol, day, flagged_at, detail) VALUES (?, ?, ?, ?)",
                (row["symbol"], row["day"], row["flagged_at"], row.get("detail")),
            )
            restored += 1
        except (KeyError, TypeError, ValueError):
            continue
    if restored:
        conn.commit()
    return restored


def _flag_if_t1_restricted(conn, symbol: str, detail: str | None) -> None:
    """Records `symbol` as T1/T2T-restricted for today the first time its
    detail string carries either of Kotak's own same-day-sell rejection
    markers - see real_t1_restricted's own CREATE TABLE comment for the
    full reasoning, and _T2T_SAME_DAY_MARKER's own comment above for why
    there are two. Call this at every site that logs a real SL/exit
    rejection detail. Idempotent (day-scoped PRIMARY KEY, INSERT OR
    IGNORE) and never raises - a failure to flag must never break the
    real order flow it's observing."""
    if not detail or (_T1_HOLDINGS_MARKER not in detail and _T2T_SAME_DAY_MARKER not in detail):
        return
    today = ist_now().strftime("%Y-%m-%d")
    try:
        conn.execute(
            "INSERT OR IGNORE INTO real_t1_restricted (symbol, day, flagged_at, detail) VALUES (?, ?, ?, ?)",
            (symbol, today, time.time(), detail),
        )
        conn.commit()
        _sync_t1_restricted_external(conn)
        print(f"[T1-restricted] {symbol} flagged for {today} - new real entries blocked permanently: {detail}")
    except Exception as e:
        print(f"[T1-restricted] failed to flag {symbol} (non-fatal): {e}")


def _is_t1_restricted(conn, symbol: str) -> bool:
    """True if `symbol` has EVER hit a T1-holdings or Trade-to-Trade (T2T)
    same-day-sell rejection, on any day - checked before any NEW real
    equity entry (see _maybe_place_real_entry). Equity-only: F&O
    positions aren't CNC holdings and carry no T1/T2T settlement
    restriction, so this is never checked on that path.

    PERMANENT, not day-scoped, as of 2026-09-09 (explicit user
    instruction: "if we can't exit same day then pick strategy
    accordingly... else dont pick these restricted assets" - a T2T/T1
    classification is a structural attribute of the STOCK ITSELF (its
    exchange trading segment), not a one-day fluke that clears overnight.
    Live finding the same day: MEDICAMEQ.NS and SILVERCASE.NS both hit
    this same wall, and the OLD day-scoped check meant tomorrow's
    scheduler would cheerfully re-enter the exact same T2T stock with
    real capital and get exactly the same rejection again - this
    strategy's whole design assumes a same-day exit is always possible,
    so a symbol that has ever proven otherwise is permanently
    incompatible with it, not just "restricted today." real_t1_restricted
    itself still records EACH day a rejection is newly confirmed (its own
    day-scoped PRIMARY KEY, unchanged - useful audit history), but this
    read now checks for ANY row ever, regardless of which day it was
    inserted on."""
    return conn.execute(
        "SELECT 1 FROM real_t1_restricted WHERE symbol = ?", (symbol,)
    ).fetchone() is not None


def _holding_strategy(trd_sym):
    """B-1282: recovered strategy for a Kotak delivery holding with no tracked row; never blank."""
    try:
        with closing(get_db()) as _c:
            return _recover_strategy_for_untracked_position(_c, trd_sym, "B") or "kotak_untracked"
    except Exception:
        return "kotak_untracked"


def _recover_strategy_for_untracked_position(conn, kotak_trading_symbol: str, side: str) -> str | None:
    """Best-effort recovery of which strategy actually placed a Kotak
    position this app no longer has a real_positions/real_positions_short
    row for (see get_real_open_positions' own kotak_untracked branch).

    2026-09-30, explicit user correction: "All 'not bot-managed' are
    placed by you only" - a position missing from real_positions does NOT
    mean this app never placed it; it means the bookkeeping ROW for it was
    lost (e.g. the entry's local INSERT never ran because the process
    crashed/restarted right after Kotak confirmed the fill but before the
    INSERT, or an exit's DELETE ran optimistically before a broker-side
    failure/partial-fill left the position still actually open). Showing
    "not bot-managed" for a position THIS APP'S OWN order log shows it
    placed is a misleading label, not an honest "unknown."

    real_trades is the fix: it's an APPEND-ONLY log written at every real
    entry ATTEMPT (see _log_real_attempt), confirmed or not, and is never
    deleted when a position closes or its real_positions row is dropped -
    so the strategy that placed a CONFIRMED entry is recoverable from here
    even after the position-tracking row itself is gone. Returns None only
    when no confirmed real_trades row for this exact kotak_trading_symbol/
    side exists at all - which DOES mean this app genuinely never placed
    it (a true kotak_untracked position, e.g. NEWGEN/SANDUMA from the
    2026-09-09 finding), as opposed to placed-but-untracked."""
    try:
        ut = conn.execute(
            "SELECT strategy FROM user_strategy_tags WHERE symbol = ?",
            ((kotak_trading_symbol or "").split("-")[0].upper(),),
        ).fetchone()
        if ut:
            return "user: " + ut["strategy"]
    except Exception:
        pass
    row = conn.execute(
        "SELECT strategy FROM real_trades WHERE kotak_trading_symbol = ? AND side = ? "
        "AND status = 'confirmed' AND strategy IS NOT NULL ORDER BY ts DESC LIMIT 1",
        (kotak_trading_symbol, side),
    ).fetchone()
    if row:
        return row["strategy"]
    # B-402: widen beyond real_trades - an open swing signal row names the
    # strategy even when the Kotak-side bookkeeping row is gone.
    try:
        base = (kotak_trading_symbol or "").split("-")[0].upper()
        if base and side == "B":
            r2 = conn.execute(
                "SELECT strategy FROM signal_state_swing WHERE UPPER(symbol) IN (?, ?) LIMIT 1",
                (base + ".NS", base),
            ).fetchone()
            if r2 and r2["strategy"]:
                return r2["strategy"]
            r3 = conn.execute(
                "SELECT strategy FROM real_positions_swing WHERE UPPER(symbol) IN (?, ?) AND strategy IS NOT NULL LIMIT 1",
                (base + ".NS", base),
            ).fetchone()
            if r3 and r3["strategy"]:
                return r3["strategy"]
    except Exception:
        pass
    return None


def _stamp_viability_reason(detail, strategy_tag):
    """B-1390: append `viability_reason=<reason>` (recomputed at the moment of the skip) to a rejection row's detail."""
    try:
        reason = _viability_verdict(strategy_tag)[1]
        if reason in ("viable", "override"):
            reason = "unknown"  # gate passes now: the call site used another check (e.g. check_switch=False path)
    except Exception:
        reason = "unknown"
    tail = f"viability_reason={reason}"
    return f"{detail} {tail}" if detail else tail


def _log_real_attempt(conn, symbol, side, status, kotak_trading_symbol=None, qty=None,
                       price_est=None, notional_inr=None, order_id=None, detail=None, raw_response=None,
                       strategy=None):
    if status == "skipped_strategy_not_viable":
        detail = _stamp_viability_reason(detail, strategy)
    conn.execute(
        "INSERT INTO real_trades (ts, day, symbol, kotak_trading_symbol, side, qty, price_est, "
        "notional_inr, status, order_id, detail, raw_response, strategy) "
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (time.time(), ist_now().strftime("%Y-%m-%d"), symbol, kotak_trading_symbol, side, qty,
         price_est, notional_inr, status, order_id, detail,
         json.dumps(raw_response, default=str) if raw_response is not None else None, strategy),
    )
    conn.commit()


def _log_real_order_event(conn, symbol, leg, event, kotak_trading_symbol=None, order_id=None,
                           prev_state=None, new_state=None, detail=None, reason=None):
    """Appends one row to the order state-transition log (real_order_events -
    see its own CREATE TABLE comment) - explicit user instruction
    2026-09-08: "I want to see the log of what order you have placed and
    from what prev state to what current new order state." Called
    alongside (never instead of) whatever else a call site already does
    (real_positions updates, _log_real_attempt for entry/exit) - this
    table's only job is a complete, human-readable, forever-kept history
    of every entry/exit/sl/target order-state change this app makes.
    Never raises on its own account - a plain INSERT/commit, same
    simplicity as _log_real_attempt above.

    2026-10-06, explicit user instruction ("Maintain each log with reason
    that why u executed any order"): `reason` is the WHY of the order -
    stored as a leading "reason: ..." in `detail` so it rides the existing
    Upstash mirror and docs/real_order_log.json (git) with no schema
    change. Every exit path passes it (see _REASON_UNSTATED)."""
    if not reason:
        reason = _default_order_reason(leg, event)
    if reason:
        detail = f"reason: {reason}" + (f" | {detail}" if detail else "")
    conn.execute(
        "INSERT INTO real_order_events (ts, symbol, kotak_trading_symbol, leg, event, order_id, "
        "prev_state, new_state, detail) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (time.time(), symbol, kotak_trading_symbol, leg, event, order_id, prev_state, new_state, detail),
    )
    conn.commit()
    # 2026-10-07 (user: sync within 5 min everywhere): push the order log to Upstash
    # right now instead of waiting for the next tick, so a restart or overlapping
    # deploy cannot lose the reason for an order that already reached Kotak.
    try:
        sync_generic_tables_external(only=("real_order_events",))
    except Exception as e:
        print(f"[order_log] immediate mirror failed (tick sync will retry): {e}")
    # B-1355: the order log is git-tier, so the Upstash call above does not carry it. Wake the git push thread now:
    # NATIONALUM 23-Oct sold at 09:22:27 IST, Render restarted at 09:22:35, and the last git push was 09:21:26.
    _git_tier_push_wake.set()


_DEFAULT_ORDER_REASONS = {
    ("sl", "placed"): "resting stop-loss placed so the open position is protected",
    ("sl", "failed"): "stop-loss placement was rejected or failed; position stays unprotected and is retried",
    ("sl", "trailed"): "stop-loss ratcheted up to lock in profit as the trail rule moved",
    ("sl", "moved"): "stop-loss moved to follow the trailing stop",
    ("sl", "reconciled"): "stop-loss reconciled against Kotak's live order book",
    ("sl", "found_dead_on_reconcile"): "resting stop-loss was no longer live at Kotak; re-protecting the position",
    ("sl", "cas_transition_market_exit_attempt"): "Kotak rejected the stop modify (cancel-and-secure transition); exiting at market to stay safe",
    ("short_sl", "placed"): "resting buy-stop placed so the open short is protected",
    ("short_sl", "failed"): "short stop-loss placement failed; retried while unprotected",
    ("target", "placed"): "resting profit target placed for the current ladder leg",
    ("target", "failed"): "profit target placement failed",
    ("target", "skipped_sl_not_confirmed"): "target skipped because the stop-loss was not confirmed live first",
    ("entry", "confirmed"): "entry order fill confirmed at Kotak",
    ("entry", "confirmed_inferred"): "entry fill inferred from Kotak positions after the order status was unclear",
    ("entry", "failed"): "entry order failed or was rejected at Kotak",
}


def _default_order_reason(leg, event):
    """Never leave an order event without a reason (user, 2026-10-06): used
    only when a call site passed none."""
    return _DEFAULT_ORDER_REASONS.get((leg, event)) or f"automatic {leg} {event} by the real-order engine"


_REASON_UNSTATED = "UNSTATED - caller passed no exit reason (a bug to fix, never a normal state)"


def is_real_fo_trading_enabled() -> bool:
    """SEPARATE gate from is_real_trading_enabled (equity) - explicit
    user instruction 2026-09-07 ("i can update the capital any time. so
    build it right now"). Same single-env-var pattern is_real_trading_
    enabled itself settled on 2026-09-04 (a DB-row second switch was
    tried and found to be an invisible, un-manageable gate - see that
    function's own docstring) - REAL_FO_TRADING_ENABLED is a Render env
    var set manually there, independent of REAL_TRADING_ENABLED, so
    turning on equity real trading never silently turns on F&O too
    (much larger notional/margin per lot)."""
    return _category_real_toggle("real_enabled_fo", "REAL_FO_TRADING_ENABLED")


def is_real_swing_trading_enabled() -> bool:
    """SEPARATE gate from is_real_trading_enabled (intraday equity) and
    is_real_fo_trading_enabled (F&O) - 2026-09-22, real-order mirroring
    build for the Gap and Go swing engine. Same single-env-var pattern as
    both of those - REAL_SWING_TRADING_ENABLED is its own Render env var,
    independent of REAL_TRADING_ENABLED, so turning on intraday real
    trading never silently turns on multi-day real trading too (capital
    locked up for weeks at a time instead of minutes/hours - a materially
    different risk shape that deserves its own explicit switch)."""
    return _category_real_toggle("real_enabled_swing", "REAL_SWING_TRADING_ENABLED")


def _real_fo_today_spent_inr(conn) -> float:
    """Sum of today's (IST calendar day) CONFIRMED real F&O buy notional
    (premium * qty for a bought option) - what the F&O daily spend cap
    (_day_open_capital_inr, see its call sites) actually caps against.
    Mirrors _real_today_spent_inr's own reasoning exactly,
    sourced from real_fo_trades (this codebase's own record, populated at
    order-attempt time), not from Kotak's own trade/order reports."""
    today = ist_now().strftime("%Y-%m-%d")
    row = conn.execute(
        "SELECT COALESCE(SUM(notional_inr), 0) AS s FROM real_fo_trades "
        "WHERE day = ? AND side = 'B' AND status = 'confirmed'",
        (today,),
    ).fetchone()
    return float(row["s"] or 0.0)


def _log_real_fo_attempt(conn, leg_key, side, status, kotak_trading_symbol=None, qty=None,
                          price_est=None, notional_inr=None, order_id=None, detail=None, raw_response=None):
    if status == "skipped_strategy_not_viable":
        _m = re.search(r"strategy_tag=(\S+)", str(detail or ""))
        detail = _stamp_viability_reason(detail, _m.group(1) if _m else None)
    conn.execute(
        "INSERT INTO real_fo_trades (ts, day, leg_key, kotak_trading_symbol, side, qty, price_est, "
        "notional_inr, status, order_id, detail, raw_response) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (time.time(), ist_now().strftime("%Y-%m-%d"), leg_key, kotak_trading_symbol, side, qty,
         price_est, notional_inr, status, order_id, detail,
         json.dumps(raw_response, default=str) if raw_response is not None else None),
    )
    conn.commit()


def _describe_real_qty_sizing(paper_qty, max_by_cap, max_by_capital, qty):
    """One-line, plain-English reason for why a REAL buy order requests
    exactly `qty` shares - qty is always min(paper_qty, max_by_cap,
    max_by_capital) (see _maybe_place_real_entry just below), but that
    arithmetic was previously only ever visible in code, never in the
    order log/ledger. User request 2026-09-23: "In each of scorecard add
    a logic of placing why you buy only x qty when a buy order is placed
    each time."."""
    if qty == paper_qty:
        return (f"sized to the paper signal's own qty ({paper_qty}) - "
                f"remaining daily cap and real account capital both had room for at least that many")
    binding = []
    if max_by_cap <= qty:
        binding.append(f"remaining daily cap (room for {max_by_cap})")
    if max_by_capital <= qty:
        binding.append(f"real account capital (room for {max_by_capital})")
    return f"paper signal called for {paper_qty}, capped to {qty} by " + " and ".join(binding)


def _maybe_place_real_short_entry(conn, symbol: str):
    """Short mirror of _maybe_place_real_entry (2026-09-29, explicit user
    instruction to implement short selling; NOT gated on a separate kill
    switch - reuses is_real_trading_enabled, same as the long side, per
    explicit user decision). Called right after _short_signal_core
    returns action_taken == "entered_short".

    FIRST-CUT SCOPE, deliberately narrower than _maybe_place_real_entry:
    places the entry and one resting stop-loss (BUY-stop, buy-to-cover),
    but does NOT yet replicate that function's staged-ladder qty-
    recalculation (shorts have no ladder - single target), CAS-transition
    market-exit escalation, or the full protection-degraded retry state
    machine (_maybe_sync_real_stop_loss has no short-side mirror yet - a
    failed SL placement here is logged and left for a future tick/manual
    check, not auto-retried). This is a real, working gap, not a silent
    one - flagged here and in the commit history rather than glossed
    over; closing it is follow-up work, not blocking for a first real-
    money-short cut given the RANGE-short strategy's own thin validation
    evidence so far.

    No short-sell-eligibility pre-check (explicit user decision 2026-09-
    29) - see place_real_short_entry's own docstring."""
    if not is_real_trading_enabled(conn):
        return

    asset_class, _, _ = _asset_class_and_source(symbol)
    if asset_class != "nse_equity":
        _log_real_attempt(conn, symbol, "S", "skipped_not_eligible_asset_class")
        return

    _etf_ok, _etf_why = _etf_entry_range_ok(symbol)
    if not _etf_ok:
        _log_real_attempt(conn, symbol, "S", "skipped_etf_range_gate", detail="ETF entry range gate: " + _etf_why)
        return


    if conn.execute("SELECT 1 FROM real_positions_short WHERE symbol = ?", (symbol,)).fetchone():
        _log_real_attempt(conn, symbol, "S", "skipped_already_open")
        return
    if conn.execute("SELECT 1 FROM real_positions_swing_short WHERE symbol = ?", (symbol,)).fetchone():
        # B-871 engine ownership: a symbol held by the short-SWING engine is never touched by the intraday short engine.
        _log_real_attempt(conn, symbol, "S", "skipped_owned_by_swing_short_engine")
        return
    if conn.execute("SELECT 1 FROM real_positions WHERE symbol = ?", (symbol,)).fetchone():
        # No simultaneous real long+short on the same symbol - mirrors
        # _short_signal_core's own paper-side "skipped_existing_long_same_symbol" guard.
        _log_real_attempt(conn, symbol, "S", "skipped_existing_real_long_same_symbol")
        return

    import kotak_live_feed
    tick = kotak_live_feed.get_live_ticks().get(symbol)
    if not tick or not tick.get("ltp") or not tick.get("trading_symbol"):
        _log_real_attempt(conn, symbol, "S", "skipped_no_live_tick")
        return
    ltp = float(tick["ltp"])
    kotak_symbol = tick["trading_symbol"]
    if ltp <= 0:
        _log_real_attempt(conn, symbol, "S", "skipped_no_live_tick", kotak_trading_symbol=kotak_symbol)
        return
    if _kotak_bought_today(kotak_symbol):
        _log_real_attempt(conn, symbol, "S", "skipped_same_day_cooldown", kotak_trading_symbol=kotak_symbol,
                          price_est=ltp, detail="Kotak shows a completed BUY (cover/stop-out) on this symbol today - no same-day short re-entry")
        return

    paper_row = conn.execute(
        "SELECT qty, stop_loss, strategy FROM signal_state_short WHERE symbol = ? AND status = 'short'",
        (symbol,),
    ).fetchone()

    # 2026-09-30 PFnet >= 1 real-money gate - see _is_strategy_viable_for_
    # real_money's own module comment (long side's mirror, same reasoning).
    # Both current short strategies (range_short_staged_ladder 0.21,
    # trend_down_momentum_short 0.09) are below the floor, so this blocks
    # new real short entries today - existing open real short positions
    # are untouched.
    strategy_tag = paper_row["strategy"] if paper_row else None
    if not _is_strategy_viable_for_real_money(strategy_tag):
        _log_real_attempt(
            conn, symbol, "S", "skipped_strategy_not_viable", strategy=strategy_tag,
            detail=f"strategy {strategy_tag!r} not viable per the current explorer definition (or ALL TRADING switch off, or no validated metrics) "
                   "(or has no validated metrics) - see strategy_registry.py",
        )
        _log_signal_shadow(conn, strategy_tag if 0<2 else strategy, symbol, 'short', False, 'real entry: strategy below PFnet floor', hard_gate=True)
        return

    if strategy_tag in CHAN_SHORT_CELLS:
        _n = ist_now()
        if _n.hour * 60 + _n.minute >= CHAN_SHORT_ENTRY_CUTOFF_MIN:
            _log_real_attempt(conn, symbol, "S", "skipped_after_entry_cutoff",
                              detail="chan_kalman short: no new real entries from 15:00 IST (flatten at 15:10)")
            return

    paper_qty = paper_row["qty"] if paper_row and paper_row["qty"] else 0
    remaining_cap_inr = _effective_real_daily_cap_inr(conn) - _real_today_spent_inr(conn)
    real_capital_for_sizing = get_scheduler_capital_inr()
    max_by_cap = math.floor(remaining_cap_inr / ltp) if ltp > 0 else 0
    max_by_capital = math.floor(real_capital_for_sizing / ltp) if ltp > 0 else 0
    qty = int(min(paper_qty, max_by_cap, max_by_capital))
    if qty <= 0:
        _log_real_attempt(
            conn, symbol, "S", "skipped_insufficient_real_qty", kotak_trading_symbol=kotak_symbol,
            price_est=ltp,
            detail=f"paper qty {paper_qty}, 1 share = Rs{ltp:.2f} - capped to 0 by "
                   f"remaining daily cap Rs{remaining_cap_inr:.2f} (max {max_by_cap}) "
                   f"and/or real capital Rs{real_capital_for_sizing:.2f} (max {max_by_capital})",
        )
        return

    loss_check = _real_loss_budget(conn)
    if loss_check["real_pnl_today"] is None:
        _log_real_attempt(
            conn, symbol, "S", "skipped_real_pnl_unknown", kotak_trading_symbol=kotak_symbol,
            price_est=ltp, detail=loss_check["detail"],
        )
        return
    if not loss_check["ok"]:
        _log_real_attempt(
            conn, symbol, "S", "skipped_real_daily_loss_cap_hit", kotak_trading_symbol=kotak_symbol,
            price_est=ltp, detail=loss_check["detail"],
        )
        return

    # B-962: re-read the newest viable stack immediately before the order.
    _load_viable_overrides()
    if not _is_strategy_viable_for_real_money(strategy_tag):
        _log_real_attempt(conn, symbol, "S", "skipped_strategy_not_viable", kotak_trading_symbol=kotak_symbol,
                          strategy=strategy_tag,
                          detail=f"strategy {strategy_tag!r} no longer viable on the fresh stack re-check just before the order")
        return

    import kotak_real_orders
    result = kotak_real_orders.place_real_short_entry(kotak_symbol, qty, ltp)
    if not result.get("ok"):
        _log_real_attempt(
            conn, symbol, "S", "failed", kotak_trading_symbol=kotak_symbol, price_est=ltp,
            detail=result.get("detail"), raw_response=result.get("raw_response"),
            strategy=strategy_tag,  # B-1285: failed entries count per tag in /entry-funnel
        )
        print(f"[REAL SHORT] entry FAILED for {kotak_symbol}: {result.get('detail')}")
        _flag_if_t1_restricted(conn, symbol, result.get("detail"))
        return

    now = time.time()
    real_qty = int(result["qty"])
    real_entry_price = result["fill_price"]
    real_strategy = paper_row["strategy"] if paper_row else None
    conn.execute(
        "INSERT INTO real_positions_short (symbol, kotak_trading_symbol, qty, entry_price, "
        "entry_order_id, opened_at, day, strategy) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        (symbol, kotak_symbol, real_qty, real_entry_price, result["order_id"], now,
         ist_now().strftime("%Y-%m-%d"), real_strategy),
    )
    conn.commit()
    _sync_real_positions_short_external(conn)
    _log_real_attempt(
        conn, symbol, "S", "confirmed", kotak_trading_symbol=kotak_symbol,
        qty=real_qty, price_est=real_entry_price, notional_inr=real_qty * real_entry_price,
        order_id=result["order_id"], raw_response=result.get("raw_response"),
        strategy=real_strategy,
    )
    print(f"[REAL SHORT] SELL-TO-OPEN {real_qty} {kotak_symbol} (order {result['order_id']}) "
          f"~Rs{real_entry_price:.2f} (fill_confirmed={result['fill_price_confirmed']})")
    _log_real_order_event(
        conn, symbol, "short_entry", "confirmed", kotak_trading_symbol=kotak_symbol,
        order_id=result["order_id"], prev_state="no position",
        new_state=f"short {real_qty} @ Rs{real_entry_price:.2f}",
        detail=None if result["fill_price_confirmed"] else "fill not yet confirmed by Kotak",
        reason=f"paper short entry signal from strategy {real_strategy or 'unknown'} passed the PFnet gate",
    )
    _log_signal_shadow(conn, real_strategy, symbol, "short", True, "real short entry placed")

    if paper_row and paper_row["stop_loss"]:
        sl_result = kotak_real_orders.place_real_short_stop_loss(
            kotak_symbol, real_qty, round(paper_row["stop_loss"], 2)
        )
        if sl_result.get("ok"):
            conn.execute(
                "UPDATE real_positions_short SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
                (sl_result["order_id"], sl_result["trigger_price"], symbol),
            )
            conn.commit()
            _sync_real_positions_short_external(conn)
            print(f"[REAL SHORT] SL (buy-to-cover) resting @ Rs{sl_result['trigger_price']:.2f} "
                  f"for {kotak_symbol} (order {sl_result['order_id']})")
            _log_real_order_event(
                conn, symbol, "short_sl", "placed", kotak_trading_symbol=kotak_symbol,
                order_id=sl_result["order_id"], prev_state="none",
                new_state=f"resting BUY trigger Rs{sl_result['trigger_price']:.2f}",
            )
        else:
            print(f"[REAL SHORT] SL placement FAILED for {kotak_symbol}: {sl_result.get('detail')} "
                  f"- position open at Kotak with NO resting stop yet (no auto-retry for shorts "
                  f"in this first cut - see this function's own docstring)")
            _log_real_order_event(
                conn, symbol, "short_sl", "failed", kotak_trading_symbol=kotak_symbol,
                prev_state="none", new_state="none (placement failed)", detail=sl_result.get("detail"),
            )
            conn.execute(
                "UPDATE real_positions_short SET protection_degraded_since = ? WHERE symbol = ?",
                (now, symbol),
            )
            conn.commit()
            _sync_real_positions_short_external(conn)
            if real_strategy in CHAN_INTRADAY_SHORT_TAGS:
                # No trade without SL: a chan short whose stop cannot be placed is unwound at market now.
                _maybe_place_real_short_exit(conn, symbol, reason="entry_sl_failed_unwind")
    elif real_strategy in CHAN_INTRADAY_SHORT_TAGS:
        _maybe_place_real_short_exit(conn, symbol, reason="entry_sl_failed_unwind")


def _maybe_place_real_short_exit(conn, symbol: str, reason: str = None):
    """Short mirror of _maybe_place_real_exit - covers a real short
    position when the paper short (_short_signal_core) has already
    closed. Cancels any resting SL order first (mirrors the long side's
    own cancel-before-market-exit sequencing), then market buy-to-covers
    the exact real_positions_short qty. Never raises."""
    _why_log = functools.partial(_log_real_order_event, reason=reason or _REASON_UNSTATED)
    real_row = conn.execute("SELECT * FROM real_positions_short WHERE symbol = ?", (symbol,)).fetchone()
    if not real_row:
        return

    # B-313 (Kotak-first): never send a buy-to-cover for a position Kotak does not show as short
    # (a stale row outlived NYKAA/DRREDDY longs and fired ~20 overnight cover attempts). A confirmed
    # "not short" clears the stale row; an unreadable fetch (None) falls through as before.
    if _kotak_symbol_still_open_short(real_row["kotak_trading_symbol"]) is False:
        conn.execute("DELETE FROM real_positions_short WHERE symbol = ?", (symbol,))
        conn.commit()
        _sync_real_positions_short_external(conn)
        _why_log(conn, symbol, "short_cover", "stale_row_cleared", kotak_trading_symbol=real_row["kotak_trading_symbol"],
                 prev_state=f"short {real_row['qty']} (app row)", new_state="no short at Kotak; row removed, no order sent")
        return

    import kotak_real_orders
    _why_log(
        conn, symbol, "short_cover", "intent", kotak_trading_symbol=real_row["kotak_trading_symbol"],
        prev_state=f"short {real_row['qty']}",
        new_state="cancel resting SL, then market BUY-to-cover to be sent to Kotak")
    if real_row["sl_order_id"]:
        _cancel = kotak_real_orders.cancel_real_order(real_row["sl_order_id"])
        _why_log(
            conn, symbol, "sl", "cancelled" if _cancel.get("ok") else "cancel_failed",
            kotak_trading_symbol=real_row["kotak_trading_symbol"], order_id=real_row["sl_order_id"],
            prev_state=f"resting @ Rs{real_row['sl_trigger_price']}",
            new_state="cancelled (position covering)" if _cancel.get("ok") else "cancel failed - may still be resting",
            detail=None if _cancel.get("ok") else _cancel.get("detail"),
        )

    result = kotak_real_orders.place_real_short_cover(real_row["kotak_trading_symbol"], real_row["qty"])
    if not result.get("ok"):
        print(f"[REAL SHORT] cover FAILED for {real_row['kotak_trading_symbol']}: {result.get('detail')} "
              f"- position remains open at Kotak, will retry next tick")
        _why_log(
            conn, symbol, "short_cover", "failed", kotak_trading_symbol=real_row["kotak_trading_symbol"],
            prev_state=f"short {real_row['qty']}", new_state=f"short {real_row['qty']} (cover failed)",
            detail=result.get("detail"),
        )
        return

    conn.execute("DELETE FROM real_positions_short WHERE symbol = ?", (symbol,))
    conn.commit()
    _sync_real_positions_short_external(conn)
    _log_real_attempt(
        conn, symbol, "B", "confirmed", kotak_trading_symbol=real_row["kotak_trading_symbol"],
        qty=real_row["qty"], price_est=result.get("fill_price"), order_id=result["order_id"],
        raw_response=result.get("raw_response"), strategy=real_row["strategy"],
    )
    print(f"[REAL SHORT] BUY-TO-COVER {real_row['qty']} {real_row['kotak_trading_symbol']} "
          f"(order {result['order_id']})")
    _why_log(
        conn, symbol, "short_cover", "confirmed", kotak_trading_symbol=real_row["kotak_trading_symbol"],
        order_id=result["order_id"], prev_state=f"short {real_row['qty']}", new_state="no position",
    )


REAL_INTRADAY_MAX_STOP_PCT = 0.05
# 2026-10-21 (live: CANBK stop 17% and BANKBARODA 15% below entry, both
# outside NSE's price band, Kotak rejected, bot exited flat within minutes):
# a real intraday long's resting stop is never wider than this below the
# entry. Paper keeps its own stop; only what is sent to Kotak is capped.


def _cap_real_intraday_stop(entry_price: float, stop_price: float) -> float:
    floor = entry_price * (1 - REAL_INTRADAY_MAX_STOP_PCT)
    return round(max(float(stop_price), floor), 2)


def _maybe_place_real_entry(conn, symbol: str):
    """Mirrors a paper "entered_long" as a REAL buy, ONLY when every gate
    holds. Called from _scheduler_loop right after _auto_signal_core
    returns action_taken == "entered_long" for an equity symbol - never
    from inside _auto_signal_core itself, so paper trading's own logic
    stays completely unaware of real trading. Never raises - any
    unexpected error here must not break the scheduler tick (see the
    try/except around this call site)."""
    if not is_real_trading_enabled(conn):
        return  # expected default state - not logged, this isn't an "attempt"

    asset_class, _, _ = _asset_class_and_source(symbol)
    if asset_class != "nse_equity":
        _log_real_attempt(conn, symbol, "B", "skipped_not_eligible_asset_class")
        return

    _etf_ok, _etf_why = _etf_entry_range_ok(symbol)
    if not _etf_ok:
        _log_real_attempt(conn, symbol, "B", "skipped_etf_range_gate", detail="ETF entry range gate: " + _etf_why)
        return

    if conn.execute("SELECT 1 FROM real_positions WHERE symbol = ?", (symbol,)).fetchone():
        _log_real_attempt(conn, symbol, "B", "skipped_already_open")
        return

    if _is_t1_restricted(conn, symbol):
        _log_real_attempt(
            conn, symbol, "B", "skipped_t1_restricted",
            detail="permanently avoided - a real T1-holdings/T2T same-day-sell rejection was "
                   "confirmed for this symbol before, and this strategy needs a same-day exit "
                   "to be possible every time",
        )
        return

    import kotak_live_feed
    tick = kotak_live_feed.get_live_ticks().get(symbol)
    if not tick or not tick.get("ltp") or not tick.get("trading_symbol"):
        _log_real_attempt(conn, symbol, "B", "skipped_no_live_tick")
        return
    ltp = float(tick["ltp"])
    kotak_symbol = tick["trading_symbol"]
    if ltp <= 0:
        _log_real_attempt(conn, symbol, "B", "skipped_no_live_tick", kotak_trading_symbol=kotak_symbol)
        return
    if _kotak_sold_today(kotak_symbol):
        _log_real_attempt(conn, symbol, "B", "skipped_same_day_cooldown", kotak_trading_symbol=kotak_symbol,
                          price_est=ltp, detail="Kotak shows a completed SELL on this symbol today - no same-day re-entry")
        return

    # Real qty - explicit user instruction 2026-09-08: "Qty should be same
    # as you pick in render. No hard coding needed." The paper engine
    # (_auto_signal_core, same tick, same symbol) already sized this exact
    # signal and wrote its qty to signal_state - read that back rather
    # than inventing a separate real sizing formula, then cap it down (an
    # integer floor, NSE cash equities are whole-share-only) by whatever
    # real money actually allows: the remaining real_daily_cap_inr budget
    # AND the real account's own available capital. min() of the three -
    # never buy more than the paper signal called for, and never more
    # than real money can actually afford, whichever is smaller.
    paper_row = conn.execute(
        "SELECT qty, stop_loss, target, exit_legs_json, strategy FROM signal_state WHERE symbol = ? AND status = 'long'",
        (symbol,),
    ).fetchone()

    # 2026-09-30 PFnet >= 1 real-money gate (see _is_strategy_viable_for_
    # real_money's own module comment) - checked here, right after the
    # paper entry's own strategy tag is known, and before any order
    # placement below. universal_score (the only tag every WATCHLIST
    # symbol currently uses) is below the floor, so this blocks new real
    # long entries today - existing open real positions are untouched.
    strategy_tag = paper_row["strategy"] if paper_row else None
    _lra_tag = functools.partial(_log_real_attempt, strategy=strategy_tag)  # B-1285: tag skipped attempts with the strategy
    if not _is_strategy_viable_for_real_money(strategy_tag):
        _lra_tag(
            conn, symbol, "B", "skipped_strategy_not_viable",
            detail=f"strategy {strategy_tag!r} does not clear the PFnet >= 1 real-money floor "
                   "(or has no validated metrics) - see strategy_registry.py",
        )
        _log_signal_shadow(conn, strategy_tag if 1<2 else strategy, symbol, 'long', False, 'real entry: strategy below PFnet floor', hard_gate=True)
        return

    if strategy_tag in CHAN_GAP_LONG_CELLS:
        _n = ist_now()
        if _n.hour * 60 + _n.minute >= CHAN_GAP_ENTRY_CUTOFF_MIN + 15:
            _lra_tag(conn, symbol, "B", "skipped_after_entry_cutoff",
                              detail="chan_gap buy-on-gap: no new real entries after 10:30 IST (research enters at the open)")
            return

    if strategy_tag in CHAN_LONG_CELLS:
        _n = ist_now()
        if _n.hour * 60 + _n.minute >= CHAN_LONG_ENTRY_CUTOFF_MIN:
            _lra_tag(conn, symbol, "B", "skipped_after_entry_cutoff",
                              detail="chan_kalman long: no new real entries from 15:00 IST (flatten at 15:10)")
            return

    paper_qty = paper_row["qty"] if paper_row and paper_row["qty"] else 0
    remaining_cap_inr = _effective_real_daily_cap_inr(conn) - _real_today_spent_inr(conn)
    real_capital_for_sizing = get_scheduler_capital_inr()
    max_by_cap = math.floor(remaining_cap_inr / ltp) if ltp > 0 else 0
    max_by_capital = math.floor(real_capital_for_sizing / ltp) if ltp > 0 else 0
    qty = int(min(paper_qty, max_by_cap, max_by_capital))
    if qty <= 0:
        _lra_tag(
            conn, symbol, "B", "skipped_insufficient_real_qty", kotak_trading_symbol=kotak_symbol,
            price_est=ltp,
            detail=f"paper qty {paper_qty}, 1 share = Rs{ltp:.2f} - capped to 0 by "
                   f"remaining daily cap Rs{remaining_cap_inr:.2f} (max {max_by_cap}) "
                   f"and/or real capital Rs{real_capital_for_sizing:.2f} (max {max_by_capital})",
        )
        return

    # REAL daily loss cap - added 2026-09-07 ("when ur data had been in
    # sync with kotak then it would have seen the live trades and taken
    # the wise step for the 2% calculations"), 2026-09-08 (moved to the
    # shared _real_loss_budget - "keep it as a % of total money available
    # at the beginning of day. kotak balance" - a FIXED day-open capital
    # basis, joint with F&O, not a live-refreshing per-check figure). See
    # that function's own docstring/module comment for the full reasoning.
    # Fails CLOSED: an unknown real-P&L state refuses the entry rather
    # than trading blind.
    loss_check = _real_loss_budget(conn)
    if loss_check["real_pnl_today"] is None:
        _lra_tag(
            conn, symbol, "B", "skipped_real_pnl_unknown", kotak_trading_symbol=kotak_symbol,
            price_est=ltp, detail=loss_check["detail"],
        )
        return
    if not loss_check["ok"]:
        _lra_tag(
            conn, symbol, "B", "skipped_real_daily_loss_cap_hit", kotak_trading_symbol=kotak_symbol,
            price_est=ltp, detail=loss_check["detail"],
        )
        return

    # B-960: re-read the viable stack fresh immediately before the order (it may have changed since the checks above).
    _load_viable_overrides()
    if not _is_strategy_viable_for_real_money(strategy_tag):
        _lra_tag(conn, symbol, "B", "skipped_strategy_not_viable", kotak_trading_symbol=kotak_symbol,
                          detail=f"strategy {strategy_tag!r} no longer viable on the fresh stack re-check just before the order")
        return

    import kotak_real_orders
    if paper_row and paper_row["stop_loss"]:
        _sl_ok, _sl_why = kotak_real_orders.stop_placeable_for_entry(
            kotak_symbol, _cap_real_intraday_stop(ltp, paper_row["stop_loss"]), ltp)
        if not _sl_ok:  # B-1308: no trade without a placeable SL
            _lra_tag(conn, symbol, "B", "skipped_stop_outside_price_band", kotak_trading_symbol=kotak_symbol,
                     price_est=ltp, detail=_sl_why)
            return
    result = kotak_real_orders.place_real_entry(kotak_symbol, qty, ltp)
    if result.get("ok"):
        now = time.time()
        # Resync to Kotak's OWN confirmed fill data when available, not
        # the pre-trade estimate - explicit user instruction 2026-09-08:
        # "the exact buy or sell price vary due to gap in time of
        # execution... resync data ... to match all decision making based
        # on execution data." result["qty"]/["fill_price"] ARE the real
        # fldQty/avgPrc from Kotak's order_report when
        # fill_price_confirmed is True (see kotak_real_orders.
        # place_real_entry) - falls back to the requested qty/ltp estimate
        # only when Kotak hasn't reported a fill yet.
        real_qty = int(result["qty"])
        real_entry_price = result["fill_price"]

        # Staged profit-booking ladder for the REAL position (2026-09-09
        # architecture revamp; price-recalculation fixed 2026-09-10, found
        # in review). real_qty can be SMALLER than the paper signal's own
        # qty (capped by remaining_cap_inr/real capital above), so the
        # paper ladder's qty-per-leg can't just be copied over as-is - see
        # _split_exit_legs' own docstring for the qty-aware leg-count rule.
        #
        # Leg PRICES can't be copied over either, and this used to do
        # exactly that (paper's own target_price, verbatim). The real fill
        # (real_entry_price, just resolved above from Kotak's own fill
        # report) routinely differs from the paper signal's entry price by
        # slippage - reusing paper's absolute price levels silently changes
        # what R the real position is actually risking/targeting relative
        # to its OWN real entry. Recomputed here instead: same R-multiple
        # FRACTIONS (1.0R/1.5R/2.0R, parsed off each leg's own
        # r_multiple label) applied to real_r = real_entry_price minus the
        # real stop-loss PRICE LEVEL (paper_row["stop_loss"] - unchanged;
        # that's the same absolute price the real SL order below is placed
        # at, so this is real_r as actually risked by this real fill, not
        # paper's R). None for any non-universal_score entry
        # (paper_row["exit_legs_json"] is None there) - falls through to
        # the pre-revamp single-target behavior unchanged.
        real_exit_legs = None
        if paper_row and paper_row["exit_legs_json"] and paper_row["stop_loss"]:
            paper_legs = json.loads(paper_row["exit_legs_json"])
            real_r = real_entry_price - paper_row["stop_loss"]
            if real_r > 0:
                r_multiples_by_key = {}
                for leg in paper_legs:
                    if not leg["r_multiple"]:
                        continue
                    mult = float(leg["r_multiple"].rstrip("R"))
                    r_multiples_by_key[leg["r_multiple"]] = real_entry_price + mult * real_r
                real_exit_legs = _split_exit_legs(real_qty, r_multiples_by_key)

        # strategy (2026-09-21) - copied from the paper signal that triggered
        # this real entry, same reasoning as real_exit_legs just above: a
        # real position mirrors a specific paper decision, so it should
        # carry that decision's own attribution, not a generic constant.
        # None whenever there's no matched paper_row (shouldn't normally
        # happen for a fresh real entry, but never assumed).
        real_strategy = paper_row["strategy"] if paper_row else None
        conn.execute(
            "INSERT INTO real_positions (symbol, kotak_trading_symbol, qty, entry_price, "
            "entry_order_id, opened_at, day, exit_legs_json, strategy) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (symbol, kotak_symbol, real_qty, real_entry_price, result["order_id"], now,
             ist_now().strftime("%Y-%m-%d"), json.dumps(real_exit_legs) if real_exit_legs else None, real_strategy),
        )
        qty_reason = _describe_real_qty_sizing(paper_qty, max_by_cap, max_by_capital, qty)
        if not result["fill_price_confirmed"]:
            qty_reason += "; fill not yet confirmed by Kotak - using requested qty/estimated LTP"
        _log_real_attempt(
            conn, symbol, "B", "confirmed", kotak_trading_symbol=kotak_symbol,
            qty=real_qty, price_est=real_entry_price, notional_inr=real_qty * real_entry_price,
            order_id=result["order_id"], raw_response=result.get("raw_response"),
            detail=qty_reason,
            strategy=real_strategy,
        )
        print(f"[REAL TRADE] BUY {real_qty} {kotak_symbol} (order {result['order_id']}) "
              f"~Rs{real_entry_price:.2f} (fill_confirmed={result['fill_price_confirmed']})")
        _log_real_order_event(
            conn, symbol, "entry", "confirmed", kotak_trading_symbol=kotak_symbol,
            order_id=result["order_id"], prev_state="no position",
            new_state=f"long {real_qty} @ Rs{real_entry_price:.2f}",
            detail=None if result["fill_price_confirmed"] else "fill not yet confirmed by Kotak",
            reason=f"paper long entry signal from strategy {real_strategy or 'unknown'} passed the PFnet gate",
        )
        _log_signal_shadow(conn, real_strategy, symbol, "long", True, "real long entry placed")
        _sync_real_positions_external(conn)

        # Real resting stop-loss (2026-09-07, explicit user instruction:
        # "share stop-loss/trailing-stop to Kotak") - the paper stop this
        # SAME tick's _auto_signal_core just computed and wrote to
        # signal_state is the only stop this real position has ever had;
        # mirror it to the broker immediately so it's protected even if
        # this app never runs another tick. Best-effort: a failed SL
        # placement is logged but does NOT undo the real entry above -
        # the position genuinely exists at Kotak either way, and
        # _maybe_sync_real_stop_loss retries placing it on every later
        # tick for as long as real_positions.sl_order_id stays NULL.
        # sl_confirmed gates the target placement below (2026-09-21,
        # explicit user instruction, live Cochin Shipyard incident - see
        # that fix's full comment on the staged-leg version of this same
        # SL-then-target sequencing in _maybe_place_real_partial_exit):
        # never rest a target order for a position with no confirmed stop.
        sl_confirmed = False
        if paper_row and paper_row["stop_loss"]:
            sl_result = kotak_real_orders.place_real_stop_loss(
                kotak_symbol, real_qty, _cap_real_intraday_stop(real_entry_price, paper_row["stop_loss"])
            )
            if sl_result.get("ok"):
                sl_confirmed = True
                conn.execute(
                    "UPDATE real_positions SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
                    (sl_result["order_id"], sl_result["trigger_price"], symbol),
                )
                print(f"[REAL TRADE] SL resting @ Rs{sl_result['trigger_price']:.2f} for {kotak_symbol} "
                      f"(order {sl_result['order_id']})")
                _log_real_order_event(
                    conn, symbol, "sl", "placed", kotak_trading_symbol=kotak_symbol,
                    order_id=sl_result["order_id"], prev_state="none",
                    new_state=f"resting SELL trigger Rs{sl_result['trigger_price']:.2f}",
                )
                _sync_real_positions_external(conn)
            else:
                print(f"[REAL TRADE] SL placement FAILED for {kotak_symbol}: {sl_result.get('detail')} "
                      f"- position open at Kotak with NO resting stop yet, will retry next tick")
                _log_real_order_event(
                    conn, symbol, "sl", "failed", kotak_trading_symbol=kotak_symbol,
                    prev_state="none", new_state="none (placement failed)", detail=sl_result.get("detail"),
                )
                _flag_if_t1_restricted(conn, symbol, sl_result.get("detail"))
                # CAS-transition rejection (2026-09-22, see
                # kotak_real_orders.is_cas_transition_rejection's own
                # docstring) - this symbol's paper signal shouldn't even
                # be firing an entry this close to squareoff_min any more
                # (see ENTRY_CUTOFF_BEFORE_SQUAREOFF_MINUTES), but if it
                # somehow still happens, don't wait out the usual degraded
                # window on a position that's seconds old - go straight to
                # a market exit attempt, same escalation as
                # _maybe_sync_real_stop_loss uses for this exact rejection.
                if kotak_real_orders.is_cas_transition_rejection(sl_result.get("detail")):
                    print(f"[REAL TRADE] {kotak_symbol} SL rejected mid-CAS-transition right after entry - "
                          f"escalating straight to a market exit attempt instead of waiting")
                    _log_real_order_event(
                        conn, symbol, "sl", "cas_transition_market_exit_attempt", kotak_trading_symbol=kotak_symbol,
                        prev_state="none (placement failed, CAS transition)", new_state="attempting market exit",
                        detail=sl_result.get("detail"),
                    )
                    _maybe_place_real_exit(conn, symbol, reason="SL rejected in CAS transition right after entry - cannot leave position unprotected, market exit")
                    return
                if real_strategy in CHAN_INTRADAY_LONG_TAGS:
                    # No trade without SL: a chan long whose stop cannot be placed is unwound at market now.
                    _maybe_place_real_exit(conn, symbol, reason="entry_sl_failed_unwind")
                    return
                # 2026-09-10: unprotected from the moment of entry - same
                # degraded-protection clock/timeout as every other SL gap,
                # not a special case. _maybe_sync_real_stop_loss's own
                # top-of-function check picks this up and either keeps
                # retrying or escalates once the capital-scaled tolerance
                # is exceeded.
                _mark_protection_degraded(conn, symbol)

        # Real resting target/profit-booking order (2026-09-08, explicit
        # user instruction: "place the target you have planned for each
        # trade so that it can be booked once reached") - same immediate-
        # mirror reasoning as the SL leg above, for the other side of the
        # trade. Best-effort like the SL placement: a failure is logged
        # but does not undo the real entry - see kotak_real_orders'
        # "Real resting target" docstring for why this one is NOT retried
        # on a later tick the way the SL is.
        # Staged ladder (2026-09-09): the FIRST unfilled fixed leg's own
        # qty/price, not the full real_qty/paper_row["target"] - later legs
        # get their own resting target placed only once the one ahead of
        # them books (see _maybe_place_real_partial_exit). Falls back to
        # the exact pre-revamp single-target behavior (full real_qty at
        # paper_row["target"]) when there's no ladder at all (real_exit_legs
        # is None) OR the only leg is "trail" (qty<=1 at entry - see
        # _split_exit_legs).
        # sl_confirmed gate (2026-09-21): only rest a target once the SL
        # above is confirmed - see this block's own top comment.
        first_leg = next((l for l in (real_exit_legs or []) if l["leg"] != "trail"), None)
        target_leg_qty = first_leg["qty"] if first_leg else real_qty
        target_leg_price = first_leg["target_price"] if first_leg else (paper_row["target"] if paper_row else None)
        if real_strategy in CHAN_INTRADAY_LONG_TAGS:
            target_leg_price = None  # chan long exits are stop / state / hold / flatten; no resting target
        if not sl_confirmed and target_leg_qty and target_leg_price:
            _log_real_order_event(
                conn, symbol, "target", "skipped_sl_not_confirmed", kotak_trading_symbol=kotak_symbol,
                prev_state="none",
                new_state="none (SL placement failed or unavailable - target withheld to avoid a naked position)",
            )
        if sl_confirmed and target_leg_qty and target_leg_price:
            target_result = kotak_real_orders.place_real_target(
                kotak_symbol, target_leg_qty, round(target_leg_price, 2)
            )
            if target_result.get("ok"):
                conn.execute(
                    "UPDATE real_positions SET target_order_id = ?, target_price = ? WHERE symbol = ?",
                    (target_result["order_id"], target_result["target_price"], symbol),
                )
                print(f"[REAL TRADE] TARGET resting @ Rs{target_result['target_price']:.2f} for {kotak_symbol} "
                      f"(order {target_result['order_id']})"
                      + (f" [leg {first_leg['leg']}, {target_leg_qty}/{real_qty} shares]" if first_leg else ""))
                _log_real_order_event(
                    conn, symbol, "target", "placed", kotak_trading_symbol=kotak_symbol,
                    order_id=target_result["order_id"], prev_state="none",
                    new_state=f"resting SELL limit Rs{target_result['target_price']:.2f}",
                )
                _sync_real_positions_external(conn)
            else:
                print(f"[REAL TRADE] TARGET placement FAILED for {kotak_symbol}: {target_result.get('detail')} "
                      f"- position open at Kotak with NO resting target, profit-booking still handled by "
                      f"the scheduler's own per-tick poll instead")
                # Still record the INTENDED target price even though no real
                # order backs it (2026-09-09, explicit user instruction:
                # "Show me on render what is target for each entered trade")
                # - target_order_id stays null (honest: no real order is
                # resting), but target_price is no longer conflated with
                # "only ever set on a confirmed order" - the dashboard reads
                # target_status (target_order_id null + real_t1_restricted/
                # real_order_events lookup, see /real-open-positions) to
                # show WHY, right next to this number.
                conn.execute(
                    "UPDATE real_positions SET target_price = ? WHERE symbol = ?",
                    (round(target_leg_price, 2), symbol),
                )
                _log_real_order_event(
                    conn, symbol, "target", "failed", kotak_trading_symbol=kotak_symbol,
                    prev_state="none", new_state="none (placement failed)", detail=target_result.get("detail"),
                )
                # NOT a _flag_if_t1_restricted call, on purpose (2026-09-22
                # correction of the original 2026-09-09 MEDICAMEQ.NS
                # reasoning below) - live research + this session's own
                # evidence (3 symbols, same day: IDEA/ASHOKLEY/CONCOR all
                # rejected here, then sold successfully seconds-to-minutes
                # after their SL was cancelled - real T+1 settlement cannot
                # clear that fast) confirms Kotak's RMS enforces "one exit
                # order per holding" - this rejection fires because
                # sl_confirmed is True, meaning the SL immediately above IS
                # the competing resting order, not because this SYMBOL is
                # unsellable same-day. Flagging it here would have
                # permanently blacklisted every real position this
                # architecture ever gives BOTH a resting SL and a resting
                # target - which is every staged-ladder entry - eventually
                # blacklisting the whole real-trading universe one symbol
                # at a time. A genuine T1/T2T-restricted symbol still gets
                # caught elsewhere: _maybe_place_real_exit's own rejection
                # (after both legs are confirmed cancelled first) has no
                # such competing-order explanation available.
    else:
        _log_real_attempt(
            conn, symbol, "B", "failed", kotak_trading_symbol=kotak_symbol, price_est=ltp,
            detail=result.get("detail"), raw_response=result.get("raw_response"),
            strategy=strategy_tag,  # B-1285: failed entries count per tag in /entry-funnel
        )
        print(f"[REAL TRADE] BUY FAILED {kotak_symbol}: {result.get('detail')}")
        _log_real_order_event(
            conn, symbol, "entry", "failed", kotak_trading_symbol=kotak_symbol,
            prev_state="no position", new_state="no position (buy failed)", detail=result.get("detail"),
            reason="paper long entry signal; Kotak rejected or failed the buy",
        )


def _kotak_symbol_still_open(kotak_trading_symbol: str) -> bool | None:
    """Ground-truth check against Kotak's OWN positions(), same query
    shape as get_real_capital_deployed_inr - added 2026-09-08 after a
    live-confirmed duplicate-exit finding (see _maybe_place_real_exit):
    a Render restart landing between a real exit order being CONFIRMED
    and its real_positions row's DELETE actually committing (SQLite,
    wiped on every restart like every other table here) restores that
    row from the last journal snapshot as if the position were still
    open - if a second exit attempt then fires off this stale state, it
    places a REAL duplicate sell with no legitimate open position behind
    it, drawing from whatever the account happens to hold in that symbol
    (confirmed live: this drew from a separate manually-purchased holding
    in the same symbol, not this app's own tracked shares - net position
    ended up flat by coincidence, not by design).

    Returns True if Kotak shows a genuinely open (not fully squared-off)
    position for this exact trading symbol, False if it shows none/fully
    squared off, or None on a fetch failure (fails OPEN - never used to
    silently swallow a legitimate exit over a transient API hiccup; see
    the caller)."""
    try:
        import kotak_neo
        positions = kotak_neo.positions()
        rows = positions.get("data") or [] if isinstance(positions, dict) else []
    except Exception:
        return None
    for row in rows:
        if row.get("trdSym") != kotak_trading_symbol or row.get("exSeg") != "nse_cm":
            continue
        try:
            fl_buy = float(row.get("flBuyQty", 0) or 0)
            fl_sell = float(row.get("flSellQty", 0) or 0)
        except (TypeError, ValueError):
            continue
        if fl_buy > 0 and fl_buy != fl_sell:
            return True
    return False


def _kotak_swing_symbol_still_held(kotak_trading_symbol: str) -> bool | None:
    """Swing positions are DELIVERY holdings: Kotak shows them in holdings(),
    not positions() (B-46b probe, 2026-10-06). 2026-10-07 bug (NYKAA): the swing
    exit used positions() alone, so a still-held holding read as "already closed
    at Kotak" and its row was cleared (skipped_duplicate). Held = in positions()
    as open OR in holdings(). False only when BOTH fetched fine and neither shows
    it; None (fail open, as before) when either fetch failed and the other did
    not show it."""
    pos = _kotak_symbol_still_open(kotak_trading_symbol)
    if pos is True:
        return True
    holdings = _kotak_holdings_open_by_trdsym()
    if holdings is not None and kotak_trading_symbol in holdings:
        return True
    if pos is None or holdings is None:
        return None
    return False


def _real_held_qty(kotak_trading_symbol: str) -> float | None:
    """Ground-truth CURRENT quantity actually held at Kotak for this exact
    trading symbol (flBuyQty - flSellQty), same query shape and fields as
    _kotak_symbol_still_open - 2026-09-23, live SUZLON.NS finding. Returns
    None on a fetch failure (never 0 - a failed read must never be
    mistaken for a genuinely flat/closed position)."""
    try:
        import kotak_neo
        positions = kotak_neo.positions()
        rows = positions.get("data") or [] if isinstance(positions, dict) else []
    except Exception:
        return None
    for row in rows:
        if row.get("trdSym") != kotak_trading_symbol or row.get("exSeg") != "nse_cm":
            continue
        try:
            fl_buy = float(row.get("flBuyQty", 0) or 0)
            fl_sell = float(row.get("flSellQty", 0) or 0)
        except (TypeError, ValueError):
            return None
        return fl_buy - fl_sell
    return 0.0


def _reconcile_real_qty(conn, real_row):
    """Corrects real_positions.qty against what Kotak's own positions()
    actually shows held, if they disagree - 2026-09-23, live SUZLON.NS
    finding. A resting order (SL or target) can fill ORGANICALLY at
    Kotak, matched directly by the exchange, entirely independent of this
    app's own tick-based polling - that's the whole POINT of resting
    orders (see the "Double-sell fix" comment in
    _maybe_place_real_partial_exit for the same mechanism from the other
    side). This app's own qty tracking only ever gets updated by a call
    INTO that function, which itself only fires when the PAPER side's own
    condition also independently decides a leg fired. If the two never
    line up - the real fill lands first, or the paper condition never
    matches the real one exactly - real_positions.qty silently goes stale
    while Kotak's own book has already moved on, and every later SL
    sizing decision (this function's own trailing-sync included) sizes
    off the WRONG, too-high quantity from then on. Confirmed live:
    SUZLON.NS's real qty went 3->2 via an organic fill at 11:32 (order
    completed at Kotak, no corresponding entry in real_order_events - the
    paper side never called into the partial-exit mirror for it), and
    every SL placement attempt from 11:34 onward kept asking Kotak to
    rest a sell for 3 shares against a holding that only had 2 - itself
    plausibly why those specific attempts were rejected ("insufficient
    quantity held" is one of the reasons Kotak's own compound rejection
    message lists), independent of the T1/T2T question addressed
    separately below.

    Best-effort and fail-quiet on an unreadable check (returns real_row
    unchanged) - the same "unknown -> don't force a change" stance as
    every other broker reconciliation in this file. Returns the
    (possibly re-fetched, corrected) real_row for the caller to use."""
    held = _real_held_qty(real_row["kotak_trading_symbol"])
    if held is None or held <= 0:
        return real_row  # unreadable, or Kotak shows it fully closed - let the normal exit/cleanup paths handle that
    if held == real_row["qty"]:
        return real_row
    print(f"[REAL TRADE] {real_row['kotak_trading_symbol']} qty mismatch - this app tracked "
          f"{real_row['qty']}, Kotak actually holds {held:.0f} - correcting local record "
          f"(a resting order likely filled organically without this app's own mirror firing)")
    _log_real_order_event(
        conn, real_row["symbol"], "qty", "reconciled", kotak_trading_symbol=real_row["kotak_trading_symbol"],
        prev_state=f"tracked qty {real_row['qty']}", new_state=f"corrected to Kotak's actual {held:.0f}",
    )
    conn.execute("UPDATE real_positions SET qty = ? WHERE symbol = ?", (held, real_row["symbol"]))
    conn.commit()
    return conn.execute("SELECT * FROM real_positions WHERE symbol = ?", (real_row["symbol"],)).fetchone()


def _real_held_qty_short(kotak_trading_symbol: str) -> float | None:
    """Short mirror of _real_held_qty (2026-09-30, "make short positions
    equally mirrored as done in buy positions") - flSellQty - flBuyQty,
    positive when genuinely short. _real_held_qty's own `fl_buy - fl_sell`
    would be NEGATIVE for a pure short, and _reconcile_real_qty's own
    `held <= 0` guard would then treat every genuine short as "unreadable
    or closed" and skip reconciling it entirely - this is why that
    function can't be reused as-is for shorts. Returns None on a fetch
    failure (never 0 - a failed read must never be mistaken for a
    genuinely flat/closed position, same contract as the long version)."""
    try:
        import kotak_neo
        positions = kotak_neo.positions()
        rows = positions.get("data") or [] if isinstance(positions, dict) else []
    except Exception:
        return None
    for row in rows:
        if row.get("trdSym") != kotak_trading_symbol or row.get("exSeg") != "nse_cm":
            continue
        try:
            fl_buy = float(row.get("flBuyQty", 0) or 0)
            fl_sell = float(row.get("flSellQty", 0) or 0)
        except (TypeError, ValueError):
            return None
        if _is_delivery_sell_not_short(row, fl_buy - fl_sell):
            continue  # B-1403: a sold delivery holding is never short qty
        return fl_sell - fl_buy
    return 0.0


def _reconcile_real_qty_short(conn, real_row):
    """Short mirror of _reconcile_real_qty (2026-09-30) - corrects
    real_positions_short.qty against what Kotak's own positions() actually
    shows held short, using _real_held_qty_short (NOT _real_held_qty,
    which is long-signed and would misread every genuine short as
    unreadable/closed - see that function's own docstring). Same
    best-effort, fail-quiet-on-unreadable contract as the long version:
    returns real_row unchanged on a failed or non-positive read, letting
    the normal exit/cleanup paths handle a genuinely closed position."""
    held = _real_held_qty_short(real_row["kotak_trading_symbol"])
    if held is None or held <= 0:
        return real_row
    if held == real_row["qty"]:
        return real_row
    print(f"[REAL SHORT] {real_row['kotak_trading_symbol']} qty mismatch - this app tracked "
          f"{real_row['qty']}, Kotak actually holds {held:.0f} short - correcting local record")
    _log_real_order_event(
        conn, real_row["symbol"], "qty", "reconciled", kotak_trading_symbol=real_row["kotak_trading_symbol"],
        prev_state=f"tracked qty {real_row['qty']}", new_state=f"corrected to Kotak's actual {held:.0f}",
    )
    conn.execute("UPDATE real_positions_short SET qty = ? WHERE symbol = ?", (held, real_row["symbol"]))
    conn.commit()
    _sync_real_positions_short_external(conn)
    return conn.execute("SELECT * FROM real_positions_short WHERE symbol = ?", (real_row["symbol"],)).fetchone()


def _maybe_place_real_partial_exit(conn, symbol: str, staged_exit: dict):
    """Mirrors ONE staged profit-booking LEG (see _execute_staged_leg_exit)
    as a REAL partial sell - 2026-09-09 architecture revamp. Unlike
    _maybe_place_real_exit (which always closes the FULL real_positions
    row), this only ever sells the leg's own qty and UPDATES the row's qty
    downward, advancing the resting target order to the NEXT unfilled leg
    (if any) and placing a fresh stop-loss sized to the smaller remaining
    qty, without closing the position.

    SL-first-cancel fix (2026-09-14, real live rejection - BECTORFOOD SELL
    0/1 REJECTED "Insufficient quantity held for this order"): the resting
    SL order (sized to the FULL original qty) is cancelled BEFORE this
    leg's sell is attempted, not after. Kotak holds shares against ANY
    resting sell order, so attempting a partial sell while the old SL is
    still resting gets rejected outright - exactly what the live rejection
    showed. A failed SL cancel defers the whole leg (most likely the SL
    already triggered for real, or the true state is otherwise unknown -
    never guess); a failed sell AFTER a successful SL cancel restores the
    ORIGINAL stop (full qty) before returning, rather than leaving the
    position naked over an unrelated sell failure.

    Best-effort at every step, same conventions as every other real-order
    function in this file: a failure to advance the target/place the fresh
    SL is logged but never undoes the partial sell that already happened -
    the position genuinely has fewer shares at Kotak either way."""
    row = conn.execute("SELECT * FROM real_positions WHERE symbol = ?", (symbol,)).fetchone()
    if not row:
        return  # no real position was ever opened for this paper trade - nothing to partially exit
    leg_name = staged_exit.get("leg")
    # The PAPER side's `staged_exit` only tells us WHICH leg just fired -
    # how much to sell on the REAL side comes from the REAL position's own
    # ladder (real_exit_legs, re-derived for real_qty at entry time - see
    # _maybe_place_real_entry), NOT the paper leg's own qty. Real qty can be
    # (and often is) smaller than paper qty, so the two ladders' same-named
    # legs hold DIFFERENT qtys by design - using the paper qty here would
    # over-sell the real position on its very first leg.
    real_legs = json.loads(row["exit_legs_json"]) if row["exit_legs_json"] else []
    real_leg = next((l for l in real_legs if l["leg"] == leg_name), None)
    if real_leg is None or real_leg["status"] != "open":
        # No matching (or already-filled) leg on the REAL side - this real
        # position may never have been given a staged ladder at all (too
        # small at entry - see _split_exit_legs's qty==1 case - or it
        # predates this revamp/was adopted via reconcile), or this exact
        # leg already booked at Kotak on an earlier tick. Either way there
        # is nothing new to sell for THIS leg name; the position's existing
        # full-exit path (_maybe_place_real_exit) still governs it normally
        # once a real exit_reason eventually fires.
        return
    leg_qty = min(int(real_leg["qty"]), int(row["qty"]))
    if leg_qty <= 0:
        _log_real_attempt(
            conn, symbol, "S", "skipped_zero_leg_qty", kotak_trading_symbol=row["kotak_trading_symbol"],
            detail=f"staged leg {leg_name} had qty<=0 after capping to real position's own qty {row['qty']}",
        )
        return

    import kotak_real_orders

    # Double-sell fix (2026-09-10, found in review): the resting target
    # LIMIT order this exact leg is protected by (row["target_order_id"])
    # exists specifically so a downtime window doesn't leave the position
    # unprotected - which means it can genuinely fill on its own, at
    # Kotak, between one scheduler tick and the next, with NO involvement
    # from this app. The code below used to place a fresh market sell for
    # leg_qty unconditionally, with no check against that possibility -
    # if the resting order had already filled for real, this would sell
    # the same shares a SECOND time (an oversell CNC would likely reject,
    # but silently corrupts this app's own qty/P&L bookkeeping either way).
    #
    # Fix: cancel the resting order for THIS leg FIRST. cancel_real_order's
    # own docstring names "the order already filled" as the leading reason
    # a cancel can fail - so a failed cancel here is treated as strong
    # evidence the leg already executed at Kotak, and this reconciles the
    # local qty/leg status from that inference instead of placing a
    # redundant sell. A successful cancel proves the order was still
    # resting (so it could not have filled), and only THEN is it safe to
    # sell leg_qty at market ourselves.
    already_filled_at_kotak = False
    # B-1350: write the reason BEFORE any Kotak cancel/sell, so a crash or a lost
    # post-call log can never leave a Kotak order with no app reason row.
    _log_real_order_event(
        conn, symbol, f"staged_{leg_name}", "intent", kotak_trading_symbol=row["kotak_trading_symbol"],
        prev_state=f"long {row['qty']} @ Rs{row['entry_price']:.2f}",
        new_state=f"cancel resting target/SL, then SELL {leg_qty} for staged leg {leg_name}",
        reason=f"staged profit-booking leg {leg_name} reached",
    )
    if row["target_order_id"]:
        cancel_result = kotak_real_orders.cancel_real_order(row["target_order_id"])
        if not cancel_result.get("ok"):
            already_filled_at_kotak = True
            print(f"[REAL TRADE] STAGED LEG {leg_name} resting target order for "
                  f"{row['kotak_trading_symbol']} could not be cancelled "
                  f"({cancel_result.get('detail')}) - most likely already filled at Kotak; "
                  f"reconciling qty instead of placing a second sell")

    # SL-first-cancel fix (2026-09-14, real live rejection - BECTORFOOD SELL
    # 0/1 REJECTED "Insufficient quantity held for this order"): Kotak holds
    # shares against ANY resting sell order, SL included - not just the
    # leg's own target order handled above. Placing this leg's profit-
    # booking sell while the OLD stop (still sized to the FULL qty) is
    # resting gets rejected outright, exactly as seen live. Correct
    # sequence (per the actual rejection, matching what was needed to fix
    # it): cancel the resting SL FIRST, then sell the leg, then place a
    # fresh SL sized to the remaining qty - never resize the old one in
    # place, and never attempt the sell while the old one still rests.
    # Applies regardless of already_filled_at_kotak: either way the
    # position's qty is about to shrink, and the OLD SL (sized to the full
    # original qty) must go before the end-of-function block below places
    # a fresh one for the remaining qty - leaving it resting would create a
    # SECOND, duplicate SL order alongside the new one, both racing to sell
    # the same shares.
    sl_was_cancelled = False
    if row["sl_order_id"]:
        sl_cancel_result = kotak_real_orders.cancel_real_order(row["sl_order_id"])
        if sl_cancel_result.get("ok"):
            sl_was_cancelled = True
            # No resting broker-side stop exists from this instant until a
            # fresh one lands below - the same degraded-protection clock
            # every other SL gap already uses, not a silent hole.
            _mark_protection_degraded(conn, symbol)
        else:
            # Could not cancel - most likely it already triggered for real
            # (the position may already be closed for a loss at Kotak) or
            # a transient API error masks the true state either way. Defer
            # this leg's booking entirely rather than guess: the next tick
            # (or _maybe_sync_real_stop_loss's own reconcile path) will
            # sort out what actually happened before anything here risks
            # compounding it with a sell against an unknown real state.
            _log_real_attempt(
                conn, symbol, "S", "skipped_sl_cancel_failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                detail=f"staged leg {leg_name}: could not cancel resting SL {row['sl_order_id']} "
                       f"before partial booking ({sl_cancel_result.get('detail')})",
            )
            print(f"[REAL TRADE] STAGED LEG {leg_name} for {row['kotak_trading_symbol']} DEFERRED - "
                  f"could not cancel resting SL first: {sl_cancel_result.get('detail')}")
            return

    if already_filled_at_kotak:
        exit_qty = leg_qty
        fill_price = real_leg.get("target_price") or row["entry_price"]
        _log_real_attempt(
            conn, symbol, "S", "confirmed_inferred", kotak_trading_symbol=row["kotak_trading_symbol"],
            qty=exit_qty, price_est=fill_price, notional_inr=exit_qty * fill_price,
            detail=f"staged leg {leg_name} - resting target order for this leg could not be "
                   f"cancelled (already filled at Kotak independently of this app); qty "
                   f"reconciled from the order's own price, NOT a fresh sell",
        )
        remaining_qty = row["qty"] - exit_qty
        print(f"[REAL TRADE] STAGED LEG {leg_name} for {row['kotak_trading_symbol']} already filled "
              f"at Kotak (resting order) - reconciling qty only, {remaining_qty} shares remain")
        _log_real_order_event(
            conn, symbol, f"staged_{leg_name}", "confirmed_inferred", kotak_trading_symbol=row["kotak_trading_symbol"],
            prev_state=f"long {row['qty']} @ Rs{row['entry_price']:.2f}",
            new_state=f"long {remaining_qty} (leg already filled at Kotak, qty reconciled, no new order placed)",
        )
    else:
        result = kotak_real_orders.place_real_exit(row["kotak_trading_symbol"], leg_qty)
        if not result.get("ok"):
            _log_real_attempt(
                conn, symbol, "S", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                qty=leg_qty, detail=result.get("detail"), raw_response=result.get("raw_response"),
            )
            print(f"[REAL TRADE] STAGED LEG {leg_name} SELL FAILED {row['kotak_trading_symbol']}: "
                  f"{result.get('detail')} - position still holds the full qty, will retry next tick "
                  f"the same way any other unfilled real-order leg does")
            _log_real_order_event(
                conn, symbol, f"staged_{leg_name}", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                prev_state=f"long {row['qty']} @ Rs{row['entry_price']:.2f}",
                new_state="unchanged - staged leg sell failed", detail=result.get("detail"),
            )
            _flag_if_t1_restricted(conn, symbol, result.get("detail"))
            if sl_was_cancelled:
                # Nothing sold - the position still holds its full original
                # qty, but the SL cancelled above is gone. Restore it
                # (same qty, same trigger) rather than leaving the
                # position naked over an unrelated sell failure.
                restore = _place_real_stop_loss_with_retry(
                    row["kotak_trading_symbol"], row["qty"], row["sl_trigger_price"]
                )
                if restore.get("ok"):
                    conn.execute(
                        "UPDATE real_positions SET sl_order_id = ? WHERE symbol = ?",
                        (restore["order_id"], symbol),
                    )
                    conn.commit()
                    _clear_protection_degraded(conn, symbol)
                    _log_real_order_event(
                        conn, symbol, "sl", "placed", kotak_trading_symbol=row["kotak_trading_symbol"],
                        order_id=restore["order_id"], prev_state="restored after staged sell failure",
                        new_state=f"resting SELL trigger Rs{restore['trigger_price']:.2f} for {row['qty']} shares",
                    )
                else:
                    conn.execute("UPDATE real_positions SET sl_order_id = NULL WHERE symbol = ?", (symbol,))
                    conn.commit()
                    # Stays degraded (already marked above) - the existing
                    # _maybe_sync_real_stop_loss escalation machinery
                    # covers this exactly as any other SL-placement gap.
                    _log_real_order_event(
                        conn, symbol, "sl", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                        prev_state="restoring after staged sell failure",
                        new_state="none (re-placement failed)", detail=restore.get("detail"),
                    )
                    _flag_if_t1_restricted(conn, symbol, restore.get("detail"))
            return

        exit_qty = int(result["qty"])
        fill_price = result.get("fill_price")
        remaining_qty = row["qty"] - exit_qty
        _log_real_attempt(
            conn, symbol, "S", "confirmed", kotak_trading_symbol=row["kotak_trading_symbol"],
            qty=exit_qty, price_est=fill_price,
            notional_inr=exit_qty * fill_price if fill_price else None,
            order_id=result["order_id"], raw_response=result.get("raw_response"),
            detail=f"staged leg {leg_name} partial exit"
                   + ("" if result["fill_price_confirmed"] else " - fill not yet confirmed by Kotak"),
        )
        print(f"[REAL TRADE] STAGED LEG {leg_name} SELL {exit_qty} {row['kotak_trading_symbol']} "
              f"(order {result['order_id']}) - {remaining_qty} shares remain")
        _log_real_order_event(
            conn, symbol, f"staged_{leg_name}", "confirmed", kotak_trading_symbol=row["kotak_trading_symbol"],
            order_id=result["order_id"], prev_state=f"long {row['qty']} @ Rs{row['entry_price']:.2f}",
            new_state=f"long {remaining_qty} (booked {exit_qty} @ Rs{fill_price or 0:.2f})",
        )

    # Mark this leg filled in the real-side ladder (mirrors
    # _execute_staged_leg_exit's own paper-side bookkeeping) - reuses
    # real_legs computed above rather than re-parsing exit_legs_json.
    legs = real_legs
    for leg_entry in legs:
        if leg_entry["leg"] == leg_name:
            leg_entry["status"] = "filled"

    if remaining_qty <= 0:
        # Every leg (including trail) somehow booked here rather than
        # through the normal full-exit path - close the row outright,
        # same as _maybe_place_real_exit's own DELETE.
        conn.execute("DELETE FROM real_positions WHERE symbol = ?", (symbol,))
        conn.commit()
        _sync_real_positions_external(conn)
        return
    conn.execute(
        "UPDATE real_positions SET qty = ?, exit_legs_json = ? WHERE symbol = ?",
        (remaining_qty, json.dumps(legs) if legs else None, symbol),
    )
    conn.commit()
    _sync_real_positions_external(conn)

    # 2026-09-21, explicit user instruction, live Cochin Shipyard incident:
    # this path used to place the NEW target for the next leg FIRST, then
    # the fresh SL for the same leg second - here the SL placement got
    # REJECTED, leaving the position with a resting profit target but NO
    # stop-loss at all until the user noticed and manually cancelled the
    # target and re-placed the SL themselves. "First after entry, I want
    # SL order then confirm and then send the target order." SL now goes
    # FIRST; the new target is only placed once the SL is CONFIRMED - if
    # SL placement fails, the new target is withheld entirely (same "no
    # naked target" principle, not just a reordering) rather than resting
    # an unprotected profit order. _maybe_sync_real_stop_loss keeps
    # retrying the SL every later tick exactly as an outright SL-placement
    # failure already does, and the scheduler's own per-tick poll
    # (_maybe_place_real_exit) still handles this leg's profit-booking
    # with no resting order backing it in the meantime.

    # Place a fresh SL sized to the smaller remaining qty FIRST. The OLD
    # SL order was already cancelled UP FRONT (before the sell attempt
    # above, per the 2026-09-14 fix) - this never resizes/cancels-then-
    # replaces here, it only ever PLACES, since nothing is left resting
    # to cancel. Also fires when there was no old sl_order_id at all but
    # a trigger price is still known (e.g. a prior placement failure had
    # already cleared it) - closes a pre-existing gap where such a
    # position would never get a fresh SL attempt from this path.
    sl_confirmed = False
    if remaining_qty > 0 and row["sl_trigger_price"]:
        sl_result = _place_real_stop_loss_with_retry(
            row["kotak_trading_symbol"], remaining_qty, row["sl_trigger_price"]
        )
        if sl_result.get("ok"):
            sl_confirmed = True
            conn.execute(
                "UPDATE real_positions SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
                (sl_result["order_id"], sl_result["trigger_price"], symbol),
            )
            _clear_protection_degraded(conn, symbol)
            _log_real_order_event(
                conn, symbol, "sl", "placed", kotak_trading_symbol=row["kotak_trading_symbol"],
                order_id=sl_result["order_id"], prev_state="placed fresh after staged leg booking",
                new_state=f"resting SELL trigger Rs{sl_result['trigger_price']:.2f} for {remaining_qty} shares",
            )
        else:
            # 2026-09-10, explicit user instruction after review: no
            # IMMEDIATE force-close here - starts (or leaves running) the
            # same degraded-protection clock _maybe_sync_real_stop_loss's
            # own top-of-function check escalates on, rather than either
            # force-closing on this one failure or trusting the tick-based
            # stop_hit check to cover the gap indefinitely. See
            # _protection_degraded_timeout_seconds' own docstring.
            conn.execute("UPDATE real_positions SET sl_order_id = NULL WHERE symbol = ?", (symbol,))
            _mark_protection_degraded(conn, symbol)
            _log_real_order_event(
                conn, symbol, "sl", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                prev_state="placing fresh after staged leg booking",
                new_state="none (placement failed)", detail=sl_result.get("detail"),
            )
            _flag_if_t1_restricted(conn, symbol, sl_result.get("detail"))

    # Advance the resting target to the NEXT unfilled fixed leg (if any) -
    # cancel the one that just filled (best-effort; it may already show
    # filled/gone at Kotak, a cancel on an already-filled order is a
    # harmless no-op rejection) and place a fresh one sized to the next
    # leg's own qty/price - ONLY once the fresh SL above is confirmed
    # resting (see this function's own 2026-09-21 comment above). No new
    # target is placed once only the "trail" leg remains - that qty is
    # governed by the position's existing target/leading-target-extend/
    # trailing-stop machinery exactly as a pre-revamp single-target
    # position, via the normal full-exit path (_maybe_place_real_exit)
    # whenever the paper engine's own exit_reason chain next fires.
    if row["target_order_id"]:
        kotak_real_orders.cancel_real_order(row["target_order_id"])
    else:
        # 2026-09-21, explicit user instruction ("check which order there
        # and then if u want place a better order then cancel that from
        # order book and then validate and then place new order") - same
        # lost-tracking gap cancel_existing_resting_sl was built for
        # (2026-09-08 AGL incident): target_order_id can be NULL here even
        # though a real resting target still exists at Kotak (a restart
        # landing between "a target got placed" and the next journal-sync
        # snapshot capturing its id). Sweeps the broker's OWN order book
        # (ground truth) for any bot-placed resting target on this symbol
        # and cancels it first, so advancing to the next leg can never
        # stack a duplicate target order on top of an orphaned one.
        kotak_real_orders.cancel_existing_resting_target(row["kotak_trading_symbol"])
    next_leg = next((l for l in legs if l["leg"] != "trail" and l["status"] == "open"), None)
    if sl_confirmed and next_leg and next_leg.get("target_price"):
        target_result = kotak_real_orders.place_real_target(
            row["kotak_trading_symbol"], next_leg["qty"], round(next_leg["target_price"], 2)
        )
        if target_result.get("ok"):
            conn.execute(
                "UPDATE real_positions SET target_order_id = ?, target_price = ? WHERE symbol = ?",
                (target_result["order_id"], target_result["target_price"], symbol),
            )
            _log_real_order_event(
                conn, symbol, "target", "placed", kotak_trading_symbol=row["kotak_trading_symbol"],
                order_id=target_result["order_id"], prev_state="advancing to next staged leg",
                new_state=f"resting SELL limit Rs{target_result['target_price']:.2f} for leg {next_leg['leg']}",
            )
        else:
            conn.execute("UPDATE real_positions SET target_order_id = NULL WHERE symbol = ?", (symbol,))
            _log_real_order_event(
                conn, symbol, "target", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                prev_state="advancing to next staged leg",
                new_state="none (placement failed)", detail=target_result.get("detail"),
            )
            # NOT a _flag_if_t1_restricted call - same 2026-09-22 correction
            # as the entry-flow target placement above (see its own comment
            # for the full reasoning): sl_confirmed being True here means
            # the fresh SL just placed above IS the competing resting
            # order this rejection is actually about, not evidence this
            # symbol is genuinely unsellable same-day.
    else:
        conn.execute("UPDATE real_positions SET target_order_id = NULL WHERE symbol = ?", (symbol,))
        if not sl_confirmed and next_leg and next_leg.get("target_price"):
            _log_real_order_event(
                conn, symbol, "target", "skipped_sl_not_confirmed", kotak_trading_symbol=row["kotak_trading_symbol"],
                prev_state="advancing to next staged leg",
                new_state="none (SL placement failed or unavailable - target withheld to avoid a naked position)",
            )
    _sync_real_positions_external(conn)


def _maybe_place_real_exit(conn, symbol: str, reason: str = None):
    """Mirrors a paper exit (any exit_reason) as a REAL sell that closes
    the matching real_positions row, if one exists. Deliberately NOT
    gated by is_real_trading_enabled() - see kotak_real_orders.
    place_real_exit's docstring: closing an already-open real position
    must never be blocked by the same switch that gates new entries."""
    _why_log = functools.partial(_log_real_order_event, reason=reason or _REASON_UNSTATED)
    row = conn.execute("SELECT * FROM real_positions WHERE symbol = ?", (symbol,)).fetchone()
    if not row:
        return  # no real position was ever opened for this paper trade - nothing to close
    # 2026-10-06 engine-ownership thumb rule (CLAUDE.md): a position is exited
    # only by the engine that entered it. The intraday engine never closes a
    # symbol the swing engine owns (RVNL/SAIL/DRREDDY/VBL incident).
    if (conn.execute("SELECT 1 FROM real_positions_swing WHERE symbol = ?", (symbol,)).fetchone()
            or conn.execute("SELECT 1 FROM signal_state_swing WHERE symbol = ?", (symbol,)).fetchone()):
        print(f"[REAL] intraday exit REFUSED for {symbol}: owned by the swing engine")
        return

    import kotak_real_orders

    # BUG found live 2026-09-08 (investigating a related duplicate-SL
    # question): this app's own real_positions row can survive a restart
    # that landed between "the exit already executed at Kotak" and "the
    # DELETE that would have removed this row actually committing" - see
    # _kotak_symbol_still_open's own docstring for the full mechanism.
    # Verify against Kotak's OWN positions() before placing a second real
    # sell for a position that may already be closed - None (fetch
    # failed) still proceeds, since refusing a genuinely-needed exit is
    # worse than risking a check that couldn't run.
    still_open = _kotak_symbol_still_open(row["kotak_trading_symbol"])
    if still_open is False:
        conn.execute("DELETE FROM real_positions WHERE symbol = ?", (symbol,))
        conn.commit()
        _sync_real_positions_external(conn)
        _log_real_attempt(
            conn, symbol, "S", "skipped_already_closed_at_kotak", kotak_trading_symbol=row["kotak_trading_symbol"],
            qty=row["qty"],
            detail="Kotak shows no open position for this symbol - stale real_positions row "
                   "(likely a restart-interrupted DELETE from an earlier exit) cleared without a second sell",
        )
        print(f"[REAL TRADE] SKIPPED duplicate exit for {row['kotak_trading_symbol']} - "
              f"Kotak already shows it closed, stale local row cleared instead of re-selling")
        _why_log(
            conn, symbol, "exit", "skipped_duplicate", kotak_trading_symbol=row["kotak_trading_symbol"],
            prev_state=f"tracked open (stale), long {row['qty']} @ Rs{row['entry_price']:.2f}",
            new_state="cleared - Kotak already shows this closed",
        )
        return
    _why_log(
        conn, symbol, "exit", "intent", kotak_trading_symbol=row["kotak_trading_symbol"],
        prev_state=f"long {row['qty']} @ Rs{row['entry_price']:.2f}",
        new_state="cancel resting SL/target, then market SELL to be sent to Kotak")
    # Cancel the resting real stop-loss FIRST (if one was ever placed) -
    # best-effort, never blocks the exit below even if the cancel fails
    # (e.g. the SL already fired, which is itself a valid reason
    # real_positions still shows this row - see the reconcile endpoint).
    # Left behind uncancelled, a stale SL sell order with nothing left
    # to sell once this exit fills would just sit as a harmless rejected
    # order at Kotak, not a real risk - but cancelling first keeps the
    # order book clean and avoids that rejection noise.
    if row["sl_order_id"]:
        cancel_result = kotak_real_orders.cancel_real_order(row["sl_order_id"])
        if cancel_result.get("ok"):
            _why_log(
                conn, symbol, "sl", "cancelled", kotak_trading_symbol=row["kotak_trading_symbol"],
                order_id=row["sl_order_id"], prev_state=f"resting @ Rs{row['sl_trigger_price']}",
                new_state="cancelled (position exiting)",
            )
        else:
            print(f"[REAL TRADE] SL cancel failed for {row['kotak_trading_symbol']} "
                  f"(order {row['sl_order_id']}): {cancel_result.get('detail')} - proceeding with exit anyway")
            _why_log(
                conn, symbol, "sl", "cancel_failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                order_id=row["sl_order_id"], prev_state=f"resting @ Rs{row['sl_trigger_price']}",
                new_state="cancel failed - may still be resting", detail=cancel_result.get("detail"),
            )
    # Same reasoning, for the other resting leg (2026-09-08): whichever of
    # SL/target actually triggered this exit, the OTHER one is still
    # resting at Kotak with nothing left to sell once this order fills -
    # cancel it too, best-effort, before placing the exit itself.
    if row["target_order_id"]:
        cancel_result = kotak_real_orders.cancel_real_order(row["target_order_id"])
        if cancel_result.get("ok"):
            _why_log(
                conn, symbol, "target", "cancelled", kotak_trading_symbol=row["kotak_trading_symbol"],
                order_id=row["target_order_id"], prev_state=f"resting @ Rs{row['target_price']}",
                new_state="cancelled (position exiting)",
            )
        else:
            print(f"[REAL TRADE] target cancel failed for {row['kotak_trading_symbol']} "
                  f"(order {row['target_order_id']}): {cancel_result.get('detail')} - proceeding with exit anyway")
            _why_log(
                conn, symbol, "target", "cancel_failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                order_id=row["target_order_id"], prev_state=f"resting @ Rs{row['target_price']}",
                new_state="cancel failed - may still be resting", detail=cancel_result.get("detail"),
            )

    result = kotak_real_orders.place_real_exit(row["kotak_trading_symbol"], row["qty"])
    if result.get("ok"):
        conn.execute("DELETE FROM real_positions WHERE symbol = ?", (symbol,))
        # Resync to Kotak's own confirmed fill data for the audit log, same
        # reasoning as the entry side (explicit user instruction 2026-09-08)
        # - fill_price is the real avgPrc when confirmed, else None (the
        # real P&L figure this app displays/gates on is sourced separately,
        # straight from Kotak's own positions() aggregation - see
        # get_real_pnl_today_inr - so this is a logging-accuracy fix, not a
        # P&L-correctness one).
        exit_qty = int(result["qty"])
        _log_real_attempt(
            conn, symbol, "S", "confirmed", kotak_trading_symbol=row["kotak_trading_symbol"],
            qty=exit_qty, price_est=result.get("fill_price"),
            notional_inr=exit_qty * result["fill_price"] if result.get("fill_price") else None,
            order_id=result["order_id"], raw_response=result.get("raw_response"),
            detail=None if result["fill_price_confirmed"] else "fill not yet confirmed by Kotak",
        )
        _sync_real_positions_external(conn)
        print(f"[REAL TRADE] SELL {exit_qty} {row['kotak_trading_symbol']} (order {result['order_id']}) "
              f"(fill_confirmed={result['fill_price_confirmed']})")
        _why_log(
            conn, symbol, "exit", "confirmed", kotak_trading_symbol=row["kotak_trading_symbol"],
            order_id=result["order_id"],
            prev_state=f"long {row['qty']} @ Rs{row['entry_price']:.2f}",
            new_state=f"closed, {exit_qty} @ Rs{result.get('fill_price') or 0:.2f}",
            detail=None if result["fill_price_confirmed"] else "fill not yet confirmed by Kotak",
        )
    else:
        # The dangerous failure mode: a real position we believe is open
        # and TRIED to close, but couldn't confirm. Left in real_positions
        # deliberately (never guess it closed) - surfaces via
        # GET /kotak-neo/real-positions until a human/retry resolves it.
        _log_real_attempt(
            conn, symbol, "S", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
            qty=row["qty"], detail=result.get("detail"), raw_response=result.get("raw_response"),
        )
        print(f"[REAL TRADE] SELL FAILED {row['kotak_trading_symbol']}: {result.get('detail')} - POSITION STILL OPEN, NEEDS ATTENTION")
        _why_log(
            conn, symbol, "exit", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
            prev_state=f"long {row['qty']} @ Rs{row['entry_price']:.2f}",
            new_state="still open - exit attempt failed", detail=result.get("detail"),
        )
        _flag_if_t1_restricted(conn, symbol, result.get("detail"))


def _ensure_signal_state_for_real_position(conn, real_row) -> bool:
    """Backfills a missing signal_state row for a symbol that already has
    an open real_positions row - factored out of
    kotak_neo_reconcile_real_positions' own governance-backfill loop
    (2026-09-08) so _maybe_sync_real_stop_loss (below) can call the SAME
    logic on every tick, not just during a periodic/manual reconcile.

    2026-09-09, explicit user finding: "the trailing stop loss is not
    being maintained at the end of Kotak Neo... if not being done then
    do that now." Root cause traced live: /daily-summary showed
    open_positions: [] (paper signal_state completely empty) while 4 real
    positions were genuinely open - this Render service's own restart
    cadence (many deploys in a short window, same as every other restart-
    race this session) wiped signal_state for these symbols before it
    could be journal-synced. _maybe_sync_real_stop_loss's very first real
    check (SELECT stop_loss FROM signal_state WHERE symbol=? AND
    status='long') was returning nothing for every one of them, so it
    returned early EVERY TICK - never once syncing the trailing stop to
    Kotak, exactly matching what was reported. Worse: with no signal_state
    row, _auto_signal_core's own open-position management branch never
    even saw these symbols, so nothing was managing them past their
    initial static stop at all.

    Sized off the symbol's own WATCHLIST risk config (stop_pct) and the
    live rr setting, applied to the REAL entry price already on the
    real_positions row - the same math a fresh entry would have used,
    computed after the fact. entry_ts is set to NOW (backfill time), not
    a guessed real fill time - pragmatic and safe: it only makes the
    trailing-stop's "highest close since entry" window and the stale-
    timeout's elapsed-time count start a little late, never early.
    Returns True if a row was created, False if one already existed OR
    real_row turned out to be a GHOST (Kotak shows no genuinely open
    position for it - see the 2026-09-09 addition below).

    2026-09-09, explicit user finding right after this self-heal first
    shipped: DEEP.NS showed as REAL LIVE on the dashboard after already
    being exited - this function would otherwise have backfilled a fresh
    signal_state row (and _maybe_sync_real_stop_loss would then have
    tried placing a real SL) for a real_positions row that was itself
    already a GHOST (a restart landed between the exit's DELETE and its
    own commit, same restart-race class as the SL-tracking bug
    documented in _maybe_place_real_exit/_kotak_symbol_still_open).
    Backfilling paper tracking for a position that's ALREADY CLOSED at
    Kotak would have resurrected management of nothing, and any SL
    placement attempt would have been a pointless, confusing rejection
    (no real shares behind it). Ground-truth check FIRST, one Kotak
    positions() call - cheap here specifically because this only runs
    when a signal_state row is about to be freshly created (rare - once
    per symbol whose tracking was actually wiped), never on the
    steady-state per-tick path where a row already exists. still_open is
    None (a fetch failure) is treated as "assume open" - the same fail-
    OPEN precedent _kotak_symbol_still_open's own docstring already
    establishes, since silently abandoning a genuinely open position over
    a transient API hiccup is worse than one extra backfill attempt."""
    already = conn.execute(
        "SELECT 1 FROM signal_state WHERE symbol = ? AND status = 'long'", (real_row["symbol"],)
    ).fetchone()
    if already:
        return False
    still_open = _kotak_symbol_still_open(real_row["kotak_trading_symbol"])
    if still_open is False:
        conn.execute("DELETE FROM real_positions WHERE symbol = ?", (real_row["symbol"],))
        conn.commit()
        _sync_real_positions_external(conn)
        print(f"[signal_state_backfill] {real_row['symbol']} is a ghost real_positions row "
              f"(Kotak shows no open position) - removed instead of backfilling paper tracking for it")
        return False
    watchlist_by_symbol = {cfg["symbol"]: cfg for cfg in WATCHLIST}
    cfg = watchlist_by_symbol.get(real_row["symbol"], {})
    stop_pct = cfg.get("stop_pct", 2.0)
    live_rr = get_runtime_setting(conn, "rr")
    entry_price = real_row["entry_price"]
    stop_loss = round(entry_price * (1 - stop_pct / 100), 2)
    target = round(entry_price + live_rr * (entry_price - stop_loss), 2)
    conn.execute(
        "INSERT INTO signal_state (symbol, day, status, entry_price, stop_loss, "
        "initial_stop_loss, target, qty, entry_ts, fx_to_inr, interval) "
        "VALUES (?, ?, 'long', ?, ?, ?, ?, ?, ?, 1.0, '5m') "
        "ON CONFLICT(symbol) DO NOTHING",
        (real_row["symbol"], ist_now().strftime("%Y-%m-%d"), entry_price, stop_loss, stop_loss, target,
         real_row["qty"], time.time()),
    )
    conn.commit()
    print(f"[signal_state_backfill] restored missing paper tracking for {real_row['symbol']} "
          f"(entry Rs{entry_price:.2f}, stop Rs{stop_loss:.2f}, target Rs{target:.2f})")
    return True


def _kotak_symbol_still_open_short(kotak_trading_symbol: str) -> bool | None:
    """Short mirror of _kotak_symbol_still_open (2026-09-30, "make it auto
    heal" for shorts too) - that function's own `fl_buy > 0` check makes it
    return False for EVERY genuine short (a pure short has flBuyQty == 0),
    so it can never be reused here; a short position is genuinely open when
    flSellQty > 0 and differs from flBuyQty. Same fail-OPEN precedent on a
    fetch failure (None) as the long version."""
    try:
        import kotak_neo
        positions = kotak_neo.positions()
        rows = positions.get("data") or [] if isinstance(positions, dict) else []
    except Exception:
        return None
    for row in rows:
        if row.get("trdSym") != kotak_trading_symbol or row.get("exSeg") != "nse_cm":
            continue
        try:
            fl_buy = float(row.get("flBuyQty", 0) or 0)
            fl_sell = float(row.get("flSellQty", 0) or 0)
        except (TypeError, ValueError):
            continue
        if _is_delivery_sell_not_short(row, fl_buy - fl_sell):
            continue  # B-1403
        if fl_sell > 0 and fl_sell != fl_buy:
            return True
    return False


def _ensure_signal_state_for_real_position_short(conn, real_row) -> bool:
    """Short mirror of _ensure_signal_state_for_real_position (2026-09-30,
    explicit user instruction after the MFSL.NS incident: "For short
    positions and all live positions make it auto heal") - backfills a
    missing signal_state_short row for a symbol that already has an open
    real_positions_short row, so _reconcile_real_positions_core's own
    governance-backfill loop can then synchronously place a real
    protective BUY-side stop for it, exactly mirroring what the long side
    has done since 2026-09-08.

    Sized off the same WATCHLIST stop_pct/live rr config as the long
    version, mirrored: initial_stop_loss sits ABOVE entry_price (a short's
    stop), target sits BELOW it. entry_ts is set to NOW (backfill time),
    same "starts a little late, never early" reasoning as the long
    version. Returns True if a row was created, False if one already
    existed OR real_row turned out to be a ghost (Kotak shows no
    genuinely open SHORT for it - see _kotak_symbol_still_open_short)."""
    already = conn.execute(
        "SELECT 1 FROM signal_state_short WHERE symbol = ? AND status = 'short'", (real_row["symbol"],)
    ).fetchone()
    if already:
        return False
    still_open = _kotak_symbol_still_open_short(real_row["kotak_trading_symbol"])
    if still_open is False:
        conn.execute("DELETE FROM real_positions_short WHERE symbol = ?", (real_row["symbol"],))
        conn.commit()
        _sync_real_positions_short_external(conn)
        print(f"[signal_state_backfill_short] {real_row['symbol']} is a ghost real_positions_short row "
              f"(Kotak shows no open short) - removed instead of backfilling paper tracking for it")
        return False
    watchlist_by_symbol = {cfg["symbol"]: cfg for cfg in WATCHLIST}
    cfg = watchlist_by_symbol.get(real_row["symbol"], {})
    stop_pct = cfg.get("stop_pct", 2.0)
    live_rr = get_runtime_setting(conn, "rr")
    entry_price = real_row["entry_price"]
    stop_loss = round(entry_price * (1 + stop_pct / 100), 2)
    target = round(entry_price - live_rr * (stop_loss - entry_price), 2)
    conn.execute(
        "INSERT INTO signal_state_short (symbol, day, status, entry_price, stop_loss, "
        "initial_stop_loss, target, qty, entry_ts, fx_to_inr, interval, strategy) "
        "VALUES (?, ?, 'short', ?, ?, ?, ?, ?, ?, 1.0, '5m', ?) "
        "ON CONFLICT(symbol) DO NOTHING",
        (real_row["symbol"], ist_now().strftime("%Y-%m-%d"), entry_price, stop_loss, stop_loss, target,
         real_row["qty"], time.time(), real_row["strategy"] or "range_short"),
    )
    conn.commit()
    print(f"[signal_state_backfill_short] restored missing paper tracking for {real_row['symbol']} "
          f"(entry Rs{entry_price:.2f}, stop Rs{stop_loss:.2f}, target Rs{target:.2f})")
    return True


def _real_sl_order_is_live(order_id: str) -> bool | None:
    """True if `order_id`'s own status at Kotak (via order_report) is a
    genuinely still-resting/pending state; False if it's dead with no
    fill (rejected/cancelled); None if the read itself failed or came
    back unparseable - callers must treat None as "unknown this tick",
    never as either live or dead (see _maybe_sync_real_stop_loss's own
    call site for why).

    2026-09-22 live finding (ASHOKLEY.NS, real position): a resting SL
    order's own placement response only ever proves Kotak ACCEPTED the
    conditional order - never that a future trigger-time sell will
    succeed. Confirmed live same-day: a plain LIMIT sell (the profit
    target, order 260922000149358) for this exact symbol was rejected
    immediately with ordSt "rejected" / rejRsn "RMS:Rule: Check T1
    holdings...", rejLongDesc "...Selling Trade-to-Trade stocks on the
    same day of purchase is not allowed" - while the SL-TRG order (order
    260922000149135, SAME symbol, same underlying shares) sat at ordSt
    "trigger pending" with no rejection at all. A price-type "SL" order
    is accepted to REST without this same-day-sell check; it is not
    exempt from it once it actually fires. That means a resting SL for a
    T1/T2T-restricted symbol can go from genuinely fine to silently dead
    the instant it triggers, with NOTHING pushed back to this app -
    _maybe_sync_real_stop_loss used to trust its own local sl_order_id
    column as proof of live protection forever, with no active
    reconciliation against Kotak's own order book to catch this."""
    import kotak_neo
    try:
        resp = kotak_neo.order_report(order_id=order_id)
    except Exception:
        return None
    rows = resp.get("data") if isinstance(resp, dict) else None
    if not rows or not isinstance(rows, list) or not isinstance(rows[0], dict):
        return None
    ord_st = str(rows[0].get("ordSt", "")).strip().lower()
    if not ord_st:
        return None
    # Confirmed live values (2026-09-22): "trigger pending" (resting,
    # not yet fired - fine), "rejected" (dead, T1/T2T at trigger time -
    # the case this exists to catch). "open"/"pending" added defensively
    # for other still-resting phrasings Kotak may use elsewhere in its
    # order lifecycle - never independently confirmed live, unlike the
    # two above. Deliberately a live-state ALLOWLIST, not a dead-state
    # blocklist: an unrecognized future status reads as dead (fail
    # toward re-placing a fresh SL / escalating the existing degraded-
    # protection timer, never toward silently trusting a status this
    # app has never actually seen).
    return ord_st in ("trigger pending", "open", "pending")


def _real_sl_rejection_detail(order_id: str) -> str | None:
    """Best-effort fetch of WHY `order_id` was rejected, for the reconcile
    path (2026-09-23, live SUZLON.NS finding - see the module comment
    above _maybe_sync_real_stop_loss's T1/T2T handling). A SEPARATE call
    from _real_sl_order_is_live (which only classifies live-vs-dead, by
    design - its own 5 unit tests pin bool | None as its contract) rather
    than changing that function's return shape.

    Kotak's rejection reason can land in EITHER rejRsn or rejLongDesc
    depending on rejection type - the live ASHOKLEY.NS fixture that
    motivated _real_sl_order_is_live itself shows the T1/T2T same-day-sell
    marker specifically in rejLongDesc, not rejRsn (rejRsn there was a
    generic "RMS:Rule: Check T1 holdings..." line that _T1_HOLDINGS_MARKER
    already catches, but the more specific T2T wording
    _T2T_SAME_DAY_MARKER looks for is only in rejLongDesc) - so both are
    concatenated and handed to _flag_if_t1_restricted's substring check
    rather than guessing which field carries it. Returns None on any
    failure - never raises, matching every other real-order read in this
    file."""
    import kotak_neo
    try:
        resp = kotak_neo.order_report(order_id=order_id)
    except Exception:
        return None
    rows = resp.get("data") if isinstance(resp, dict) else None
    if not rows or not isinstance(rows, list) or not isinstance(rows[0], dict):
        return None
    row = rows[0]
    parts = [str(row.get("rejRsn") or "").strip(), str(row.get("rejLongDesc") or "").strip()]
    detail = " ".join(p for p in parts if p)
    return detail or None


ORPHAN_SWING_STRATEGY_TAG = "swing_rerouted_orphan"
ORPHAN_SWING_GAP_R_MULT = 0.5   # gap-down through the carried stop: new stop = open - 0.5R
ORPHAN_SWING_TRAIL_R_MULT = 1.0  # trail = peak close - 1R (R stored in atr_at_entry)
ORPHAN_SWING_LAST_RESORT_STOP_PCT = 0.01  # only if no prior stop AND no prior-day low is obtainable


def _orphan_prev_day_stop(conn, symbol, entry):
    """Previous trading day's stop for an orphan holding (user, 2026-10-06:
    "replicate the stop loss from previous trading day, store it, reuse it").
    1) the latest resting-SL trigger this app logged for the symbol (below
    entry); 1b) else the most recent SL order for the stock in Kotak's order
    book; 2) else the prior session's low from daily bars; 3) else a 1%
    last-resort so a position is never left unprotected. Returns (stop, source)."""
    import re
    for (ns,) in conn.execute(
        "SELECT new_state FROM real_order_events WHERE symbol = ? AND leg = 'sl' "
        "AND event IN ('placed','trailed','moved') ORDER BY ts DESC LIMIT 10", (symbol,)
    ).fetchall():
        m = re.search(r"Rs([0-9]+(?:\.[0-9]+)?)", ns or "")
        if m and 0 < float(m.group(1)) < entry:
            return round(float(m.group(1)), 2), "previous resting stop-loss logged for this symbol"
    # 1b) not in the app log (user, 2026-10-06): the most recent SL order for
    # this stock in Kotak's own order book, whatever its status.
    try:
        trd = None
        for tbl in ("real_positions_swing", "real_positions"):
            r0 = conn.execute(f"SELECT kotak_trading_symbol FROM {tbl} WHERE symbol = ?", (symbol,)).fetchone()
            if r0 and r0[0]:
                trd = r0[0]
                break
        if trd:
            import kotak_neo
            rows = (kotak_neo.order_report() or {}).get("data") or []
            sls = [r for r in rows if r.get("trdSym") == trd and r.get("trnsTp") == "S"
                   and str(r.get("prcTp", "")).upper() in ("SL", "SL-M")]
            sls.sort(key=lambda r: str(r.get("ordDtTm", "")), reverse=True)
            for r in sls:
                try:
                    trg = float(r.get("trgPrc"))
                except (TypeError, ValueError):
                    continue
                if 0 < trg < entry:
                    return round(trg, 2), "most recent SL order in Kotak's order book for this stock"
    except Exception as e:
        print(f"[REAL] orphan Kotak order-book SL lookup failed for {symbol}: {e}")
    try:
        df = fetch_ohlc(symbol, "10d", "1d")
        today = ist_now().strftime("%Y-%m-%d")
        prior = [i for i in range(len(df)) if str(df.index[i])[:10] < today]
        if prior:
            low = float(df["Low"].iloc[prior[-1]])
            if 0 < low < entry:
                return round(low, 2), "previous trading day's low"
    except Exception as e:
        print(f"[REAL] orphan prev-day stop lookup failed for {symbol}: {e}")
    return round(entry * (1 - ORPHAN_SWING_LAST_RESORT_STOP_PCT), 2), "last-resort 1% (no prior stop or prior-day low available)"


def _orphan_refresh_stop(conn, row):
    """Called just before an orphan swing row's SL is placed. Rows created
    before this logic (atr_at_entry NULL) get the carried previous-day stop
    stored once and reused. Then, if today's OPEN gapped through that stop,
    the stop becomes open - 0.5R (R = entry - carried stop). Trailing is the
    ordinary daily ratchet (_swing_strategy_stop_level). Returns the stop to
    place, or None if today's open isn't available yet."""
    symbol = row["symbol"]
    st = conn.execute("SELECT * FROM signal_state_swing WHERE symbol = ?", (symbol,)).fetchone()
    if not st:
        return round(row["stop_loss"], 2)
    entry = float(st["entry_price"])
    stop, r = float(st["initial_stop_loss"]), st["atr_at_entry"]
    if r is None:  # carried stop not stored yet
        stop, src = _orphan_prev_day_stop(conn, symbol, entry)
        r = round(entry - stop, 4)
        conn.execute(
            "UPDATE signal_state_swing SET initial_stop_loss = ?, gap_low = ?, atr_at_entry = ?, "
            "running_max_close = COALESCE(running_max_close, ?) WHERE symbol = ?",
            (stop, stop, r, entry, symbol))
        conn.execute("UPDATE real_positions_swing SET stop_loss = ? WHERE symbol = ?", (stop, symbol))
        conn.commit()
        _log_real_order_event(
            conn, symbol, "reroute", "stop_carried", kotak_trading_symbol=row["kotak_trading_symbol"],
            prev_state=f"placeholder stop Rs{float(row['stop_loss']):.2f}",
            new_state=f"stored stop Rs{stop:.2f}, R Rs{r:.2f}",
            reason=f"orphan swing stop replicated from {src} and stored for reuse")
    try:
        df = fetch_ohlc(symbol, "5d", "1d")
        if str(df.index[-1])[:10] != ist_now().strftime("%Y-%m-%d"):
            return None
        open_px = float(df["Open"].iloc[-1])
    except Exception as e:
        print(f"[REAL] orphan open lookup failed for {symbol}: {e}")
        return None
    if open_px <= stop:
        new_stop = round(open_px - ORPHAN_SWING_GAP_R_MULT * float(r), 2)
        conn.execute("UPDATE signal_state_swing SET initial_stop_loss = ?, gap_low = ? WHERE symbol = ?",
                     (new_stop, new_stop, symbol))
        conn.execute("UPDATE real_positions_swing SET stop_loss = ? WHERE symbol = ?", (new_stop, symbol))
        conn.commit()
        _log_real_order_event(
            conn, symbol, "reroute", "stop_gap_reset", kotak_trading_symbol=row["kotak_trading_symbol"],
            prev_state=f"carried stop Rs{stop:.2f}", new_state=f"stop Rs{new_stop:.2f}",
            reason=f"opened Rs{open_px:.2f} at/below carried stop; stop reset to open - 0.5R (R Rs{float(r):.2f})")
        _sync_real_positions_swing_external(conn)
        _sync_signal_state_swing_external(conn)
        return new_stop
    _sync_real_positions_swing_external(conn)
    _sync_signal_state_swing_external(conn)
    return round(stop, 2)


def _reroute_orphan_intraday_to_swing(conn, real_row) -> bool:
    """2026-10-06 (DRREDDY/RVNL, user: option 1): a real_positions row with NO
    strategy, NO resting SL and NO target is an adopted/orphaned holding, not
    an intraday entry (the entry path always stamps a strategy). Left in the
    intraday table it gets the intraday emergency market-sell, which breaks
    the engine-ownership rule for swing buys. Move it to the swing engine:
    paper signal_state_swing row + real_positions_swing row (swing backfill
    then places its SL), drop the intraday row, log the reason. Returns True
    if moved."""
    if real_row["strategy"] or real_row["sl_order_id"] or real_row["target_order_id"]:
        return False
    symbol = real_row["symbol"]
    entry = float(real_row["entry_price"])
    stop, _src = _orphan_prev_day_stop(conn, real_row["symbol"], entry)
    r = round(entry - stop, 4)
    qty = int(real_row["qty"])
    day = real_row["day"]
    conn.execute(
        "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, initial_stop_loss, "
        "gap_low, qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) "
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1.0, ?, ?) ON CONFLICT(symbol) DO NOTHING",
        (symbol, ORPHAN_SWING_STRATEGY_TAG, day, entry, stop, stop, qty, real_row["opened_at"], r, entry),
    )
    conn.execute(
        "INSERT INTO real_positions_swing (symbol, kotak_trading_symbol, qty, entry_price, entry_order_id, "
        "opened_at, day, stop_loss, strategy) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(symbol) DO NOTHING",
        (symbol, real_row["kotak_trading_symbol"], qty, entry, real_row["entry_order_id"],
         real_row["opened_at"], day, stop, ORPHAN_SWING_STRATEGY_TAG),
    )
    conn.execute("DELETE FROM real_positions WHERE symbol = ?", (symbol,))
    apply_paper_trade(conn, symbol, "buy", qty, entry)  # so the swing paper exit has a position to close
    conn.commit()
    _sync_real_positions_external(conn)
    _sync_real_positions_swing_external(conn)
    _sync_signal_state_swing_external(conn)
    _log_real_order_event(
        conn, symbol, "reroute", "moved_to_swing", kotak_trading_symbol=real_row["kotak_trading_symbol"],
        prev_state="intraday table (no strategy, no SL, no target)",
        new_state=f"swing table, stop Rs{stop:.2f} (from {_src})",
        reason="orphan holding in the intraday table; swing engine owns it so no intraday emergency/EOD sell",
    )
    print(f"[REAL] rerouted orphan {symbol} intraday -> swing (stop Rs{stop:.2f})")
    return True


def _maybe_sync_real_stop_loss(conn, symbol: str):
    """Keeps a real position's RESTING stop-loss order at Kotak in step
    with the paper trailing stop _auto_signal_core just ratcheted (see
    the `current_stop = trail_candidate` branch there) - explicit user
    instruction 2026-09-07 ("update stop-loss to Kotak on trigger").
    Called every tick for every symbol (cheap: one SELECT when there's no
    real position for it), right after the entry/exit mirroring above -
    deliberately NOT called from inside _auto_signal_core itself, same
    isolation principle as _maybe_place_real_entry/_exit.

    Only ever moves the resting stop UP (mirrors the paper trail, which
    itself never ratchets down - see _auto_signal_core) and only replaces
    it when the paper stop has actually moved since the last sync, so a
    held position isn't cancel/replaced every single tick for no reason.
    If no SL is resting yet (an earlier placement failed), this also
    retries placing it fresh at the paper stop's current level - see
    _maybe_place_real_entry's own comment on that retry path.

    2026-09-10, explicit user instruction (state-machine correction on
    top of #13's own fix): the FIRST thing this function does, every
    call, is check whether the position is currently missing a resting
    SL and if so how long that's been true - see
    _protection_degraded_timeout_seconds' own docstring for the full
    reasoning (the tick-based stop_hit check alone only covers a SLOW
    move through the stop, never a gap/flash-move/halt/outage). Degraded
    but within tolerance -> keep retrying below, same as always.
    Degraded past tolerance -> force a full exit right here, before
    anything else runs this tick."""
    real_row = conn.execute("SELECT * FROM real_positions WHERE symbol = ?", (symbol,)).fetchone()
    if not real_row:
        return
    if _reroute_orphan_intraday_to_swing(conn, real_row):
        return  # now owned by the swing engine (its own SL backfill takes over)

    # Self-heal a missing paper counterpart RIGHT HERE, every tick - see
    # _ensure_signal_state_for_real_position's own docstring for the
    # 2026-09-09 bug this closes (a restart wiping signal_state for a
    # symbol that still has a genuinely open real position, silently
    # stopping trailing-stop sync AND all other paper-side management of
    # it, discovered only when the user reported the trailing stop
    # wasn't moving). Previously this only got fixed by a periodic/
    # manual reconcile dispatch; now it can never persist past one tick.
    _ensure_signal_state_for_real_position(conn, real_row)

    # Qty reconciliation (2026-09-23, live SUZLON.NS finding) - see
    # _reconcile_real_qty's own docstring for why this must run before any
    # SL sizing decision below: an organic fill at Kotak this app's own
    # mirror never caught leaves real_positions.qty stale and too HIGH,
    # which then sizes every subsequent SL placement for more shares than
    # are actually held.
    real_row = _reconcile_real_qty(conn, real_row)

    # Active reconciliation against Kotak's own order book (2026-09-22,
    # see _real_sl_order_is_live's own docstring for the live ASHOKLEY.NS
    # finding this closes) - sl_order_id being set here only ever meant
    # "the last placement attempt was accepted," never "still true right
    # now." A resting SL-TRG order can go dead (rejected at trigger time,
    # same T1/T2T restriction a same-day sell always risks) with nothing
    # pushed back to this app - the only way to know is to ask. Runs
    # before the degraded-protection check below so a confirmed-dead SL
    # feeds the EXACT SAME escalation ladder as "no SL was ever placed,"
    # not a separate path - re-fetches real_row after clearing so every
    # later reference in this function sees the corrected state.
    if real_row["sl_order_id"]:
        sl_is_live = _real_sl_order_is_live(real_row["sl_order_id"])
        if sl_is_live is False:
            # Logged for visibility only, NOT fed to _flag_if_t1_restricted
            # (2026-09-23 correction of a mistake made earlier the same
            # day, live SUZLON.NS - see the module comment above
            # _maybe_place_real_entry's own target-placement-failure
            # branch, "NOT a _flag_if_t1_restricted call, on purpose",
            # 2026-09-22/IDEA.NS-ASHOKLEY.NS-CONCOR.NS finding: a rejection
            # HERE can equally be caused by a competing resting order
            # (Kotak's "one exit order per holding" rule) or by asking to
            # sell MORE than is currently held (see _reconcile_real_qty,
            # added the same day this SUZLON.NS case surfaced) - neither
            # of which means the symbol is genuinely unsellable same-day.
            # Flagging here without ruling those out is exactly the false-
            # positive /kotak-neo/t1-unflag exists to undo. A genuine T1/T2T
            # symbol still gets caught via _maybe_place_real_exit's own
            # rejection, which has no such competing-order/qty explanation
            # available by the time it fires.
            rejection_detail = _real_sl_rejection_detail(real_row["sl_order_id"])
            print(f"[REAL TRADE] resting SL {real_row['sl_order_id']} for "
                  f"{real_row['kotak_trading_symbol']} found DEAD on reconcile "
                  f"(no fill) - clearing it so the retry/escalation path below picks it up. "
                  f"detail: {rejection_detail}")
            _log_real_order_event(
                conn, symbol, "sl", "found_dead_on_reconcile", kotak_trading_symbol=real_row["kotak_trading_symbol"],
                order_id=real_row["sl_order_id"], prev_state="assumed resting",
                new_state="dead at Kotak (rejected/cancelled, no fill)", detail=rejection_detail,
            )
            # sl_trigger_price cleared too, not just sl_order_id: left in
            # place, it still represents the DEAD order's price, and the
            # "no upward move since last sync" gate further down (`if
            # current_sl_price is not None and new_stop <= current_sl_price:
            # return`) would then skip re-placing this same tick whenever
            # the paper stop hasn't moved since - the degraded clock would
            # start but nothing would actually retry until it eventually
            # does, working against "retry aggressively while degraded."
            # NULL here reads as "no known resting price," same as a
            # position that never had an SL yet, which already falls
            # through to an immediate placement attempt.
            conn.execute(
                "UPDATE real_positions SET sl_order_id = NULL, sl_trigger_price = NULL WHERE symbol = ?",
                (symbol,),
            )
            conn.commit()
            real_row = conn.execute("SELECT * FROM real_positions WHERE symbol = ?", (symbol,)).fetchone()
        # sl_is_live is None (order_report itself failed/unparseable) or
        # True: say nothing and trust the existing local state for this
        # tick - an unreadable check must never force an exit on an API
        # hiccup rather than a real event, same fail-quiet-on-unknown
        # stance as _real_loss_budget's own "unknown -> refuse, don't
        # force" philosophy elsewhere in this file.

    # Degraded-protection timeout check (2026-09-10, explicit user
    # instruction - the state-machine correction on #13's own fix) -
    # runs FIRST, unconditionally, before anything below that could
    # return early without ever seeing it. See
    # _protection_degraded_timeout_seconds' own docstring for the full
    # reasoning: retry aggressively while degraded (already happens every
    # tick below), tolerate a bounded window, escalate to a full exit
    # only once that window is genuinely exceeded - never on the very
    # first failure, never indefinitely either.
    if not real_row["sl_order_id"]:
        if real_row["protection_degraded_since"] is None:
            _mark_protection_degraded(conn, symbol)
        else:
            elapsed = time.time() - real_row["protection_degraded_since"]
            timeout = _protection_degraded_timeout_seconds(get_scheduler_capital_inr())
            if elapsed > timeout:
                print(f"[REAL TRADE] {real_row['kotak_trading_symbol']} has had NO resting stop "
                      f"for {elapsed:.0f}s (tolerance {timeout:.0f}s at current capital) - "
                      f"forcing an emergency exit")
                _log_real_order_event(
                    conn, symbol, "sl", "emergency_exit_triggered", kotak_trading_symbol=real_row["kotak_trading_symbol"],
                    prev_state=f"unprotected for {elapsed:.0f}s", new_state="forcing full exit",
                    detail=f"protection_degraded_since timeout ({timeout:.0f}s) exceeded",
                )
                _maybe_place_real_exit(conn, symbol, reason=f"emergency: no resting stop for {elapsed:.0f}s (tolerance {timeout:.0f}s)")
                return
            # Still inside the tolerance window - fall through and keep
            # retrying below, same as every other tick.

    paper_row = conn.execute(
        "SELECT stop_loss FROM signal_state WHERE symbol = ? AND status = 'long'", (symbol,)
    ).fetchone()
    if not paper_row or not paper_row["stop_loss"]:
        return
    new_stop = round(paper_row["stop_loss"], 2)
    if real_row["entry_price"]:
        # B-1330: same 5% cap as the entry SL (B-1307); uncapped, a missing SL was re-placed at the paper stop
        # 15% below entry, outside the price band, and Kotak rejected it again on every tick.
        new_stop = _cap_real_intraday_stop(real_row["entry_price"], new_stop)
    current_sl_price = real_row["sl_trigger_price"]

    if current_sl_price is not None and new_stop <= current_sl_price:
        _note_sl_loosen_attempt(symbol, False, new_stop, current_sl_price)
        return  # no upward move since the last sync - nothing to do

    # T1/T2T infinite-retry-loop fix (2026-09-23, live SUZLON.NS finding):
    # a resting SL order for a T1/T2T-restricted symbol is ALWAYS accepted
    # at placement (Kotak only enforces the same-day-sell rule when the
    # order actually fires) - so placing a fresh one here always
    # "succeeds," which used to unconditionally call
    # _clear_protection_degraded below, resetting the degraded-protection
    # clock back to zero every single cycle. Net effect: the position was
    # genuinely unprotected the entire time (every SL dies again at its
    # next trigger, detected on reconcile above, which is what flagged
    # this restriction in the first place), but the clock never
    # accumulated past a few seconds before being wiped, so the 60s
    # emergency-exit escalation could never fire - an infinite loop of
    # doomed placements that looked like progress but wasn't.
    #
    # Fix: once a symbol is confirmed T1/T2T-restricted, stop attempting
    # to place a new SL for it at all - we already know it cannot
    # genuinely protect the position. Ensure the degraded clock is
    # running (idempotent - a no-op if already set) and let real wall-
    # clock time accumulate untouched, so the top-of-function timeout
    # check can correctly escalate to a forced exit attempt once it's
    # actually been exceeded. That exit attempt will likely ALSO be
    # rejected for the same T1/T2T reason (nothing sells a T2T stock
    # same-day, no order type is exempt) - this does not un-stick the
    # position, it stops the pointless repeated-placement spam and lets
    # the system honestly reflect "cannot be protected today" instead of
    # a resetting clock that never escalates.
    if _is_t1_restricted(conn, symbol):
        _mark_protection_degraded(conn, symbol)
        print(f"[REAL TRADE] {real_row['kotak_trading_symbol']} is T1/T2T-restricted - "
              f"not attempting another doomed SL placement, letting the degraded-protection "
              f"clock run toward its own escalation instead of resetting on a fresh accept")
        return

    # Exit-in-flight race fix (2026-09-28, live IDEA.NS finding: an exit
    # completed at Kotak, then THREE fresh SL-TRG sells for the original
    # qty were placed and rejected one minute later, one per tick). This
    # function only ever checked "is sl_order_id missing" before retrying
    # a placement - it never asked whether the position is still actually
    # open at Kotak. In the gap between _maybe_place_real_exit confirming
    # a sell (which cancels the resting SL/target FIRST, before the sell
    # itself fills) and its own DELETE of this real_positions row actually
    # committing, this function can still see a real_row with no live SL
    # and repeatedly attempt fresh placements against a position that's
    # mid-exit or already fully closed - each doomed to rejection (no
    # holding left / a competing exit order at Kotak). Ground-truth check
    # closes the gap: None (fetch failed) still falls through and retries
    # as before - failing open here, same as every other use of this
    # check, since refusing a genuinely needed SL over a transient API
    # hiccup is worse than one more retry next tick.
    if _kotak_symbol_still_open(real_row["kotak_trading_symbol"]) is False:
        print(f"[REAL TRADE] {real_row['kotak_trading_symbol']} shows no open position at Kotak - "
              f"skipping SL placement (likely exiting/already closed, stale real_positions row "
              f"will be cleared by the exit path or next reconcile)")
        return

    import kotak_real_orders
    # B-1350: reason row BEFORE the Kotak cancel/replace (see _maybe_place_real_partial_exit).
    _log_real_order_event(
        conn, symbol, "sl", "move_intent", kotak_trading_symbol=real_row["kotak_trading_symbol"],
        order_id=real_row["sl_order_id"],
        prev_state=f"Rs{current_sl_price:.2f}" if current_sl_price is not None else "none",
        new_state=f"cancel resting SL, then place SL at Rs{new_stop:.2f}",
        reason="trailing stop-loss tightened",
    )
    if real_row["sl_order_id"]:
        cancel_result = kotak_real_orders.cancel_real_order(real_row["sl_order_id"])
        if not cancel_result.get("ok"):
            print(f"[REAL TRADE] trailing-SL cancel failed for {real_row['kotak_trading_symbol']} "
                  f"(order {real_row['sl_order_id']}): {cancel_result.get('detail')} - skipping this sync, will retry next tick")
            return  # don't place a second resting SL on top of one that might still be live
    else:
        # BUG found live 2026-09-08 (explicit user finding, screenshot):
        # TWO live resting SL orders for the same 1-share AGL position,
        # same trigger/limit price, 11 minutes apart. sl_order_id is NULL
        # here for one of two reasons: no SL was ever placed yet (nothing
        # to cancel, genuinely fine), OR - the actual bug - a Render
        # restart landed between an earlier SL placement and the next
        # journal-sync snapshot capturing its order id (real_positions is
        # SQLite, wiped on every restart like every other table, only as
        # fresh as the last snapshot), restoring this position with
        # sl_order_id back to NULL even though a real order was already
        # resting at Kotak. Sweep the broker's OWN order book first (the
        # only ground truth this app's stale/lost tracking can't corrupt)
        # so a leftover live SL is cancelled before a fresh one is placed,
        # instead of accumulating a silent duplicate every time this
        # exact race recurs.
        kotak_real_orders.cancel_existing_resting_sl(real_row["kotak_trading_symbol"])

    sl_result = _place_real_stop_loss_with_retry(real_row["kotak_trading_symbol"], real_row["qty"], new_stop)
    if sl_result.get("ok"):
        conn.execute(
            "UPDATE real_positions SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
            (sl_result["order_id"], sl_result["trigger_price"], symbol),
        )
        conn.commit()
        _clear_protection_degraded(conn, symbol)  # a live resting SL exists again - stop the clock
        _sync_real_positions_external(conn)
        print(f"[REAL TRADE] trailing SL moved to Rs{new_stop:.2f} for {real_row['kotak_trading_symbol']} "
              f"(order {sl_result['order_id']})")
        _log_real_order_event(
            conn, symbol, "sl", "moved", kotak_trading_symbol=real_row["kotak_trading_symbol"],
            order_id=sl_result["order_id"],
            prev_state=f"Rs{current_sl_price:.2f}" if current_sl_price is not None else "none",
            new_state=f"Rs{new_stop:.2f}",
        )
    else:
        # Old order is already cancelled (or never existed) and the
        # replacement failed (even after _place_real_stop_loss_with_retry's
        # own retries) - clear sl_order_id so the position isn't left
        # pointing at a dead order id, and start (or leave running) the
        # degraded-protection clock the top-of-function check escalates on.
        conn.execute("UPDATE real_positions SET sl_order_id = NULL WHERE symbol = ?", (symbol,))
        conn.commit()
        _mark_protection_degraded(conn, symbol)
        _sync_real_positions_external(conn)
        print(f"[REAL TRADE] trailing SL replacement FAILED for {real_row['kotak_trading_symbol']}: "
              f"{sl_result.get('detail')}")
        _log_real_order_event(
            conn, symbol, "sl", "failed", kotak_trading_symbol=real_row["kotak_trading_symbol"],
            prev_state=f"Rs{current_sl_price:.2f}" if current_sl_price is not None else "none",
            new_state="none (replacement failed)", detail=sl_result.get("detail"),
        )
        _flag_if_t1_restricted(conn, symbol, sl_result.get("detail"))

        # CAS-transition rejection (2026-09-22, explicit user instruction,
        # live finding WAAREEENER.NS/NATIONALUM.NS - see
        # kotak_real_orders.is_cas_transition_rejection's own docstring):
        # this specific rejection means retrying the SAME resting LIMIT/
        # SL-LIMIT order is pointless - go straight to a market exit
        # attempt instead of waiting out the usual degraded-protection
        # timeout. _maybe_place_real_exit is already order_type="MKT" and
        # fully state-aware (closes the position correctly if it fills,
        # leaves state untouched if Kotak rejects this attempt too) - if
        # the freeze hasn't cleared yet this call simply fails and the
        # NEXT tick's own call into this same function retries it again,
        # same self-healing cadence as every other real-order retry here.
        if kotak_real_orders.is_cas_transition_rejection(sl_result.get("detail")):
            print(f"[REAL TRADE] {real_row['kotak_trading_symbol']} SL rejected mid-CAS-transition - "
                  f"escalating straight to a market exit attempt instead of waiting")
            _log_real_order_event(
                conn, symbol, "sl", "cas_transition_market_exit_attempt",
                kotak_trading_symbol=real_row["kotak_trading_symbol"],
                prev_state="none (replacement failed, CAS transition)", new_state="attempting market exit",
                detail=sl_result.get("detail"),
            )
            _maybe_place_real_exit(conn, symbol, reason="SL replacement rejected in CAS transition - cannot leave position unprotected, market exit")
            return

        # 2026-09-10, explicit user instruction after review: the resting
        # broker-side SL order was never the ONLY thing protecting this
        # position - _auto_signal_core's own tick check
        # (`elif last_close <= current_stop: exit_reason = "stop_hit"`)
        # runs every scheduler tick regardless of whether any resting
        # order exists at Kotak at all, and places a fresh market sell
        # for the full qty the moment price actually crosses the trailing
        # stop. That mechanism already proved itself live (GC=F/SI=F
        # ratcheting correctly through real ticks this session) and needs
        # no resting order to work. A force-close escalation here (tried,
        # then reverted the same session) would have sold on an API
        # hiccup instead of an actual price event - a real trade and its
        # cost for no extra protection the tick check doesn't already
        # give. _place_real_stop_loss_with_retry's own retries (above)
        # are still worth attempting - cheap, and they close the gap
        # faster on a genuinely transient failure - but no further escalation
        # beyond retrying happens here; the next tick's stop_hit check is
        # the real backstop, same as it always was for target/trend/
        # stale-timeout/squareoff exits too.


def _maybe_sync_real_stop_loss_short(conn, symbol: str):
    """Short mirror of _maybe_sync_real_stop_loss (2026-09-30, explicit
    user instruction: "make short positions equally mirrored as done in
    buy positions") - the per-TICK (every ~30s, not just the 5-min
    reconcile pass) trailing-stop/retry/degraded-protection engine for a
    real short position, bringing it to full parity with the long side.
    Before this, a short's ONLY auto-heal mechanism was the 5-min
    reconcile's own governance-backfill loop (see that function's own
    2026-09-30 additions) - this closes the remaining gap: the paper
    trailing stop set by _short_signal_core now gets mirrored to Kotak
    every tick, not just re-checked every 5 minutes, and a short that
    loses its resting SL gets the SAME aggressive same-tick retry +
    bounded degraded-protection timeout + emergency-exit escalation a
    long position has had since 2026-09-08/09-10.

    Every mechanic below is the long version's own, mirrored exactly,
    with the direction and the table flipped:
    - a short's stop only ever trails DOWN (toward entry) as price falls,
      the opposite of a long's up-trail - so the "no favorable move since
      last sync" skip is `new_stop >= current_sl_price`, not `<=`.
    - the protective order is a resting BUY (cancel_existing_resting_sl_
      short, place_real_short_stop_loss), not a resting SELL.
    - emergency-exit escalation calls _maybe_place_real_short_exit (a
      buy-to-cover), not _maybe_place_real_exit (a sell).
    - qty reconciliation uses _real_held_qty_short (flSellQty - flBuyQty),
      not _real_held_qty, which is long-signed and would misread a
      genuine short as unreadable/closed.

    _real_sl_order_is_live, _real_sl_rejection_detail, _is_t1_restricted,
    _flag_if_t1_restricted, _protection_degraded_timeout_seconds, and
    kotak_real_orders.is_cas_transition_rejection are all reused AS-IS -
    none of them assume a direction (they operate on an order id, a
    symbol-keyed restriction flag, or a capital figure)."""
    real_row = conn.execute("SELECT * FROM real_positions_short WHERE symbol = ?", (symbol,)).fetchone()
    if not real_row:
        return

    _ensure_signal_state_for_real_position_short(conn, real_row)
    real_row = _reconcile_real_qty_short(conn, real_row)

    if real_row["sl_order_id"]:
        sl_is_live = _real_sl_order_is_live(real_row["sl_order_id"])
        if sl_is_live is False:
            rejection_detail = _real_sl_rejection_detail(real_row["sl_order_id"])
            print(f"[REAL SHORT] resting SL {real_row['sl_order_id']} for "
                  f"{real_row['kotak_trading_symbol']} found DEAD on reconcile "
                  f"(no fill) - clearing it so the retry/escalation path below picks it up. "
                  f"detail: {rejection_detail}")
            _log_real_order_event(
                conn, symbol, "sl", "found_dead_on_reconcile", kotak_trading_symbol=real_row["kotak_trading_symbol"],
                order_id=real_row["sl_order_id"], prev_state="assumed resting",
                new_state="dead at Kotak (rejected/cancelled, no fill)", detail=rejection_detail,
            )
            conn.execute(
                "UPDATE real_positions_short SET sl_order_id = NULL, sl_trigger_price = NULL WHERE symbol = ?",
                (symbol,),
            )
            conn.commit()
            _sync_real_positions_short_external(conn)
            real_row = conn.execute("SELECT * FROM real_positions_short WHERE symbol = ?", (symbol,)).fetchone()

    if not real_row["sl_order_id"]:
        if real_row["protection_degraded_since"] is None:
            _mark_protection_degraded_short(conn, symbol)
        else:
            elapsed = time.time() - real_row["protection_degraded_since"]
            timeout = _protection_degraded_timeout_seconds(get_scheduler_capital_inr())
            if elapsed > timeout:
                print(f"[REAL SHORT] {real_row['kotak_trading_symbol']} has had NO resting stop "
                      f"for {elapsed:.0f}s (tolerance {timeout:.0f}s at current capital) - "
                      f"forcing an emergency cover")
                _log_real_order_event(
                    conn, symbol, "sl", "emergency_exit_triggered", kotak_trading_symbol=real_row["kotak_trading_symbol"],
                    prev_state=f"unprotected for {elapsed:.0f}s", new_state="forcing full cover",
                    detail=f"protection_degraded_since timeout ({timeout:.0f}s) exceeded",
                )
                _maybe_place_real_short_exit(conn, symbol, reason=f"emergency: no resting stop for {elapsed:.0f}s (tolerance {timeout:.0f}s)")
                return

    paper_row = conn.execute(
        "SELECT stop_loss FROM signal_state_short WHERE symbol = ? AND status = 'short'", (symbol,)
    ).fetchone()
    if not paper_row or not paper_row["stop_loss"]:
        return
    new_stop = round(paper_row["stop_loss"], 2)
    current_sl_price = real_row["sl_trigger_price"]

    # A short's stop only ever trails DOWN (toward entry) - the mirror of
    # the long side's "only ever moves the resting stop UP" - so no
    # favorable move means the new stop hasn't gotten any LOWER.
    if current_sl_price is not None and new_stop >= current_sl_price:
        _note_sl_loosen_attempt(symbol, True, new_stop, current_sl_price)
        return

    if _is_t1_restricted(conn, symbol):
        _mark_protection_degraded_short(conn, symbol)
        print(f"[REAL SHORT] {real_row['kotak_trading_symbol']} is T1/T2T-restricted - "
              f"not attempting another doomed SL placement, letting the degraded-protection "
              f"clock run toward its own escalation instead of resetting on a fresh accept")
        return

    if _kotak_symbol_still_open_short(real_row["kotak_trading_symbol"]) is False:
        print(f"[REAL SHORT] {real_row['kotak_trading_symbol']} shows no open short at Kotak - "
              f"skipping SL placement (likely covering/already closed, stale real_positions_short "
              f"row will be cleared by the exit path or next reconcile)")
        return

    import kotak_real_orders
    if real_row["sl_order_id"]:
        cancel_result = kotak_real_orders.cancel_real_order(real_row["sl_order_id"])
        if not cancel_result.get("ok"):
            print(f"[REAL SHORT] trailing-SL cancel failed for {real_row['kotak_trading_symbol']} "
                  f"(order {real_row['sl_order_id']}): {cancel_result.get('detail')} - skipping this sync, will retry next tick")
            return
    else:
        kotak_real_orders.cancel_existing_resting_sl_short(real_row["kotak_trading_symbol"])

    sl_result = _place_real_stop_loss_with_retry_short(real_row["kotak_trading_symbol"], real_row["qty"], new_stop)
    if sl_result.get("ok"):
        conn.execute(
            "UPDATE real_positions_short SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
            (sl_result["order_id"], sl_result["trigger_price"], symbol),
        )
        conn.commit()
        _clear_protection_degraded_short(conn, symbol)
        print(f"[REAL SHORT] trailing SL moved to Rs{new_stop:.2f} for {real_row['kotak_trading_symbol']} "
              f"(order {sl_result['order_id']})")
        _log_real_order_event(
            conn, symbol, "sl", "moved", kotak_trading_symbol=real_row["kotak_trading_symbol"],
            order_id=sl_result["order_id"],
            prev_state=f"Rs{current_sl_price:.2f}" if current_sl_price is not None else "none",
            new_state=f"Rs{new_stop:.2f}",
        )
    else:
        conn.execute("UPDATE real_positions_short SET sl_order_id = NULL WHERE symbol = ?", (symbol,))
        conn.commit()
        _mark_protection_degraded_short(conn, symbol)
        print(f"[REAL SHORT] trailing SL replacement FAILED for {real_row['kotak_trading_symbol']}: "
              f"{sl_result.get('detail')}")
        _log_real_order_event(
            conn, symbol, "sl", "failed", kotak_trading_symbol=real_row["kotak_trading_symbol"],
            prev_state=f"Rs{current_sl_price:.2f}" if current_sl_price is not None else "none",
            new_state="none (replacement failed)", detail=sl_result.get("detail"),
        )
        _flag_if_t1_restricted(conn, symbol, sl_result.get("detail"))

        if kotak_real_orders.is_cas_transition_rejection(sl_result.get("detail")):
            print(f"[REAL SHORT] {real_row['kotak_trading_symbol']} SL rejected mid-CAS-transition - "
                  f"escalating straight to an emergency cover attempt instead of waiting")
            _log_real_order_event(
                conn, symbol, "sl", "cas_transition_market_exit_attempt",
                kotak_trading_symbol=real_row["kotak_trading_symbol"],
                prev_state="none (replacement failed, CAS transition)", new_state="attempting market cover",
                detail=sl_result.get("detail"),
            )
            _maybe_place_real_short_exit(conn, symbol, reason="SL replacement rejected in CAS transition - emergency cover")
            return


