def _maybe_place_real_fo_call_entry(conn, symbol: str, spot: float, strategy_tag: str | None):
    return _maybe_place_real_fo_option_entry(conn, symbol, spot, strategy_tag, "call")


def _maybe_place_real_fo_put_entry(conn, symbol: str, spot: float, strategy_tag: str | None):
    return _maybe_place_real_fo_option_entry(conn, symbol, spot, strategy_tag, "put")


def _maybe_place_real_fo_option_entry(conn, symbol: str, spot: float, strategy_tag: str | None, right: str = "call",
                                      tag_col: str | None = None):
    """Mirrors a paper long (index OR MCX commodity, entered_long) as a
    REAL long call on the matching F&O underlying, sized at exactly 1 lot
    (smallest tradeable unit - same "qty=1" first-version precedent
    kotak_real_orders.py set for equity). Never raises.

    2026-10-01, closing a gap found during a routine backlog review: this
    function (and _straddle_signal_core's own real entry below) had NO
    PFnet real-money viability check at all, despite CLAUDE.md's own
    2026-09-30 standing rule explicitly claiming the gate applies "across
    every category (buy, short_sell, swing, futures, options)" - the gate
    was only ever wired into the three EQUITY/SWING entry functions. Since
    this mirrors whatever paper strategy fired on the underlying (almost
    always universal_score, PFnet 0.05 - already correctly blocked from
    opening a real EQUITY position for exactly this reason), the options
    mirror was bypassing the identical protection the equity path already
    enforces. `strategy_tag` is the underlying paper signal's own
    strategy field (`result["strategy"]` from _auto_signal_core/
    _short_signal_core), checked the same way every other real entry
    checks it - fails closed on anything unrecognized, same as always."""
    if not is_real_fo_trading_enabled():
        return
    fo_underlying = _REAL_OPTION_UNDERLYING.get(symbol)
    if fo_underlying is None:
        return
    leg_key = f"{fo_underlying}:{right.upper()}"
    if not _is_strategy_viable_for_real_money(strategy_tag):
        _log_real_fo_attempt(conn, leg_key, "B", "skipped_strategy_not_viable", detail=f"strategy_tag={strategy_tag}")
        _log_signal_shadow(conn, strategy_tag, symbol, 'long', False, 'option entry: strategy below PFnet floor', hard_gate=True)
        return
    if conn.execute("SELECT 1 FROM real_fo_positions WHERE leg_key = ?", (leg_key,)).fetchone():
        _log_real_fo_attempt(conn, leg_key, "B", "skipped_already_open")
        return

    import nse_fo_chain
    contract, err = nse_fo_chain.select_nse_option_contract(fo_underlying, spot, right)
    if contract is None:
        _log_real_fo_attempt(conn, leg_key, "B", "skipped_no_contract", detail=err)
        return

    return _real_fo_buy_contract(
        conn, leg_key, fo_underlying, contract, strategy_tag, tag_col or f"single_leg_{right}",
        f"{right} bought on viable setup strategy_tag={strategy_tag} index signal on {symbol}, spot {spot}",
    )


_OPTION_POOL_CATEGORIES = ("buy", "options")


def _option_pool_allows(strategy_tag: str | None) -> bool:
    """B-1314 (user 2026-10-21): a single-leg option position may only be opened by an option strategy or an
    intraday buy strategy. A strategy registered ONLY in swing, short_sell, futures or bidirectional is excluded;
    unrecognised tags fail closed."""
    registry_name = _STRATEGY_TAG_TO_REGISTRY_NAME.get(strategy_tag or "")
    if not registry_name:
        return False
    import strategy_registry as sr
    strat = _registry_entry(registry_name)
    if strat is None:
        return False
    cats = {getattr(c, "value", c) for c in strat.categories}
    return bool(cats & set(_OPTION_POOL_CATEGORIES))


def _real_fo_buy_contract(conn, leg_key: str, fo_underlying: str, contract: dict, strategy_tag, tag_col: str,
                          reason: str, trail_dist: float | None = None, budget_inr: float | None = None):
    """Shared real BUY of ONE resolved option contract (caps, loss budget,
    margin check, order, row insert, initial trailing SL). Used by the index
    mirror (ATM strike) and the per-strike setup scan (the strike whose own
    candles fired a viable setup)."""
    if not _option_pool_allows(strategy_tag):
        _log_real_fo_attempt(conn, leg_key, "B", "skipped_not_option_pool", detail=f"B-1314 strategy_tag={strategy_tag}")
        return
    # B-1328: every option entry and every risk-cut exit is a MARKET order, so a wide bid/ask on a thin strike
    # is paid twice (half-spread in, half-spread out) on top of costs. Skip when Kotak shows the spread wider
    # than FO_OPTION_MAX_SPREAD_PCT of mid. The quote shape is not yet confirmed live, so an unreadable quote
    # does not block (it would halt every option entry); it is logged on the confirmed row instead.
    _prem = float(contract.get("premium") or 0)
    _stop_dist = trail_dist if trail_dist else _prem * FO_OPTION_INITIAL_STOP_PCT / 100.0
    _stop_pct = (_stop_dist / _prem * 100.0) if _prem > 0 else 0.0
    if _prem > 0 and _stop_dist < FO_OPTION_MIN_STOP_TICKS * FO_OPTION_TICK:
        _log_real_fo_attempt(conn, leg_key, "B", "skipped_stop_inside_ticks",
                             kotak_trading_symbol=contract.get("kotak_trading_symbol"), price_est=_prem,
                             detail=f"B-1310 stop {_stop_dist:.3f} < {FO_OPTION_MIN_STOP_TICKS} ticks of {FO_OPTION_TICK} "
                                    f"(premium {_prem})")
        return
    _spread_cap_pct = min(FO_OPTION_MAX_SPREAD_PCT, _stop_pct * FO_OPTION_MAX_SPREAD_TO_STOP) if _stop_pct else FO_OPTION_MAX_SPREAD_PCT
    _spread_note = "spread unread"
    try:
        import nse_fo_chain as _nfc
        _liq = _nfc.fetch_option_liquidity(contract)
        _bid, _ask = _liq.get("bid"), _liq.get("ask")
        if _bid and _ask and _bid > 0 and _ask >= _bid:
            _spread_pct = (_ask - _bid) / ((_ask + _bid) / 2.0) * 100.0
            _spread_note = f"spread {_spread_pct:.1f}% (bid {_bid} ask {_ask})"
            if _spread_pct > _spread_cap_pct:
                _log_real_fo_attempt(conn, leg_key, "B", "skipped_spread_too_wide",
                                     kotak_trading_symbol=contract.get("kotak_trading_symbol"),
                                     price_est=contract.get("premium"),
                                     detail=f"B-1328/B-1310 {_spread_note} > {_spread_cap_pct:.2f}% "
                                            f"(min of {FO_OPTION_MAX_SPREAD_PCT}% and half the {_stop_pct:.2f}% stop)")
                return
    except Exception as _e:
        _spread_note = f"spread unread ({_e})"
        _bid = None
    # B-1316: prove the initial protective SL (the 3% trigger _sync_real_fo_option_sl places, with
    # place_real_fo_stop_loss's own tick rounding) can rest before buying; never buy what must be unwound.
    import kotak_real_fo_orders as _krfo
    _slp_ok, _slp_why = _krfo.option_entry_sl_placeable(_prem, FO_OPTION_INITIAL_STOP_PCT, bid=_bid)
    if not _slp_ok:
        _log_real_fo_attempt(conn, leg_key, "B", "skipped_option_stop_not_placeable",
                             kotak_trading_symbol=contract.get("kotak_trading_symbol"), price_est=_prem,
                             detail=f"B-1316 {_slp_why}")
        return
    qty = contract["lot_size"]
    if budget_inr and contract["premium"] > 0:
        # user 2026-10-08: size from the money available in the account (lots that fit
        # the budget, at least 1, capped at FO_MAX_LOTS_PER_ENTRY as an order-size guard)
        lots = int(budget_inr // (contract["lot_size"] * contract["premium"]))
        qty = contract["lot_size"] * min(max(lots, 1), FO_MAX_LOTS_PER_ENTRY)
    notional_inr = qty * contract["premium"]  # every F&O underlying wired here is INR-native, no fx conversion
    # 2026-09-17, explicit user instruction ("Daily F&O cap = Kotak
    # available capital. Not a fix number"): the daily F&O spend ceiling
    # is now the account's OWN real capital as of today's open (the same
    # _day_open_capital_inr basis the joint real-loss-cap right below
    # already uses, for the same "keep it as a % of/here, all of real
    # money available at the beginning of day" reasoning) - not a
    # separately-configured runtime setting that could drift out of sync
    # with what the account can actually afford.
    remaining = _day_open_capital_inr(conn) - _real_fo_today_spent_inr(conn)
    if notional_inr > remaining:
        _log_real_fo_attempt(
            conn, leg_key, "B", "skipped_over_daily_cap", kotak_trading_symbol=contract["kotak_trading_symbol"],
            price_est=contract["premium"], qty=qty,
            detail=f"1 lot = Rs{notional_inr:.2f}, remaining budget Rs{remaining:.2f}",
        )
        return

    # Joint real daily-loss cap (2026-09-08, explicit user instruction:
    # "joint cap... keep it as a % of total money available at the
    # beginning of day") - see _real_loss_budget's own docstring. Same
    # gate equity's _maybe_place_real_entry already enforces; this was
    # the missing half that made it not actually joint before.
    loss_check = _real_loss_budget(conn)
    if loss_check["real_pnl_today"] is None:
        _log_real_fo_attempt(conn, leg_key, "B", "skipped_real_pnl_unknown",
                              kotak_trading_symbol=contract["kotak_trading_symbol"],
                              price_est=contract["premium"], qty=qty, detail=loss_check["detail"])
        return
    if not loss_check["ok"]:
        _log_real_fo_attempt(conn, leg_key, "B", "skipped_real_daily_loss_cap_hit",
                              kotak_trading_symbol=contract["kotak_trading_symbol"],
                              price_est=contract["premium"], qty=qty, detail=loss_check["detail"])
        return

    # B-1317: size the entry risk on the whole lot (qty x premium x max stop %),
    # not per unit, and refuse when it exceeds what is left of today's loss budget.
    _cap = loss_check.get("cap_inr")
    if _cap is not None and loss_check.get("real_pnl_today") is not None:
        _left = _cap + min(loss_check["real_pnl_today"], 0.0)
        # B-1323: worst case is the initial stop PLUS the SL-limit offset (the stop is a limit 5% under
        # its trigger, so a gap can fill that far below), not the 3% stop alone; shrink the lots to fit
        # what is left of the budget instead of skipping the trade.
        _risk_pct = max(FO_STRIKE_TRAIL_MAX_PCT, FO_OPTION_INITIAL_STOP_PCT) + FO_OPTION_SL_LIMIT_OFFSET_PCT
        _unit_risk = contract["lot_size"] * contract["premium"] * _risk_pct / 100.0
        _lots_fit = int(_left // _unit_risk) if _unit_risk > 0 else 0
        if _lots_fit < 1:
            _risk = _unit_risk
            _log_real_fo_attempt(conn, leg_key, "B", "skipped_entry_risk_over_loss_budget",
                                  kotak_trading_symbol=contract["kotak_trading_symbol"],
                                  price_est=contract["premium"], qty=qty,
                                  detail=f"B-1323 1-lot risk Rs{_risk:.2f} (lot {contract['lot_size']} x {contract['premium']} x {_risk_pct}%) > budget left Rs{_left:.2f}")
            return
        if _lots_fit * contract["lot_size"] < qty:
            qty = _lots_fit * contract["lot_size"]
            notional_inr = qty * contract["premium"]
    import kotak_real_fo_orders
    margin_check = kotak_real_fo_orders.check_margin_affordable(
        exchange_segment=contract["exchange_segment"], instrument_token=contract["instrument_token"],
        transaction_type="B", quantity=qty,
    )
    if not margin_check["ok"]:
        _log_real_fo_attempt(
            conn, leg_key, "B", "skipped_margin_unaffordable", kotak_trading_symbol=contract["kotak_trading_symbol"],
            price_est=contract["premium"], qty=qty, detail=margin_check["detail"],
            raw_response=margin_check.get("raw_response"),
        )
        return

    result = kotak_real_fo_orders.place_real_fo_entry(
        contract["kotak_trading_symbol"], contract["exchange_segment"], qty,
    )
    if result.get("ok"):
        conn.execute(
            "INSERT INTO real_fo_positions (leg_key, underlying, strategy_tag, kotak_trading_symbol, "
            "instrument_token, exchange_segment, expiry, strike, lot_size, qty, entry_price, entry_order_id, "
            "opened_at, day, peak_price, trail_dist) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (leg_key, fo_underlying, f"{tag_col}", contract["kotak_trading_symbol"], contract["instrument_token"],
             contract["exchange_segment"], contract["expiry"], contract["strike"], contract["lot_size"], qty,
             contract["premium"], result["order_id"], time.time(), ist_now().strftime("%Y-%m-%d"), contract["premium"], trail_dist),
        )
        _log_real_fo_attempt(
            conn, leg_key, "B", "confirmed", kotak_trading_symbol=contract["kotak_trading_symbol"],
            qty=qty, price_est=contract["premium"], notional_inr=notional_inr,
            order_id=result["order_id"], raw_response=result.get("raw_response"),
            detail=f"reason: {reason}; {_spread_note}; trailing SL follows",
        )
        # CLAUDE.md 2026-10-11 "no trade without SL or SLM ever": an entry whose stop cannot be
        # placed is unwound at once, not left naked for the 180s tick grace. "fresh_entry_awaiting_position"
        # (Kotak position not yet visible) cannot be unwound or protected yet; the 30s tick retries it
        # and the 180s risk-cut remains the backstop for that single case.
        _sl_status = None
        try:
            _sl_status = _sync_real_fo_option_sl(conn, leg_key, reason="initial protective SL right after entry")
        except Exception as _e:
            _sl_status = "sl_exception"
            print(f"[REAL F&O] initial SL raised for {leg_key}: {_e}")
        # B-1270: Kotak's position can lag the fill by a few seconds; retry the SL briefly here so the window without a stop is
        # seconds, not the next 30s tick. If the position is still invisible it cannot be unwound (a sell would be naked), so the
        # tick retry + 180s risk cut + 5-min backcheck remain the backstop and the alarm below is logged.
        for _i in range(FO_ENTRY_SL_RETRIES):
            if _sl_status != "fresh_entry_awaiting_position":
                break
            time.sleep(FO_ENTRY_SL_RETRY_SLEEP_S)
            try:
                _sl_status = _sync_real_fo_option_sl(conn, leg_key, reason="initial protective SL retry (position not yet visible at Kotak)")
            except Exception as _e:
                _sl_status = "sl_exception"
                print(f"[REAL F&O] SL retry raised for {leg_key}: {_e}")
        if _sl_status == "fresh_entry_awaiting_position":
            _log_real_fo_attempt(conn, leg_key, "B", "sl_pending_position_not_visible", kotak_trading_symbol=contract["kotak_trading_symbol"],
                                 qty=qty, detail="reason: no SL yet, Kotak position not visible after retries; 30s tick retries, 180s risk cut backstop")
            print(f"[REAL F&O] ALARM {leg_key} entry has NO stop-loss yet (position not visible at Kotak)")
        # B-1318: a first SL failure (transient reject, no order id, unreadable Kotak) must not dump the entry at once;
        # keep retrying the stop for FO_ENTRY_SL_FAIL_RETRY_WINDOW_S before unwinding (the position stays naked only that long).
        _t0 = time.time()
        while (_sl_status in ("sl_failed", "sl_exception") or str(_sl_status).startswith("kotak_unreadable")) \
                and time.time() - _t0 < FO_ENTRY_SL_FAIL_RETRY_WINDOW_S:
            time.sleep(FO_ENTRY_SL_FAIL_RETRY_SLEEP_S)
            try:
                _sl_status = _sync_real_fo_option_sl(conn, leg_key, reason="initial protective SL retry after a failed placement")
            except Exception as _e:
                _sl_status = "sl_exception"
                print(f"[REAL F&O] SL fail-retry raised for {leg_key}: {_e}")
        if _sl_status in ("sl_failed", "sl_exception") or str(_sl_status).startswith("kotak_unreadable"):
            _row = conn.execute("SELECT * FROM real_fo_positions WHERE leg_key = ?", (leg_key,)).fetchone()
            if _row:
                _close_real_fo_option_leg(
                    conn, _row, f"entry unwound: protective trailing SL could not be placed ({_sl_status})")
                conn.commit()
        print(f"[REAL F&O] BUY {leg_key} {qty} {contract['kotak_trading_symbol']} (order {result['order_id']}) "
              f"~Rs{contract['premium']:.2f}")
    else:
        _log_real_fo_attempt(
            conn, leg_key, "B", "failed", kotak_trading_symbol=contract["kotak_trading_symbol"],
            qty=qty, price_est=contract["premium"], detail=result.get("detail"), raw_response=result.get("raw_response"),
        )
        print(f"[REAL F&O] BUY CALL FAILED {contract['kotak_trading_symbol']}: {result.get('detail')}")


def _maybe_place_real_fo_call_exit(conn, symbol: str, reason: str = "UNSTATED"):
    return _maybe_place_real_fo_option_exit(conn, symbol, "call", reason)


def _maybe_place_real_fo_put_exit(conn, symbol: str, reason: str = "UNSTATED"):
    return _maybe_place_real_fo_option_exit(conn, symbol, "put", reason)


def _cancel_live_option_sls(kotak_trading_symbol: str, state: dict | None = None) -> list:
    """Cancels every live resting SELL SL on `kotak_trading_symbol` (fresh
    Kotak read when `state` isn't supplied). A resting SELL SL left behind a
    closed long option could later SELL SHORT, so exits always clear them."""
    import kotak_real_fo_orders
    import kotak_real_orders
    st = state if state is not None else kotak_real_fo_orders.fetch_kotak_option_state(kotak_trading_symbol)
    cancelled = []
    for o in (st.get("live_sls") or []):
        r = kotak_real_orders.cancel_real_order(o["order_id"])
        cancelled.append({"order_id": o["order_id"], "ok": r.get("ok")})
    return cancelled


def _maybe_place_real_fo_option_exit(conn, symbol: str, right: str, reason: str = "UNSTATED"):
    """Closes the real single-strike option leg opened by
    _maybe_place_real_fo_option_entry when the SAME underlying's paper index
    position exits (any reason). No gate of its own - closing an open
    position must never be blocked. Cancels the resting trailing SL first
    (reason logged), then sells at market."""
    fo_underlying = _REAL_OPTION_UNDERLYING.get(symbol)
    if fo_underlying is None:
        return
    leg_key = f"{fo_underlying}:{right.upper()}"
    row = conn.execute("SELECT * FROM real_fo_positions WHERE leg_key = ?", (leg_key,)).fetchone()
    if not row:
        return
    if str(row["strategy_tag"]).startswith("single_leg_mcx_"):
        return  # engine ownership: MCX daily engine exits only its own legs
    return _close_real_fo_option_leg(conn, row, reason)


def _close_real_fo_option_leg(conn, row, reason: str):
    import kotak_real_fo_orders
    leg_key = row["leg_key"]
    # Governance sequence: Kotak positions + order book first. A readable Kotak that shows no open qty
    # (SL already hit) means NO order: clear the row. An unreadable Kotak never blocks a close.
    st = kotak_real_fo_orders.fetch_kotak_option_state(row["kotak_trading_symbol"])
    exit_qty = row["qty"]
    if st.get("ok"):
        if st["net_qty"] <= 0 and time.time() - float(row["opened_at"]) >= 120:
            if st["live_sls"]:
                _cancel_live_option_sls(row["kotak_trading_symbol"], st)
            conn.execute("DELETE FROM real_fo_positions WHERE leg_key = ?", (leg_key,))
            _log_real_fo_attempt(conn, leg_key, "S", "closed_per_kotak", kotak_trading_symbol=row["kotak_trading_symbol"],
                                 qty=row["qty"], detail=f"reason: {reason}; Kotak positions show no open qty, no exit order sent")
            return True
        if 0 < st["net_qty"] < exit_qty:
            exit_qty = int(st["net_qty"])
    cancelled = _cancel_live_option_sls(row["kotak_trading_symbol"])
    if cancelled:
        _log_real_fo_attempt(conn, leg_key, "S", "sl_cancelled", kotak_trading_symbol=row["kotak_trading_symbol"],
                             qty=row["qty"], detail=f"reason: {reason}; cancelled {cancelled}")
    result = kotak_real_fo_orders.place_real_fo_exit(row["kotak_trading_symbol"], row["exchange_segment"], exit_qty)
    if result.get("ok"):
        conn.execute("DELETE FROM real_fo_positions WHERE leg_key = ?", (leg_key,))
        _log_real_fo_attempt(
            conn, leg_key, "S", "confirmed", kotak_trading_symbol=row["kotak_trading_symbol"],
            qty=row["qty"], order_id=result["order_id"], raw_response=result.get("raw_response"),
            detail=f"reason: {reason}",
        )
        print(f"[REAL F&O] SELL {leg_key} {row['qty']} {row['kotak_trading_symbol']} (order {result['order_id']}) - {reason}")
        return True
    _log_real_fo_attempt(
        conn, leg_key, "S", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
        qty=row["qty"], detail=f"reason: {reason}; {result.get('detail')}", raw_response=result.get("raw_response"),
    )
    print(f"[REAL F&O] SELL {leg_key} FAILED {row['kotak_trading_symbol']}: {result.get('detail')} "
          f"- POSITION STILL OPEN, NEEDS ATTENTION")
    # B-1324: the exit failed after the resting SLs were cancelled above, so the leg is now naked;
    # re-place the trailing SL at once instead of waiting for the next 30s tick.
    if cancelled and leg_key not in _fo_restoring_sl:
        _fo_restoring_sl.add(leg_key)  # guard: the sync below can itself try to close (gap/risk cut)
        try:
            _sync_real_fo_option_sl(conn, leg_key, reason="SL restored after a failed exit")
        except Exception as _e:
            print(f"[REAL F&O] SL restore after failed exit raised for {leg_key}: {_e}")
        finally:
            _fo_restoring_sl.discard(leg_key)
    return False


_fo_sl_unprotected_since: dict = {}
_fo_restoring_sl: set = set()


def _option_ltp(row) -> float | None:
    import kotak_neo
    import nse_fo_chain
    try:
        q = kotak_neo.quotes([{"instrument_token": str(row["instrument_token"]),
                               "exchange_segment": row["exchange_segment"]}], quote_type="ltp")
        return nse_fo_chain._extract_ltp(q)
    except Exception:
        return None


def _option_feed_high_since(conn, row) -> float | None:
    """Highest premium the option candle feed saw since this leg was opened:
    max(high) over persisted fo_option_candles bars that START at/after
    opened_at, plus the in-progress bar if it also starts at/after opened_at.
    Bars starting before entry are excluded so a pre-entry spike can never
    inflate the peak (never overstates; may understate by the entry bar).
    The feed is tick-driven, so it catches spikes between the 30s LTP polls
    that a last-tick-only peak misses. None when nothing usable (caller falls
    back to the polled LTP, unchanged behaviour)."""
    try:
        token = str(row["instrument_token"])
        opened = float(row["opened_at"])
        r = conn.execute(
            "SELECT MAX(high) AS h FROM fo_option_candles WHERE instrument_token = ? AND bucket_start_ts >= ?",
            (token, opened)).fetchone()
        best = float(r["h"]) if r and r["h"] is not None else None
        import kotak_fo_candle_feed as _kfc
        cur = _kfc._in_progress_candles.get(token)
        if cur and float(cur["bucket_start_ts"]) >= opened:
            best = max(best, float(cur["high"])) if best is not None else float(cur["high"])
        return best if best and best > 0 else None
    except Exception:
        return None


def _sync_real_fo_option_sl(conn, leg_key: str, reason: str = "trailing sync") -> str:
    """One governance pass for ONE real single-strike option leg, in the
    mandatory order: (1) Kotak positions, (2) Kotak order book, (3) compare
    with the app row, (4) act with the options engine's own actions only.
    Returns a short status string. The SL is a TRAILING stop on the premium:
    trigger = max(previous trigger, running peak * (1 - FO_OPTION_TRAIL_PCT%)).
    Kotak wins: the row is rewritten from Kotak's SL / flat state."""
    import kotak_real_fo_orders
    row = conn.execute("SELECT * FROM real_fo_positions WHERE leg_key = ?", (leg_key,)).fetchone()
    if not row or not str(row["strategy_tag"]).startswith(("single_leg_", "strike_setup_")):
        return "not_option_leg"
    sym = row["kotak_trading_symbol"]
    st = kotak_real_fo_orders.fetch_kotak_option_state(sym)
    if not st["ok"]:
        # B-1320: an unreadable Kotak state must not hide an unprotected leg forever.
        # Only legs we have no SL on count; the timer is cleared as soon as a SL is confirmed.
        if not row["sl_order_id"]:
            since = _fo_sl_unprotected_since.setdefault(leg_key, time.time())
            if time.time() - since >= FO_OPTION_SL_FAIL_EXIT_SECONDS:
                _close_real_fo_option_leg(conn, row, f"risk cut: Kotak state unreadable and no SL on record for {FO_OPTION_SL_FAIL_EXIT_SECONDS}s")
                _fo_sl_unprotected_since.pop(leg_key, None)
                return "risk_cut_exit"
        return f"kotak_unreadable: {st['detail']}"
    # Kotak shows no open qty: stopped out / closed elsewhere -> close our row.
    if st["net_qty"] <= 0:
        if time.time() - float(row["opened_at"]) < 120:
            return "fresh_entry_awaiting_position"
        if st["live_sls"]:
            _cancel_live_option_sls(sym, st)
        conn.execute("DELETE FROM real_fo_positions WHERE leg_key = ?", (leg_key,))
        _log_real_fo_attempt(conn, leg_key, "S", "closed_per_kotak", kotak_trading_symbol=sym, qty=row["qty"],
                             detail="reason: Kotak positions show no open qty (trailing SL hit or position closed at Kotak)")
        _fo_sl_unprotected_since.pop(leg_key, None)
        return "closed_per_kotak"
    import nse_fo_chain as _nfc
    if row["expiry"] and _nfc.must_force_close_before_expiry(row["underlying"], row["expiry"]):
        _close_real_fo_option_leg(conn, row, "force close before expiry/physical-settlement window")
        return "expiry_force_close"
    if str(row["strategy_tag"]).startswith("single_leg_swing_") and _swing_option_hold_exceeded(conn, row):
        _close_real_fo_option_leg(conn, row, "B-1386 hold window reached: market hours since entry >= strategy hold hours")
        return "hold_window_exit"
    qty = int(st["net_qty"])
    ltp = _option_ltp(row)
    peak = float(row["peak_price"] or row["entry_price"])
    if ltp is not None and ltp > peak:
        peak = ltp
    feed_high = _option_feed_high_since(conn, row)
    if feed_high is not None and feed_high > peak:
        peak = feed_high  # tick-built candle high catches spikes between 30s polls
    prev_trigger = float(row["sl_trigger_price"] or 0)
    # B-1321: the resting SL is a limit order 5% under its trigger; a premium already below
    # that limit cannot fill it, so cut at market instead of trusting the stuck order.
    if ltp is not None and prev_trigger > 0 and ltp < prev_trigger * 0.95:
        _close_real_fo_option_leg(conn, row, f"risk cut: premium {ltp} gapped below the SL limit ({prev_trigger * 0.95:.2f}); resting SL cannot fill")
        _fo_sl_unprotected_since.pop(leg_key, None)
        return "gap_through_exit"
    # user 2026-10-08: 3% initial stop below entry; once the premium is 1% above entry,
    # trail 1% below the highest LTP since entry; the trigger never lowers.
    entry = float(row["entry_price"])
    if peak >= entry * (1 + FO_OPTION_TRAIL_ARM_PCT / 100.0):
        desired = max(prev_trigger, peak * (1 - FO_OPTION_TRAIL_PCT / 100.0))
    else:
        desired = max(prev_trigger, entry * (1 - FO_OPTION_INITIAL_STOP_PCT / 100.0))
    if row["exchange_segment"] == "nse_fo" and kotak_real_orders_closing_session():
        return "skipped_closing_session"
    res = kotak_real_fo_orders.ensure_option_trailing_sl(sym, row["exchange_segment"], qty, desired, st["live_sls"])
    if res.get("ok"):
        conn.execute("UPDATE real_fo_positions SET peak_price = ?, sl_order_id = ?, sl_trigger_price = ? WHERE leg_key = ?",
                     (peak, res["order_id"], res["trigger_price"], leg_key))
        conn.commit()
        _fo_sl_unprotected_since.pop(leg_key, None)
        if res["action"] != "adopted_existing":
            _log_real_fo_attempt(conn, leg_key, "S", f"sl_{res['action']}", kotak_trading_symbol=sym, qty=qty,
                                 order_id=res["order_id"], price_est=res["trigger_price"],
                                 detail=f"reason: {reason}; trailing SL trigger {res['trigger_price']} (peak {peak}, ltp {ltp})")
        return res["action"]
    if res.get("restored_order_id"):
        conn.execute("UPDATE real_fo_positions SET sl_order_id = ?, sl_trigger_price = ? WHERE leg_key = ?",
                     (res["restored_order_id"], res["restored_trigger"], leg_key))
        conn.commit()
        return "replace_failed_old_restored"
    # No SL rests and placement failed: cut the risk after a short grace.
    since = _fo_sl_unprotected_since.setdefault(leg_key, time.time())
    _log_real_fo_attempt(conn, leg_key, "S", "sl_failed", kotak_trading_symbol=sym, qty=qty,
                         detail=f"reason: {reason}; SL placement failed: {res.get('detail')}")
    print(f"[REAL F&O] ALARM {leg_key} has NO stop-loss: {res.get('detail')}")
    if time.time() - since >= FO_OPTION_SL_FAIL_EXIT_SECONDS:
        _close_real_fo_option_leg(conn, row, f"risk cut: no SL could be placed for {FO_OPTION_SL_FAIL_EXIT_SECONDS}s ({res.get('detail')})")
        _fo_sl_unprotected_since.pop(leg_key, None)
        return "risk_cut_exit"
    return "sl_failed"


def kotak_real_orders_closing_session() -> bool:
    import kotak_real_orders
    return kotak_real_orders._in_closing_session()


# Per-strike setup scan (2026-10-08, explicit user instruction: "treat each
# strike of all option chains in terms of candle; if that candle matches the
# entry setup of any VIABLE buy or swing strategy, the relevant strike (call
# or put, as that strike is) is bought and held until the trailing SL exits").
# Runs the real main.py entry-signal functions on each strike's OWN 5-minute
# premium candles from kotak_fo_candle_feed. Disclosed limits: those
# strategies were validated on daily stock bars, so their PFnet does not
# measure this; candles only accumulate forward (no backfill), so signals need
# enough history first; volume is the tick-count proxy.
FO_STRIKE_SETUP_MAX_OPEN = 2  # user 2026-10-08: per index, at most 1 call + 1 put
_FO_STRIKE_SCAN_UNDERLYINGS = ("NIFTY", "BANKNIFTY", "SENSEX", "FINNIFTY", "MIDCPNIFTY")
FO_STRIKE_SETUP_SCAN_SECONDS = 300
FO_MAX_LOTS_PER_ENTRY = 20
FO_STRIKE_TRAIL_ATR_MULT = 6.0  # same multiple the viable OB/VP swing setups trail with (B-26)
FO_STRIKE_TRAIL_MIN_PCT = 2.0
FO_STRIKE_TRAIL_MAX_PCT = 3.0   # user 2026-10-08: max loss 3% of premium
_fo_strike_scan_last_ts = 0.0


def _fo_strike_setup_signals():
    """(registry tag, entry fn) for every buy/swing setup that has an entry
    function on a bare OHLCV frame. Viability is checked per tag at use.
    2026-10-09 (user: strikes had no monitoring vs the flagged-viable
    strategies): was only 3 of the 7 viable entry fns; now all of them."""
    return (("power_play", power_play_entry_signal),
            ("primary_base", primary_base_entry_signal),
            ("minervini_vcp_livermore", minervini_vcp_entry_signal_livermore_confirmed),
            ("minervini_vcp", minervini_vcp_entry_signal),
            ("order_block_delta", order_block_entry_signal),
            ("volume_profile_poc", volume_profile_poc_entry_signal),
            ("gap_and_go", gap_and_go_entry_signal))


_FO_STRIKE_SHADOW_STRATEGIES = (
    ("sma_crossover", {"fast": 9, "slow": 21}),
    ("rsi_reversal", {"rsi_period": 14, "oversold": 30, "overbought": 70}),
    ("bollinger_mean_reversion", {}), ("supertrend", {}),
    ("keltner_channel_breakout", {}), ("donchian_breakout", {}),
)

# Per-strike monitoring ledger (2026-10-09): every option strike in the candle
# feed, which viable setups were evaluated on its own candles, when, and why it
# was skipped. Served by GET /fo-strike-monitoring. In-memory by design: it is
# recomputed every 5-min scan (a pure derived view, not state read back later).
_fo_strike_monitor: dict = {}
_fo_strike_monitor_meta: dict = {"last_scan_ts": None, "viable_tags": [], "real_enabled": None,
                                 "entry_window_open": None, "scans_today": 0, "day": ""}


_index_swing_option_scan_day = None
_INDEX_SWING_OPTION_SYMBOLS = ("^NSEI", "^NSEBANK", "^BSESN")


def _run_index_swing_option_scan(conn):
    """User 2026-10-08: an index's own daily swing signal drives an option on THAT index - a
    long signal buys the CALL, a short signal buys the PUT (single strike, trailing SL, 20-lot cap
    sized from money available, one call + one put per index, all enforced inside
    _maybe_place_real_fo_option_entry / _real_fo_buy_contract). Once per IST day; each side gated
    by its own strategy's PFnet viability (the short mirror fails closed until it is viable)."""
    global _index_swing_option_scan_day
    if not is_real_fo_trading_enabled():
        return
    t = ist_now()
    today = t.strftime("%Y-%m-%d")
    if t.weekday() >= 5 or _index_swing_option_scan_day == today or not ((9, 20) <= (t.hour, t.minute) < (15, 0)):
        return
    _index_swing_option_scan_day = today
    for sym in _INDEX_SWING_OPTION_SYMBOLS:
        try:
            df = fetch_ohlc(sym, "2y", "1d")
            if df is None or len(df) < 50:
                continue
            spot = float(df["Close"].iloc[-1])
            for _t in ("gap_and_go", "gap_and_go_short"):  # B-1274: per-symbol coverage for index option cells
                _note_symbol_strategy_scan(sym, _t)
            if gap_and_go_entry_signal(df):
                _maybe_place_real_fo_call_entry(conn, sym, spot, "gap_and_go")
            elif gap_and_go_entry_signal_short(df):
                _maybe_place_real_fo_put_entry(conn, sym, spot, "gap_and_go_short")
        except Exception as e:
            print(f"[INDEX SWING OPT] {sym} failed (non-fatal): {e}")


# B-345 (user 2026-10-10: "build the MCX daily engine for the best cells"): daily
# candle scan on COMEX proxies; a fresh signal buys the matching MCX option (call
# for long cells), exit when the signal drops. Uses the existing F&O switch, PFnet
# gate, margin check (rejections are fine), trailing SL and reasoned order log.
# Cells are the exact-rule variants (no ATR stop; the option trailing SL protects).
_MCX_DAILY_CELLS_FALLBACK = (
    # (registry tag, proxy symbol, add_strategy_signal name, params)
    # fallback = gold only: the one cell whose ATR-stopped variants also clear 1.1 and with n >= 30
    ("sma_crossover__gc__long__1d__atrnone__v1", "GC=F", "sma_crossover", {"fast": 9, "slow": 21}),
)


def _load_mcx_daily_cells():
    """User 2026-10-11: wire every PFnet>1 exact-rule MCX cell (scripts/gen_mcx_live_cells.py)."""
    try:
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "docs", "mcx_live_cells.json")) as f:
            cells = tuple((r[0], r[1], r[2], dict(r[3])) for r in json.load(f)["cells"])
        if cells:
            return cells
    except Exception as e:
        print(f"[MCX DAILY] live cell list unreadable, using fallback: {e}")
    return _MCX_DAILY_CELLS_FALLBACK


def _mcx_replay_row_name(tag):
    """B-1270: registry row of the main.py-calling replay (run 38582151119) for an MCX cell: the research tag with `_mr` on the variant."""
    return tag.replace("__long__", "_mr__long__", 1).replace("__short__", "_mr__short__", 1)


def _mcx_replay_clears_floor(tag):
    """True unless the cell's `_mr` replay row exists AND is below PFNET_LIVE_FLOOR (wiring has ONE condition: replay PFnet >= floor).
    A cell with no replay row stays (the real-money gate still fails closed on it). Derived at read time, never stored."""
    try:
        import strategy_registry as _sr
        r = next((x for x in _sr.REGISTRY if x.name == _mcx_replay_row_name(tag)), None)
        return r is None or r.metrics is None or r.metrics.pfnet >= _sr.PFNET_LIVE_FLOOR
    except Exception:
        return True


# B-1270: unwire (scan + entry) every MCX cell whose real-main replay row is below the floor; its research and replay registry rows stay.
_MCX_DAILY_CELLS = tuple(c for c in _load_mcx_daily_cells() if _mcx_replay_clears_floor(c[0]))
for _c in _load_mcx_daily_cells():
    # the gate/dashboard use the replay PFnet (the `_mr` row) when it exists, else the research row (unchanged)
    _STRATEGY_TAG_TO_REGISTRY_NAME[_c[0]] = _mcx_replay_row_name(_c[0]) if any(
        x.name == _mcx_replay_row_name(_c[0]) for x in __import__("strategy_registry").REGISTRY) else _c[0]


def _mcx_inr_spot(fo_underlying):
    """INR price of the matching MCX future from Kotak. The COMEX proxy is USD, so it
    can never be used to pick an MCX strike. None => caller skips (fail closed)."""
    try:
        import nse_fo_chain, kotak_neo
        fut, err = nse_fo_chain.select_nse_future(fo_underlying)
        if fut is None:
            return None
        q = kotak_neo.quotes([{"instrument_token": fut["instrument_token"],
                               "exchange_segment": fut["exchange_segment"]}], quote_type="ltp")
        v = nse_fo_chain._extract_ltp(q)
        return float(v) if v and v > 0 else None
    except Exception as e:
        print(f"[MCX DAILY] INR spot {fo_underlying} failed: {e}")
        return None
_mcx_daily_scan_day = None


def _mcx_daily_flags(df, strategy, params, short=False):
    """(entry_fresh, flag_on) on the last COMPLETED daily bar."""
    t = ist_now().strftime("%Y-%m-%d")
    if len(df) and str(df.index[-1])[:10] == t:
        df = df.iloc[:-1]  # today's bar is still forming
    if short:  # mirror = same signal on the reciprocal price series (matches mcx_strategy_sweep)
        m = df.copy()
        m["Open"], m["Close"] = 1 / df["Open"], 1 / df["Close"]
        m["High"], m["Low"] = 1 / df["Low"], 1 / df["High"]
        df = m
    flag = add_strategy_signal(df, strategy, dict(params))["long"].fillna(False).astype(bool)
    if len(flag) < 2:
        return False, False
    return bool(flag.iloc[-1] and not flag.iloc[-2]), bool(flag.iloc[-1])


_mcx_cell_cursor = 0
_mcx_cell_entry_day: dict = {}  # tag -> IST day of its last entry attempt (one per cell per day)


def _run_mcx_daily_scan(conn, force: bool = False):
    """Round robin (user 2026-10-11: "make them run in round robin fashion"):
    every scheduler tick scans ONE MCX cell in rotation, 09:20-23:00 IST
    Mon-Fri, so every cell is re-checked every few minutes instead of once a
    day. Signals use the last COMPLETED daily bar, so a re-scan never changes
    an entry signal; it keeps the dashboard count live and catches a dropped
    signal (exit) sooner. At most one entry per cell per IST day, so a stop-out
    can't trigger a same-day re-entry on the same bar. force=True scans all."""
    global _mcx_cell_cursor
    t = ist_now()
    today = t.strftime("%Y-%m-%d")
    if not force and (t.weekday() >= 5 or not ((9, 20) <= (t.hour, t.minute) < (23, 0))):
        return
    _entries_ok = _switch_allows_entries(conn)  # B-1282: scanning is counted even when trading is OFF; only entries are gated
    if not _MCX_DAILY_CELLS:
        return
    if force:
        cells = list(_MCX_DAILY_CELLS)
    else:
        _mcx_cell_cursor %= len(_MCX_DAILY_CELLS)
        cells = [_MCX_DAILY_CELLS[_mcx_cell_cursor]]
        _mcx_cell_cursor += 1
        if _mcx_cell_cursor >= len(_MCX_DAILY_CELLS):
            global _mcx_daily_scan_day
            _mcx_daily_scan_day = today  # one full rotation done (banner)
    for tag, sym, strat, params in cells:
        try:
            _tok = _current_scan_symbol.set(sym)  # B-1274: per-symbol coverage for MCX cells
            try:
                _record_strategy_scan(tag)
            finally:
                _current_scan_symbol.reset(_tok)
            df = fetch_ohlc(sym, "2y", "1d")
            if df is None or len(df) < 60:
                continue
            is_short = "__short__" in tag
            fresh, on = _mcx_daily_flags(df, strat, params, short=is_short)
            right = "put" if is_short else "call"
            fo_u = _REAL_OPTION_UNDERLYING.get(sym)
            row = conn.execute("SELECT * FROM real_fo_positions WHERE leg_key = ?", (f"{fo_u}:{right.upper()}",)).fetchone() if fo_u else None
            own = f"single_leg_mcx_{tag}"  # each cell exits only the leg it opened
            if row is not None and str(row["strategy_tag"]) == own and not on:
                _close_real_fo_option_leg(conn, row, f"{tag}: daily signal dropped, exit")
            elif fresh and row is None and _entries_ok and _mcx_cell_entry_day.get(tag) != today:
                spot = _mcx_inr_spot(fo_u) if fo_u else None
                if spot is None:
                    _log_real_fo_attempt(conn, f"{fo_u}:{right.upper()}", "B", "skipped_no_inr_spot", detail=f"strategy_tag={tag}")
                    continue
                _mcx_cell_entry_day[tag] = today
                _maybe_place_real_fo_option_entry(conn, sym, spot, tag, right, tag_col=own)
        except Exception as e:
            print(f"[MCX DAILY] {tag} failed (non-fatal): {e}")
    try:
        _persist_strategy_scan_counts(conn)  # B-1282: MCX counts survive a restart
    except Exception:
        pass


def _run_fo_strike_setup_scan(conn):
    """Throttled scan (once per 5-min candle). EVERY index option strike with
    its own candles is evaluated against every VIABLE setup (monitoring runs
    whether or not real F&O trading is on, 09:15-15:30 IST, and is recorded
    per strike for /fo-strike-monitoring). Only when the real switch is on and
    inside 09:20-15:00 IST does a fired setup buy that contract for real and
    let the trailing SL manage it."""
    global _fo_strike_scan_last_ts
    now = time.time()
    if now - _fo_strike_scan_last_ts < FO_STRIKE_SETUP_SCAN_SECONDS:
        return
    t = ist_now()
    if t.weekday() >= 5 or not ((9, 15) <= (t.hour, t.minute) < (15, 30)):
        return
    _fo_strike_scan_last_ts = now
    real_ok = is_real_fo_trading_enabled()
    entry_window = (9, 20) <= (t.hour, t.minute) < (15, 0)
    import kotak_fo_candle_feed
    import nse_fo_chain
    viable = [(tag, fn) for tag, fn in _fo_strike_setup_signals() if _is_strategy_viable_for_real_money(tag)]
    today = t.strftime("%Y-%m-%d")
    meta = _fo_strike_monitor_meta
    if meta["day"] != today:
        meta.update(day=today, scans_today=0)
    meta.update(last_scan_ts=now, viable_tags=[tg for tg, _ in viable], real_enabled=real_ok,
                entry_window_open=entry_window, scans_today=meta["scans_today"] + 1)
    if not viable:
        return
    # user 2026-10-08: per INDEX, at most one call + one put (NIFTY max 2, BANKNIFTY max 2, ...)
    held_sides = {(r[1], "call" if (r[0] or "").upper().endswith("CE") else "put") for r in conn.execute(
        "SELECT kotak_trading_symbol, underlying FROM real_fo_positions WHERE strategy_tag LIKE 'strike_setup_%'").fetchall()}
    held = {r[0] for r in conn.execute("SELECT kotak_trading_symbol FROM real_fo_positions").fetchall()}
    seen = set()
    for (segment, token), d in kotak_fo_candle_feed.get_cached_fo_universe().items():
        if d["kind"] != "option" or d["underlying"] not in _FO_STRIKE_SCAN_UNDERLYINGS:
            continue
        sym = d["kotak_trading_symbol"]
        seen.add(sym)
        rec = _fo_strike_monitor.setdefault(sym, {"scanned": {}, "last_signal": None})
        if rec.get("day") != today:
            rec.update(day=today, scanned={}, last_signal=None)
        rec.update(underlying=d["underlying"], right=d["right"], strike=d["strike"], expiry=d["expiry"],
                   expiry_class=d.get("expiry_class"))
        if d["expiry"] and str(d["expiry"])[:10] < today:
            rec["status"] = "expired_series"  # stale cache: never trade it
            continue
        df = kotak_fo_candle_feed.read_fo_candles_as_df(token)
        rec["candles"] = 0 if df is None else len(df)
        if df is None or len(df) < 30:
            rec["status"] = "warming_up_need_30_candles"
            continue
        age = (pd.Timestamp.now(tz="UTC") - df["Date"].iloc[-1]).total_seconds()
        rec["last_candle_age_s"] = round(age)
        try:  # B-868: lets /signal-funds price 1 lot (lot_size x premium) for the "need" figure
            rec["lot_size"], rec["last_close"] = d["lot_size"], float(df["Close"].iloc[-1])
        except Exception:
            pass
        if age > 900:
            rec["status"] = "no_fresh_candle"  # dropped out of the band
            continue
        fired = None
        for tag, fn in viable:
            try:
                sig = fn(df)
            except Exception:
                sig = None
            rec["scanned"][tag] = rec["scanned"].get(tag, 0) + 1
            _note_symbol_strategy_scan(d["underlying"], tag)  # B-1274: per-underlying coverage for strike setups
            if sig and fired is None:
                fired = (tag, sig)
                rec["last_signal"] = {"tag": tag, "ts": now}
        # user 2026-10-11: ALL applicable strategies on strikes. The atomic indicator strategies have no
        # option-premium PFnet yet, so they fail the real-money gate (fail closed): evaluated and recorded
        # here as SHADOW signals only (no order), building the evidence for a premium backtest.
        shadow = rec.setdefault("shadow", {})
        for _st, _pr in _FO_STRIKE_SHADOW_STRATEGIES:
            try:
                _fl = add_strategy_signal(df, _st, dict(_pr))["long"].fillna(False).astype(bool)
                _hit = bool(len(_fl) > 1 and _fl.iloc[-1] and not _fl.iloc[-2])
            except Exception:
                _hit = False
            _c = shadow.setdefault(_st, {"scans": 0, "signals": 0})
            _c["scans"] += 1
            _c["signals"] += int(_hit)
        rec["last_eval_ts"] = now
        # surface in the per-asset "checks today / last checked" table (one check per scan pass)
        _record_scheduler_check(f"{sym}:STRIKE")
        _scheduler_last_results[f"{sym}:STRIKE"] = {
            "status": "checked", "checked_at_utc": now,
            "action_taken": ("setup_" + fired[0]) if fired else "no_setup"}
        if not fired:
            rec["status"] = "monitored_no_setup"
            continue
        tag, sig = fired
        if not real_ok or not entry_window:
            rec["status"] = f"setup_fired_{tag}_not_traded_" + ("real_switch_off" if not real_ok else "outside_entry_window")
            continue
        if (d["underlying"], d["right"]) in held_sides:
            rec["status"] = f"setup_fired_{tag}_side_already_held"
            continue
        if sym in held or nse_fo_chain.must_force_close_before_expiry(d["underlying"], d["expiry"]):
            rec["status"] = f"setup_fired_{tag}_held_or_expiry_window"
            continue
        atr = _compute_atr_value(df, 14)
        entry_px = float(sig["entry_price"])
        if not atr or atr <= 0 or entry_px <= 0:
            rec["status"] = f"setup_fired_{tag}_bad_atr_or_price"
            continue
        dist = min(max(FO_STRIKE_TRAIL_ATR_MULT * atr, entry_px * FO_STRIKE_TRAIL_MIN_PCT / 100),
                   entry_px * FO_STRIKE_TRAIL_MAX_PCT / 100)
        contract = {"kotak_trading_symbol": sym, "instrument_token": token,
                    "exchange_segment": segment, "expiry": d["expiry"], "strike": d["strike"],
                    "lot_size": d["lot_size"], "premium": entry_px}
        leg_key = f"{sym}:SETUP"
        # each standalone side gets an equal share of the money still available today
        budget = (_day_open_capital_inr(conn) - _real_fo_today_spent_inr(conn)) / max(1, len(_FO_STRIKE_SCAN_UNDERLYINGS) * 2 - len(held_sides))
        _real_fo_buy_contract(
            conn, leg_key, d["underlying"], contract, tag, f"strike_setup_{tag}",
            f"{d['right']} strike {d['strike']} {d['expiry']} own 5m candle matched viable setup {tag}; "
            f"entry {entry_px:.2f}, trail {dist:.2f} ({FO_STRIKE_TRAIL_ATR_MULT}x ATR {atr:.2f}, "
            f"clamped {FO_STRIKE_TRAIL_MIN_PCT}-{FO_STRIKE_TRAIL_MAX_PCT}%)",
            trail_dist=dist, budget_inr=budget,
        )
        if conn.execute("SELECT 1 FROM real_fo_positions WHERE leg_key = ?", (leg_key,)).fetchone():
            held_sides.add((d["underlying"], d["right"]))
            held.add(sym)
            rec["status"] = f"bought_{tag}"
        else:
            rec["status"] = f"setup_fired_{tag}_buy_not_placed_see_real_order_log"
    for sym in list(_fo_strike_monitor):
        if sym not in seen:
            _fo_strike_monitor.pop(sym, None)  # strike left the feed (rolled / out of band)


@app.get("/fo-strike-monitoring")
def fo_strike_monitoring(symbol: str | None = None):
    """Per-strike view of the monitoring done by _run_fo_strike_setup_scan:
    every option strike in the live candle feed, the viable setups evaluated
    on its own candles today, its last fired setup and its current status
    (no token needed: read-only, no account data). ?symbol= filters by
    trading-symbol substring, case-insensitive (e.g. NIFTY2610...21750CE)."""
    q = (symbol or "").strip().upper()
    rows = []
    for sym, r in sorted(_fo_strike_monitor.items()):
        if q and q not in sym.upper():
            continue
        rows.append({"symbol": sym, **{k: v for k, v in r.items() if k != "day"}})
    counts: dict = {}
    for r in rows:
        counts[r.get("status")] = counts.get(r.get("status"), 0) + 1
    return {"meta": dict(_fo_strike_monitor_meta), "strikes_tracked": len(rows), "status_counts": counts,
            "strikes": rows}


@app.get("/fo-entry-diagnosis")
def fo_entry_diagnosis():
    """Why is no index call/put being bought? Read-only, no token, NO account data
    (no balances/capital/order ids). Per underlying: switch states, entry window,
    viable setup tags, per-status strike counts from the in-memory monitor, held
    sides, today's skipped_* reason counts from real_fo_trades, and one
    'primary_blocker' picked by priority."""
    t = ist_now()
    today = t.strftime("%Y-%m-%d")
    in_window = t.weekday() < 5 and (9, 20) <= (t.hour, t.minute) < (15, 0)
    real_fo = bool(is_real_fo_trading_enabled())
    master = True
    skipped: dict = {}
    held_by_u: dict = {}
    try:
        with closing(get_db()) as conn:
            master = _switch_allows_entries(conn)
            for r in conn.execute(
                    "SELECT status, COUNT(*) AS c FROM real_fo_trades WHERE day = ? AND side = 'B' "
                    "AND status LIKE 'skipped_%' GROUP BY status", (today,)).fetchall():
                skipped[r["status"]] = int(r["c"])
            for r in conn.execute("SELECT kotak_trading_symbol, underlying FROM real_fo_positions").fetchall():
                side = "call" if (r["kotak_trading_symbol"] or "").upper().endswith("CE") else "put"
                held_by_u.setdefault(r["underlying"], set()).add(side)
    except Exception:
        pass
    tags = [tg for tg, _ in _fo_strike_setup_signals()]
    viable_tags = [tg for tg in tags if _is_strategy_viable_for_real_money(tg, check_switch=False)]
    monitor_u: dict = {}
    for r in _fo_strike_monitor.values():
        c = monitor_u.setdefault(r.get("underlying"), {})
        st = r.get("status") or "unscanned"
        key = ("setup_fired_" + st.split("_not_traded_")[-1] if "_not_traded_" in st else st)
        if st.startswith("setup_fired_") and "_not_traded_" not in st:
            key = "setup_fired_other"
        if st.startswith("bought_"):
            key = "bought"
        c[key] = c.get(key, 0) + 1
    meta = dict(_fo_strike_monitor_meta)
    # Candle-feed health (no account data): names WHY the strike monitor is empty.
    feed = {"connected": None, "last_error": None, "subscribed_instruments": None,
            "unresolved_legs_count": None, "started_at_utc": None, "universe_cached": None,
            "db_candle_rows": None, "db_candle_tokens": None, "latest_candle_age_seconds": None}
    try:
        import kotak_fo_candle_feed
        fs = kotak_fo_candle_feed.get_feed_status()
        feed.update({"connected": fs.get("connected"), "last_error": fs.get("last_error"),
                     "subscribed_instruments": fs.get("subscribed_instruments"),
                     "unresolved_legs_count": len(fs.get("unresolved_legs") or []),
                     "started_at_utc": fs.get("started_at_utc"),
                     "universe_cached": len(kotak_fo_candle_feed.get_cached_fo_universe()),
                     "connect_count": fs.get("connect_count"), "ticks_received": fs.get("ticks_received"),
                     "last_tick_ts": fs.get("last_tick_ts"),
                     "last_disconnect_reason": fs.get("last_disconnect_reason"),
                     "missing_index_underlyings": kotak_fo_candle_feed.universe_missing_index_underlyings(
                         kotak_fo_candle_feed.get_cached_fo_universe())})
        with closing(get_db()) as conn:
            r = conn.execute("SELECT COUNT(*) AS n, COUNT(DISTINCT instrument_token) AS t, "
                             "MAX(bucket_start_ts) AS m FROM fo_option_candles").fetchone()
            feed["db_candle_rows"], feed["db_candle_tokens"] = int(r["n"] or 0), int(r["t"] or 0)
            if r["m"]:
                feed["latest_candle_age_seconds"] = int(time.time() - float(r["m"]))
    except Exception as e:
        feed["last_error"] = feed["last_error"] or f"diagnosis_feed_read_failed: {e}"
    if feed["connected"] is False:
        feed_cause = "candle_feed_not_connected_see_candle_feed_last_error"
    elif not feed["universe_cached"]:
        feed_cause = "candle_feed_universe_not_resolved_yet"
    elif feed.get("missing_index_underlyings"):
        feed_cause = "candle_feed_universe_missing_index_underlyings_see_unresolved_spot"
    elif feed.get("ticks_received") == 0:
        feed_cause = "candle_feed_subscribed_but_zero_ticks_received"
    elif not feed["db_candle_rows"]:
        feed_cause = "candle_feed_connected_no_completed_5m_candle_yet"
    else:
        feed_cause = "no_strikes_in_candle_feed"
    unders = {}
    for u in _FO_STRIKE_SCAN_UNDERLYINGS:
        counts = monitor_u.get(u, {})
        total = sum(counts.values())
        if not master:
            blocker = "master_trading_switch_off"
        elif not real_fo:
            blocker = "real_fo_switch_off"
        elif not in_window:
            blocker = "outside_entry_window_0920_1500_ist"
        elif not viable_tags:
            blocker = "no_viable_strike_setup_tag"
        elif total == 0:
            blocker = feed_cause
        elif counts.get("warming_up_need_30_candles", 0) + counts.get("no_fresh_candle", 0) + counts.get("expired_series", 0) >= total:
            blocker = "all_strikes_warming_up_or_stale_candles"
        elif len(held_by_u.get(u, ())) >= 2:
            blocker = "call_and_put_already_held"
        elif sum(v for k, v in counts.items() if k.startswith("setup_fired") or k == "bought") == 0:
            blocker = "no_setup_fired_on_monitored_strikes"
        elif skipped:
            blocker = "setup_fired_but_buy_skipped_see_skipped_reasons"
        else:
            blocker = "none_detected"
        unders[u] = {"strikes_by_status": counts, "held_sides": sorted(held_by_u.get(u, ())),
                     "primary_blocker": blocker}
    return {"as_of_ist": t.strftime("%Y-%m-%d %H:%M:%S"), "real_fo_switch_on": real_fo,
            "master_trading_switch_on": master, "entry_window_open_ist_0920_1500": in_window,
            "viable_strike_setup_tags": viable_tags, "setup_tags_checked": tags,
            "last_scan_ts": meta.get("last_scan_ts"), "scans_today": meta.get("scans_today"),
            "skipped_reasons_today": skipped, "candle_feed": feed, "underlyings": unders}


# B-868 (2026-10-12): "available = X, need = Y" for every non-green signal. X is Kotak's
# own Net available margin, fetched fresh (<= 30s old) via the existing limits() helper and
# failing soft to unknown; Y is the money the trade needs (1 unit/contract/lot, from the
# sizing code's own notional). Exposure: /fo-entry-diagnosis stays account-data free; the
# figures are served by /signal-funds, which matches /scheduler-status (already public and
# already publishing the same Net figure for the trade-view page).
SIGNAL_FUNDS_MAX_AGE_SECONDS = 30
_NON_GREEN_ACTION_MARKERS = ("blocked", "insufficient", "budget_too_small", "skipped", "no_funds",
                             "warming", "not_ready", "no_qualifying", "no_fresh", "unavailable")


def _available_money_now(max_age_seconds: float = SIGNAL_FUNDS_MAX_AGE_SECONDS):
    """Kotak available cash right now, or None when it cannot be read."""
    if time.time() - (_real_capital_cache["fetched_at"] or 0.0) > max_age_seconds:
        _refresh_real_capital_cache()
    return _real_capital_cache["value"]


def _fmt_inr(v) -> str:
    return f"Rs {v:,.0f}"


def _funds_line(available, need) -> str:
    a = _fmt_inr(available) if available is not None else "unknown"
    n = _fmt_inr(need) if need is not None else "unknown"
    return f"available = {a}, need = {n}"


def _aggregate_risk_line(v) -> str:
    """B-1252: plain-language reason for blocked_aggregate_open_risk (risk cap, not cash).
    Need is the trade's own risk, which is only sized after the gate, so it is stated as
    'any risk > 0' because the gate is closed (realized loss + reserved risk >= cap)."""
    cap = v.get("daily_loss_cap_inr")
    res = v.get("open_reserved_risk_inr")
    lost = v.get("realized_loss_today_inr")
    if cap is None or res is None:
        return "daily risk cap reached (realized loss + open positions' reserved risk >= cap)"
    room = max(0.0, cap - (lost or 0.0) - res)
    return (f"daily risk room = {_fmt_inr(room)} (cap {_fmt_inr(cap)}, realized loss "
            f"{_fmt_inr(lost or 0.0)}, other open positions' reserved risk {_fmt_inr(res)}); "
            f"need = any trade risk > 0, so no new entry")


def _entry_why_for(key: str, v: dict) -> dict:
    """B-1252 (1): per-symbol 'why no entry' row. Ratios only: no balances, no INR."""
    act = v.get("action_taken") or v.get("status")
    gate = None
    ratio = None
    if (act or "") == "blocked_aggregate_open_risk":
        gate = "aggregate_open_risk"
        cap = v.get("daily_loss_cap_inr")
        if cap:
            ratio = {"reserved_vs_cap": round(((v.get("open_reserved_risk_inr") or 0.0)
                                               + (v.get("realized_loss_today_inr") or 0.0)) / cap, 3),
                     "cap_ratio": 1.0}
    elif (act or "") == "blocked_daily_loss_cap":
        gate = "daily_loss_cap"
    elif act and _is_non_green_action(act):
        gate = "other_blocker"
    return {"display": _display_name(key), "status": act, "gate": gate, "ratio": ratio,
            "entered": bool(act and str(act).startswith("entered"))}


@app.get("/entry-why")
def entry_why():
    """No-token, no-balance per-symbol 'why no entry' for the long engine."""
    out = {}
    for k, v in list(_scheduler_last_results.items()):
        if k.endswith(":STRIKE") or not isinstance(v, dict):
            continue
        out[k] = _entry_why_for(k, v)
    return {"as_of_ist": ist_now().strftime("%Y-%m-%d %H:%M:%S"), "symbols": out}


def _is_non_green_action(action) -> bool:
    a = (action or "").lower()
    return any(m in a for m in _NON_GREEN_ACTION_MARKERS)


@app.get("/signal-funds")
def signal_funds():
    """available/need line for every non-green equity/options signal and every
    non-clear F&O underlying. Same exposure as /scheduler-status (public, no token)."""
    available = _available_money_now()
    equity = {}
    for k, v in list(_scheduler_last_results.items()):
        act = v.get("action_taken") or v.get("status")
        if k.endswith(":STRIKE") or not _is_non_green_action(act):
            continue
        need = v.get("need_inr")
        # Show the free-pool figure the sizing decision actually used (Kotak cash minus
        # capital already deployed in open positions), not gross Kotak cash, so the line
        # agrees with the "insufficient capital" label it sits under.
        used = v.get("available_capital_inr")
        shown = used if used is not None else available
        if (act or "") == "blocked_aggregate_open_risk":
            # B-1252: this block is about the 2% daily RISK cap, not cash. Explain it in
            # risk terms instead of a misleading "available = X, need = unknown".
            equity[k] = {"display": _display_name(k), "action": act, "need_inr": None,
                         "available_inr": None, "kotak_cash_inr": available,
                         "line": _aggregate_risk_line(v)}
            continue
        equity[k] = {"display": _display_name(k), "action": act, "need_inr": need,
                     "available_inr": shown, "kotak_cash_inr": available,
                     "line": _funds_line(shown, need)}
    fo = {}
    try:
        diag = fo_entry_diagnosis()
        for u, r in diag["underlyings"].items():
            if r["primary_blocker"] == "none_detected":
                continue
            costs = [float(m["lot_size"]) * float(m["last_close"]) for m in _fo_strike_monitor.values()
                     if m.get("underlying") == u and m.get("lot_size") and m.get("last_close")]
            need = min(costs) if costs else None
            fo[u] = {"primary_blocker": r["primary_blocker"], "need_inr": need,
                     "line": _funds_line(available, need)}
    except Exception as e:
        fo = {"error": str(e)}
    return {"as_of_ist": ist_now().strftime("%Y-%m-%d %H:%M:%S"), "available_inr": available,
            "equity": equity, "fo": fo}


def _maybe_sync_real_fo_option_stop_losses(conn):
    """Scheduler-tick pass (every ~30s): trails/heals the SL of every open real
    single-strike option leg. Covers the 5-minute-backcheck requirement
    in-process; each call reads Kotak first."""
    for r in conn.execute("SELECT leg_key FROM real_fo_positions WHERE strategy_tag LIKE 'single_leg_%' OR strategy_tag LIKE 'strike_setup_%'").fetchall():
        try:
            _sync_real_fo_option_sl(conn, r["leg_key"])
        except Exception as e:
            print(f"[REAL F&O] SL sync error {r['leg_key']}: {e}")


STRADDLE_STOP_PCT = 40.0    # combined-premium stop, % below entry combined premium
STRADDLE_TARGET_RR = 1.5    # combined-premium target, multiple of the stop distance


def _close_real_straddle_legs(conn, fo_underlying: str):
    """Closes both real straddle legs (whichever are actually open - a
    failed entry earlier may have left only one). No gate - closing must
    never be blocked, same principle as every other real-money exit."""
    import kotak_real_fo_orders
    for right in ("CE", "PE"):
        leg_key = f"{fo_underlying}:STRADDLE-{right}"
        row = conn.execute("SELECT * FROM real_fo_positions WHERE leg_key = ?", (leg_key,)).fetchone()
        if not row:
            continue
        result = kotak_real_fo_orders.place_real_fo_exit(row["kotak_trading_symbol"], row["exchange_segment"], row["qty"])
        if result.get("ok"):
            conn.execute("DELETE FROM real_fo_positions WHERE leg_key = ?", (leg_key,))
            _log_real_fo_attempt(
                conn, leg_key, "S", "confirmed", kotak_trading_symbol=row["kotak_trading_symbol"],
                qty=row["qty"], order_id=result["order_id"], raw_response=result.get("raw_response"),
            )
            print(f"[REAL F&O] SELL STRADDLE-{right} {row['qty']} {row['kotak_trading_symbol']} (order {result['order_id']})")
        else:
            _log_real_fo_attempt(
                conn, leg_key, "S", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                qty=row["qty"], detail=result.get("detail"), raw_response=result.get("raw_response"),
            )
            print(f"[REAL F&O] SELL STRADDLE-{right} FAILED {row['kotak_trading_symbol']}: {result.get('detail')} "
                  f"- POSITION STILL OPEN, NEEDS ATTENTION")


def _straddle_signal_core(conn, fo_underlying: str, vol_signal, halted: bool, is_squareoff_time: bool, spot):
    """Long Straddle (docs/STRATEGY_LOG.md row #3) - NOT YET BACKTESTED.
    Paper-tracks unconditionally (nse_straddle_state); real order
    mirroring only when is_real_fo_trading_enabled() AND the
    real_straddle_enabled runtime setting are BOTH on. Called every
    scheduler tick for NIFTY/BANKNIFTY, independent of the directional
    single-leg call mirror above - manages any open straddle first (never
    also opens a new one the same tick), else checks for a fresh entry."""
    import nse_fo_chain
    today_str = ist_now().strftime("%Y-%m-%d")
    row = conn.execute("SELECT * FROM nse_straddle_state WHERE underlying = ?", (fo_underlying,)).fetchone()

    if row:
        call_c, _ = nse_fo_chain.select_nse_option_contract(fo_underlying, spot, "call") if spot else (None, None)
        put_c, _ = nse_fo_chain.select_nse_option_contract(fo_underlying, spot, "put") if spot else (None, None)
        # Only trust a requote when it's the SAME contract already held -
        # spot moving far enough can shift the "ATM" search to a different
        # strike; mark-to-market against the wrong contract would be worse
        # than falling back to the flat entry premium (never guessed).
        call_premium = call_c["premium"] if call_c and call_c["strike"] == row["strike"] else None
        put_premium = put_c["premium"] if put_c and put_c["strike"] == row["strike"] else None
        combined_now = (call_premium + put_premium) if (call_premium is not None and put_premium is not None) else None
        combined_entry = row["call_entry_premium"] + row["put_entry_premium"]

        dte_left = (dt.datetime.strptime(row["expiry"], "%Y-%m-%d") - dt.datetime.utcnow()).days
        exit_reason = None
        if halted:
            exit_reason = "daily_loss_cap_hit"
        elif dte_left <= 0:
            exit_reason = "expiry_reached"
        elif is_squareoff_time:
            exit_reason = "eod_squareoff"
        elif combined_now is not None:
            stop_dist = combined_entry * STRADDLE_STOP_PCT / 100
            if combined_now <= combined_entry - stop_dist:
                exit_reason = "stop_hit"
            elif combined_now >= combined_entry + STRADDLE_TARGET_RR * stop_dist:
                exit_reason = "target_hit"

        if exit_reason:
            exit_call = call_premium if call_premium is not None else row["call_entry_premium"]
            exit_put = put_premium if put_premium is not None else row["put_entry_premium"]
            fx, qty = row["fx_to_inr"], row["qty"]
            total_pnl_inr = 0.0
            for right, exit_p, entry_p in (("CE", exit_call, row["call_entry_premium"]),
                                            ("PE", exit_put, row["put_entry_premium"])):
                pnl_inr = (exit_p - entry_p) * qty * fx
                total_pnl_inr += pnl_inr
                opt_symbol = f"{fo_underlying}:STRADDLE-{right}"
                payload = {
                    "symbol": opt_symbol, "underlying": fo_underlying, "right": right, "action": "sell",
                    "qty": qty, "price": exit_p, "currency": "INR", "fx_to_inr": fx,
                    "strategy": "long_straddle", "exit_reason": exit_reason,
                    "entry_price": entry_p, "pnl_inr": round(pnl_inr, 2),
                }
                apply_paper_trade(conn, opt_symbol, "sell", qty, exit_p)
                conn.execute(
                    "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
                    "VALUES (?, ?, 'sell', ?, ?, ?, 'long_straddle', ?)",
                    (time.time(), opt_symbol, qty, exit_p, fx, json.dumps(payload)),
                )
            conn.execute("DELETE FROM nse_straddle_state WHERE underlying = ?", (fo_underlying,))
            conn.commit()
            print(f"[STRADDLE] paper exit {fo_underlying} ({exit_reason}) combined pnl Rs{round(total_pnl_inr, 2)}")
            _close_real_straddle_legs(conn, fo_underlying)  # unconditional - closing is never gated
        return  # managed (or held) this tick - never also check for a new entry the same tick

    # ---- no straddle open - check for a fresh entry ----
    if halted or is_squareoff_time or not vol_signal or spot is None:
        return
    # Once per day per underlying - STRATEGY_LOG's own "not yet
    # backtested" caution argues for the conservative read here.
    if conn.execute(
        "SELECT 1 FROM trades WHERE symbol = ? AND strategy = 'long_straddle' AND ts >= ?",
        (f"{fo_underlying}:STRADDLE-CE", ist_midnight_epoch(ist_now())),
    ).fetchone():
        return

    call_c, _ = nse_fo_chain.select_nse_option_contract(fo_underlying, spot, "call")
    put_c, _ = nse_fo_chain.select_nse_option_contract(fo_underlying, spot, "put")
    if call_c is None or put_c is None or call_c["strike"] != put_c["strike"] or call_c["expiry"] != put_c["expiry"]:
        return  # no matching ATM pair this tick - never force a mismatched strike/expiry pair

    qty = call_c["lot_size"]
    fx = 1.0  # every underlying wired to this strategy (NSE index, MCX commodity) is INR-native
    conn.execute(
        "INSERT INTO nse_straddle_state (underlying, day, expiry, strike, lot_size, qty, "
        "call_entry_premium, put_entry_premium, call_kotak_symbol, put_kotak_symbol, "
        "call_instrument_token, put_instrument_token, entry_ts, fx_to_inr) "
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (fo_underlying, today_str, call_c["expiry"], call_c["strike"], call_c["lot_size"], qty,
         call_c["premium"], put_c["premium"], call_c["kotak_trading_symbol"], put_c["kotak_trading_symbol"],
         call_c["instrument_token"], put_c["instrument_token"], time.time(), fx),
    )
    for right, c in (("CE", call_c), ("PE", put_c)):
        opt_symbol = f"{fo_underlying}:STRADDLE-{right}"
        payload = {
            "symbol": opt_symbol, "underlying": fo_underlying, "right": right, "action": "buy",
            "qty": qty, "price": c["premium"], "currency": "INR", "fx_to_inr": fx,
            "strategy": "long_straddle", "entry_reason": "vol_contraction_signal",
            "strike": c["strike"], "expiry": c["expiry"],
        }
        apply_paper_trade(conn, opt_symbol, "buy", qty, c["premium"])
        conn.execute(
            "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
            "VALUES (?, ?, 'buy', ?, ?, ?, 'long_straddle', ?)",
            (time.time(), opt_symbol, qty, c["premium"], fx, json.dumps(payload)),
        )
    conn.commit()
    print(f"[STRADDLE] paper entry {fo_underlying} strike {call_c['strike']} exp {call_c['expiry']} "
          f"call Rs{call_c['premium']:.2f} put Rs{put_c['premium']:.2f}")

    if not is_real_fo_trading_enabled() or get_runtime_setting(conn, "real_straddle_enabled") < 0.5:
        return
    # 2026-10-01, same gap/fix as _maybe_place_real_fo_call_entry's own
    # docstring explains: long_straddle has never been backtested or
    # registered in strategy_registry.py at all (see this function's own
    # "NOT YET BACKTESTED" docstring line) - _is_strategy_viable_for_
    # real_money("long_straddle") fails closed on the unrecognized tag,
    # correctly blocking every real straddle leg until this strategy is
    # actually validated and registered, never "innocent until proven
    # unprofitable" the way it silently was before this fix.
    if not _is_strategy_viable_for_real_money("long_straddle"):
        for right, c in (("CE", call_c), ("PE", put_c)):
            _log_real_fo_attempt(
                conn, f"{fo_underlying}:STRADDLE-{right}", "B", "skipped_strategy_not_viable",
                kotak_trading_symbol=c["kotak_trading_symbol"], price_est=c["premium"], qty=qty,
                detail="strategy_tag=long_straddle",
            )
        return

    import kotak_real_fo_orders
    combined_notional = qty * (call_c["premium"] + put_c["premium"])
    # Same live-capital basis as the single-leg call entry above - see
    # that call site's own comment.
    remaining = _day_open_capital_inr(conn) - _real_fo_today_spent_inr(conn)
    if combined_notional > remaining:
        for right, c in (("CE", call_c), ("PE", put_c)):
            _log_real_fo_attempt(
                conn, f"{fo_underlying}:STRADDLE-{right}", "B", "skipped_over_daily_cap",
                kotak_trading_symbol=c["kotak_trading_symbol"], price_est=c["premium"], qty=qty,
                detail=f"combined 2-leg cost Rs{combined_notional:.2f}, remaining budget Rs{remaining:.2f}",
            )
        return

    # Joint real daily-loss cap (2026-09-08) - see _real_loss_budget's own
    # docstring; same gate equity and the single-leg F&O entry both
    # enforce, applied here for the same "never place one leg alone"
    # reasoning as the margin check below.
    loss_check = _real_loss_budget(conn)
    if not loss_check["ok"]:
        status = "skipped_real_pnl_unknown" if loss_check["real_pnl_today"] is None else "skipped_real_daily_loss_cap_hit"
        for right, c in (("CE", call_c), ("PE", put_c)):
            _log_real_fo_attempt(
                conn, f"{fo_underlying}:STRADDLE-{right}", "B", status,
                kotak_trading_symbol=c["kotak_trading_symbol"], price_est=c["premium"], qty=qty,
                detail=loss_check["detail"],
            )
        return

    call_margin = kotak_real_fo_orders.check_margin_affordable(
        call_c["exchange_segment"], call_c["instrument_token"], "B", qty)
    put_margin = kotak_real_fo_orders.check_margin_affordable(
        put_c["exchange_segment"], put_c["instrument_token"], "B", qty)
    if not (call_margin["ok"] and put_margin["ok"]):
        # Never place one leg alone - a naked single leg was not the
        # signal that fired.
        for right, c, m in (("CE", call_c, call_margin), ("PE", put_c, put_margin)):
            _log_real_fo_attempt(
                conn, f"{fo_underlying}:STRADDLE-{right}", "B", "skipped_only_one_leg_affordable",
                kotak_trading_symbol=c["kotak_trading_symbol"], price_est=c["premium"], qty=qty,
                detail=m["detail"], raw_response=m.get("raw_response"),
            )
        return

    for right, c in (("CE", call_c), ("PE", put_c)):
        result = kotak_real_fo_orders.place_real_fo_entry(c["kotak_trading_symbol"], c["exchange_segment"], qty)
        leg_key = f"{fo_underlying}:STRADDLE-{right}"
        if result.get("ok"):
            conn.execute(
                "INSERT INTO real_fo_positions (leg_key, underlying, strategy_tag, kotak_trading_symbol, "
                "instrument_token, exchange_segment, expiry, strike, lot_size, qty, entry_price, entry_order_id, "
                "opened_at, day) VALUES (?, ?, 'long_straddle', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (leg_key, fo_underlying, c["kotak_trading_symbol"], c["instrument_token"], c["exchange_segment"],
                 c["expiry"], c["strike"], c["lot_size"], qty, c["premium"], result["order_id"],
                 time.time(), today_str),
            )
            _log_real_fo_attempt(
                conn, leg_key, "B", "confirmed", kotak_trading_symbol=c["kotak_trading_symbol"],
                qty=qty, price_est=c["premium"], notional_inr=qty * c["premium"],
                order_id=result["order_id"], raw_response=result.get("raw_response"),
            )
            print(f"[REAL F&O] BUY STRADDLE-{right} {qty} {c['kotak_trading_symbol']} (order {result['order_id']})")
        else:
            _log_real_fo_attempt(
                conn, leg_key, "B", "failed", kotak_trading_symbol=c["kotak_trading_symbol"],
                qty=qty, price_est=c["premium"], detail=result.get("detail"), raw_response=result.get("raw_response"),
            )
            print(f"[REAL F&O] BUY STRADDLE-{right} FAILED {c['kotak_trading_symbol']}: {result.get('detail')} "
                  f"- OTHER LEG MAY ALREADY BE OPEN, NEEDS ATTENTION")


FO_OPTIONS_SCAN_INTERVAL_SECONDS = 300  # matches kotak_fo_candle_feed.CANDLE_INTERVAL_SECONDS - no point scanning faster than a new candle bar can complete
_fo_options_scan_last_ts = 0.0


def _open_fo_option_paper_position(conn, instrument_token: str, exchange_segment: str, descriptor: dict, signal: dict):
    qty = descriptor["lot_size"]
    entry_price = signal["entry_price"]
    day = ist_now().strftime("%Y-%m-%d")
    conn.execute(
        "INSERT INTO signal_state_fo_options (instrument_token, kotak_trading_symbol, underlying, right, "
        "strike, expiry, exchange_segment, lot_size, entry_price, initial_stop_loss, entry_bar_ts, entry_ts, day) "
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (instrument_token, descriptor["kotak_trading_symbol"], descriptor["underlying"], descriptor["right"],
         descriptor["strike"], descriptor["expiry"], exchange_segment, qty, entry_price, signal["stop_loss"],
         signal["entry_bar_ts"].isoformat(), time.time(), day),
    )
    paper_symbol = f"{descriptor['kotak_trading_symbol']}:RSI2FO"
    payload = {
        "symbol": paper_symbol, "underlying": descriptor["underlying"], "right": descriptor["right"],
        "strike": descriptor["strike"], "expiry": descriptor["expiry"], "action": "buy", "qty": qty,
        "price": entry_price, "strategy": "rsi2_premium_reversion", "entry_reason": "rsi2_mean_reversion_signal",
        "rsi2": signal["rsi2"], "stop_loss": signal["stop_loss"],
    }
    apply_paper_trade(conn, paper_symbol, "buy", qty, entry_price)
    conn.execute(
        "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
        "VALUES (?, ?, 'buy', ?, ?, 1.0, 'rsi2_premium_reversion', ?)",
        (time.time(), paper_symbol, qty, entry_price, json.dumps(payload)),
    )
    conn.commit()
    print(f"[FO_RSI2] paper entry {descriptor['kotak_trading_symbol']} strike {descriptor['strike']} "
          f"exp {descriptor['expiry']} premium Rs{entry_price:.2f} rsi2={signal['rsi2']:.2f}")


def _manage_open_fo_option_position(conn, row, descriptor: dict | None):
    """Exits `row` (a signal_state_fo_options row) on either a
    physical-settlement force-close (checked unconditionally first -
    same "closing must never be blocked" principle as
    _close_real_straddle_legs) or fo_option_strategy's own RSI2 exit
    signal. No-op if neither fires. `descriptor` may be None if this
    leg dropped out of the currently resolved universe (e.g. a universe
    refresh moved it out of the ATM band) - force-close and the candle
    read both still work from the row's own stored fields in that case,
    same "manage what's open regardless of subscription churn"
    reasoning kotak_fo_candle_feed.read_fo_candles_as_df's own docstring
    flags as a real constraint of this data source."""
    import fo_option_strategy
    import kotak_fo_candle_feed
    import nse_fo_chain

    force_close = nse_fo_chain.must_force_close_before_expiry(row["underlying"], row["expiry"])
    df = kotak_fo_candle_feed.read_fo_candles_as_df(row["instrument_token"])

    exit_reason = "physical_settlement_force_close" if force_close else None
    if exit_reason is None and df is not None:
        entry_bar_ts = pd.Timestamp(row["entry_bar_ts"])
        exit_reason = fo_option_strategy.rsi2_mean_reversion_exit_reason(df, entry_bar_ts, row["initial_stop_loss"])
    if exit_reason is None:
        return

    exit_price = float(df["Close"].iloc[-1]) if df is not None and len(df) else row["entry_price"]
    qty = row["lot_size"]
    pnl_inr = (exit_price - row["entry_price"]) * qty
    paper_symbol = f"{row['kotak_trading_symbol']}:RSI2FO"
    payload = {
        "symbol": paper_symbol, "underlying": row["underlying"], "right": row["right"], "strike": row["strike"],
        "expiry": row["expiry"], "action": "sell", "qty": qty, "price": exit_price,
        "strategy": "rsi2_premium_reversion", "exit_reason": exit_reason,
        "entry_price": row["entry_price"], "pnl_inr": round(pnl_inr, 2),
    }
    apply_paper_trade(conn, paper_symbol, "sell", qty, exit_price)
    conn.execute(
        "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
        "VALUES (?, ?, 'sell', ?, ?, 1.0, 'rsi2_premium_reversion', ?)",
        (time.time(), paper_symbol, qty, exit_price, json.dumps(payload)),
    )
    conn.execute("DELETE FROM signal_state_fo_options WHERE instrument_token = ?", (row["instrument_token"],))
    conn.commit()
    print(f"[FO_RSI2] paper exit {row['kotak_trading_symbol']} ({exit_reason}) pnl Rs{round(pnl_inr, 2)}")


def _run_fo_options_scan(conn):
    """RSI(2) mean-reversion paper-trading loop over F&O OPTION legs from
    kotak_fo_candle_feed's own resolved universe - FUTURES are skipped
    entirely (matches kotak_real_fo_orders.py's own real-order scope,
    which never auto-trades futures either). Guarded by
    FO_OPTIONS_SCAN_INTERVAL_SECONDS via the module-level
    _fo_options_scan_last_ts, same in-memory-guard/acceptable-restart-
    cost tradeoff _fo_chain_monitoring_snapshot already uses - this is
    PAPER only, not yet real money, so a restart causing one extra scan
    sooner than 5 minutes after the last one is a non-issue.

    Paper trades are tagged strategy='rsi2_premium_reversion', NOT
    'orb-*' prefixed - matching nse_straddle_state's own 'long_straddle'
    precedent, this deliberately excludes them from
    today_realized_pnl's shared daily-loss-cap and from
    deployed_notional's shared capital pool, consistent with every
    other F&O options-buying engine in this file.

    Manages every already-open position first (exit signal OR
    force-close), and only then considers opening a new one on a leg
    with nothing open - never both the same tick for the same leg, same
    discipline as _straddle_signal_core."""
    global _fo_options_scan_last_ts
    now = time.time()
    if now - _fo_options_scan_last_ts < FO_OPTIONS_SCAN_INTERVAL_SECONDS:
        return
    _fo_options_scan_last_ts = now

    import fo_option_strategy
    import kotak_fo_candle_feed
    import nse_fo_chain

    universe = kotak_fo_candle_feed.get_cached_fo_universe()
    descriptors_by_token = {token: d for (_seg, token), d in universe.items()}

    open_rows = conn.execute("SELECT * FROM signal_state_fo_options").fetchall()
    for row in open_rows:
        _record_scheduler_check(f"{row['kotak_trading_symbol']}:RSI2FO")
        _manage_open_fo_option_position(conn, row, descriptors_by_token.get(row["instrument_token"]))

    open_tokens = {row["instrument_token"] for row in open_rows}
    for (exchange_segment, instrument_token), descriptor in universe.items():
        if descriptor["kind"] != "option" or instrument_token in open_tokens:
            continue
        if nse_fo_chain.must_force_close_before_expiry(descriptor["underlying"], descriptor["expiry"]):
            _record_scheduler_skipped_visit()  # B-1271: visited, nothing evaluated
            continue  # too close to physical settlement to open a fresh position on this leg

        df = kotak_fo_candle_feed.read_fo_candles_as_df(instrument_token)
        if df is None:
            _record_scheduler_skipped_visit()  # B-1271: no candles, nothing evaluated
            continue
        # B-1271: a check is counted only once candles exist and the entry rule is actually evaluated
        _record_scheduler_check(f"{descriptor['kotak_trading_symbol']}:RSI2FO")
        signal = fo_option_strategy.rsi2_mean_reversion_entry_signal(df)
        if signal is None:
            continue
        _open_fo_option_paper_position(conn, instrument_token, exchange_segment, descriptor, signal)


# Explicit user decision (2026-09-16, AskUserQuestion) on how long the
# RSI2-options paper engine must run before real-order wiring is even
# CONSIDERED - not a technical constraint, a deliberately chosen bar
# per CLAUDE.md's standing "never ship real-money logic blind"
# discipline. Both conditions (see fo_rsi2_validation_status) must
# hold; meeting them is necessary, not sufficient - an honest results
# review (win rate/expectancy, not just count) still has to happen
# before wiring is proposed, same as every other strategy here.
FO_RSI2_VALIDATION_MIN_DAYS = 28  # 4 weeks
FO_RSI2_VALIDATION_MIN_CLOSED_TRADES = 30


def fo_rsi2_validation_status(conn) -> dict:
    """Whether the RSI2-options paper engine has accumulated enough
    paper-trading evidence to be considered for real-order wiring, per
    FO_RSI2_VALIDATION_MIN_DAYS/FO_RSI2_VALIDATION_MIN_CLOSED_TRADES
    above. A closed trade is counted as a 'sell' row tagged
    strategy='rsi2_premium_reversion' in `trades` - each one is exactly
    one position _manage_open_fo_option_position closed out."""
    first_ts = conn.execute(
        "SELECT MIN(ts) AS first_ts FROM trades WHERE strategy = 'rsi2_premium_reversion'"
    ).fetchone()["first_ts"]
    closed_trades = conn.execute(
        "SELECT COUNT(*) AS n FROM trades WHERE strategy = 'rsi2_premium_reversion' AND action = 'sell'"
    ).fetchone()["n"]
    days_elapsed = (time.time() - first_ts) / 86400 if first_ts else 0.0
    return {
        "first_paper_trade_ts": first_ts,
        "days_elapsed": round(days_elapsed, 1),
        "days_required": FO_RSI2_VALIDATION_MIN_DAYS,
        "closed_trades": closed_trades,
        "closed_trades_required": FO_RSI2_VALIDATION_MIN_CLOSED_TRADES,
        "meets_minimum_criteria": (
            first_ts is not None
            and days_elapsed >= FO_RSI2_VALIDATION_MIN_DAYS
            and closed_trades >= FO_RSI2_VALIDATION_MIN_CLOSED_TRADES
        ),
    }


def _force_close_all_positions(conn, reason: str) -> dict:
    """The kill switch's actual work: exits EVERY open position - paper
    equity, paper options, AND real Kotak positions (added 2026-09-07) -
    right now, at the best available current price, regardless of where
    price sits versus stop/target. Deliberately standalone from the
    normal tick-based exit code in _auto_signal_core/_options_signal_core -
    an emergency-stop action should never share a code path with (and risk
    being broken by some future change to) the everyday exit logic that
    protects every other open position."""
    watchlist_by_symbol = {cfg["symbol"]: cfg for cfg in WATCHLIST}
    closed = []
    total_pnl_inr = 0.0
    live_rr = get_runtime_setting(conn, "rr")  # for the rr_target field below, live not static

    for row in conn.execute("SELECT * FROM signal_state WHERE status = 'long'").fetchall():
        symbol = row["symbol"]
        cfg = watchlist_by_symbol.get(symbol, {})
        interval = row["interval"] or "5m"
        try:
            df = fetch_ohlc(symbol, "5d", interval)
            exit_price = float(df["Close"].iloc[-1])
        except Exception:
            exit_price = row["entry_price"]  # never let a data hiccup block a kill

        strategy = cfg.get("strategy", "orb_breakout")
        strategy_tag = (
            f"{ORB_STRATEGY_PREFIX}{cfg.get('orb_minutes', 15)}m-sma{cfg.get('sma_fast', 9)}-{cfg.get('sma_slow', 21)}"
            if strategy == "orb_breakout"
            else f"{ORB_STRATEGY_PREFIX}bullish-engulfing-trend{cfg.get('trend_sma', 0)}"
        )
        qty = row["qty"]
        entry_fx = row["fx_to_inr"]
        pnl_native = (exit_price - row["entry_price"]) * qty
        pnl_inr = pnl_native * entry_fx
        stop_dist = row["entry_price"] - row["stop_loss"]
        rr_achieved = round((exit_price - row["entry_price"]) / stop_dist, 2) if stop_dist else None
        payload = {
            "symbol": symbol, "action": "sell", "qty": qty, "price": exit_price,
            "currency": cfg.get("currency", "INR"), "fx_to_inr": entry_fx,
            "strategy": strategy_tag, "exit_reason": reason,
            "entry_price": row["entry_price"], "stop_loss": row["stop_loss"], "target": row["target"],
            "rr_target": live_rr, "rr_achieved": rr_achieved,
            "pnl_native": round(pnl_native, 2), "pnl_inr": round(pnl_inr, 2),
        }
        apply_paper_trade(conn, symbol, "sell", qty, exit_price)
        conn.execute(
            "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
            "VALUES (?, ?, 'sell', ?, ?, ?, ?, ?)",
            (time.time(), symbol, qty, exit_price, entry_fx, strategy_tag, json.dumps(payload)),
        )
        conn.execute("DELETE FROM signal_state WHERE symbol = ?", (symbol,))
        total_pnl_inr += pnl_inr
        closed.append({"symbol": symbol, "instrument": "equity", "exit_price": exit_price, "pnl_inr": round(pnl_inr, 2)})

    for row in conn.execute("SELECT * FROM option_state").fetchall():
        opt_symbol = row["opt_symbol"]
        exit_premium = _requote_contract(row["underlying"], row["expiry"], row["strike"], row["right"])
        if exit_premium is None:
            exit_premium = row["entry_premium"]  # same stale-requote fallback as the normal exit path

        contracts = row["contracts"]
        qty = contracts * 100
        entry_fx = row["fx_to_inr"]
        pnl_native = (exit_premium - row["entry_premium"]) * qty
        pnl_inr = pnl_native * entry_fx
        risk_per_contract = row["entry_premium"] - row["stop_premium"]
        rr_achieved = round((exit_premium - row["entry_premium"]) / risk_per_contract, 2) if risk_per_contract else None
        payload = {
            "symbol": opt_symbol, "underlying": row["underlying"], "right": row["right"], "action": "sell",
            "qty": qty, "contracts": contracts, "price": exit_premium, "currency": "USD", "fx_to_inr": entry_fx,
            "strategy": OPTIONS_STRATEGY_TAG, "exit_reason": reason,
            "entry_price": row["entry_premium"], "stop_loss": row["stop_premium"], "target": row["target_premium"],
            "rr_target": live_rr, "rr_achieved": rr_achieved,
            "pnl_native": round(pnl_native, 2), "pnl_inr": round(pnl_inr, 2),
        }
        apply_paper_trade(conn, opt_symbol, "sell", qty, exit_premium)
        conn.execute(
            "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
            "VALUES (?, ?, 'sell', ?, ?, ?, ?, ?)",
            (time.time(), opt_symbol, qty, exit_premium, entry_fx, OPTIONS_STRATEGY_TAG, json.dumps(payload)),
        )
        conn.execute("DELETE FROM option_state WHERE opt_symbol = ?", (opt_symbol,))
        total_pnl_inr += pnl_inr
        closed.append({"symbol": opt_symbol, "instrument": "option", "exit_price": exit_premium, "pnl_inr": round(pnl_inr, 2)})

    # REAL Kotak positions - added 2026-09-07 ("Kill switch on render is
    # not killing my live trade on Kotak"). Before this, the kill switch
    # closed ONLY paper positions above - an "emergency stop" that left
    # real money on the table was worse than having no kill switch at all.
    # Unconditional, no is_real_trading_enabled gate - same principle
    # _maybe_place_real_exit already established: closing an already-open
    # real position must never be blocked by any switch, including this
    # one's own reason for existing.
    real_closed = []
    real_close_failed = []
    import kotak_real_orders
    for row in conn.execute("SELECT * FROM real_positions").fetchall():
        if row["sl_order_id"]:
            cancel_result = kotak_real_orders.cancel_real_order(row["sl_order_id"])
            if not cancel_result.get("ok"):
                print(f"[REAL TRADE] KILL SWITCH SL cancel failed for {row['kotak_trading_symbol']} "
                      f"(order {row['sl_order_id']}): {cancel_result.get('detail')} - proceeding with exit anyway")
            _log_real_order_event(
                conn, row["symbol"], "sl", "cancelled" if cancel_result.get("ok") else "cancel_failed",
                kotak_trading_symbol=row["kotak_trading_symbol"], order_id=row["sl_order_id"],
                prev_state=f"resting @ Rs{row['sl_trigger_price']}", new_state="cancelled (kill switch)",
                detail=reason,
            )
        if row["target_order_id"]:
            cancel_result = kotak_real_orders.cancel_real_order(row["target_order_id"])
            if not cancel_result.get("ok"):
                print(f"[REAL TRADE] KILL SWITCH target cancel failed for {row['kotak_trading_symbol']} "
                      f"(order {row['target_order_id']}): {cancel_result.get('detail')} - proceeding with exit anyway")
            _log_real_order_event(
                conn, row["symbol"], "target", "cancelled" if cancel_result.get("ok") else "cancel_failed",
                kotak_trading_symbol=row["kotak_trading_symbol"], order_id=row["target_order_id"],
                prev_state=f"resting @ Rs{row['target_price']}", new_state="cancelled (kill switch)",
                detail=reason,
            )
        result = kotak_real_orders.place_real_exit(row["kotak_trading_symbol"], row["qty"])
        if result.get("ok"):
            conn.execute("DELETE FROM real_positions WHERE symbol = ?", (row["symbol"],))
            _log_real_attempt(
                conn, row["symbol"], "S", "confirmed", kotak_trading_symbol=row["kotak_trading_symbol"],
                qty=row["qty"], order_id=result["order_id"], raw_response=result.get("raw_response"),
                detail=reason,
            )
            real_closed.append({
                "symbol": row["symbol"], "kotak_trading_symbol": row["kotak_trading_symbol"],
                "qty": row["qty"], "order_id": result["order_id"],
            })
            print(f"[REAL TRADE] KILL SWITCH SELL {row['qty']} {row['kotak_trading_symbol']} (order {result['order_id']})")
            _log_real_order_event(
                conn, row["symbol"], "exit", "confirmed", kotak_trading_symbol=row["kotak_trading_symbol"],
                order_id=result["order_id"], prev_state=f"long {row['qty']} @ Rs{row['entry_price']:.2f}",
                new_state="closed (kill switch)", detail=reason,
            )
            _sync_real_positions_external(conn)
        else:
            # Same dangerous-failure handling as _maybe_place_real_exit -
            # left in real_positions, never guessed closed. Surfaced in the
            # kill response itself (not just /kotak-neo/real-positions) so
            # a human sees it immediately.
            _log_real_attempt(
                conn, row["symbol"], "S", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                qty=row["qty"], detail=result.get("detail"), raw_response=result.get("raw_response"),
            )
            real_close_failed.append({
                "symbol": row["symbol"], "kotak_trading_symbol": row["kotak_trading_symbol"],
                "qty": row["qty"], "detail": result.get("detail"),
            })
            print(f"[REAL TRADE] KILL SWITCH SELL FAILED {row['kotak_trading_symbol']}: "
                  f"{result.get('detail')} - POSITION STILL OPEN, NEEDS ATTENTION")
            _log_real_order_event(
                conn, row["symbol"], "exit", "failed", kotak_trading_symbol=row["kotak_trading_symbol"],
                prev_state=f"long {row['qty']} @ Rs{row['entry_price']:.2f}",
                new_state="still open - kill switch exit failed", detail=result.get("detail"),
            )
            _flag_if_t1_restricted(conn, row["symbol"], result.get("detail"))

    # 2026-10-11 user: "when I toggle OFF it should stop new trades immediately and close the live trades, all the
    # positions, holdings and anything live". The loop above only covered the intraday long table; close every OTHER
    # real category through its own engine's exit path (short cover, swing/holdings sell, option/MCX legs), each
    # cancelling its resting SL first and logging the reason. Failures are listed, never guessed closed.
    why = f"kill_switch: {reason}"
    for tbl, closer in (
        ("real_positions_short", lambda r: _maybe_place_real_short_exit(conn, r["symbol"], reason=why)),
        ("real_positions_swing", lambda r: _maybe_place_real_swing_exit(conn, r["symbol"], reason=why)),
        ("real_fo_positions", lambda r: _close_real_fo_option_leg(conn, r, why)),
    ):
        try:
            rows = conn.execute(f"SELECT * FROM {tbl}").fetchall()
        except Exception as e:
            print(f"[REAL TRADE] KILL SWITCH could not read {tbl}: {e}")
            continue
        for r in rows:
            try:
                closer(r)
                conn.commit()
            except Exception as e:
                print(f"[REAL TRADE] KILL SWITCH close failed in {tbl} for {dict(r).get('symbol') or dict(r).get('leg_key')}: {e}")
        for r in conn.execute(f"SELECT * FROM {tbl}").fetchall():
            rd = dict(r)
            real_close_failed.append({"symbol": rd.get("symbol") or rd.get("leg_key"), "table": tbl,
                                      "qty": rd.get("qty"), "detail": "still open after kill-switch close attempt"})
    conn.commit()
    return {
        "closed_count": len(closed), "closed": closed, "total_pnl_inr": round(total_pnl_inr, 2),
        "real_closed_count": len(real_closed), "real_closed": real_closed,
        "real_close_failed_count": len(real_close_failed), "real_close_failed": real_close_failed,
    }


def _banner_extras() -> dict:
    """B-396 (user 2026-10-11 "build these"): extra scan-banner facts. Every field is best-effort and never raises."""
    out: dict = {}
    try:
        t = ist_now()
        today = t.strftime("%Y-%m-%d")
        done = _mcx_daily_scan_day == today
        out["mcx_scan_done_today"] = done
        if done:
            out["mcx_next_scan"] = "tomorrow 09:20 IST" if t.weekday() < 4 else "Monday 09:20 IST"
        elif t.weekday() >= 5:
            out["mcx_next_scan"] = "Monday 09:20 IST"
        elif (t.hour, t.minute) < (9, 20):
            out["mcx_next_scan"] = "today 09:20 IST"
        elif (t.hour, t.minute) < (23, 0):
            out["mcx_next_scan"] = "due now"
        else:
            out["mcx_next_scan"] = "tomorrow 09:20 IST" if t.weekday() < 4 else "Monday 09:20 IST"
        out["mcx_cells"] = len(_MCX_DAILY_CELLS)
    except Exception:
        pass
    try:
        with closing(get_db()) as c:
            out["trading_enabled"] = bool(is_trading_enabled(c))
            row = c.execute("SELECT checked_at FROM real_protection_snapshot WHERE id = 1").fetchone()
        out["protection_check_age_s"] = None if not row else int(time.time() - row["checked_at"])
    except Exception:
        pass
    try:
        out["shadow_scans_total"] = sum(v["scans"] for r in _fo_strike_monitor.values() for v in r.get("shadow", {}).values())
        out["shadow_signals_total"] = sum(v["signals"] for r in _fo_strike_monitor.values() for v in r.get("shadow", {}).values())
    except Exception:
        pass
    try:
        wired = [t for t in _STRATEGY_TAG_TO_REGISTRY_NAME]
        open_n = sum(1 for t in wired if _is_strategy_wired(t))
        out["wired_strategies"] = len(wired)
        out["wired_gate_open"] = open_n
        out["wired_gate_closed"] = len(wired) - open_n
    except Exception:
        pass
    return out


@app.post("/strategy-tag")
def set_user_strategy_tag(symbol: str, strategy: str):
    """B-402: the user names the strategy of a position the app could not
    recover. Display/attribution only: engine ownership and SL rules are
    unchanged. Mirrored to Upstash via the generic mirror."""
    base = symbol.split("-")[0].split(".")[0].strip().upper()
    name = strategy.strip()[:80]
    if not base or not name:
        raise HTTPException(status_code=400, detail="symbol and strategy required")
    with closing(get_db()) as conn:
        conn.execute(
            "INSERT INTO user_strategy_tags (symbol, strategy, tagged_at) VALUES (?,?,?) "
            "ON CONFLICT(symbol) DO UPDATE SET strategy=excluded.strategy, tagged_at=excluded.tagged_at",
            (base, name, time.time()),
        )
        conn.commit()
    return {"ok": True, "symbol": base, "strategy": "user: " + name}


@app.get("/trading-control")
def get_trading_control():
    with closing(get_db()) as conn:
        row = conn.execute("SELECT * FROM trading_control WHERE id = 1").fetchone()
    return dict(row) if row else {"id": 1, "enabled": True, "updated_at": None, "updated_by": None, "reason": None}


@app.post("/trading-control")
def set_trading_control(action: str, reason: str | None = None):
    """The kill switch's HTTP surface. action:
      - 'pause'  - stop taking NEW entries; existing open positions keep
                   being managed normally (stop/target/trend/eod).
      - 'resume' - allow new entries again. Reconciles against Kotak's own
                   live account FIRST (see the resume branch's own
                   comment below) - explicit user ask 2026-09-28: "it
                   should fetch live trades in kotak account first and
                   then based on that it should decide what to do next."
      - 'kill'   - force-close every open position right now (see
                   _force_close_all_positions) AND pause, so nothing
                   reopens on the very next tick.
    """
    if action not in ("pause", "resume", "kill"):
        raise HTTPException(status_code=400, detail="action must be one of: pause, resume, kill")

    with closing(get_db()) as conn:
        if action == "kill":
            summary = _force_close_all_positions(conn, reason or "manual_kill_switch")
            conn.execute(
                "INSERT INTO trading_control (id, enabled, updated_at, updated_by, reason) "
                "VALUES (1, 0, ?, 'user', ?) "
                "ON CONFLICT(id) DO UPDATE SET enabled=0, updated_at=excluded.updated_at, "
                "updated_by=excluded.updated_by, reason=excluded.reason",
                (time.time(), reason or "kill switch"),
            )
            conn.commit()
            return {"status": "killed", "enabled": False, **summary}

        # 2026-09-28: reconcile against Kotak's own live account BEFORE
        # resuming - explicit user ask, this switch also gates real order
        # mirroring (is_real_trading_enabled's other, independent gate),
        # so whatever happened at the broker while this was OFF (a manual
        # trade, an organic fill, a position this app lost track of) is
        # folded into real_positions/signal_state before new entries can
        # fire again, rather than resuming blind against stale local
        # state. adopt="*" (never a narrower symbol list) matches the
        # existing scheduled reconcile's own policy (kotak-reconcile.yml)
        # - only ever adopts a position whose entry carries Kotak's own
        # bot-order tag (see _reconcile_real_positions_core's own
        # docstring), so this can never silently take over a manual
        # trade. Calls the CORE function directly (no token, no HTTP
        # round trip - see that function's own 2026-09-28 note) and is
        # best-effort: a Kotak/network hiccup must never block resuming
        # PAPER trading, which doesn't itself depend on Kotak at all.
        kotak_reconcile = None
        if action == "resume":
            try:
                kotak_reconcile = _reconcile_real_positions_core(adopt="*")
            except Exception as e:
                kotak_reconcile = {"error": f"reconcile failed, resuming anyway: {e}"}

        enabled = 1 if action == "resume" else 0
        conn.execute(
            "INSERT INTO trading_control (id, enabled, updated_at, updated_by, reason) "
            "VALUES (1, ?, ?, 'user', ?) "
            "ON CONFLICT(id) DO UPDATE SET enabled=excluded.enabled, updated_at=excluded.updated_at, "
            "updated_by=excluded.updated_by, reason=excluded.reason",
            (enabled, time.time(), reason),
        )
        conn.commit()
        result = {"status": "paused" if action == "pause" else "resumed", "enabled": bool(enabled)}
        if action == "resume":
            result["kotak_reconcile"] = kotak_reconcile
        return result


# --- Stage 3: real order placement - HTTP surface ---------------------------
# Token-gated (same KOTAK_NEO_API_TOKEN as every other real-account
# endpoint) - unlike /trading-control (paper, no token needed), these touch
# real money and must never be callable by an unauthenticated request.


@app.get("/real-pnl-today")
def get_real_pnl_today():
    """Real (Kotak) P&L summary only - no token required, unlike
    /real-trading-control. Explicit user instruction (2026-09-07): "why
    token needed. make it without any checks" - deliberately narrower
    than /real-trading-control rather than just dropping that endpoint's
    own gate: this returns ONLY the P&L/budget numbers, never
    open_real_positions (symbol, qty, entry price, order id) or the
    enable/disable switch state - the actual account/order detail stays
    behind the token, only the summary figure the trade-view dashboard
    shows is public. Same numbers as /real-trading-control's own
    real_pnl_today_inr/real_loss_cap_inr/real_loss_budget_remaining_inr -
    see get_real_pnl_today_inr's docstring for how this is computed."""
    with closing(get_db()) as conn:
        loss_check = _real_loss_budget(conn)
    real_capital = get_scheduler_capital_inr()
    real_pnl_today = loss_check["real_pnl_today"]
    real_capital_deployed = get_real_capital_deployed_inr()
    real_loss_cap_inr = round(loss_check["cap_inr"], 2)
    return {
        "real_pnl_today_inr": round(real_pnl_today, 2) if real_pnl_today is not None else None,
        "real_pnl_source": "kotak_positions_today" if real_pnl_today is not None else "unavailable",
        "real_pnl_fetch_error": _real_trades_cache["error"],
        "real_loss_cap_inr": real_loss_cap_inr,
        "real_loss_budget_remaining_inr": (
            round(max(0.0, real_loss_cap_inr - max(0.0, -real_pnl_today)), 2) if real_pnl_today is not None else None
        ),
        # real_loss_cap_inr is now daily_risk_pct% of a FIXED day-open
        # capital snapshot (2026-09-08, explicit user instruction: "keep
        # it as a % of total money available at the beginning of day") -
        # joint across equity + F&O, see _real_loss_budget's own
        # docstring. real_capital_available_inr below stays the LIVE,
        # continuously-refreshing figure (a different concept - "what's
        # available right now", used for position sizing, not the cap) so
        # the two are never conflated.
        "real_capital_day_open_inr": round(loss_check["day_open_capital_inr"], 2),
        "real_capital_available_inr": round(real_capital, 2),
        "real_capital_deployed_inr": real_capital_deployed,
        # Kotak wins: show exactly what limits() returned and when, so a
        # mismatch with the Kotak app is diagnosable from the field names.
        "real_capital_fetched_at_epoch": _real_capital_cache["fetched_at"] or None,
        "real_capital_fetch_error": _real_capital_cache["error"],
        "real_capital_kotak_limits_raw": _real_capital_cache.get("raw"),
    }


def _explain_kotak_exit_fill(o, order_rows, conn, short: bool = False) -> dict:
    """B-815: states WHY a Kotak order-book SELL fill happened, with numbers.
    Kotak first: the order's own prcTp/trgPrc/avgPrc and today's completed BUY fill
    (entry) come from the order book. The app's own data only adds the logged
    'reason:' (real_order_events), and the engine's own SL/target levels (swing row,
    then intraday-long row; engine-ownership: a symbol is explained from the table
    that owns it). Returns {kind, reason, remark, entry, sl_level, target_level}."""
    import re as _re
    tsym, oid = o.get("trdSym") or "", str(o.get("nOrdNo"))
    fill = float(o.get("avgPrc") or 0)
    ptype = str(o.get("prcTp", "")).upper()
    try:
        trig = float(o.get("trgPrc") or 0)
    except (TypeError, ValueError):
        trig = 0.0
    try:
        lim = float(o.get("prc") or 0)
    except (TypeError, ValueError):
        lim = 0.0
    entry = sl_level = target_level = None
    engine = None
    # B-817: a short cover is a BUY fill; entry is the day's completed SELL fill, the
    # owning engine is real_positions_short, and pnl sign is mirrored (entry - exit).
    _tbls = ((("real_positions_short", "entry_price, sl_trigger_price, NULL"),) if short else
             (("real_positions_swing", "entry_price, COALESCE(sl_trigger_price, stop_loss), NULL"),
              ("real_positions", "entry_price, sl_trigger_price, target_price")))
    _entry_side = "S" if short else "B"
    for tbl, cols in _tbls:
        try:
            r = conn.execute(f"SELECT {cols} FROM {tbl} WHERE kotak_trading_symbol=?", (tsym,)).fetchone() if tsym else None
        except Exception:
            r = None
        if r:
            engine = "short" if tbl.endswith("short") else ("swing" if tbl.endswith("swing") else "intraday")
            entry = float(r[0]) if r[0] else None
            sl_level = float(r[1]) if r[1] else None
            target_level = float(r[2]) if r[2] else None
            break
    # Kotak wins for entry: today's completed BUY fill for this symbol.
    for b in order_rows or []:
        try:
            if (b.get("trdSym") == tsym and str(b.get("trnsTp", "")).upper() == _entry_side
                    and str(b.get("ordSt", "")).strip().lower() == "complete" and float(b.get("avgPrc") or 0) > 0):
                entry = float(b["avgPrc"])
        except (TypeError, ValueError):
            continue
    reason = None
    ev = conn.execute("SELECT detail FROM real_order_events WHERE order_id=? ORDER BY id DESC LIMIT 1", (oid,)).fetchone()
    if ev and ev[0] and str(ev[0]).startswith("reason:"):
        reason = str(ev[0])[7:].split(";")[0].split(" | ")[0].strip()[:160]
    if not sl_level and tsym:
        for r in conn.execute("SELECT new_state FROM real_order_events WHERE kotak_trading_symbol=? AND leg='sl' "
                              "ORDER BY id DESC LIMIT 5", (tsym,)).fetchall():
            m = _re.search(r"[Rr]s\s?([0-9]+(?:\.[0-9]+)?)", str(r[0] or ""))
            if m:
                sl_level = float(m.group(1))
                break

    def f(x):
        return f"{x:.2f}"
    outcome = None
    if entry:
        pct = ((entry - fill) if short else (fill - entry)) / entry * 100
        outcome = f"{'gain' if pct >= 0 else 'loss'} {abs(pct):.2f}%"
    base = f"fill {f(fill)}" + (f", entry {f(entry)}" if entry else ", entry n/a") + (f", {outcome}" if outcome else "")
    low = (reason or "").lower()
    if ptype in ("SL", "SL-M") and (trig > 0 or sl_level):
        t = trig or sl_level
        trailed = bool(entry and (t < entry if short else t > entry))
        kind = "trailing_stop_triggered_at_kotak" if trailed else "stop_loss_triggered_at_kotak"
        head = ("Trailing stop-loss" if trailed else "Stop-loss") + f" triggered at Kotak (exchange, not an app exit): trigger {f(t)}, {base}"
        if trailed:
            head += " (stop had ratcheted " + ("below" if short else "above") + " entry)"
        if sl_level and abs(sl_level - t) > 0.005:
            head += f"; app SL record {f(sl_level)}"
    elif "square" in low or "3:14" in low or "15:14" in low:
        kind, head = "square_off", f"Intraday square-off {'cover' if short else 'exit'}: {base}"
    elif "target" in low or (ptype == "L" and target_level and abs(fill - target_level) / target_level < 0.005):
        kind = "target_hit"
        tl = target_level or lim
        head = f"Target hit: {base}" + (f", target {f(tl)}" if tl else "")
    elif reason:
        kind, head = "app_exit", f"App exit ({engine or 'engine n/a'}): {base}"
        if sl_level:
            head += f", SL level {f(sl_level)}"
        if target_level:
            head += f", target {f(target_level)}"
    else:
        kind = "unmatched"
        head = (f"Exit fill from Kotak order book, no app log for order {oid}: {base}"
                + (f", SL level {f(sl_level)}" if sl_level else ", SL level n/a"))
    remark = head + (f" | reason: {reason}" if reason else "")
    return {"kind": kind, "reason": reason, "remark": remark, "entry": entry, "sl_level": sl_level,
            "target_level": target_level, "engine": engine}


def _kotak_exit_fills_today(order_rows, closed_symbols, conn) -> list:
    """B-295 part 4: today's exit fills straight from Kotak's order book (fldQty/avgPrc
    of COMPLETE orders, Kotak wins over app data), reason from the app's own order log.
    positions() only reports a fully squared-off round trip, so a swing/CNC holding sold
    today (buy leg is in holdings, not today's positions) never reached the dashboard.
    Rows here cover every completed SELL today whose symbol is NOT already in the
    positions-derived closed trades. B-815: each row carries `exit_remark`, a
    numbers-bearing explanation (see _explain_kotak_exit_fill). pnl is given when an
    entry is known (Kotak's own BUY fill, else the app's row); otherwise None."""
    out, today = [], ist_now().strftime("%d-%b-%Y").lower()
    # B-817: BUY fills count as exits (short covers) only for symbols with a
    # real_positions_short row; long behaviour (SELL only) is unchanged.
    try:
        short_syms = {r[0] for r in conn.execute("SELECT kotak_trading_symbol FROM real_positions_short").fetchall()}
    except Exception:
        short_syms = set()
    for o in order_rows or []:
        try:
            if str(o.get("ordSt", "")).strip().lower() != "complete":
                continue
            tt = str(o.get("trnsTp", "")).upper()
            is_cover = tt == "B" and (o.get("trdSym") or "") in short_syms
            if tt == "S" and (o.get("trdSym") or "") in short_syms:
                continue  # SELL on a short-engine symbol is the short ENTRY, not an exit
            if tt != "S" and not is_cover:
                continue
            if today not in str(o.get("ordDtTm", "")).lower():
                continue
            tsym = o.get("trdSym") or ""
            if tsym in closed_symbols:
                continue
            qty, avg = float(o.get("fldQty") or 0), float(o.get("avgPrc") or 0)
            if qty <= 0 or avg <= 0:
                continue
            ex = _explain_kotak_exit_fill(o, order_rows, conn, short=is_cover)
            entry = ex["entry"]
            exit_reason = ex["reason"] or (ex["kind"] if ex["kind"] != "unmatched" else "kotak_order_book_sell")
            out.append({"symbol": tsym, "order_id": str(o.get("nOrdNo")), "qty": qty, "exit_price_native": avg,
                        "exit_time_ist": o.get("ordDtTm"), "entry_price_native": entry,
                        "pnl_inr": round(((entry - avg) if is_cover else (avg - entry)) * qty, 2) if entry else None,
                        "side": "short" if is_cover else "long",
                        "exit_reason": exit_reason, "exit_remark": ex["remark"], "exit_kind": ex["kind"],
                        "source": "kotak_order_report"})
        except (TypeError, ValueError):
            continue
    return out


@app.get("/real-trades-today")
def get_real_trades_today():
    """Every closed REAL trade today, Kotak's own ground truth - not just
    the aggregate real_pnl_today_inr, and not this app's own real_trades
    table (which only ever logs orders THIS code places, so it has zero
    record of anything traded directly on Kotak - see get_real_pnl_today_inr's
    docstring for the same gap). Explicit user finding (2026-09-07): "i can
    see no trade here, while you know that trade happened today - they why
    not in sync as of now?" - the trade-view Trade Log table only ever
    showed PAPER trades; this is the real-trade equivalent, merged into
    that same table client-side (see trade-view.html's renderTradeLog).

    No token required, same reasoning as /real-pnl-today ("make it without
    any checks") - per-trade symbol/qty/price is more detail than the
    aggregate, but this is still a closed/historical trade list, not
    account state or order IDs (those stay behind /kotak-neo/positions'
    own token gate). Same fully-squared-off filter as get_real_pnl_today_inr
    (flBuyQty == flSellQty, dated today) - an OPEN real position never
    appears here, only completed round trips.

    2026-09-07 (second pass): now reads get_real_trades_today_list()'s
    shared cache instead of its own separate positions() call - one
    Kotak fetch serves this endpoint, get_real_pnl_today_inr, and the
    account-wide daily-loss figure alike, instead of three."""
    trades_raw = get_real_trades_today_list()
    if trades_raw is None:
        return {"error": _real_trades_cache["error"], "trades": []}
    trades = []
    with closing(get_db()) as conn:
        for t in trades_raw:
            # pnl_pct (2026-09-21, explicit user instruction: "I can't see
            # pnL % in each row. Update it") - same convention as the open
            # real positions' own unrealized_pnl_pct (100 * pnl / invested),
            # not a raw price move, so both are directly comparable at a
            # glance.
            #
            # strategy (2026-09-30, explicit user instruction, asked
            # repeatedly: "I want strategy name for all entered trade...
            # without exception"): this endpoint is the WHOLE-ACCOUNT Kotak
            # aggregate and deliberately includes manually-placed trades
            # too (2026-09-07 finding) - a flat "real (Kotak)" for every
            # row was true "we don't distinguish" laziness, not an honest
            # "unknowable." t["symbol"] here is Kotak's OWN trading symbol
            # (trdSym, e.g. "TCS-EQ" - see _refresh_real_trades_cache),
            # already exactly what _recover_strategy_for_untracked_position
            # needs: the SAME real_trades log lookup the open-positions
            # endpoints use, which outlives any tracking row and doesn't
            # care whether the position is still open or already closed.
            # side="B" - every row here is a closed BUY-then-SELL round
            # trip (see _refresh_real_trades_cache's own fl_buy==fl_sell
            # filter), so the entry leg to recover is always a buy. Only a
            # genuinely unrecoverable row (no matching confirmed entry in
            # this app's own order log at all) still shows "real (Kotak)" -
            # an honest "not ours," not a guess.
            strategy = _recover_strategy_for_untracked_position(conn, t["symbol"], "B") or "real (Kotak)"
            invested_inr = (t.get("entry_price_native") or 0) * (t.get("qty") or 0)
            pnl_pct = round(100 * t["pnl_inr"] / invested_inr, 3) if invested_inr else None
            trades.append({
                **t, "pnl_pct_of_capital": None, "pnl_pct": pnl_pct, "exit_reason": "kotak_real_trade",
                "rr_target": None, "rr_achieved": None, "strategy": strategy,
            })
    trades.sort(key=lambda t: t["exit_time_utc"], reverse=True)
    exit_fills = []
    try:
        import kotak_neo
        rep = kotak_neo.order_report()
        rows = (rep.get("data") or []) if isinstance(rep, dict) else []
        with closing(get_db()) as conn:
            exit_fills = _kotak_exit_fills_today(rows, {t["symbol"] for t in trades}, conn)
    except Exception as e:
        print(f"[real-trades-today] exit fills unavailable (non-fatal): {e}")
    return {"date_ist": ist_now().strftime("%Y-%m-%d"), "trades_count": len(trades), "trades": trades,
            "exit_fills_not_in_closed_trades": exit_fills}


@app.get("/real-trades-today-bot-only")
def get_real_trades_today_bot_only():
    """This app's OWN real trading only - both currently-open positions
    and today's closed round-trips - filtered to just the orders THIS
    code itself placed (real_trades/real_positions, tracked by order id),
    unlike /real-trades-today's whole-account Kotak aggregate (which
    deliberately includes manually-placed trades in the same symbol too -
    that was explicit user-requested behavior on 2026-09-07, kept as-is).

    Added 2026-09-08, explicit user request: "add a bot-only real-trade
    view (filtered to just this app's own order IDs, separate from the
    whole-account aggregate) so you have a row that's actually comparable
    to the paper one at a glance" - when a symbol is also traded manually
    outside this app (confirmed live today: AGL), the whole-account
    number and the paper engine's own number are computed from
    unrelated data and were never going to match; THIS view is what
    actually corresponds 1:1 with a single paper decision, since it's
    built from the exact rows _maybe_place_real_entry/_exit themselves
    wrote when mirroring that decision.

    No token required, same reasoning as /real-trades-today and
    /real-pnl-today ("make it without any checks") - real symbol/qty/
    price detail already exposed publicly there; this is the same data,
    just re-filtered and re-shaped.

    closed_trades pairs each day's confirmed BUY with the confirmed SELL
    that follows it for the same symbol, in chronological order - safe
    because this app only ever holds ONE open real position per symbol
    at a time (see real_positions.symbol's PRIMARY KEY), so a B is always
    immediately followed by its own matching S, never interleaved with
    another B for the same symbol before that S. An unmatched trailing
    BUY (position still open) is intentionally left out of closed_trades -
    it's already visible in open_positions instead."""
    today = ist_now().strftime("%Y-%m-%d")
    with closing(get_db()) as conn:
        open_positions = [dict(r) for r in conn.execute("SELECT * FROM real_positions").fetchall()]
        rows = conn.execute(
            "SELECT symbol, kotak_trading_symbol, side, qty, price_est, notional_inr, ts, order_id, strategy "
            "FROM real_trades WHERE day = ? AND status = 'confirmed' ORDER BY symbol, ts",
            (today,),
        ).fetchall()
    closed_trades = []
    open_buy_by_symbol: dict = {}
    for r in rows:
        r = dict(r)
        if r["side"] == "B":
            open_buy_by_symbol[r["symbol"]] = r
        elif r["side"] == "S" and r["symbol"] in open_buy_by_symbol:
            buy = open_buy_by_symbol.pop(r["symbol"])
            qty = r["qty"] or buy["qty"] or 0
            pnl_inr = round((r["price_est"] - buy["price_est"]) * qty, 2) if (
                r["price_est"] is not None and buy["price_est"] is not None) else None
            # invested_inr/pnl_pct (2026-09-21, explicit user instruction:
            # "I can't see pnL % in each row... does not mention which
            # strategy or algo used") - pnl_pct matches the same convention
            # open real positions' own unrealized_pnl_pct already uses
            # (100 * pnl / invested); strategy is the ACTUAL strategy_tag
            # this real entry mirrored (real_trades.strategy, set at entry
            # time by _maybe_place_real_entry from the paper signal), not
            # a generic placeholder - "unknown" only for a real_trades row
            # logged before this column existed.
            invested_inr = (buy["price_est"] or 0) * qty
            pnl_pct = round(100 * pnl_inr / invested_inr, 3) if pnl_inr is not None and invested_inr else None
            closed_trades.append({
                "symbol": r["symbol"], "kotak_trading_symbol": r["kotak_trading_symbol"],
                "entry_price_native": buy["price_est"], "exit_price_native": r["price_est"],
                "qty": qty, "pnl_inr": pnl_inr, "pnl_pct": pnl_pct,
                "entry_order_id": buy["order_id"], "exit_order_id": r["order_id"],
                "entry_time_utc": buy["ts"], "exit_time_utc": r["ts"],
                "strategy": buy.get("strategy") or "unknown",
            })
    closed_trades.sort(key=lambda t: t["exit_time_utc"], reverse=True)
    return {
        "date_ist": today,
        "open_positions": open_positions,
        "closed_trades_count": len(closed_trades),
        "closed_trades": closed_trades,
    }


@app.get("/real-order-log")
def get_real_order_log(days: int = 1):
    """The order STATE-TRANSITION log - explicit user instruction
    2026-09-08: "I want to see the log of what order you have placed and
    from what prev state to what current new order state." Every real
    entry/exit/sl/target state change this app makes gets one row here
    (see _log_real_order_event and real_order_events' own CREATE TABLE
    comment) - this is the raw feed static/order-log.html (GET /order-log)
    renders, newest first.

    days: how many days back to include (default 1 - today only; this
    table is only as durable as the SQLite process it lives in between
    journal-sync snapshots, same caveat as every other real_* table here -
    see docs/real_order_log.json, appended by journal-sync.yml, for the
    permanent record beyond a single Render process's lifetime).

    No token required - same reasoning as /real-trades-today-bot-only:
    this is the same real order data already exposed there, just reshaped
    into a state-transition view."""
    cutoff = time.time() - max(days, 1) * 86400
    with closing(get_db()) as conn:
        rows = conn.execute(
            "SELECT * FROM real_order_events WHERE ts >= ? ORDER BY ts DESC", (cutoff,)
        ).fetchall()
    return {"count": len(rows), "events": [dict(r) for r in rows]}


