_PATTERN_LIVE_CELLS = _load_pattern_live_cells()
_PATTERN_LIVE_TAGS = {c[0]: c for c in _PATTERN_LIVE_CELLS}
for _c in _PATTERN_LIVE_CELLS:
    _STRATEGY_TAG_TO_REGISTRY_NAME.setdefault(_c[0], _c[0])  # PFnet gate resolves each variant to its own registry row
PATTERN_MAX_NEW_PER_DAY = 3
_pattern_lab_mod = None


def _pattern_lab():
    """Loads scripts/pattern_lab.py (the backtest's own rule code) once, with its default 1d env."""
    global _pattern_lab_mod
    if _pattern_lab_mod is None:
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "pattern_lab_live", os.path.join(os.path.dirname(os.path.abspath(__file__)), "scripts", "pattern_lab.py"))
        mod = importlib.util.module_from_spec(spec)
        _prev_uni = os.environ.get("UNI")
        os.environ["UNI"] = "n200"  # volume-profile rules exist only for the live universe; the backtests ran with UNI=n200
        try:
            spec.loader.exec_module(mod)
        finally:
            if _prev_uni is None:
                os.environ.pop("UNI", None)
            else:
                os.environ["UNI"] = _prev_uni
        _pattern_lab_mod = mod
    return _pattern_lab_mod


def pattern_fresh_long_signals(df) -> dict:
    """{rule_key: bool} - is the LONG signal true on the last bar of df (cleaned like the backtest)."""
    pl = _pattern_lab()
    d = pl.clean_bars(df[["Open", "High", "Low", "Close", "Volume"]].dropna())
    if len(d) < 120:
        return {}
    sigs = pl.all_signals(d)
    sigs = {**sigs, **{k.replace("__", "_"): v for k, v in sigs.items()}}  # tags collapse '__' inside rule names
    out = {}
    for rule in {c[1] for c in _PATTERN_LIVE_CELLS}:
        if "&" in rule:  # trigger & filter-within-3-bars, exactly combo_lab's pairing
            a, b = rule.split("&")
            if a in sigs and b in sigs:
                out[rule] = bool((np.asarray(sigs[a][0], bool) & pl.near_helper(np.asarray(sigs[b][0], bool)))[-1]) if hasattr(pl, "near_helper") else bool(
                    np.asarray(sigs[a][0], bool)[-1] and np.asarray(sigs[b][0], bool)[-3:].any())
        elif rule in sigs:
            out[rule] = bool(np.asarray(sigs[rule][0], bool)[-1])
    return out


def pattern_cell_exit_reason(df, entry_day: str, initial_stop: float, hold_days: int):
    if len(df) == 0:
        return None
    if float(df["Close"].iloc[-1]) <= float(initial_stop):
        return "stop_hit"
    if int(np.sum(df["Date"].astype(str).to_numpy() > entry_day)) >= hold_days:
        return "max_hold_timeout"
    return None


def _run_pattern_cell_entries(conn, dfs: dict, capital, today: str):
    for c in _PATTERN_LIVE_CELLS:
        _record_strategy_scan(c[0])
    risk_pct = NSE_STOCK_DEFAULT_PARAMS["risk_pct"]
    opened = 0
    # Rank today's candidates by the quality (list position = PFnet order) of the best cell each symbol matches, so the
    # per-day cap goes to the strongest signals, not to whichever symbols happen to be scanned first.
    ranked = []
    fresh_by_sym = {}
    for sym, df in _scan_visit_items(dfs.items()):
        for _c in _PATTERN_LIVE_CELLS:  # B-1274 stage 2: per-symbol marks (counter bumped once per pass above)
            if ("_etf__" in _c[0]) == (sym in ETF_SYMBOLS):
                _record_symbol_strategy_scan(_c[0])
        if conn.execute("SELECT 1 FROM signal_state_swing WHERE symbol = ?", (sym,)).fetchone():
            try:  # B-1275: held symbol still gets its triggers evaluated (scan-only); a second entry stays blocked
                pattern_fresh_long_signals(df)
            except Exception:
                pass
            continue  # one swing position per symbol
        try:
            fresh_by_sym[sym] = pattern_fresh_long_signals(df)
        except Exception as e:
            print(f"[PATTERN] signal eval failed for {sym}: {e}")
            continue
        _etf_sym = sym in ETF_SYMBOLS
        for _i, (_tag, _rule, _h, _k) in enumerate(_PATTERN_LIVE_CELLS):
            if fresh_by_sym[sym].get(_rule) and ("_etf__" in _tag) == _etf_sym:
                ranked.append((_i, sym))
                break
    for _rank, sym in sorted(ranked):
        df = dfs[sym]
        if opened >= PATTERN_MAX_NEW_PER_DAY:
            break
        is_etf = sym in ETF_SYMBOLS
        fresh = fresh_by_sym[sym]
        for tag, rule, hold, k in _PATTERN_LIVE_CELLS:  # first matching cell wins (listed best-first)
            if not fresh.get(rule) or ("_etf__" in tag) != is_etf:  # stock cells for stocks, ETF cells for ETFs only
                continue
            entry_price = float(df["Close"].iloc[-1])
            atr_v = _compute_atr_value(df, 14)
            if not atr_v or atr_v <= 0:
                break
            stop_loss = entry_price - k * atr_v
            qty = _swing_position_size(conn, capital, risk_pct, entry_price, stop_loss)
            if qty <= 0:
                break
            conn.execute(
                "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, "
                "initial_stop_loss, gap_low, qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (sym, tag, today, entry_price, stop_loss, None, qty, time.time(), 1.0, float(atr_v), entry_price),
            )
            apply_paper_trade(conn, sym, "buy", qty, entry_price)
            conn.execute(
                "INSERT INTO trades (ts, symbol, action, qty, price, fx_to_inr, strategy, raw_payload) "
                "VALUES (?, ?, 'buy', ?, ?, ?, ?, ?)",
                (time.time(), sym, qty, entry_price, 1.0, SWING_STRATEGY_TAG,
                 json.dumps({"entry_reason": tag, "stop_loss": stop_loss, "atr_at_entry": float(atr_v)})),
            )
            conn.commit()
            opened += 1
            print(f"[SWING] entry {sym} ({tag}) qty={qty} @ {entry_price:.2f} stop={stop_loss:.2f}")
            try:
                _maybe_place_real_swing_entry(conn, sym, qty, entry_price, stop_loss, tag)
            except Exception as e:
                print(f"[REAL SWING] entry mirror failed for {sym} (non-fatal, paper entry already recorded): {e}")
            break


_swing_sl_trail_last_day = None


def _swing_strategy_stop_level(strategy, initial_stop, atr_at_entry, running_max_close):
    """The stop a swing position's OWN strategy exit rule is currently using:
    chandelier strategies = max(initial stop, peak close - mult x frozen ATR)
    (same arithmetic as minervini_vcp_exit_reason & co.); gap_and_go (and any
    unknown tag) = its frozen initial stop. Pure; never guesses a multiplier
    for an unrecognised strategy."""
    mult = {
        "minervini_vcp": MINERVINI_ATR_STOP_MULT,
        "minervini_vcp_livermore": MINERVINI_ATR_STOP_MULT,
        "primary_base": MINERVINI_ATR_STOP_MULT,
        "power_play": POWER_PLAY_ATR_STOP_MULT,
        "order_block_delta": ORDER_BLOCK_ATR_TRAIL_MULT,
        "volume_profile_poc": VP_ATR_TRAIL_MULT,
        ORPHAN_SWING_STRATEGY_TAG: ORPHAN_SWING_TRAIL_R_MULT,  # atr_at_entry holds R for this tag
    }.get(strategy)
    if mult is None or not atr_at_entry or running_max_close is None:
        return float(initial_stop)
    return max(float(initial_stop), float(running_max_close) - mult * float(atr_at_entry))


def _log_sl_fills_from_kotak(conn, order_rows) -> int:
    """B-1285 part 1: a stop-loss that executes at Kotak leaves no 'B' real_trades row, so win % never
    counted SL closes. Kotak's order book is ground truth: every COMPLETE order whose nOrdNo is a resting
    SL this app logged (real_order_events leg in sl/short_sl, event placed/moved) gets ONE
    leg='sl', event='filled' row (new_state 'filled @ Rs<avgPrc>', trnsTp in detail), idempotent per
    order id. The per-tag win-rate reader derives closed SL trades from these rows."""
    n = 0
    try:
        sl_ids = {str(r[0]) for r in conn.execute(
            "SELECT order_id FROM real_order_events WHERE leg IN ('sl','short_sl') AND event IN ('placed','moved') "
            "AND order_id IS NOT NULL").fetchall()}
        done = {str(r[0]) for r in conn.execute(
            "SELECT order_id FROM real_order_events WHERE leg='sl' AND event='filled' AND order_id IS NOT NULL").fetchall()}
        for row in order_rows or []:
            oid = str(row.get("nOrdNo") or "")
            if not oid or oid not in sl_ids or oid in done:
                continue
            if str(row.get("ordSt", "")).strip().lower() != "complete":
                continue
            try:
                avg = float(row.get("avgPrc") or 0)
            except (TypeError, ValueError):
                continue
            if avg <= 0:
                continue
            tsym = row.get("trdSym") or ""
            conn.execute(
                "INSERT INTO real_order_events (ts, symbol, kotak_trading_symbol, leg, event, order_id, "
                "prev_state, new_state, detail) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (time.time(), tsym.rsplit("-", 1)[0] + ".NS" if tsym else None, tsym, "sl", "filled", oid,
                 "resting", f"filled @ Rs{avg:.2f}",
                 f"reason: stop-loss executed at Kotak (counted in win %) | trnsTp={row.get('trnsTp','')} qty={row.get('qty','')}"))
            done.add(oid)
            n += 1
        if n:
            conn.commit()
            sync_generic_tables_external(only=("real_order_events",))
    except Exception as e:
        print(f"[order_log] SL-fill logging failed (non-fatal): {e}")
    return n


def _sl_fills_today(conn, since_ts) -> list:
    """(symbol, fill_price, trnsTp) for each SL fill row logged since since_ts, oldest first."""
    import re as _re2
    out = []
    for r in conn.execute("SELECT symbol, new_state, detail FROM real_order_events WHERE leg='sl' AND event='filled' "
                          "AND ts >= ? ORDER BY ts", (since_ts,)).fetchall():
        m = _re2.search(r"Rs\s?([0-9]+(?:\.[0-9]+)?)", str(r[1] or ""))
        if m and r[0]:
            out.append((r[0], float(m.group(1)), "S" if "trnsTp=S" in str(r[2] or "") else "B"))
    return out


def _log_unlogged_kotak_orders(conn, order_rows) -> int:
    """B-307: Kotak's order book is ground truth, so every order in it must have an
    app log row (reason rule). Any Kotak order whose nOrdNo has no real_order_events
    row (an order this app placed but failed to log, a cancel made on a path that
    logs nothing, or a manual order) gets a `kotak_order_not_in_app_log` row built
    from Kotak's own fields, so the log can never silently miss an order. Runs every
    5-min reconcile; idempotent (the new row carries the order id)."""
    n = 0
    try:
        known = {r[0] for r in conn.execute("SELECT order_id FROM real_order_events WHERE order_id IS NOT NULL").fetchall()}
        for row in order_rows or []:
            oid = str(row.get("nOrdNo") or "")
            if not oid or oid in known:
                continue
            tsym = row.get("trdSym") or ""
            detail = (f"reason: UNLOGGED - no app log row for this Kotak order (placed outside a logging path or "
                      f"manually); Kotak facts: {row.get('ordDtTm','')} {row.get('trnsTp','')} {row.get('prcTp','')} "
                      f"qty {row.get('qty','')} trg {row.get('trgPrc','')} status {row.get('ordSt','')} "
                      f"rejRsn {str(row.get('rejRsn') or '')[:120]}")
            conn.execute(
                "INSERT INTO real_order_events (ts, symbol, kotak_trading_symbol, leg, event, order_id, "
                "prev_state, new_state, detail) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (time.time(), tsym.rsplit("-", 1)[0] + ".NS" if tsym else None, tsym, "kotak",
                 "kotak_order_not_in_app_log", oid, None, str(row.get("ordSt") or ""), detail))
            known.add(oid)
            n += 1
        if n:
            conn.commit()
            sync_generic_tables_external(only=("real_order_events",))
    except Exception as e:
        print(f"[order_log] unlogged-kotak-orders check failed (non-fatal): {e}")
    return n


def _align_entry_prices_to_kotak(conn, order_rows) -> list:
    """B-295 audit part 2 (Kotak-is-truth): a real position's entry_price must be the
    price Kotak actually filled its entry order at. The row can hold the pre-trade
    LTP estimate when the fill was not yet reported at entry time. For every row
    (intraday long, short, swing) whose entry_order_id is a COMPLETE order in Kotak's
    order book with a positive avgPrc, entry_price is rewritten to that avgPrc.
    Rows with no entry_order_id, or whose entry order is not complete/listed, are left
    untouched (never guessed). An empty order book changes nothing."""
    if not order_rows:
        return []
    by_id = {str(o.get("nOrdNo")): o for o in order_rows if o.get("nOrdNo") is not None}
    out = []
    for table in ("real_positions", "real_positions_short", "real_positions_swing"):
        for r in conn.execute(f"SELECT symbol, entry_order_id, entry_price FROM {table} "
                              "WHERE entry_order_id IS NOT NULL").fetchall():
            o = by_id.get(str(r["entry_order_id"]))
            if not o or str(o.get("ordSt", "")).strip().lower() != "complete":
                continue
            try:
                avg = float(o.get("avgPrc"))
            except (TypeError, ValueError):
                continue
            if avg <= 0:
                continue
            if r["entry_price"] is None or abs(float(r["entry_price"]) - avg) > 0.005:
                conn.execute(f"UPDATE {table} SET entry_price = ? WHERE symbol = ?", (avg, r["symbol"]))
                out.append({"symbol": r["symbol"], "table": table, "action": "entry_price_aligned_to_kotak",
                            "was": r["entry_price"], "now": avg})
    # F&O legs (B-295 F&O rows): entry_price is the pre-trade premium estimate.
    for r in conn.execute("SELECT leg_key, entry_order_id, entry_price FROM real_fo_positions "
                          "WHERE entry_order_id IS NOT NULL").fetchall():
        o = by_id.get(str(r["entry_order_id"]))
        if not o or str(o.get("ordSt", "")).strip().lower() != "complete":
            continue
        try:
            avg = float(o.get("avgPrc"))
        except (TypeError, ValueError):
            continue
        if avg > 0 and (r["entry_price"] is None or abs(float(r["entry_price"]) - avg) > 0.005):
            conn.execute("UPDATE real_fo_positions SET entry_price = ? WHERE leg_key = ?", (avg, r["leg_key"]))
            out.append({"symbol": r["leg_key"], "table": "real_fo_positions",
                        "action": "entry_price_aligned_to_kotak", "was": r["entry_price"], "now": avg})
    if out:
        conn.commit()
        _sync_real_positions_external(conn)
        _sync_real_positions_short_external(conn)
        _sync_real_positions_swing_external(conn)
        for a in out:
            _log_real_order_event(
                conn, a["symbol"], "entry", a["action"], new_state=str(a["now"]),
                prev_state=str(a["was"]),
                reason="Kotak fill price (avgPrc of the entry order) is ground truth; app entry price rewritten to match")
    return out


def _align_intraday_sl_rows_to_kotak(conn, order_rows) -> list:
    """B-295 audit, Kotak-is-truth for the intraday LONG (real_positions) and SHORT
    (real_positions_short) tables, same rule as _align_swing_sl_rows_to_kotak: a live
    resting SL at Kotak (SELL for longs, BUY for shorts) is adopted into the row
    (sl_order_id/sl_trigger_price); the tighter trigger wins (highest for longs,
    lowest for shorts). Deliberately more conservative than the swing version on the
    clear side: a stored sl_order_id is cleared only when Kotak lists THAT order in a
    terminal state - an id merely absent from the book may be order-report lag right
    after placement, and clearing it would trigger a duplicate SL. An empty order book
    changes nothing."""
    if not order_rows:
        return []
    terminal = ("complete", "rejected", "cancelled", "cancelled by user", "cancelledbyuser", "expired")
    out = []
    for table, side, pick in (("real_positions", "S", max), ("real_positions_short", "B", min)):
        for r in conn.execute(f"SELECT * FROM {table}").fetchall():
            live, stored_state = [], None
            for o in order_rows:
                if o.get("trdSym") != r["kotak_trading_symbol"]:
                    continue
                if str(o.get("nOrdNo")) == str(r["sl_order_id"]):
                    stored_state = str(o.get("ordSt", "")).strip().lower()
                if o.get("trnsTp") != side or str(o.get("prcTp", "")).upper() not in ("SL", "SL-M"):
                    continue
                if str(o.get("ordSt", "")).strip().lower() in terminal:
                    continue
                try:
                    live.append((float(o.get("trgPrc") or 0), str(o.get("nOrdNo"))))
                except (TypeError, ValueError):
                    continue
            if live:
                trg, oid = pick(live)
                cur = r["sl_trigger_price"]
                if r["sl_order_id"] != oid or cur is None or abs(float(cur) - trg) > 0.005:
                    conn.execute(f"UPDATE {table} SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
                                 (oid, trg, r["symbol"]))
                    out.append({"symbol": r["symbol"], "table": table, "action": "aligned_to_kotak",
                                "order_id": oid, "trigger": trg})
            elif r["sl_order_id"] and stored_state in terminal:
                conn.execute(f"UPDATE {table} SET sl_order_id = NULL WHERE symbol = ?", (r["symbol"],))
                out.append({"symbol": r["symbol"], "table": table, "action": "cleared_sl_terminal_at_kotak"})
    if out:
        conn.commit()
        _sync_real_positions_external(conn)
        _sync_real_positions_short_external(conn)
        for a in out:
            _log_real_order_event(
                conn, a["symbol"], "sl", a["action"], new_state=str(a.get("trigger", "none")),
                reason="Kotak order book is ground truth; this app's intraday SL record was rewritten to match it")
    return out


def _align_intraday_target_to_kotak(conn, order_rows) -> list:
    """B-295 audit part 3 (Kotak-is-truth): the intraday LONG row's target_order_id /
    target_price must match the live resting SELL LIMIT at Kotak. A live SELL limit
    (prcTp L) on the symbol is adopted (id + price; the lowest price wins, i.e. the
    nearest target). A stored target_order_id is cleared only when Kotak lists THAT
    order in a terminal state (an id merely absent may be order-report lag). An empty
    order book changes nothing."""
    if not order_rows:
        return []
    terminal = ("complete", "rejected", "cancelled", "cancelled by user", "cancelledbyuser", "expired")
    out = []
    for r in conn.execute("SELECT * FROM real_positions").fetchall():
        live, stored_state = [], None
        for o in order_rows:
            if o.get("trdSym") != r["kotak_trading_symbol"]:
                continue
            st = str(o.get("ordSt", "")).strip().lower()
            if r["target_order_id"] and str(o.get("nOrdNo")) == str(r["target_order_id"]):
                stored_state = st
            if o.get("trnsTp") != "S" or str(o.get("prcTp", "")).upper() != "L" or st in terminal:
                continue
            try:
                live.append((float(o.get("prc") or 0), str(o.get("nOrdNo"))))
            except (TypeError, ValueError):
                continue
        live = [x for x in live if x[0] > 0]
        if live:
            prc, oid = min(live)
            cur = r["target_price"]
            if r["target_order_id"] != oid or cur is None or abs(float(cur) - prc) > 0.005:
                conn.execute("UPDATE real_positions SET target_order_id = ?, target_price = ? WHERE symbol = ?",
                             (oid, prc, r["symbol"]))
                out.append({"symbol": r["symbol"], "action": "target_aligned_to_kotak", "order_id": oid, "price": prc})
        elif r["target_order_id"] and stored_state in terminal:
            conn.execute("UPDATE real_positions SET target_order_id = NULL WHERE symbol = ?", (r["symbol"],))
            out.append({"symbol": r["symbol"], "action": "target_cleared_terminal_at_kotak"})
    if out:
        conn.commit()
        _sync_real_positions_external(conn)
        for a in out:
            _log_real_order_event(
                conn, a["symbol"], "target", a["action"], new_state=str(a.get("price", "none")),
                reason="Kotak order book is ground truth; this app's intraday target record was rewritten to match it")
    return out


def _align_swing_sl_rows_to_kotak(conn, order_rows) -> list:
    """Kotak-is-truth alignment (2026-10-07 thumb rule): wherever Kotak's own order
    book and this app's real_positions_swing row disagree about the resting SL, the
    ROW is rewritten to match Kotak, never the reverse. Live SELL SL on the symbol
    -> row's sl_order_id/sl_trigger_price become that order's id/trigger (highest
    trigger wins); no live SL but the row claims one -> sl_order_id cleared so the
    backfill re-places it. An empty/unreadable order book changes nothing."""
    if not order_rows:
        return []
    out = []
    for r in conn.execute("SELECT * FROM real_positions_swing").fetchall():
        live = []
        for o in order_rows:
            if o.get("trdSym") != r["kotak_trading_symbol"] or o.get("trnsTp") != "S":
                continue
            if str(o.get("prcTp", "")).upper() not in ("SL", "SL-M"):
                continue
            if str(o.get("ordSt", "")).strip().lower() in ("complete", "rejected", "cancelled", "cancelled by user", "cancelledbyuser", "expired"):
                continue
            try:
                live.append((float(o.get("trgPrc") or 0), str(o.get("nOrdNo"))))
            except (TypeError, ValueError):
                continue
        if live:
            trg, oid = max(live)
            cur = r["sl_trigger_price"]
            if r["sl_order_id"] != oid or cur is None or abs(float(cur) - trg) > 0.005:
                conn.execute("UPDATE real_positions_swing SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
                             (oid, trg, r["symbol"]))
                out.append({"symbol": r["symbol"], "action": "aligned_to_kotak", "order_id": oid, "trigger": trg})
        elif r["sl_order_id"]:
            conn.execute("UPDATE real_positions_swing SET sl_order_id = NULL WHERE symbol = ?", (r["symbol"],))
            out.append({"symbol": r["symbol"], "action": "cleared_no_live_sl_at_kotak"})
    if out:
        conn.commit()
        _sync_real_positions_swing_external(conn)
        for a in out:
            _log_real_order_event(
                conn, a["symbol"], "sl", a["action"], new_state=str(a.get("trigger", "none")),
                reason="Kotak order book is ground truth; this app's swing SL record was rewritten to match it")
    return out


def _sync_swing_resting_sl_to_strategy(conn):
    """Daily (2026-10-06, explicit user instruction): move each open real
    swing position's RESTING Kotak stop to the level its own strategy's exit
    rule now implies, ratcheting UP only. Place-new-then-cancel-old so the
    position is never unprotected; a rejected new order leaves the old SL in
    place. Not gated by is_real_swing_trading_enabled (protection of an
    already-open position is never switched off). Returns a list of actions."""
    import kotak_real_orders
    actions = []
    for r in conn.execute("SELECT * FROM real_positions_swing WHERE sl_order_id IS NOT NULL").fetchall():
        st = conn.execute("SELECT * FROM signal_state_swing WHERE symbol = ?", (r["symbol"],)).fetchone()
        if not st:
            continue
        target = round(_swing_strategy_stop_level(
            st["strategy"], st["initial_stop_loss"], st["atr_at_entry"], st["running_max_close"]), 2)
        current = float(r["sl_trigger_price"] or r["stop_loss"])
        if target <= current + 0.05:
            continue
        res = kotak_real_orders.ensure_resting_sl(r["kotak_trading_symbol"], r["qty"], target)
        if not res.get("ok"):
            print(f"[REAL SWING] SL trail to {target} failed for {r['kotak_trading_symbol']} "
                  f"({res.get('detail')}) - action {res.get('action')}")
            if res.get("restored_order_id"):
                # old stop was cancelled for the replace and then re-placed: re-point the row at it
                conn.execute("UPDATE real_positions_swing SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
                             (res["restored_order_id"], res["restored_trigger"], r["symbol"]))
                conn.commit()
                _sync_real_positions_swing_external(conn)
            _log_real_order_event(
                conn, r["symbol"], "sl", "trail_failed", kotak_trading_symbol=r["kotak_trading_symbol"],
                prev_state=f"resting SELL trigger Rs{current:.2f}",
                new_state="old stop re-placed" if res.get("restored_order_id") else "unchanged/unknown",
                detail=str(res.get("detail"))[:200],
                reason=f"{st['strategy']} trail wanted Rs{target:.2f} but the replace failed",
            )
            actions.append({"symbol": r["symbol"], "ok": False, "target": target})
            continue
        conn.execute("UPDATE real_positions_swing SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
                     (res["order_id"], res["trigger_price"], r["symbol"]))
        conn.commit()
        _sync_real_positions_swing_external(conn)
        _log_real_order_event(
            conn, r["symbol"], "sl", "adopted" if res.get("action") == "adopted_existing" else "trailed",
            kotak_trading_symbol=r["kotak_trading_symbol"],
            order_id=res["order_id"], prev_state=f"resting SELL trigger Rs{current:.2f}",
            new_state=f"resting SELL trigger Rs{res['trigger_price']:.2f}",
            detail=f"daily {st['strategy']} stop ratchet ({res.get('action')}; Kotak order book scanned first)",
            reason=f"{st['strategy']} trail rule raised the stop from Rs{current:.2f} to Rs{res['trigger_price']:.2f}",
        )
        actions.append({"symbol": r["symbol"], "ok": True, "from": current, "to": res["trigger_price"]})
    return actions


# --- 2026-10-07 (B-294): LTP-peak trail for rerouted orphans + gap_and_go state for NYKAA ---
SWING_LTP_TRAIL_EVERY_N_TICKS = 10  # ~5 min at the 30s tick, same cadence as the backcheck
SWING_LTP_TRAIL_SYMBOLS = ("RVNL.NS", "DRREDDY.NS")  # user, 2026-10-07: these two trail 1R off the peak live price


def _swing_live_ltp_peak(symbol: str) -> tuple[float | None, float | None]:
    """(latest price, highest 1-minute close today) from the freshest 1m bars.
    The peak is a max over 1m closes polled every ~5 min, so it can understate
    a sub-minute spike - it never overstates the price actually traded."""
    try:
        df = fetch_ohlc(symbol, "1d", "1m")
        if df is None or len(df) == 0:
            return None, None
        closes = df["Close"].astype(float)
        return float(closes.iloc[-1]), float(closes.max())
    except Exception as e:
        print(f"[SWING LTP TRAIL] price fetch failed for {symbol}: {e}")
        return None, None


def _ltp_trail_stop(peak_ltp: float, r: float, initial_stop: float) -> float:
    """Stop = peak live LTP - 1R (R = atr_at_entry for the orphan tag); never
    below the carried initial stop. Pure; ratchet-up is enforced by the caller
    (only raises, never lowers, the resting SL)."""
    return round(max(float(initial_stop), float(peak_ltp) - ORPHAN_SWING_TRAIL_R_MULT * float(r)), 2)


def _sync_swing_ltp_trail(conn) -> list:
    """RVNL/DRREDDY (rerouted orphan swing rows): trail the REAL resting SL to
    peak live LTP - 1R, ratchet up only (user, 2026-10-07). Follows the thumb
    rule sequence: Kotak holdings+positions first, then the Kotak order book
    (ensure_resting_sl scans it before placing/replacing), only then the DB.
    Intraday cadence, market hours only, never lowers a stop, logs the reason."""
    if not _nse_equity_market_open_now():
        return []
    import kotak_real_orders
    held = _kotak_holdings_open_by_trdsym()
    if held is None:
        return []  # unknown is not "not held" - skip this pass
    actions = []
    # 2026-10-07: DRREDDY's row was relabelled volume_profile_poc after its reroute, so
    # select by the user's named symbols as well as by the orphan tag.
    _trail_rows = conn.execute(
        "SELECT * FROM real_positions_swing WHERE strategy = ? OR symbol IN (%s)" % ",".join("?" * len(SWING_LTP_TRAIL_SYMBOLS)),
        (ORPHAN_SWING_STRATEGY_TAG, *SWING_LTP_TRAIL_SYMBOLS)).fetchall()
    for r in _trail_rows:
        if r["kotak_trading_symbol"] not in held and _kotak_symbol_still_open(r["kotak_trading_symbol"]) is not True:
            continue
        st = conn.execute("SELECT * FROM signal_state_swing WHERE symbol = ?", (r["symbol"],)).fetchone()
        if not st:
            continue
        r_unit = float(st["entry_price"]) - float(st["initial_stop_loss"])  # 1R = entry - initial stop
        if r_unit <= 0:
            continue
        ltp, day_peak = _swing_live_ltp_peak(r["symbol"])
        if ltp is None:
            continue
        prev = conn.execute("SELECT peak_ltp FROM swing_ltp_peak WHERE symbol = ?", (r["symbol"],)).fetchone()
        peak = max(float(prev["peak_ltp"]) if prev else float(st["entry_price"]), day_peak, ltp)
        conn.execute("INSERT INTO swing_ltp_peak (symbol, peak_ltp, updated_at) VALUES (?, ?, ?) "
                     "ON CONFLICT(symbol) DO UPDATE SET peak_ltp = excluded.peak_ltp, updated_at = excluded.updated_at",
                     (r["symbol"], peak, time.time()))
        conn.commit()
        target = _ltp_trail_stop(peak, r_unit, st["initial_stop_loss"])
        current = float(r["sl_trigger_price"] or r["stop_loss"])
        if target <= current + 0.05 or target >= ltp:
            continue  # ratchet up only; a stop at/above the live price would just fire
        res = kotak_real_orders.ensure_resting_sl(r["kotak_trading_symbol"], r["qty"], target)
        if not res.get("ok"):
            _log_real_order_event(
                conn, r["symbol"], "sl", "trail_failed", kotak_trading_symbol=r["kotak_trading_symbol"],
                prev_state=f"resting SELL trigger Rs{current:.2f}", new_state="unchanged/unknown",
                detail=str(res.get("detail"))[:200],
                reason=f"LTP trail wanted Rs{target:.2f} (peak Rs{peak:.2f} - 1R) but the replace failed")
            if res.get("restored_order_id"):
                conn.execute("UPDATE real_positions_swing SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
                             (res["restored_order_id"], res["restored_trigger"], r["symbol"]))
                conn.commit()
                _sync_real_positions_swing_external(conn)
            actions.append({"symbol": r["symbol"], "ok": False, "target": target})
            continue
        conn.execute("UPDATE real_positions_swing SET sl_order_id = ?, sl_trigger_price = ? WHERE symbol = ?",
                     (res["order_id"], res["trigger_price"], r["symbol"]))
        conn.commit()
        _sync_real_positions_swing_external(conn)
        _log_real_order_event(
            conn, r["symbol"], "sl", "trailed", kotak_trading_symbol=r["kotak_trading_symbol"],
            order_id=res["order_id"], prev_state=f"resting SELL trigger Rs{current:.2f}",
            new_state=f"resting SELL trigger Rs{res['trigger_price']:.2f}",
            detail=f"LTP trail ({res.get('action')}; Kotak holdings and order book read first)",
            reason=f"peak live price Rs{peak:.2f} - 1R (Rs{r_unit:.2f}) raised the stop from Rs{current:.2f}")
        actions.append({"symbol": r["symbol"], "ok": True, "from": current, "to": res["trigger_price"]})
    return actions


def _derive_gap_and_go_state(df, avg_price: float, lookback: int = 40):
    """Find the daily bar on which gap_and_go_entry_signal fires with a close
    within 3% of this holding's real average price, looking back `lookback`
    bars. Returns {entry_day, entry_price, stop_loss, gap_low} or None. Uses the
    real signal function; never invents a gap low."""
    n = len(df)
    for k in range(n - 1, max(n - 1 - lookback, 40), -1):
        sig = gap_and_go_entry_signal(df.iloc[:k + 1].reset_index(drop=True))
        if sig and abs(sig["entry_price"] - avg_price) / avg_price <= 0.03:
            return {"entry_day": str(df["Date"].iloc[k])[:10], "entry_price": float(sig["entry_price"]),
                    "stop_loss": float(sig["stop_loss"]), "gap_low": float(sig["gap_low"])}
    return None


GAP_AND_GO_ADOPTED_SYMBOLS = ("NYKAA.NS",)  # user, 2026-10-07: "NYKAA follows exit strategy of gap and go"
_gap_and_go_state_last_day = None


def _ensure_gap_and_go_state_for_held(conn) -> list:
    """NYKAA is a held delivery position entered as gap_and_go, but a restart/heal
    left it with a real_positions_swing row and NO signal_state_swing row, so no
    gap_and_go exit rule ever ran for it (and the swing exit then misread it).
    Re-create the paper state from the real signal function on its daily bars:
    stop_hit (close <= entry - 2.5 ATR14), gap_filled (close < gap low),
    max_hold_timeout (30 trading days), no trail. If the gap bar cannot be
    derived honestly, nothing is invented: it is logged and the ATR-stop heal
    keeps protecting the position."""
    global _gap_and_go_state_last_day
    today = ist_now().strftime("%Y-%m-%d")
    if _gap_and_go_state_last_day == today:
        return []
    out = []
    for sym in GAP_AND_GO_ADOPTED_SYMBOLS:
        row = conn.execute("SELECT * FROM real_positions_swing WHERE symbol = ?", (sym,)).fetchone()
        if not row or conn.execute("SELECT 1 FROM signal_state_swing WHERE symbol = ?", (sym,)).fetchone():
            continue
        held = _kotak_holdings_open_by_trdsym()
        if held is None or row["kotak_trading_symbol"] not in held:
            continue
        try:
            df = fetch_ohlc(sym, "1y", "1d")
            df = df.reset_index() if "Date" not in df.columns else df
            d = _derive_gap_and_go_state(df, float(held[row["kotak_trading_symbol"]]["avg_price"] or row["entry_price"]))
        except Exception as e:
            print(f"[SWING] gap_and_go state derivation failed for {sym}: {e}")
            continue
        if not d:
            _log_real_order_event(
                conn, sym, "reroute", "gap_and_go_state_not_derivable", kotak_trading_symbol=row["kotak_trading_symbol"],
                new_state="no gap_and_go signal bar near the average price",
                reason="could not honestly derive the gap low; ATR-stop protection stays, no gap_and_go exits")
            out.append({"symbol": sym, "derived": False})
            continue
        conn.execute(
            "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, initial_stop_loss, gap_low, "
            "qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) VALUES (?, 'gap_and_go', ?, ?, ?, ?, ?, ?, 1.0, NULL, NULL) "
            "ON CONFLICT(symbol) DO NOTHING",
            (sym, d["entry_day"], d["entry_price"], d["stop_loss"], d["gap_low"], row["qty"], row["opened_at"] or time.time()))
        conn.execute("UPDATE real_positions_swing SET strategy = 'gap_and_go' WHERE symbol = ?", (sym,))
        if not conn.execute("SELECT 1 FROM positions WHERE symbol = ? AND qty > 0", (sym,)).fetchone():
            apply_paper_trade(conn, sym, "buy", row["qty"], d["entry_price"])  # so the paper exit has a position to close
        conn.commit()
        _sync_signal_state_swing_external(conn)
        _sync_real_positions_swing_external(conn)
        _log_real_order_event(
            conn, sym, "reroute", "gap_and_go_state_restored", kotak_trading_symbol=row["kotak_trading_symbol"],
            new_state=f"entry {d['entry_day']} @ Rs{d['entry_price']:.2f}, stop Rs{d['stop_loss']:.2f}, gap low Rs{d['gap_low']:.2f}",
            reason="user: NYKAA follows gap_and_go exit rules; paper state re-derived from the real signal on daily bars")
        out.append({"symbol": sym, "derived": True, **d})
    _gap_and_go_state_last_day = today
    return out


_ob_state_last_day = None


def _ensure_order_block_state_for_held(conn) -> list:
    """B-1364 (2026-10-26): BANKINDIA/UNIONBANK/COALINDIA are real order_block_delta holdings whose signal_state_swing
    rows were lost (unguarded Upstash mirror push after a restart), so their chandelier trail/max-hold exit never ran
    ('retry_refused_no_paper_exit'). Re-derive the exit state honestly from daily bars: entry_day/entry_price from the
    real row, initial stop = the entry-day stop (swing_entry_stop) or the row's stop, ATR14 frozen at the entry day
    (same _compute_atr_value the entry signal uses), running max close since entry. Once per IST day; never places
    an order itself."""
    global _ob_state_last_day
    today = ist_now().strftime("%Y-%m-%d")
    if _ob_state_last_day == today:
        return []
    out = []
    for row in conn.execute("SELECT * FROM real_positions_swing WHERE strategy = 'order_block_delta'").fetchall():
        sym = row["symbol"]
        if conn.execute("SELECT 1 FROM signal_state_swing WHERE symbol = ?", (sym,)).fetchone():
            continue
        try:
            df = fetch_ohlc(sym, "1y", "1d")
            df = df.reset_index() if "Date" not in df.columns else df
            dates = df["Date"].astype(str).str[:10]
            upto = df[dates <= row["day"]]
            atr = _compute_atr_value(upto, 14) if len(upto) > 20 else None
            since = df[dates >= row["day"]]
            run_max = float(since["Close"].max()) if len(since) else float(row["entry_price"])
        except Exception as e:
            print(f"[SWING] order_block state derivation failed for {sym}: {e}")
            continue
        if not atr or atr <= 0:
            out.append({"symbol": sym, "derived": False})
            continue
        stop = _swing_entry_stop(conn, sym) or float(row["stop_loss"] or 0)
        if stop <= 0:
            continue
        conn.execute(
            "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, initial_stop_loss, gap_low, "
            "qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) VALUES (?, 'order_block_delta', ?, ?, ?, ?, ?, ?, "
            "1.0, ?, ?) ON CONFLICT(symbol) DO NOTHING",
            (sym, row["day"], float(row["entry_price"]), stop, stop, row["qty"], row["opened_at"] or time.time(),
             float(atr), run_max))
        if not conn.execute("SELECT 1 FROM positions WHERE symbol = ? AND qty > 0", (sym,)).fetchone():
            apply_paper_trade(conn, sym, "buy", row["qty"], float(row["entry_price"]))
        conn.commit()
        _sync_signal_state_swing_external(conn)
        _log_real_order_event(
            conn, sym, "reroute", "order_block_state_restored", kotak_trading_symbol=row["kotak_trading_symbol"],
            new_state=f"entry {row['day']} @ Rs{float(row['entry_price']):.2f}, stop Rs{stop:.2f}, ATR Rs{atr:.2f}, peak close Rs{run_max:.2f}",
            reason="B-1364: paper swing exit state was lost; re-derived from daily bars so the order_block_delta trail/max-hold exit runs again")
        out.append({"symbol": sym, "derived": True})
    _ob_state_last_day = today
    return out


_orphan_1h_state_last_day = None


def _swing_1h_entry_bar(df1h, opened_at: float):
    """'YYYY-MM-DD HH:MM' of the last hourly bar that had COMPLETED when the real entry opened (the bar the live 1h
    pass saw as its last bar: _hourly_with_str_date drops a bar whose start + 1h is after now), else None."""
    if df1h is None or len(df1h) == 0 or not opened_at:
        return None
    t = pd.Timestamp(dt.datetime.utcfromtimestamp(float(opened_at)) + dt.timedelta(minutes=IST_OFFSET_MIN))
    starts = pd.to_datetime(df1h["Date"].astype(str))
    done = df1h["Date"].astype(str)[(starts + pd.Timedelta(hours=1) <= t).to_numpy()]
    return str(done.iloc[-1]) if len(done) else None


def _ensure_1h_swing_state_for_orphans(conn, fetch=None) -> list:
    """B-1381 (2026-10-27): a real swing holding opened by a 1h long cell (macddiv / envelope / cup-cheat) whose
    signal_state_swing row was lost (entries were never pushed to the Upstash mirror, so a restart before the next
    daily mirror push dropped the row: GSEC5IETF 2026-10-16) got no strategy exit at all. Re-create the exit state from
    the real row and hourly bars, so _run_long_swing_1h_pass (the owning engine) evaluates that cell's OWN exit rule
    again: entry bar = last hourly bar completed at the real fill time, entry price = real fill, initial stop = the
    entry-day stop (swing_entry_stop) or the real row's stored stop. Places no order and never changes a resting stop
    (the restored stop is the entry stop, so the daily ratchet can only keep or raise it). Kotak holdings/positions
    are read first; a symbol Kotak does not show as held is skipped. Once per IST day."""
    global _orphan_1h_state_last_day
    today = ist_now().strftime("%Y-%m-%d")
    if _orphan_1h_state_last_day == today:
        return []
    fetch = fetch or fetch_ohlc
    live_1h = set(MACDDIV_LONG_LIVE_CELLS) | set(ENVELOPE_LONG_LIVE_CELLS) | set(CUP_CHEAT_LONG_LIVE_CELLS)
    orphans = [r for r in conn.execute("SELECT * FROM real_positions_swing").fetchall()
               if not conn.execute("SELECT 1 FROM signal_state_swing WHERE symbol = ?", (r["symbol"],)).fetchone()]
    if not orphans:
        _orphan_1h_state_last_day = today
        return []
    held = _kotak_holdings_open_by_trdsym()
    if held is None:
        return []  # unknown is not "not held": retry next tick
    out = []
    for row in orphans:
        sym, strat = row["symbol"], row["strategy"]
        if strat not in live_1h:
            if strat not in ("order_block_delta", "gap_and_go"):  # those have their own restore (B-1364 / NYKAA)
                out.append({"symbol": sym, "derived": False, "why": f"no 1h state rebuild for strategy {strat!r}"})
            continue
        if row["kotak_trading_symbol"] not in held and _kotak_symbol_still_open(row["kotak_trading_symbol"]) is not True:
            out.append({"symbol": sym, "derived": False, "why": "not held at Kotak"})
            continue
        try:
            df = _hourly_with_str_date(fetch(sym, "60d", "1h"))
            entry_bar = _swing_1h_entry_bar(df, row["opened_at"])
        except Exception as e:
            print(f"[SWING LONG 1h] orphan state derivation failed for {sym}: {e}")
            continue
        stop = _swing_entry_stop(conn, sym) or float(row["stop_loss"] or 0)
        entry = float(row["entry_price"] or 0)
        if not entry_bar or not (0 < stop < entry):
            _log_real_order_event(
                conn, sym, "reroute", "swing_1h_state_not_derivable", kotak_trading_symbol=row["kotak_trading_symbol"],
                new_state="no exit state restored; resting SL keeps protecting",
                reason=f"B-1381: {strat} entry bar or entry stop could not be derived honestly (bar {entry_bar}, stop {stop})")
            out.append({"symbol": sym, "derived": False, "why": "entry bar/stop not derivable"})
            continue
        conn.execute(
            "INSERT INTO signal_state_swing (symbol, strategy, entry_day, entry_price, initial_stop_loss, gap_low, "
            "qty, entry_ts, fx_to_inr, atr_at_entry, running_max_close) VALUES (?, ?, ?, ?, ?, NULL, ?, ?, 1.0, NULL, ?) "
            "ON CONFLICT(symbol) DO NOTHING",
            (sym, strat, entry_bar, entry, stop, int(row["qty"]), float(row["opened_at"]), entry))
        if not conn.execute("SELECT 1 FROM positions WHERE symbol = ? AND qty > 0", (sym,)).fetchone():
            apply_paper_trade(conn, sym, "buy", int(row["qty"]), entry)  # so the paper exit has a position to close
        conn.commit()
        _sync_signal_state_swing_external(conn)
        _log_real_order_event(
            conn, sym, "reroute", "swing_1h_state_restored", kotak_trading_symbol=row["kotak_trading_symbol"],
            new_state=f"{strat}: entry bar {entry_bar} @ Rs{entry:.2f}, stop Rs{stop:.2f}",
            reason="B-1381: paper swing exit state was lost; rebuilt from the real row and hourly bars so the 1h "
                   "engine evaluates this cell's own exit rule again (no order placed by the rebuild)")
        out.append({"symbol": sym, "derived": True, "entry_day": entry_bar, "stop": stop})
    _orphan_1h_state_last_day = today
    return out


SWING_PASS_INTERVAL_SEC = 900  # B-419: repeat swing pass every 15 min during market hours
_swing_last_pass_ts = 0.0


def _restore_strategy_scan_counts(conn):
    """B-419: scan counters are memory-only, so a restart zeroed them. Merge today's persisted counts back."""
    global _strategy_scan_counts_day
    today = ist_now().strftime("%Y-%m-%d")
    if _strategy_scan_counts_day != today:
        _strategy_scan_counts.clear()
        _strategy_scan_counts_day = today
    for r in conn.execute("SELECT tag, n FROM strategy_scan_counts WHERE day = ?", (today,)).fetchall():
        if r["n"] > _strategy_scan_counts.get(r["tag"], 0):
            _strategy_scan_counts[r["tag"]] = r["n"]


def _persist_strategy_scan_counts(conn):
    today = ist_now().strftime("%Y-%m-%d")
    for tag, n in list(_strategy_scan_counts.items()):
        conn.execute("INSERT OR REPLACE INTO strategy_scan_counts (day, tag, n) VALUES (?, ?, ?)", (today, tag, n))
    conn.commit()


def _run_swing_scan(conn):
    """First pass of the IST day (logged in swing_scan_log, as before), then a repeat pass every
    SWING_PASS_INTERVAL_SEC while NSE is open (B-419, user 2026-10-11: scan 'every few minutes in round
    robin'). Repeat passes see only completed bars and skip symbols already entered/exited today."""
    global _swing_last_pass_ts
    today = ist_now().strftime("%Y-%m-%d")
    try:
        _restore_strategy_scan_counts(conn)
    except Exception as e:
        print(f"[SWING] scan-count restore failed (non-fatal): {e}")
    if not is_nse_trading_day():
        return  # B-1291: NSE holiday - no new swing entries (exits/SL sync run elsewhere)
    first_pass = not conn.execute("SELECT 1 FROM swing_scan_log WHERE scan_date = ?", (today,)).fetchone()
    if not first_pass and (not _nse_equity_market_open_now() or time.time() - _swing_last_pass_ts < SWING_PASS_INTERVAL_SEC):
        return
    if not _switch_allows_entries(conn):
        return  # ALL TRADING OFF: no new swing entries; scan not consumed, runs after resume
    if first_pass:
        conn.execute("INSERT INTO swing_scan_log (scan_date) VALUES (?)", (today,))
        conn.commit()
    _swing_last_pass_ts = time.time()
    before = {r[0] for r in conn.execute("SELECT symbol FROM signal_state_swing").fetchall()}
    try:
        return _run_swing_scan_pass(conn)
    finally:
        try:
            after = {r[0] for r in conn.execute("SELECT symbol FROM signal_state_swing").fetchall()}
            for sym in before ^ after:
                conn.execute("INSERT OR IGNORE INTO swing_done_today (day, symbol) VALUES (?, ?)", (today, sym))
            conn.commit()
            if before != after:
                # B-1381: entries never pushed signal_state_swing to Upstash (only exits/heals and one daily push did),
                # so a restart after an entry lost the row and its strategy exit (GSEC5IETF 2026-10-16).
                _sync_signal_state_swing_external(conn)
            _persist_strategy_scan_counts(conn)
        except Exception as e:
            print(f"[SWING] post-pass bookkeeping failed (non-fatal): {e}")


def _run_swing_scan_own_conn():
    """Thread-safe wrapper: sqlite connections are per-thread, so the swing pass opens its own."""
    with closing(get_db()) as c:
        return _run_swing_scan(c)


def _fo_chain_monitoring_snapshot_own_conn():
    """Thread-safe wrapper (B-1361): the snapshot calls Kotak quotes(), so it runs off the event loop on its own conn."""
    with closing(get_db()) as c:
        return _fo_chain_monitoring_snapshot(c)


_swing_scan_task = None


def _log_swing_scan_done(t):
    if t.cancelled():
        return
    exc = t.exception()
    if exc is not None:
        print(f"[SWING] scan failed (non-fatal, intraday tick continues): {exc}")


def _fo_tick_steps():
    """F&O steps of the scheduler tick, run OFF the event loop (they do blocking Kotak and yfinance
    fetches; run inline they stalled the loop and the later steps, e.g. the MCX scan, rarely ran).
    Each step is isolated so one failure/slow step cannot skip the others."""
    real_on = is_real_fo_trading_enabled()
    steps = [_maybe_sync_real_fo_option_stop_losses] if real_on else []
    steps.append(_run_mcx_daily_scan)  # B-1282: first, so the slow strike scan can never starve it (futures counted 1 scan/day); entries gated inside
    steps.append(_run_fo_strike_setup_scan)
    if real_on:
        steps += [_run_index_swing_option_scan]
    for fn in steps:
        try:
            with closing(get_db()) as c:
                fn(c)
        except Exception as e:
            print(f"[REAL F&O] {fn.__name__} failed (non-fatal): {e}")


def _chan_short_flatten_due(symbol: str) -> bool:
    """True from 15:10 to 15:14 IST while a real chan_kalman short is still open for symbol (retried every tick)."""
    n = ist_now()
    m = n.hour * 60 + n.minute
    if not (CHAN_SHORT_FLATTEN_START_MIN <= m < CHAN_SHORT_FLATTEN_END_MIN):
        return False
    with closing(get_db()) as c:
        _qs = ",".join("?" * len(CHAN_INTRADAY_SHORT_TAGS))
        return bool(c.execute(f"SELECT 1 FROM real_positions_short WHERE symbol = ? AND strategy IN ({_qs})",
                              (symbol, *CHAN_INTRADAY_SHORT_TAGS)).fetchone())


def _chan_long_flatten_due(symbol: str) -> bool:
    """True from 15:10 to 15:14 IST while a real chan_kalman long is still open for symbol (retried every tick)."""
    n = ist_now()
    m = n.hour * 60 + n.minute
    if not (CHAN_LONG_FLATTEN_START_MIN <= m < CHAN_LONG_FLATTEN_END_MIN):
        return False
    with closing(get_db()) as c:
        _qs = ",".join("?" * len(CHAN_INTRADAY_LONG_TAGS))
        return bool(c.execute(f"SELECT 1 FROM real_positions WHERE symbol = ? AND strategy IN ({_qs})",
                              (symbol, *CHAN_INTRADAY_LONG_TAGS)).fetchone())


async def _real_off_loop(fn, *args, **kwargs):
    """B-1365: run fn(conn, *args, **kwargs) in a worker thread with its own DB connection, so a Kotak/yfinance call
    inside it can never freeze the event loop (and with it /health and Render's health check)."""
    def _run():
        with closing(get_db()) as _c:
            return fn(_c, *args, **kwargs)
    return await asyncio.to_thread(_run)


async def _scheduler_tick():
    global _scheduler_last_tick_ts, _scheduler_rr_cursor, _scheduler_currently_checking
    watchlist_by_symbol = {cfg["symbol"]: cfg for cfg in WATCHLIST}

    with closing(get_db()) as conn:
        if _nse_equity_market_open_now():
            try:  # B-1365: off the event loop (Kotak/yfinance calls froze /health -> Render restarts)
                await _real_off_loop(_ensure_gap_and_go_state_for_held)
                await _real_off_loop(_ensure_order_block_state_for_held)  # B-1364
                await _real_off_loop(_ensure_1h_swing_state_for_orphans)  # B-1381
            except Exception as e:
                print(f"[SWING] gap_and_go state restore failed (non-fatal): {e}")
        try:
            # Off the event loop (2026-10-13): the 1d swing pass fetches ~380 symbols x 2y of bars
            # synchronously, which froze the whole HTTP server (Render 502) for the length of every pass.
            # Also NOT awaited: awaiting it starved the intraday per-asset checks for minutes per tick
            # ("Last checked / Last result" blank, user 2026-10-13). One pass at a time; the next tick
            # starts a new one only when the previous finished.
            global _swing_scan_task
            if _swing_scan_task is None or _swing_scan_task.done():
                _swing_scan_task = asyncio.create_task(asyncio.to_thread(_run_swing_scan_own_conn))
                _swing_scan_task.add_done_callback(_log_swing_scan_done)
        except Exception as e:
            print(f"[SWING] scan failed (non-fatal, intraday tick continues): {e}")
        try:  # B-981: chan_gap short open-print scan, off the event loop, one pass at a time
            global _chan_gap_short_task
            if _chan_gap_short_task is None or _chan_gap_short_task.done():
                _chan_gap_short_task = asyncio.create_task(asyncio.to_thread(_run_chan_gap_short_scan))
        except Exception as e:
            print(f"[CHAN_GAP] scan launch failed (non-fatal): {e}")
        global _swing_sl_trail_last_day
        _today_ist = ist_now().strftime("%Y-%m-%d")
        # B-1365 (2026-10-26): these place/cancel real orders (Kotak login, order_report, place) and ran ON the event
        # loop: live watchdog showed MainThread in _maybe_sync_real_swing_stop_loss > ensure_resting_sl with 37 s loop
        # lag, so /health stopped answering and Render restarted the bot ~every 20 min. Now in a worker thread.
        if _swing_sl_trail_last_day != _today_ist and _nse_equity_market_open_now():
            try:
                await _real_off_loop(_sync_swing_resting_sl_to_strategy)
                await _real_off_loop(_sync_signal_state_swing_external)
                _swing_sl_trail_last_day = _today_ist
            except Exception as e:
                print(f"[REAL SWING] daily SL trail/mirror failed (non-fatal, retries next tick): {e}")
        try:  # B-1369: entry-day stop breached -> cancel open sells, then market sell (every tick, in session)
            await _real_off_loop(_swing_entry_stop_breach_sweep)
        except Exception as e:
            print(f"[REAL SWING] breach sweep failed (non-fatal): {e}")
        try:
            await _real_off_loop(_retry_pending_real_swing_orders)
        except Exception as e:
            print(f"[REAL SWING] retry pass failed (non-fatal, intraday tick continues): {e}")

        try:  # B-1361: off the event loop; its Kotak quotes() call froze /health 16 s at boot
            await asyncio.to_thread(_fo_chain_monitoring_snapshot_own_conn)
        except Exception as e:
            print(f"[FO_MONITOR] snapshot failed (non-fatal, intraday tick continues): {e}")

        try:
            await _real_off_loop(_run_fo_options_scan)  # B-1365: off the event loop
        except Exception as e:
            print(f"[FO_RSI2] scan failed (non-fatal, intraday tick continues): {e}")

        open_equity_symbols = {
            r["symbol"] for r in conn.execute(
                "SELECT symbol FROM signal_state WHERE status = 'long'"
            ).fetchall()
        }
        open_option_underlyings = {
            r["underlying"] for r in conn.execute(
                "SELECT underlying FROM option_state"
            ).fetchall()
        }
        # BUG found live 2026-09-09 (explicit user finding: real positions
        # - JSWINFRA/MIDCAPADD/PAISALO - still open well past squareoff_min
        # AND market close): open_equity_symbols above is sourced from
        # signal_state (PAPER tracking) ONLY. _auto_signal_core (the ONLY
        # place squareoff_min is ever evaluated) and the whole real-order-
        # management block (_maybe_place_real_exit/_maybe_sync_real_stop_loss,
        # including that function's OWN signal_state self-heal) only run
        # for `symbol in symbols_this_tick` below - so a real position
        # whose signal_state row is missing (the exact restart-wipe class
        # this session already fixed ONCE inside _maybe_sync_real_stop_loss)
        # was invisible to symbols_this_tick ENTIRELY unless it happened to
        # be evidenced or the round-robin cursor (thousands of symbols)
        # coincidentally reached it - the self-heal fix could never even
        # get CALLED for it. real_positions symbols now get the exact same
        # unconditional treatment open_equity_symbols/open_option_underlyings
        # already have, closing that gap at its source instead of only at
        # the one call site that happened to get fixed already.
        real_position_rows = conn.execute("SELECT * FROM real_positions").fetchall()
        open_real_symbols = {r["symbol"] for r in real_position_rows}
        # Backfill BEFORE _auto_signal_core runs this tick, not only
        # reactively inside _maybe_sync_real_stop_loss afterward - a real
        # position with no signal_state row would otherwise look FLAT to
        # _auto_signal_core (which only ever sees signal_state, never
        # real_positions), risking a fresh paper "entry" at today's
        # current price that clobbers the real position's own original
        # entry economics, instead of the real entry price this helper
        # actually restores. _ensure_signal_state_for_real_position's own
        # first check is a cheap no-op SELECT when a row already exists,
        # so calling it for every real position every tick costs nothing
        # in the common case.
        for real_row in real_position_rows:
            _ensure_signal_state_for_real_position(conn, real_row)
        trading_paused = not is_trading_enabled(conn)
        # Live thresholds (see RUNTIME_SETTINGS_META/get_runtime_setting
        # above) - read once per tick here, not per symbol, same reasoning
        # as scheduler_capital_inr below. A value saved via POST
        # /runtime-settings is picked up on the VERY NEXT tick.
        live_daily_risk_pct = get_runtime_setting(conn, "daily_risk_pct")
        live_rr = get_runtime_setting(conn, "rr")
        live_batch_size = int(get_runtime_setting(conn, "entry_scan_batch_size"))
        live_max_hold_minutes = get_runtime_setting(conn, "max_hold_minutes")

    # When paused, don't waste a Yahoo Finance call scanning flat
    # symbols for a NEW entry nobody wants right now - _auto_signal_core/
    # _options_signal_core would reject it anyway (trading_paused), this
    # just skips the round-robin batch itself. Open positions are NEVER
    # gated by this - they still get checked every tick regardless
    # (see symbols_this_tick below), same as always.
    all_symbols = [cfg["symbol"] for cfg in WATCHLIST]
    # Full-universe pool, NOT market-hours-filtered (explicit user
    # instruction, 2026-09-08: "make this [361/2661 distinct scanned]
    # running for whole 24 hour if the trading toggle is ON" - i.e. the
    # round-robin must cycle through all 2661 watchlist symbols around
    # the clock whenever the global trading toggle is on, so the
    # distinct-scanned coverage counter can reach the full watchlist in
    # a day rather than being capped by each symbol's own market hours.
    # This reverses the 2026-09-07 market-hours pool filter (see the now
    # UNUSED _market_open_for_cfg's own docstring for that reasoning) -
    # confirmed via AskUserQuestion the tradeoff (scan slots spent on
    # symbols whose market is currently shut, where _auto_signal_core/
    # _options_signal_core will just no-op past the same market-hours
    # gate before any entry decision) is accepted. An open position is
    # NEVER gated by this (open_equity_symbols/open_option_underlyings
    # below are unconditional) - only the round-robin's flat-symbol scan
    # pool composition changed.
    # EVIDENCED_SYMBOLS (real, swept backtest evidence - see its own
    # comment above NSE_STOCK_PARAM_OVERRIDES) are pulled OUT of the
    # round-robin pool entirely and given to symbols_this_tick
    # unconditionally below instead - explicit user instruction
    # 2026-09-09 ("add preference to monitor these stocks out of the
    # evidenced symbols"), so a proven symbol is never left waiting on
    # the cursor's turn through ~2,655 mostly-unproven names, and the
    # round-robin's own batch slots go further sweeping the rest of the
    # universe instead of periodically re-covering ground already
    # guaranteed here.
    flat_symbols = [] if trading_paused else [
        s for s in all_symbols
        if s not in open_equity_symbols and s not in EVIDENCED_SYMBOLS and s not in open_real_symbols
    ]
    if not is_nse_trading_day():
        # B-1291: NSE holiday - drop NEW-entry .NS candidates only. Open positions (open_*_symbols),
        # MCX/other-market symbols and all protection/exit paths are untouched.
        flat_symbols = [s for s in flat_symbols if not s.endswith(".NS")]
    if flat_symbols:
        n = len(flat_symbols)
        batch_size = min(live_batch_size, n)
        rr_batch = [flat_symbols[(_scheduler_rr_cursor + i) % n] for i in range(batch_size)]
        _scheduler_rr_cursor = (_scheduler_rr_cursor + batch_size) % n
        _sync_rr_cursor_external(_scheduler_rr_cursor)
    else:
        rr_batch = []

    # Same trading_paused gate as the round-robin pool above - an
    # evidenced symbol not currently open is still a NEW-entry scan
    # nobody wants while trading is paused, so it's held back the same
    # way flat_symbols is, not scanned unconditionally like an already-
    # open position.
    evidenced_flat = set() if trading_paused else (EVIDENCED_SYMBOLS - open_equity_symbols)
    if not is_nse_trading_day():
        evidenced_flat = {s for s in evidenced_flat if not s.endswith(".NS")}  # B-1291

    # Always: every symbol with an open equity position (time-critical
    # stop/target/eod check) + every symbol with an open REAL position
    # (same reason - a real position's squareoff/stop/target management
    # must never depend on its paper counterpart still existing) + every
    # underlying with an open option position (same reason, for the
    # overlay below) + every evidenced, currently-flat symbol (preferred
    # over the round-robin's turn) + this tick's round-robin entry-scan
    # batch of the remaining, unevidenced flat symbols.
    symbols_this_tick = (
        open_equity_symbols | open_real_symbols | open_option_underlyings | evidenced_flat | set(rr_batch)
    )

    # Hoisted once per tick, not per symbol - get_scheduler_capital_inr()
    # is TTL-cached internally anyway, but this avoids re-checking cache
    # freshness once per symbol in the loop below for no benefit.
    scheduler_capital_inr = await asyncio.to_thread(get_scheduler_capital_inr)  # B-1361: Kotak limits() froze the loop 31 s

    for symbol in _scan_visit(symbols_this_tick):
        cfg = watchlist_by_symbol.get(symbol)
        if not cfg:
            # A symbol can be IN symbols_this_tick (open_equity_symbols/
            # open_real_symbols, both sourced from DB state, not
            # WATCHLIST) while no longer having a WATCHLIST entry at all -
            # confirmed live 2026-09-21: GENCON.NS sat open, completely
            # unmanaged (no stop/target/squareoff check, no real stop-loss
            # sync, no exit) for ~10 days after the NIFTY 200 universe
            # restriction dropped it from WATCHLIST while its position was
            # still open. `continue` here silently threw away exactly the
            # open-position coverage the comments above this loop promise
            # ("must never depend on..."), for this one case - a symbol
            # leaving WATCHLIST while a position is open was never
            # exercised before (WATCHLIST had only ever grown, never
            # shrunk, until that restriction). Falls back to the same
            # conservative NSE_STOCK_DEFAULT_PARAMS a brand-new unproven
            # symbol gets, rather than abandoning management of a real
            # open position.
            cfg = {**NSE_STOCK_DEFAULT_PARAMS, "symbol": symbol}
        _scheduler_currently_checking = {
            "symbol": symbol, "kind": "equity", "started_at_utc": time.time(),
        }
        _record_scheduler_check(symbol)
        _record_intraday_strategy_scan(cfg)  # B-423: counter only, no order logic
        _sync_visit_strategy_count(symbol, 1)
        try:
            result = await asyncio.to_thread(
                _auto_signal_core,
                symbol=cfg["symbol"], capital=scheduler_capital_inr,
                daily_risk_pct=live_daily_risk_pct,
                risk_per_trade_pct=cfg["risk_pct"],
                stop_pct=cfg["stop_pct"], rr=live_rr,
                orb_minutes=cfg["orb_minutes"], sma_fast=cfg["sma_fast"], sma_slow=cfg["sma_slow"],
                interval="5m", tz_offset_min=cfg["tz_offset_min"], open_min=cfg["open_min"],
                close_min=cfg["close_min"], squareoff_min=cfg["squareoff_min"],
                trade_weekends=cfg["trade_weekends"], currency=cfg["currency"],
                # 2026-09-09 architecture revamp, explicit user instruction:
                # "revamp all of the strategy architecture from beginning" +
                # "full universe now" - the universal multi-factor scoring
                # engine (see _compute_universal_entry_score) is now THE
                # live entry trigger for every WATCHLIST symbol, replacing
                # the old per-symbol orb_breakout/bullish_engulfing choice.
                # No WATCHLIST entry sets its own "strategy" field (grep
                # confirms none do), so this default is what actually governs
                # literally every symbol - a per-symbol override remains
                # possible (WATCHLIST's own "strategy" field still works) for
                # deliberately pinning a symbol back to the old engine.
                strategy=cfg.get("strategy", "universal_score"),
                trend_sma=cfg.get("trend_sma", 0), volume_confirm=cfg.get("volume_confirm", False),
                max_hold_minutes=live_max_hold_minutes,
                # 2026-09-09, explicit user instruction: "stop using SMA
                # and replace it with EMA with immediate effect
                # everywhere" - THIS is the live scheduler's own call
                # site, the one that actually decides every real WATCHLIST
                # symbol's trend read; a per-symbol "ma_type" WATCHLIST
                # field still overrides this fallback if ever set.
                ma_type=cfg.get("ma_type", "ema"),
                # require_real_tradability (2026-09-22, see _auto_signal_core's
                # own docstring) - True only for NSE equities, the exact same
                # universe _maybe_place_real_entry below itself targets (its
                # own asset_class != "nse_equity" check skips everything
                # else) - a symbol real trading can't touch at all yet
                # (indices/commodities/US) has no real gate to replicate.
                require_real_tradability=cfg["symbol"].endswith(".NS"),
            )
            _scheduler_last_results[cfg["symbol"]] = {"checked_at_utc": time.time(), **result}
            if result.get("open_position") or str(result.get("action_taken", "")).startswith("exited_"):
                _scan_only_intraday_cells(cfg["symbol"], "long")  # B-1274 stage 2: entry chain was skipped for a held symbol

            # Stage 3: mirror this SAME decision as a real order, only
            # for the equity path (options/MCX are out of stage 3 v1 -
            # explicit user instruction). Deliberately AFTER the paper
            # result is already recorded, in its own try/except that
            # can never propagate - a real-order hiccup must never look
            # like a paper-trading scheduler failure or block the next
            # symbol's tick.
            try:
                action_taken = result.get("action_taken", "")
                if action_taken == "entered_long":
                    await _real_off_loop(_maybe_place_real_entry, cfg["symbol"])
                elif action_taken.startswith("exited_"):
                    await _real_off_loop(_maybe_place_real_exit, cfg["symbol"], reason=f"intraday paper exit: {action_taken}")
                elif action_taken.startswith("partial_booked_"):
                    # Staged profit-booking ladder (2026-09-09 architecture
                    # revamp) - the paper side already booked one leg (see
                    # _execute_staged_leg_exit); mirror it as a REAL partial
                    # sell for the SAME leg qty, same isolation principle as
                    # every other real-order mirror in this block.
                    await _real_off_loop(_maybe_place_real_partial_exit, cfg["symbol"], result.get("staged_exit") or {})
                elif _chan_long_flatten_due(cfg["symbol"]):
                    # B-960: exchange cancels resting orders at 15:15 IST, so flat by our own market sell first.
                    await _real_off_loop(_maybe_place_real_exit, cfg["symbol"], reason="flatten_1515")
                else:
                    # Position still open (or never was one) - sync any
                    # real resting stop-loss to the paper trail's latest
                    # level. A no-op unless a real position is actually
                    # open for this symbol (see _maybe_sync_real_stop_loss).
                    await _real_off_loop(_maybe_sync_real_stop_loss, cfg["symbol"])
            except Exception as e:
                print(f"[real_orders] unexpected error for {cfg['symbol']}: {e}")

            # RANGE-regime short mirror (2026-09-29, explicit user
            # instruction to implement short selling). Own try/except,
            # same isolation principle as every other block here - a
            # short-scan hiccup must never block the long path above or
            # the next symbol's tick. Runs for every WATCHLIST symbol
            # (paper), same as the long scan; real-order mirroring inside
            # _maybe_place_real_short_entry itself narrows to NSE equity
            # only (its own asset_class check), same narrowing the long
            # side's _maybe_place_real_entry already does.
            _record_short_strategy_scans()  # B-423: counter only
            _sync_visit_strategy_count(cfg["symbol"], len(_INTRADAY_SHORT_SCAN_TAGS))
            try:
                short_result = _short_signal_core(
                    symbol=cfg["symbol"], capital=scheduler_capital_inr,
                    daily_risk_pct=live_daily_risk_pct, risk_per_trade_pct=cfg["risk_pct"],
                    stop_pct=cfg["stop_pct"], rr=live_rr,
                    sma_fast=cfg["sma_fast"], sma_slow=cfg["sma_slow"],
                    interval="5m", tz_offset_min=cfg["tz_offset_min"], open_min=cfg["open_min"],
                    close_min=cfg["close_min"], squareoff_min=cfg["squareoff_min"],
                    trade_weekends=cfg["trade_weekends"], currency=cfg["currency"],
                    max_hold_minutes=live_max_hold_minutes, ma_type=cfg.get("ma_type", "ema"),
                    require_real_tradability=cfg["symbol"].endswith(".NS"),
                )
                short_action = short_result.get("action_taken", "")
                if short_action == "holding_short" or short_action.startswith("exited_short_"):
                    _scan_only_intraday_cells(cfg["symbol"], "short")  # B-1274 stage 2: entry chain was skipped for a held symbol
                if short_action == "entered_short":
                    await _real_off_loop(_maybe_place_real_short_entry, cfg["symbol"])
                    # 2026-10-08: a short signal on an index buys a single-strike PUT.
                    if cfg["symbol"] in _REAL_OPTION_UNDERLYING:
                        _e = short_result.get("entry") or {}
                        await _real_off_loop(_maybe_place_real_fo_put_entry, cfg["symbol"], _e.get("price"), _e.get("strategy"))
                elif short_action.startswith("exited_short_"):
                    await _real_off_loop(_maybe_place_real_short_exit, cfg["symbol"], reason=f"short paper exit: {short_action}")
                    if cfg["symbol"] in _REAL_OPTION_UNDERLYING:
                        await _real_off_loop(_maybe_place_real_fo_put_exit, cfg["symbol"], reason=f"paper index short exit: {short_action}")
                elif _chan_short_flatten_due(cfg["symbol"]):
                    # B-914: exchange cancels resting orders at 15:15 IST, so flat by our own market cover first.
                    await _real_off_loop(_maybe_place_real_short_exit, cfg["symbol"], reason="flatten_1515")
                else:
                    # 2026-09-30, explicit user instruction ("make short
                    # positions equally mirrored as done in buy
                    # positions") - the long side's own else-branch above
                    # syncs its trailing stop to Kotak every tick; this
                    # was the missing short-side mirror (previously a
                    # short's resting SL was only ever re-checked on the
                    # 5-min reconcile pass, not this ~30s tick).
                    await _real_off_loop(_maybe_sync_real_stop_loss_short, cfg["symbol"])
            except Exception as e:
                print(f"[real_short_orders] unexpected error for {cfg['symbol']}: {e}")

            # Real F&O (2026-09-07, extended to MCX same day per
            # explicit user instruction "also mcx") - NIFTY/BANKNIFTY/
            # GC=F/SI=F/CL=F only (see _INDEX_TO_FO_UNDERLYING). Same
            # isolation principle: its
            # own try/except, never able to break the equity mirror
            # above or the next symbol's tick.
            try:
                if cfg["symbol"] in _REAL_OPTION_UNDERLYING:
                    fo_underlying = _REAL_OPTION_UNDERLYING[cfg["symbol"]]
                    if action_taken == "entered_long":
                        await _real_off_loop(_maybe_place_real_fo_call_entry, cfg["symbol"], result.get("last_close"), result.get("strategy"))
                    elif action_taken.startswith("exited_"):
                        await _real_off_loop(_maybe_place_real_fo_call_exit, cfg["symbol"], reason=f"paper index long exit: {action_taken}")
                    if cfg["symbol"] in _INDEX_TO_FO_UNDERLYING:
                      await _real_off_loop(
                          _straddle_signal_core, fo_underlying, result.get("vol_contraction_signal"),
                          result.get("halted_for_day", False), result.get("is_squareoff_time", False),
                          result.get("last_close"),
                      )
            except Exception as e:
                print(f"[real_fo_orders] unexpected error for {cfg['symbol']}: {e}")
        except Exception as e:
            _scheduler_last_error = f"{cfg['symbol']}: {e}"
            _scheduler_last_results[cfg["symbol"]] = {
                "checked_at_utc": time.time(), "symbol": cfg["symbol"],
                "status": "error", "detail": str(e),
            }
        finally:
            _scheduler_currently_checking = None

    # Options overlay - real calls/puts on the symbols with a live
    # yfinance chain (OPTIONS_ELIGIBLE_SYMBOLS), using that same
    # symbol's own WATCHLIST session config (hours/tz/currency) so it
    # follows the same market clock as the equity engine on that ticker.
    # Covers the SAME symbols_this_tick set as the equity loop above
    # (open positions + this tick's round-robin batch) - not a
    # separate schedule - so a symbol's OHLC fetch (fetch_ohlc, cached
    # 180s) is shared between the two checks instead of doubling the
    # network calls for symbols that are both an equity WATCHLIST entry
    # and options-eligible.
    for underlying in OPTIONS_ELIGIBLE_SYMBOLS:
        if underlying not in symbols_this_tick:
            continue
        cfg = watchlist_by_symbol.get(underlying)
        if not cfg:
            continue
        key = f"{underlying}:OPT"
        _scheduler_currently_checking = {
            "symbol": key, "kind": "options", "started_at_utc": time.time(),
        }
        _record_scheduler_check(key)
        try:
            result = await asyncio.to_thread(
                _options_signal_core,
                underlying=underlying, capital=scheduler_capital_inr,
                daily_risk_pct=live_daily_risk_pct,
                risk_per_trade_pct=cfg["risk_pct"], rr=live_rr,
                trend_sma=cfg.get("trend_sma", 20),
                tz_offset_min=cfg["tz_offset_min"], open_min=cfg["open_min"],
                close_min=cfg["close_min"], squareoff_min=cfg["squareoff_min"],
                trade_weekends=cfg["trade_weekends"], currency=cfg["currency"],
            )
            _scheduler_last_results[key] = {"checked_at_utc": time.time(), **result}
        except Exception as e:
            _scheduler_last_results[key] = {
                "checked_at_utc": time.time(), "underlying": underlying,
                "status": "error", "detail": str(e),
            }
        finally:
            _scheduler_currently_checking = None

    # Once per tick (not per symbol - see _CHECK_COUNTS_REDIS_KEY's own
    # module comment for why), after every check this tick has made -
    # keeps the "distinct scanned" dict surviving a restart at ANY
    # cadence, not just ones slower than journal-sync's 15-min interval.
    _maybe_sync_check_counts_external()

    global _scheduler_tick_count
    _scheduler_tick_count += 1
    try:
        await asyncio.to_thread(sync_generic_tables_external)
    except Exception as e:
        print(f"[table_mirror] tick sync failed (non-fatal): {e}")
    try:
        await asyncio.to_thread(_maybe_sync_fo_option_candles_external)
    except Exception as e:
        print(f"[fo_candle_journal] tick sync failed (non-fatal): {e}")
    await asyncio.to_thread(_upstash_usage_persist)  # B-1342: daily Upstash budget guard (never raises)
    if _scheduler_tick_count % _MEMORY_LOG_EVERY_N_TICKS == 0:
        # B-1288a: return freed pages to the OS (glibc fragmentation after big pandas scans)
        try:
            import gc
            import ctypes
            gc.collect()
            ctypes.CDLL("libc.so.6").malloc_trim(0)
        except Exception:  # noqa: BLE001
            pass
        print(f"[memory] tick {_scheduler_tick_count}: rss_mb={_process_rss_mb()}, "
              f"data_cache_entries={len(_DATA_CACHE)}, watchlist_size={len(WATCHLIST)}")
        try:
            _memory_pressure_check()
        except Exception:  # noqa: BLE001
            pass
        _hr = _rss_headroom()
        if _hr["rss_pct"] is not None and _hr["rss_pct"] > RSS_ALARM_PCT:
            print(f"[memory] ALARM: rss_mb={_hr['rss_mb']} is {_hr['rss_pct']}% of "
                  f"{RSS_LIMIT_MB} MB limit (> {RSS_ALARM_PCT}%) - restart/OOM risk")

    # 2026-09-30: see _UNPROTECTED_BACKCHECK_EVERY_N_TICKS's own module
    # comment - this in-process call is what actually guarantees the
    # standing "unprotected position backcheck every 5 min" rule now,
    # since kotak-reconcile.yml's external GitHub Actions cron was found
    # to be firing far less often than its own `*/5` schedule promises.
    # Best-effort and isolated like every other block in this tick - a
    # Kotak/network hiccup here must never block the rest of the scan.
    if _scheduler_tick_count % SWING_LTP_TRAIL_EVERY_N_TICKS == 0:
        try:
            with closing(get_db()) as _trail_conn:
                _sync_swing_ltp_trail(_trail_conn)
        except Exception as e:
            print(f"[SWING LTP TRAIL] pass failed (non-fatal): {e}")
    # 2026-10-08 thumb rule (B-315): the exchange wipes every resting order
    # at 15:15 IST, so holdings start each day naked. From 09:15 to 09:30 IST
    # the protect pass runs on EVERY tick (~30s) instead of every ~5 min, so
    # the first action of the day is covering open positions with an SL.
    _t_ist = ist_now()
    _open_window = (_t_ist.weekday() < 5 and (9, 15) <= (_t_ist.hour, _t_ist.minute) < (9, 30))
    # B-1354: the ~5-min backcheck itself runs on its own wall-clock thread (_unprotected_backcheck_loop); a full
    # scan tick can take many minutes on a starved CPU, so "every N ticks" left /real-protection-status null for 45+
    # min on 23-Oct. The tick only adds the 09:15-09:30 every-tick protect pass, sharing the same single-flight lock.
    if _open_window:
        try:
            # B-1340: in a worker thread, still awaited (same ordering as before), so a slow Kotak/Upstash call cannot
            # freeze the event loop: on 22 Oct an inline stall starved the entry scan (260 symbol checks vs 3992 the day
            # before) and Render answered 502.
            await asyncio.to_thread(_unprotected_backcheck_once)
        except Exception as e:
            print(f"[unprotected_backcheck] in-process reconcile failed (non-fatal, external cron still covers this): {e}")
        # B-1349: the order-log git push now has its own thread (_git_tier_push_loop), not this tick block.

    # 2026-10-08: trailing SL / heal for every open real single-strike option
    # (Kotak read first inside). Runs every tick; reuses the F&O switch.
    try:
        await asyncio.wait_for(asyncio.to_thread(_fo_tick_steps), timeout=120)
    except Exception as e:
        print(f"[REAL F&O] option SL tick failed or timed out (non-fatal): {e}")

    _scheduler_last_tick_ts = time.time()
    await asyncio.sleep(SCHEDULER_INTERVAL_SECONDS)


STARTUP_HYDRATION_TIMEOUT_SECONDS = 15  # see _start_scheduler's own asyncio.wait_for comment


@app.on_event("startup")
async def _start_scheduler():
    # 5 independent Upstash reads, run CONCURRENTLY (2026-09-16, live
    # Render port-scan-timeout fix). Each is a single bounded-timeout
    # requests call (see each hydrate_*_from_external's own timeout=),
    # but running them SEQUENTIALLY - as this did before - sums their
    # worst-case latency to up to ~50s. FastAPI/uvicorn's lifespan
    # protocol gates the actual listening socket behind this startup
    # handler returning, so that ~50s directly blocked Render's port
    # scanner from ever seeing an open port - confirmed live (repeated
    # "No open ports detected" until "Port scan timeout reached", right
    # before "Application startup complete" finally printed). Running
    # these 5 concurrently cuts worst-case wall time to the SLOWEST
    # single call (~10s) instead of their sum, while changing nothing
    # about ordering: every one of these is still fully awaited here,
    # and nothing after this function returns (the scheduler tick, the
    # webhook endpoint, any request at all) can be reached until ALL 5
    # finish - exactly the same guarantee as before, just not paid for
    # serially anymore. hydrate_runtime_settings_from_external and
    # hydrate_t1_restricted_from_external each need a DB connection
    # created AND used on the SAME thread (sqlite3 connections aren't
    # cross-thread safe) - wrapped in a small closure below instead of
    # passing one in from this thread.
    def _hydrate_runtime_settings():
        with closing(get_db()) as conn:
            return hydrate_runtime_settings_from_external(conn)

    def _hydrate_t1_restricted():
        with closing(get_db()) as conn:
            return hydrate_t1_restricted_from_external(conn)

    # Hard outer deadline (2026-09-16, live follow-up): the concurrency
    # fix above assumed each hydrate call's own requests timeout=
    # bounds its worst case - but a live incident showed the app
    # hanging INDEFINITELY at this exact point (Render's port scanner
    # never even printed past its first couple of misses - not even
    # reaching "Port scan timeout reached", which itself would mean
    # SOME bounded wait). requests' timeout= only bounds the
    # connect/read phases of an already-open socket; a stalled DNS
    # lookup or a connection wedged at the TCP level can ignore it
    # entirely and hang forever, which stalls the whole to_thread call
    # (and therefore this asyncio.gather) with no way for the 10s
    # per-call timeout to ever fire. asyncio.wait_for adds an
    # asyncio-level deadline on top that fires regardless of what's
    # wrong inside the underlying network call - on timeout, every
    # hydrate is treated as "Upstash unreachable" (the exact same
    # result each function already returns for that case), so the
    # existing journal-fallback logic below runs exactly as it would
    # for a clean failure. The abandoned worker thread(s) may still be
    # stuck running in the background against the default executor's
    # limited thread pool - a real but far smaller cost than the app
    # never booting at all.
    try:
        (
            _restored_settings, _restored_t1, _real_positions_hydrated,
            _real_positions_short_hydrated, _real_positions_swing_hydrated,
            _external_rr_cursor, _external_check_counts,
        ) = await asyncio.wait_for(
            asyncio.gather(
                asyncio.to_thread(_hydrate_runtime_settings),
                asyncio.to_thread(_hydrate_t1_restricted),
                asyncio.to_thread(hydrate_real_positions_from_external),
                asyncio.to_thread(hydrate_real_positions_short_from_external),
                asyncio.to_thread(hydrate_real_positions_swing_from_external),
                asyncio.to_thread(hydrate_rr_cursor_from_external),
                asyncio.to_thread(hydrate_check_counts_from_external),
            ),
            timeout=STARTUP_HYDRATION_TIMEOUT_SECONDS,
        )
    except asyncio.TimeoutError:
        print(f"[startup_hydration] timed out after {STARTUP_HYDRATION_TIMEOUT_SECONDS}s "
              "(Upstash unreachable or network-hung) - falling back to journal-only restore, "
              "same as a clean Upstash-unset/unreachable result")
        _restored_settings, _restored_t1, _real_positions_hydrated = 0, 0, False
        _real_positions_short_hydrated = False
        _real_positions_swing_hydrated = False
        _external_rr_cursor, _external_check_counts = None, None
    try:
        await asyncio.wait_for(asyncio.to_thread(hydrate_signal_state_swing_from_external),
                               timeout=STARTUP_HYDRATION_TIMEOUT_SECONDS)
    except Exception as e:
        print(f"[signal_state_swing_external] startup hydrate skipped (non-fatal): {e}")

    # runtime_settings: Upstash-restore FIRST, before anything else reads
    # a live setting (the scheduler tick below, any endpoint) - see
    # hydrate_runtime_settings_from_external's own docstring for the
    # 2026-09-09 bug this closes.
    if _restored_settings:
        print(f"[runtime_settings_external] restored {_restored_settings} setting(s) from Upstash")
    # real_t1_restricted: same Upstash-first restore, before any real
    # entry gate could otherwise re-attempt a symbol already confirmed
    # T1/T2T-restricted on a prior restart - see hydrate_t1_restricted_
    # from_external's own docstring for the 2026-09-09 bug this closes.
    if _restored_t1:
        print(f"[t1_restricted_external] restored {_restored_t1} restriction(s) from Upstash")
    # Generic table mirror restore FIRST (2026-10-06) so the journal reconciles
    # below see these rows as already present - see hydrate_generic_tables_from_external.
    try:
        await asyncio.wait_for(asyncio.to_thread(hydrate_generic_tables_from_external),
                               timeout=STARTUP_HYDRATION_TIMEOUT_SECONDS)
    except Exception as e:
        print(f"[table_mirror] startup hydrate skipped (non-fatal, retried per tick): {e}")
    try:
        _n_sk = await asyncio.wait_for(asyncio.to_thread(hydrate_swing_skipped_from_external),
                                       timeout=STARTUP_HYDRATION_TIMEOUT_SECONDS)
        if _n_sk:
            print(f"[swing_skipped] restored {_n_sk} skipped symbol(s) from Upstash")
    except Exception as e:
        print(f"[swing_skipped] startup restore skipped (non-fatal): {e}")
    try:
        await asyncio.wait_for(asyncio.to_thread(_startup_merge_viable_stack), timeout=STARTUP_HYDRATION_TIMEOUT_SECONDS)
    except Exception as e:
        print(f"[VIABLE-STACK] startup merge skipped (non-fatal, retried on first read): {e}")
    try:
        await asyncio.wait_for(asyncio.to_thread(hydrate_fo_option_candles_from_external),
                               timeout=STARTUP_HYDRATION_TIMEOUT_SECONDS)
    except Exception as e:
        print(f"[fo_candle_journal] startup restore skipped (non-fatal): {e}")
    reconcile_open_positions_from_journal()
    reconcile_trading_control_from_journal()
    reconcile_real_trading_control_from_journal()
    try:
        reconcile_tracked_union_from_journal()
    except Exception as e:
        print(f"[tracked_union] journal restore skipped (non-fatal): {e}")
    # Upstash first - real-time and authoritative once configured, so its
    # read (even an EMPTY one) wins outright over the git journal below,
    # which only runs as a fallback when Upstash was unset or unreachable.
    # BUG found live 2026-09-08: running the journal fallback
    # unconditionally resurrected positions Upstash had already, correctly,
    # recorded as ghost-removed (AGL.NS/BHANDARI.NS) - see
    # hydrate_real_positions_from_external's own docstring for the full
    # root cause.
    if not _real_positions_hydrated:
        reconcile_real_positions_from_journal()
    reconcile_real_trades_today_from_journal()
    # rr_cursor: Upstash first (real-time), same reasoning as
    # real_positions above - reconcile_scheduler_check_counts_from_journal's
    # own rr_cursor restore only fires when this leaves the cursor at its
    # just-started default (0), so a fresher Upstash value never gets
    # clobbered by the slower git journal.
    global _scheduler_rr_cursor
    if _external_rr_cursor is not None:
        _scheduler_rr_cursor = _external_rr_cursor
        print(f"[rr_cursor_external] restored cursor to {_external_rr_cursor} from Upstash")
    # check_counts (the "distinct scanned" dict itself): Upstash first,
    # same reasoning as rr_cursor above - only applied if today's day
    # matches (a stale prior-day snapshot must never carry over, same
    # rollover rule _record_scheduler_check itself applies). The journal
    # reconcile right below only fires when this left the dict still
    # empty, so a fresher Upstash-restored dict is never clobbered.
    global _scheduler_check_counts_day
    if _external_check_counts is not None:
        _ext_day, _ext_counts = _external_check_counts
        if _ext_day == ist_now().strftime("%Y-%m-%d"):
            _scheduler_check_counts.update(_ext_counts)
            _scheduler_check_counts_day = _ext_day
            print(f"[check_counts_external] restored {len(_ext_counts)} symbol check-count(s) from Upstash")
    reconcile_scheduler_check_counts_from_journal()
    asyncio.create_task(_scheduler_loop())
    asyncio.create_task(_tracked_union_memory_loop())
    asyncio.create_task(_loop_heartbeat())  # B-1356
    try:  # B-1359: 40 workers filled up on 23-Oct and every `def` endpoint hung; 80 buys headroom while the watchdog names the stuck code
        import anyio.to_thread
        anyio.to_thread.current_default_thread_limiter().total_tokens = 80
    except Exception as e:  # noqa: BLE001
        print(f"[threadpool] could not raise worker limit (non-fatal): {e}")
    global _BACKGROUND_THREADS_STARTED
    if not _BACKGROUND_THREADS_STARTED:  # once per process: a test's repeated startups must not stack copies
        _BACKGROUND_THREADS_STARTED = True
        threading.Thread(target=_git_tier_push_loop, name="git-tier-push", daemon=True).start()  # B-1349
        threading.Thread(target=_unprotected_backcheck_loop, name="unprotected-backcheck", daemon=True).start()  # B-1354
        if not os.environ.get("PYTEST_CURRENT_TEST"):  # the heartbeat stops with each test app, so it would alarm
            global _loop_heartbeat_ts
            _loop_heartbeat_ts = time.time()  # B-1361: the stamp dates from import; startup hydration made it look like a freeze
            threading.Thread(target=_watchdog_loop, name="watchdog", daemon=True).start()  # B-1356
    asyncio.create_task(_sl_snapshot_loop())
    # Kotak Neo live tick feed (2026-09-04) - display data only, isolated
    # in its own task so a failure here (missing/misconfigured creds, a
    # broken kotakneoapi install) can never affect the scheduler above.
    # See kotak_live_feed.py's module docstring for what this is and
    # isn't - real-time ticks for display, still no live-candle history
    # (Kotak has none), still no order placement.
    try:
        import kotak_live_feed
        asyncio.create_task(kotak_live_feed.run_feed([cfg["symbol"] for cfg in WATCHLIST]))
    except Exception as e:
        print(f"[kotak_live_feed] not started: {e}")
    # F&O per-strike candle feed (2026-09-16, explicit user instruction:
    # run the existing algorithms on each option strike's own premium
    # candles, ATM+/-15 band) - own isolated task, own websocket
    # connection, separate from kotak_live_feed above on purpose (that
    # one is display-only; this one's candles will eventually feed real
    # trading decisions - see kotak_fo_candle_feed.py's own module
    # docstring for the full isolation reasoning).
    try:
        import kotak_fo_candle_feed
        asyncio.create_task(kotak_fo_candle_feed.run_fo_candle_feed())
    except Exception as e:
        print(f"[kotak_fo_candle_feed] not started: {e}")


@app.get("/scheduler-status")
def scheduler_status():
    # Unified count (2026-09-16, per the user's own earlier agreement
    # that this should stop being equity-only once the F&O RSI2 engine
    # was actually running on a schedule - see _run_fo_options_scan,
    # now wired into _scheduler_tick above). watchlist_size stays an
    # int (equity + every currently-subscribed F&O leg, options AND
    # futures) so nothing reading it as a plain count breaks; the
    # per-source split lives in watchlist_breakdown for anything that
    # needs the detail. Never raises even if the F&O feed hasn't
    # resolved a universe yet - falls back to an empty breakdown.
    try:
        import kotak_fo_candle_feed
        fo_universe = kotak_fo_candle_feed.get_cached_fo_universe()
    except Exception:
        fo_universe = {}
    fo_options = sum(1 for d in fo_universe.values() if d["kind"] == "option")
    fo_futures = sum(1 for d in fo_universe.values() if d["kind"] == "future")
    equity = len(WATCHLIST)
    watchlist_breakdown = {
        "equity": equity, "fo_options": fo_options, "fo_futures": fo_futures,
        "total": equity + fo_options + fo_futures,
    }
    return {
        "watchlist_size": watchlist_breakdown["total"],
        "watchlist_breakdown": watchlist_breakdown,
        "interval_seconds": SCHEDULER_INTERVAL_SECONDS,
        "last_tick_ts": _scheduler_last_tick_ts,
        "last_tick_ago_seconds": round(time.time() - _scheduler_last_tick_ts, 1) if _scheduler_last_tick_ts else None,
        "last_error": _scheduler_last_error,
        "checks_last_30s": checks_in_last_seconds(30),
        "scheduler_capital_inr": _real_capital_cache["value"],
        "scheduler_capital_source": "kotak_neo_real_account" if _real_capital_cache["value"] is not None else "not_yet_fetched",
        "scheduler_capital_fetched_at_utc": _real_capital_cache["fetched_at"] or None,
        "scheduler_capital_fetch_error": _real_capital_cache["error"],
        # 2026-09-28: see APP_PROCESS_STARTED_AT_EPOCH's own module comment.
        "last_deploy_completed_at_epoch": APP_PROCESS_STARTED_AT_EPOCH,
    }


